\section{Results}\label{sec:results}
In this section, we will introduce the Hyperplane Distance Depth (HDD) measure and study its properties.

\subsection{Defintion}

\begin{definition}[Hyperplane distance depth]\label{Hyperplane distance depth}
The Hyperplane distance depth (HDD) of a point $q \in \mathbb{R}^d$ relative to a set ${P}$ in $\mathbb{R}^d$ is defined as
\begin{equation}\label{hddDefinition}
    D_P(q)=\sum_{h_i \in H_P} \dist(q,h_i),
\end{equation} 
where $H_P$ is the set of all $\binom{n}{d}$ $(d-1)$-dimensional hyperplanes determined by points in $P$, and $\dist(q,h_i)$ denotes the Euclidean ($L_2$) distance from the point $q$ to the hyperplane $h_i$.
\end{definition}

Both Fermat-Weber depth and hyperplane distance depth are defined as sums of Euclidean ($L_2$) distances. 
Unlike Fermat-Weber depth, for which the location of a median cannot be computed exactly in general when $d \geq 2$ \cite{bajaj1988}, as we show in Section~\ref{Algorithms}, the location of a HDD median can be computed exactly. 

\subsection{Properties}\label{sec:properties}
%%%%%%%%%%%%%%%1D
\begin{theorem} \label{1D}
In $\mathbb{R}$, the HDD median relative to the set ${P}$ coincides with the usual univariate definition of median.
\end{theorem}
\begin{proof}
By Definition~\ref{Hyperplane distance depth}, the median is a point that minimizes the sum of the distances to all possible points passing through each point in $P$. Therefore, $H_P=P$. Consequently, the HDD median is equivalent to the usual definition of median in a one-dimensional space.
\end{proof}

%%%%%%%%%%%%%%%Convexity
\begin{theorem} \label{convexity}
The HDD function $D_P(q)$ relative to the set ${P}$ is convex over $q \in \mathbb{R}^d$.
\end{theorem}
\begin{proof}
The distance function ${d_{h_i}(q)}$ from a query point $q$ to the hyperplane $h_i$ is convex. Any non-negative linear combination of convex functions is convex. Therefore, the HDD function  $\sum_{h_i \in H_P} {d_{h_i}(q)}=D_P(q)$ is convex over $q$.
\end{proof}
%%%%%%%%%%%%%%%%Intersecion 
\begin{theorem} \label{medianOnIntersections}
The HDD median point relative to the set ${P}$ of points in $\mathbb{R}^d$ is always on one of the intersection points between $d$ hyperplanes in $H_P$.
\end{theorem}
\begin{proof}
The distance from the point $q \in \mathbb{R}^d$ to a hyperplane $h_i$ is equal to ${d_{h_i}(q)}=\frac{|{w_i}.q+{b_i}|}{\|{w_i}\|}$ where $w_i$ and $b_i$ are the hyperplane's normal vector and the offset respectively. Therefore, the HDD of the point $q$ is equal to
\begin{equation} \label{eq1}
D_P(q)=\sum_{h_i \in H_P} {d_{h_i}(q)}=\sum_{h_i \in H_P} \frac{|{w_i}.q+{b_i}|}{\|{w_i}\|}
\end{equation}
Depending on the position of $q$ with respect to $h_i$, ${d_{h_i}(q)}=\frac{|{w_i}.q+{b_i}|}{\|{w_i}\|}$ can be equal to $+\frac{{w_i}.q+{b_i}}{\|{w_i}\|}$ (above the hyperplane) ,$-\frac{{w_i}.q+{b_i}}{\|{w_i}\|}$ (below the hyperplane), or $0$ (on the hyperplane). Therefore, for any point $q$ we have
\begin{equation} \label{eq2}
\begin{split}
    & \sum_{h_i \in H_P} {d_{h_i}(q)}=\sum_{h_i \in H_P} g_{i,q} \frac{{w_i}.q+{b_i}}{\|{w_i}\|}\\
    &g_{i,q}= 
\begin{cases}
   +1,& \text{if $q$ is above $h_i$} \\
   -1,& \text{if $q$ is below $h_i$}\\
    0,& \text{if $q$ is on $h_i$}\\
\end{cases}
\end{split}
\end{equation}
It is worth noting that the derivative of the equation \eqref{eq2} exists if $q$ is not on any of the hyperplanes in $H_P$ ($g_{i,q}\neq0$). Now to find the HDD median with the minimum HDD measure, we should compute the derivative with respect to $q$ and see where it will be 
equal to $0$. For any query point $q$ inside a region bounded by some $H_P$ hyperplanes and not on any $H_P$ hyperplanes (Figure~\ref{fig:4PointsExample}) we have 
\begin{equation} \label{eq3}
\begin{split}
    \frac{d}{dq} D_P(q)& = \frac{d}{dq}\sum_{h_i \in H_P} g_{i,q} \frac{{w_i}.q+{b_i}}{\|{w_i}\|}\\& = \sum_{h_i \in H_P} g_{i,q} \frac{{w_i}}{\|{w_i}\|}
\end{split}
\end{equation}
\begin{figure}[h] 
\centering
\includegraphics[width=0.5\textwidth]{figure1.png}
\caption{Example of HDD in two dimensions: $P=\{P_0,P_1,P_2,P_3\}$ is the set of input points, $I=\{I_0,I_1,I_2\}$ is the set of intersection points, and $q$ is the query point.}
\label{fig:4PointsExample}
\end{figure}
Equation~\eqref{eq3} above cannot be equal to $0$ in general since there are no variables \eqref{eq3}. This means the assumption we made about the query point not being on the hyperplanes in $H_P$ was incorrect. Therefore, we can say the median is surely on one of the hyperplanes. If $q$ is on $h_j$, ${w_j}.q+{b_j}$ will be equal to $0$. Therefore, we can say
\begin{align}
    \frac{d}{dq} D_P(q)& =\frac{d}{dq}\sum_{h_i \in H_P-\{h_j\}} g_{i,q} \frac{{w_i}.q+{b_i}}{\|{w_i}\|} \nonumber \\
    & =\sum_{h_i \in H_P-\{h_j\}} g_{i,q} \frac{{w_i}}{\|{w_i}\|} . \label{eq5}
\end{align}
Using the same logic we can conclude that the median point should be on another hyperplane in addition to $h_j$. We can repeat these steps $d$ times and after that, it will be proved that the median should be on the intersection point of $d$ hyperplane (that will be a single point), thus the median will be on one of the intersection points.
\end{proof}
%%%%%%%%%%%%%%%Median in CH
\begin{theorem} \label{MedianInCH}
The HDD median point relative to the set ${P}$ in $\mathbb{R}^d$ is always in the convex hull of the input points $P$.
\end{theorem}
\begin{proof}
Let $D'_{p_i}(q)$ be the sum of the distances to all the hyperplanes in $H_P$ passing through the point $p_i$. The minimum of this convex function is always on the point $p_i$ where the HDD is equal to $0$. On the other hand, since each hyperplane includes $d$ input points from $P$, we have $D_P(q)=d\sum_{p_i \in P}{D'_{p_i}(q)}$.\\
Now consider a point $q_o$ outside of the convex hull. by computing the gradient of $D_P(q_o)$, we will show that by moving $q_o$ closer to the convex hull, the HDD gets smaller. Using the equation above we have $-\nabla H_{P}(q_o)=-d\sum_{p_i \in P}\nabla{D'_{p_i}(q_o)}$. Since the minimum of the function $D'_{p_i}(q)$ is on $p_i$, $-\nabla D'_{p_i}(q)$ is a vector pointing to $p_i$ for $p_i \in P$. Therefore we can conclude that for every point $q_o$ outside of the convex hull, $-\nabla H_{P}(q_o)$ points to the convex hull that means by moving toward that direction, the HDD decreases. Therefore the HDD median is always in the convex hull of $P$.
\end{proof}
%%%%%%%%%%%%%%%Center of Symmetry
\begin{theorem} \label{simmetry}
The HDD median point relative to the set ${P}$ in $\mathbb{R}^d$ is always at the center of symmetry.
\end{theorem}
\begin{proof}
Let $p_M$ be the median of the $P$ s.t. $P$ is symmetric. If $p_M$ is not on the center of symmetry, consider ${p'}_M$, the reflection of $p_M$ across the center of symmetry. Because of the symmetry, it is trivial that the HDD measure of both points is equal. Since the median point has the minimum depth measure among the other points and the depth measure function is convex, all the points on the line segment $p_m{p'}_M$ should have a depth measure equal to the median. Therefore, the median is always at the center of symmetry.
\end{proof}
%%%%%%%%%%%%%%%Vanishing at infinity
\begin{theorem} \label{vanishing}
The HDD measure relative to the set ${P}$ in $\mathbb{R}^d$ vanishes as we move the query point to infinity.
\end{theorem}
\begin{proof}
As we move the query point $q$ to infinity, it is straightforward that there exists a hyperplane $h_i \in H_P$ that gets further from $q$. Since we can move $q$ arbitrarily far from $h_i$, and the distance from $q$ to the remaining hyperplanes in $H_P$ is non-negative, therefore HDD vanishes at infinity.
\end{proof}

Note that some measures of depth are defined such that deep points have high depth values and outliers have low depth values, whereas this property is reversed for other depth measures. HDD is of the latter type, with central points having a low sum of distances to hyperplanes in $H_P$, whereas this sum approaches infinity as $q$ moves away from $P$. Consequently, for HDD, ``vanishing at infinity'' means that depth approaches $\infty$ as opposed to 0.

%%%%%%%%%%%%%%%Robustness
\begin{theorem} \label{robustness}
The HDD measure relative to the set ${P}$ in $\mathbb{R}^d$ is not robust.
\end{theorem}
\begin{proof}
We will prove this fact using a counter-example in a 2-dimensional space (Figure~\ref{fig:Property_Robustness}). We can move the HDD median by changing the location of 2 points which means the HDD is not robust. The median is always on one of the intersection points and we can place the points in a way that $I_0$ is always the median (Figure~\ref{fig:Property_Robustness}). We will compute the depth measures for the points $I_0$ \eqref{eq5} and $I_i$ \eqref{eq6}, where $I_i$ is an arbitrary intersection point except $I_0$.
\begin{figure}[htp]
    \centering
    \includegraphics[width=8cm]{Property_Robustness.png}
    \caption{A counter-example that shows the HDD is not robust}
    \label{fig:Property_Robustness}
\end{figure}

\begin{align}
D_P(I_0) & = \sum_{i\in [3,n]}{ d_{l_{P_1P_i}}(I_0)}+\sum_{i\in [3,n]}{d_{l_{P_2P_i}}(I_0)} \label{eq10} \\
D_P(I_i)& =\sum_{i\in [3,n] }{d_{l_{P_1P_i}}(I_i)} + \sum_{i\in [3,n] }{d_{l_{P_2P_i}}(I_i)} \nonumber \\
& + \binom{n-2}{2} d_{l_{P_3P_n}}(I_i) + d_{l_{P_1P_2}}(I_i) \label{eq6}
\end{align}
Regardless of the $I_0$ position, we know that $I_0H_i<I_0P_2$ and $I_0H'_i<I_0P_1$. Therefore, we have (Equation~\eqref{eq10}):
\begin{equation} \label{eq7}
D_P(I_0)<(n-2)I_0P_2 + (n-2)I_0P_1=(n-2)P_1P_2 
\end{equation}
On the other hand, using Equation~\eqref{eq6} we have:
\begin{equation} \label{eq8}
D_P(I_i)>d_{l_{P_1P_2}}(I_i)
\end{equation}
Now by moving the points $P_1$ and $P_2$ far enough, let $d_{l_{P_1P_2}}(I_i)=(n-2)P_1P_2+m$, where $m$ is a positive number. Therefore, we have (inequality \ref{eq8}):
\begin{equation} \label{eq9}
D_P(I_i)>(n-2)P_1P_2+m
\end{equation}
Combining the inequality \ref{eq7} and \ref{eq9} we have $D_P(I_i)>D_P(I_0)$.

Consequently, $I_0$ is the median. By increasing $m$, the median $I_0$ gets as far as we want. This means by moving $P_1$ and $P_2$, we can move the median point as much as we want.
\end{proof}

\begin{definition}[$k$-stability \cite{durocher2009}]
A depth measure $D$ is \emph{$k$-stable} if for all points $q$ in $\mathbb{R}^d$, all sets $P$ in $\mathbb{R}^d$, all $\epsilon > 0$, and all functions $f_\epsilon:\mathbb{R}^d \to \mathbb{R}^d$ such that $\forall p$, $\dist(p,f(p)) \leq \epsilon$, 
\begin{equation}
    k \cdot |D(q,P) - D(f_\epsilon(q),f_\epsilon(P)| \leq \epsilon ,
\end{equation}
where $f_\epsilon(P) = \{ f_\epsilon(p) \mid p \in P\}$.
\end{definition}

That is, for any $\epsilon$-perturbation of $P$ and $q$, the depth of $q$ relative to $P$ changes by at most $k \epsilon$.

%%%%%%%%%%%%%%%Stability
\begin{theorem}\label{thm:stability}
The HDD measure relative to the set ${P}$ in $\mathbb{R}^d$ is not $k$-stable for any constant $k$.
\end{theorem}

\begin{proof}
Choose any $k > 0$ and let $n = \max\{1, \lceil 1/k\rceil + 1\}$. Let $P$ be a set of $n$ points in $\mathbb{R}$ and let $q \in \mathbb{R}$ lie to the left of $P$. By moving all points of $P$ one unit to the right ($\epsilon = 1$), the hyperplane depth of $q$ relative to $P$ increases by a factor of $n$, regardless of $k$. Thus HDD is not $k$-stable.
\end{proof}

%%%%%%%%%%%%%%%
\begin{theorem} \label{transformation}
The HDD function $D_P(q)$ relative to the set ${P}$ in $\mathbb{R}^d$ is not equivariant under affine transformations.
\end{theorem}
\begin{proof}
We will prove this theorem using a counter-example. Consider the set of points $P=\{p_0(0,0), p_1(4,0), p_2(2,1)\}$. Using Theorem~\ref{medianOnIntersections} we can show that the median is on point $p_2(2,1)$. Now consider the set $P'=\{p'_0(0,0), p'_1(4,0), p'_2(2,5)\}$ that is $P$ under the non-uniform affine transformation matrix $
\begin{bmatrix}
1 & 0 \\
0 & 5
\end{bmatrix}
$.
Using theorem \ref{medianOnIntersections} and \ref{simmetry} It can be shown that the median is on the line $p'_0p'_1$ now. This means that the HDD median is not equivariant under affine transformation. 
\end{proof}

As we now show, HDD is equivariant under similarity transformations, including translation, rotation, reflection and uniform scaling, since these preserve the shape of $P$.

\begin{theorem} \label{similarity}
The HDD function $D_P(q)$ relative to the set ${P}$ in $\mathbb{R}^d$ is equivariant under the similarity transformations.
\end{theorem}

\begin{proof}
For any rotation, reflection, or translation transformation $f$, the distance from the query point $q$ to any hyperplane $h_i$ remains unchanged. That is, for any point $q$ and any hyperplane $h_i$, $\dist(q,h_i) = \dist(f(q),f(h_i))$.

For any uniform scaling transformation $f$ with a scaling factor of $k$, distances between each pair of points will be multiplied by $k$ after the transformation. Therefore it is easy to show that, for any query point $q$, the HDD will be multiplied by $k$ after uniform transformation. Therefore, the median is equivariant under the uniform scaling transformation.
\end{proof}
