\begin{lemma}
\label{lem:pi}
Let $\bm{Y} \in \mathbb{R}^{S \times D}$ be an input matrix. Then, the Jacobian of $\Pi$ with respect to $Y$ is given by
\begin{align}
\frac{\partial \Pi(\bm{Y})}{\partial \bm{Y}} = \operatorname{blockdiag}\left(\{\frac{1}{\|\bm{Y}_{[i,:]}\|}(\bm{I}_{D} - \frac{\bm{Y}_{[i,:]}\bm{Y}_{[i,:]}^\top}{\|\bm{Y}_{[i,:]}\|^2}) \}_{i=1}^{S}\right)
\end{align}
\end{lemma}
\begin{proof}
Since $\Pi$ operates independently on each row of $Y$, the Jacobian is block-diagonal, with each block corresponding to the derivative of a single normalized row:
\begin{align}
\frac{\partial \Pi(\bm{Y})}{\partial \bm{Y}} = \operatorname{blockdiag}(\{\frac{\partial \Pi(\bm{Y})_{[i,:]}}{\partial \bm{Y}_{[i,:]}}\}_{i=1}^{S}).
\end{align}
For each row, we compute the gradient of the normalized vector:
\begin{align}
\frac{\partial \Pi(\bm{Y})_{[i,:]}}{\partial \bm{Y}_{[i,:]}} &= \frac{\partial \bm{Y}_{[i,:]}/\| \bm{Y}_{[i,:]} \|}{\partial \bm{Y}_{[i,:]}} \\
&= \frac{1}{\|\bm{Y}_{[i,:]}\|}\frac{\partial \bm{Y}_{[i,:]}}{\partial \bm{Y}_{[i,:]}} + \bm{Y}_{[i,:]}\frac{\partial 1/\|\bm{Y}_{[i,:]}\|}{\partial \bm{Y}_{[i,:]}} \\
&= \frac{1}{\|\bm{Y}_{[i,:]}\|}\bm{I}_{D} - \bm{Y}_{[i,:]}\frac{\bm{Y}_{[i,:]}^\top}{\|\bm{Y}_{[i,:]}\|^3} \\
&= \frac{1}{\|\bm{Y}_{[i,:]}\|}(\bm{I}_{D} - \frac{\bm{Y}_{[i,:]}\bm{Y}_{[i,:]}^\top}{\|\bm{Y}_{[i,:]}\|^2}) .
\end{align}
\end{proof}

\begin{lemma}
\label{lem:rmsnorm}
Let $\bm{Y} \in \mathbb{R}^{S \times D}$ be an input matrix. Then, the Jacobian of $\operatorname{RMSNorm}$ with respect to $Y$ is given by
\begin{align}
\frac{\partial \operatorname{RMSNorm}(\bm{Y})}{\partial \bm{Y}} = \operatorname{blockdiag}\left(\{\frac{1}{\|\bm{Y}_{[i,:]}\|}\operatorname{diag}(\bm{\gamma})(\bm{I}_{D} - \frac{\bm{Y}_{[i,:]}\bm{Y}_{[i,:]}^\top}{\|\bm{Y}_{[i,:]}\|^2}) \}_{i=1}^{S}\right)
\end{align}
\end{lemma}
\begin{proof}
Since $\operatorname{RMSNorm}$ is expressed as 
\begin{align}
   \operatorname{RMSNorm}(\bm{Y})_{[i,:]} = \operatorname{diag}(\bm{\gamma})\Pi(\bm{Y})_{[i,:]},
\end{align}
the result follows from~\cref{lem:pi}.
\end{proof}

