\subsection{Proof of Proposition~\ref{prop:single}}
\label{proof:single}
\begin{em}
{\bf \Cref{prop:single} is restated.} \\
Consider the continuous-time dynamics for single-head SA equipped with projection~\eqref{eq:cont_SA}.
The energy function
    \begin{align}
       E_{\text{single}}(\bm{X}) &= - \sum_{i,j} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{W}^{Q} \bm{W}^{K\top} \bm{X}_{[j,:]}\right)
\end{align}
is monotonically decreasing as $d E_{\text{single}}(\bm{X})/dt \leq 0$
%\begin{align}
%       E_{\text{single}}(\bm{X}^{(t+1)}) &\le E_{\text{single}}(\bm{X}^{(t)})
%\end{align}
    under the condition: 
\begin{align}
       \bm{W}^{V} = (\bm{W}^{Q\top} \bm{W}^{K} + \bm{W}^{Q} \bm{W}^{K\top})/2.
\end{align}
\end{em}
\begin{proof}
Let $\Delta = \operatorname{softmax}(\beta \bm{X} \bm{W}^{Q} \bm{W}^{K\top} \bm{X}^{\top} ) \bm{X} \bm{W}^{V}$ and let $\bm{A}= \bm{W}^{Q} \bm{W}^{K\top}$. 
The first-order derivative of $E_{\text{single}}(\bm{X})$ with respect to $\bm{X}_{[i,:]}$ is:  
\begin{align}
    &\quad \frac{d E_{\text{single}}(\bm{X})}{d \bm{X}_{[i,:]}} \\
    &= - \sum_{j\neq i} \frac{d \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A} \bm{X}_{[j,:]}\right)}{d \bm{X}_{[i,:]}} - \sum_{j\neq i} \frac{d \exp\left( \beta \bm{X}_{[j,:]}^\top \bm{A} \bm{X}_{[i,:]}\right)}{d \bm{X}_{[i,:]}}  -\frac{d \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A} \bm{X}_{[i,:]}\right)}{d \bm{X}_{[i,:]}} \\
    &= - \sum_{j\neq i} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A} \bm{X}_{[j,:]}\right)\bm{A}^\top \bm{X}_{[j,:]} - \sum_{j\neq i} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A} \bm{X}_{[j,:]}\right)\bm{A} \bm{X}_{[j,:]} \\
    & \quad -\exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A} \bm{X}_{[j,:]}\right)(\bm{A}^\top + \bm{A}) \bm{X}_{[i,:]} \\
    &= - \sum_{j} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A} \bm{X}_{[j,:]}\right)(\bm{A}^\top + \bm{A})\bm{X}_{[j,:]}.
\end{align}
Under the given condition on the weights, $\bm{A} = \bm{A}^{\top} $we have: 
\begin{align}
    \Delta_{[i,:]} &= (\operatorname{softmax}(\beta \bm{X}\bm{W}^{V}\bm{X}^{\top})_{[i,:]}\bm{X}(\bm{A}^\top + \bm{A}))^{\top} / 2 \\
    &= \sum_{j} \frac{\exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A} \bm{X}_{[j,:]}\right)}{Z_{i}}(\bm{A}^\top + \bm{A})\bm{X}_{[j,:]} / 2,
\end{align}
where $Z_{i} = \sum_{j'} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A} \bm{X}_{[j',:]}\right)$ is the normalization term.

Thus, we have,
\begin{align}
   &\quad \frac{d E_{\text{single}}(\bm{X})}{dt} \\
   &= \frac{d E_{\text{single}}(\bm{X})}{d\bm{X}} \cdot \frac{d\bm{X}}{dt} \\
   &= -  \sum_{i} \left(\frac{d E_{\text{single}}(\bm{X})}{d \bm{X}_{[i,:]}}\cdot (\bm{I}_{D}-\bm{X}_{[i,:]}\bm{X}_{[i,:]}^{\top}) \Delta_{[i,:]} \right) \\
   &= -  \sum_{i} \left(\sum_{j} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A} \bm{X}_{[j,:]}\right)(\bm{A}^\top + \bm{A})\bm{X}_{[j,:]}\cdot (\bm{I}_{D}-\bm{X}_{[i,:]}\bm{X}_{[i,:]}^{\top}) \Delta_{[i,:]} \right) \\
   &= -  2\sum_{i} \left(Z_{i} \Delta_{[i,:]}\cdot (\bm{I}_{D}-\bm{X}_{[i,:]}\bm{X}_{[i,:]}^{\top})\Delta_{[i,:]} \right) \\
   &= -  2\sum_{i} \left(Z_{i} \Delta_{[i,:]}^{\top}(\bm{I}_{D}-\bm{X}_{[i,:]}\bm{X}_{[i,:]}^{\top}) \Delta_{[i,:]} \right) \\
   &\le 0,
\end{align}
where, in the last inequality, we used the fact that the matrix $\bm{I}_{D} - \bm{X}_{[i,:]} \bm{X}_{[i,:]}^{\top}$ is positive semi-definite.
\end{proof}

\subsection{Proof of Proposition~\ref{prop:multi}}
\label{proof:multi}
\begin{em}
{\bf \Cref{prop:multi} is restated.}
Consider the continuous-time dynamics for multi-head SA without projection: $d\bm{X}/dt=\sum_{h=1}^{H} SA_h(\bm{X})$. An energy function
    \begin{align}
       E_{\text{multi}}(\bm{X}) &= - \sum_{h}\sum_{i,j} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{W}^{Q}_{h} \bm{W}^{K\top}_{h} \bm{X}_{[j,:]}\right)
\end{align}
is monotonically decreasing as $d E_{\text{multi}}(\bm{X})/dt \leq 0$ under the condition
\begin{align}
    \bm{W}^{V}_{h} &= (\bm{W}^{Q\top}_{h} \bm{W}^{K}_{h} + \bm{W}^{Q}_{h} \bm{W}^{K\top}_{h}) / 2, \ \
     \bm{W}^{Q}_{h} \bm{W}^{K\top}_{h} = \bm{U}_{1,h} \bm{U}_{2,h}^{\top},
\end{align}
where $\bm{U}_{1(2),h} \in \mathbb{R}^{D \times D/(2H)}$ ($h\in [1, H]$) satisfies the orthogonality condition $\bm{U}_{k,h}^{\top} \bm{U}_{k',h'} = \delta_{hh'} \delta_{kk'}  \bm{I}_{D/(2H)}$.
\end{em}

\begin{proof}
Let $\Delta_{h} = \operatorname{softmax}(\beta \bm{X}\bm{W}^{Q}_{h} \bm{W}^{K\top}_{h}\bm{X}^{\top})\bm{X}\bm{W}^{V}_{h})$ and let $\bm{A}_{h} = \bm{W}^{Q}_{h} \bm{W}^{K\top}_{h}$. The first-order derivative of $E_{\text{multi}}(\bm{X})$ with respect to $\bm{X}_{[i,:]}$ is, similarly to the single-head case, given by:
\begin{align}
    \frac{\partial E_{\text{multi}}(\bm{X})}{\partial \bm{X}_{[i,:]}}
    &= - \sum_{h} \sum_{j} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A}_{h} \bm{X}_{[j,:]}\right)(\bm{A}_{h}^{\top} + \bm{A}_{h})\bm{X}_{[j,:]}
\end{align}
Under the given condition on the weights, similar to the single-head case, we have: 
\begin{align}
    \Delta_{h [i,:]} &= \sum_{j} \frac{\exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A}_{h} \bm{X}_{[j,:]}\right)}{Z_{h, i}}(\bm{A}_{h}^{\top} + \bm{A}_{h})\bm{X}_{[j,:]} / 2
\end{align}
where $Z_{h,i} = \sum_{j'} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A}_{h} \bm{X}_{[j',:]}\right)$ is the normalization term.
Thus, we have,
\begin{align}
&\quad \frac{d E_{\text{multi}}(\bm{X})}{dt} \\
   &= \frac{d E_{\text{multi}}(\bm{X})}{d\bm{X}} \cdot \frac{d\bm{X}}{dt} \\
   &= -  \sum_{i} \left(\frac{\partial E_{\text{multi}}(\bm{X})}{\partial \bm{X}_{[i,:]}}\cdot \sum_{h} \Delta_{h[i,:]} \right) \\
   &= -  \sum_{i} \left(\sum_{h} \sum_{j} \exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A}_{h} \bm{X}_{[j,:]}\right)(\bm{A}_{h}^{\top} + \bm{A}_{h})\bm{X}_{[j,:]}\cdot \sum_{h} \Delta_{h[i,:]} \right) \\
   &= -  2\sum_{i} \left(\sum_{h} Z_{h,i} \Delta_{h[i,:]}\cdot \sum_{h} \Delta_{h[i,:]} \right) \\
   &= -  2\sum_{i} \sum_{h} \left(Z_{h,i} \Delta_{h[i,:]}\cdot \Delta_{h[i,:]} \right) \\
   &= -  2\sum_{i}\sum_{h} Z_{h,i} \|\Delta_{h[i,:]}\|^{2} \\
   &\le 0. 
\end{align}
In the third-to-last line, we use the fact that for $h\neq h'$,
\begin{align}
\bm{A}_{h}^{\top}\bm{A}_{h'} = \bm{U}_{2,h}\bm{U}_{1,h}^{\top}\bm{U}_{1,h'}\bm{U}_{2,h'}^{\top} = \bm{O} \\
\bm{A}_{h}\bm{A}_{h'} = \bm{U}_{1,h}\bm{U}_{2,h}^{\top}\bm{U}_{1,h'}\bm{U}_{2,h'}^{\top} = \bm{O},
\end{align}
and thus
\begin{align}
&\quad \Delta_{h[i,:]}\cdot \Delta_{h'[i,:]} \\
&= \Delta_{h[i,:]}^{\top}\Delta_{h'[i,:]} \\
&= \left((\bm{A}_{h} + \bm{A}_{h}^{\top})\sum_{j} \frac{\exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A}_{h} \bm{X}_{[j,:]}\right)}{Z_{h, i}}\bm{X}_{[j,:]}\right)^\top \\  &\quad \quad (\bm{A}_{h'} + \bm{A}_{h'}^{\top})\sum_{j} \frac{\exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A}_{h'} \bm{X}_{[j,:]}\right)}{Z_{h', i}}\bm{X}_{[j,:]} / 4\\
&= \left(\sum_{j} \frac{\exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A}_{h} \bm{X}_{[j,:]}\right)}{Z_{h, i}}\bm{X}_{[j,:]}\right)^\top \\  
&\quad \quad (\bm{A}_{h}^{\top} + \bm{A}_{h}) (\bm{A}_{h'} + \bm{A}_{h'}^{\top})\sum_{j} \frac{\exp\left( \beta \bm{X}_{[i,:]}^\top \bm{A}_{h'} \bm{X}_{[j,:]}\right)}{Z_{h', i}}\bm{X}_{[j,:]} / 4 \\
&= 0.
\end{align}
\end{proof}

