\subsection{Proof of Proposition~\ref{prop:normalize}}
\label{proof:normalize}
\begin{em}
{\bf \Cref{prop:normalize} is restated.} 
Suppose that, in the update of ItrSA~\eqref{eq:itrsa}, the input to the normalization layer satisfies $\|\bm{X}_{[i,:]} + \eta \Delta \bm{X}_{[i,:]}\| \ge R$ for all $i \in [1, S]$. Then, the spectral norm of the Jacobian satisfies the upper bound
\begin{align}
\left\| \frac{\partial \operatorname{RMSNorm}(\bm{X} + \eta \Delta \bm{X})}{\partial \bm{X}} \right\|_2 
&\le \frac{\max_j(|\gamma_j|)}{R} \left(1 + |\eta| \left\|\bm{J}_{\text{MSA}}(\bm{X})\right\|_2 \right),
\end{align}
where $\bm{J}_{\text{MSA}}(\bm{X}) := \partial \operatorname{MSA}(\bm{X}) / \partial \bm{X}$ denotes the Jacobian of MSA.
\end{em}

\begin{proof}
First, for any vector $a \in \mathbb{R}^{D}$, the eigenvalues of the matrix $I_D - \frac{aa^\top}{\|a\|^2}$ are $1$ (with multiplicity $D-1$) and $0$ (with multiplicity $1$). Hence,
\begin{align}
\left\| I_D - \frac{aa^\top}{\|a\|^2} \right\|_2 &\le 1.
\end{align}

Using \Cref{lem:rmsnorm}, we have
% \begin{align}
% \left\| \frac{\partial \operatorname{RMSNorm}(\bm{Y})}{\partial \bm{Y}} \right\|_2 
% &= \left\| \operatorname{blockdiag} \left( \left\{ \frac{\sqrt{D}}{\|\bm{Y}_{[i,:]}\|} \operatorname{diag}(\bm{\gamma}) \left( I_D - \frac{\bm{Y}_{[i,:]}\bm{Y}_{[i,:]}^\top}{\|\bm{Y}_{[i,:]}\|^2} \right) \right\}_{i=1}^{S} \right) \right\|_2 \\
% &= \max_i \left\| \frac{\sqrt{D}}{\|\bm{Y}_{[i,:]}\|} \operatorname{diag}(\bm{\gamma}) \left( I_D - \frac{\bm{Y}_{[i,:]}\bm{Y}_{[i,:]}^\top}{\|\bm{Y}_{[i,:]}\|^2} \right) \right\|_2 \\
% &\le \frac{\sqrt{D}}{R} \max_j \gamma_j
% \end{align}
% and
\begin{align}
\left\| \frac{\partial \operatorname{RMSNorm}^{(\text{osc})}(\bm{Y})}{\partial \bm{Y}} \right\|_2 
&= \left\| \operatorname{blockdiag} \left( \left\{ \frac{1}{\|\widetilde{\bm{Y}}_{i,j}\|} \operatorname{diag}(\bm{\gamma}) \left( I_D - \frac{\widetilde{\bm{Y}}_{i,j}\widetilde{\bm{Y}}_{i,j}^\top}{\|\widetilde{\bm{Y}}_{i,j}\|^2} \right) \right\}_{i,j}^{} \right) \right\|_2 \\
&= \max_i \left\| \frac{1}{\|\bm{Y}_{[i,:]}\|} \operatorname{diag}(\bm{\gamma}) \left( I_D - \frac{\bm{Y}_{[i,:]}\bm{Y}_{[i,:]}^\top}{\|\bm{Y}_{[i,:]}\|^2} \right) \right\|_2 \\
% &\le \frac{\sqrt{D}}{R} \max_j \gamma_j
&\le \frac{\max_j |\gamma_j|}{R} .
\end{align}
Therefore, setting $\bm{Y}= \bm{X} + \eta \Delta \bm{X} = \bm{X} + \eta \left(\bm{C} + \operatorname{MSA}(\bm{X})\right)$, we have
\begin{align}
&\quad \left\| \frac{\partial \operatorname{RMSNorm}(\bm{X} + \eta \Delta \bm{X})}{\partial \bm{X}} \right\|_2 \\
&= \left\| \frac{\partial \operatorname{RMSNorm}(\bm{Y})}{\partial \bm{Y}} \frac{\partial \bm{Y}}{\partial \bm{X}}\right\|_2 \\
&\le \left\| \frac{\partial \operatorname{RMSNorm}(\bm{Y})}{\partial \bm{Y}}\right\|_2  \left\|\frac{\partial \bm{Y}}{\partial \bm{X}}\right\|_2 \\
&\le \frac{\max_j |\gamma_j|}{R} \left\|\bm{I}_{SD} + \eta \bm{J}_{\text{MSA}} \right\|_2 \\
&\le \frac{\max_j(|\gamma_j|)}{R} \left(1 + |\eta| \left\|\bm{J}_{\text{MSA}}(\bm{X})\right\|_2 \right).
\end{align}
\end{proof}

\subsection{Derivation of the eigenvalue bound in oscillatory cases (Section~\ref{sec:osc})}
\label{sec:eig_osc}
We show that all eigenvalues $\lambda_j$ of the Jacobian
\begin{align}
\bm{J}(x) = \left(\bm{I}_{D} - \frac{\bm{y}\bm{y}^\top}{\|\bm{y}\|^2}\right)\frac{1}{\|\bm{y}\|}(\bm{I}_{D} + \eta \bm{\Omega}),
\end{align}
satisfy $|\lambda_j| \le 1$, where $\bm{y} = (\bm{I}_{D} + \eta \bm{\Omega})\bm{x}$.

We begin by computing the norm of $\bm{y}$:
\begin{align}
\|\bm{y}\|^2 &= \|(\bm{I}_{D} + \eta \bm{\Omega})\bm{x}\|^2 \\
&= \bm{x}^\top(\bm{I}_{D} + \eta \bm{\Omega}^\top)(\bm{I}_{D} + \eta \bm{\Omega})\bm{x} \\
&= \bm{x}^\top \bm{x} + \eta \bm{x}^\top \bm{\Omega} \bm{x} + \eta \bm{x}^\top \bm{\Omega}^\top \bm{x} + \eta^2 \bm{x}^\top \bm{\Omega}^\top \bm{\Omega} \bm{x} \\
&= 1 + \eta^2 \|\bm{\Omega} \bm{x}\|^2, 
\end{align}
where we used the fact that for an antisymmetric matrix $\bm{\Omega}$,  $\bm{x}^\top \bm{\Omega} \bm{x} = 0$.
Note also that an antisymmetric matrix has eigenvalues of the form $\pm i \omega_j$, where $\omega_j \geq 0$ ($j=1,2,\dots$).
For simplicity, assume all eigenvalues have identical magnitude $\omega_j = \omega$. Then, we have
\begin{equation}
\|\bm{y}\|^2 = 1 + \eta^2 \omega^2.
\end{equation}



We also use the facts that
\begin{align}
\left\|\bm{I}_{D} - \frac{\bm{y}\bm{y}^\top}{\|\bm{y}\|^2}\right\|_{2} \le 1
\end{align}
and
\begin{align}
\left\|\bm{I}_{D} + \eta \bm{\Omega} \right\|_{2} &= |1 \pm i \eta \omega| = \sqrt{1 + \eta^2 \omega^2}.
\end{align}

Combining these, we obtain the following bound on the spectral norm of $\bm{J}(\bm{x})$:
\begin{align}
\|\bm{J}(\bm{x})\|_{2} &= \left\|\left(\bm{I}_{D} - \frac{\bm{y} \bm{y}^\top}{\|\bm{y}\|^2} \right)\frac{1}{\|\bm{y}\|}(\bm{I}_{D} + \eta \bm{\Omega})\right\|_{2} \\
&\le \frac{1}{\|\bm{y}\|} \left\| \bm{I}_{D} + \eta \bm{\Omega} \right\|_{2} \\
&\le \frac{\sqrt{1 + \eta^2 \omega^2}}{\sqrt{1 + \eta^2 \omega^2}} = 1.
\end{align}

This implies that all eigenvalues of $\bm{J}(\bm{x})$ satisfy $|\lambda_j| \le 1$.

\section{Experimental details}
\label{appendix:experiment}

\subsection{Experimental setup}
We solved Sudoku task, which is a puzzle played on a $9 \times 9$ grid, where some of the cells are pre-filled with digits from $1$ to $9$, and the remaining cells are left blank. The objective is to fill in the blank cells such that each 1) row, 2) column, and 3) $3 \times 3$ subgrid contains each digit exactly once.

In our experiments, we used two Sudoku datasets: the SATNet~\citep{wang2019satnet} and RRN dataset~\citep{palm2018recurrent}. The key differences between the two are that the RRN dataset is more difficult (with only $17$–$34$ given digits compared to $31$–$42$ in SATNet) and larger in size ($198$k samples vs. $10$k samples). Following~\citet{miyato2024artificial}, we used the SATNet dataset for training as in-distribution (ID) data and the RRN dataset as out-of-distribution (OOD) data. This setup allows us to evaluate the ability of models to generalize to more challenging settings.

We primarily followed~\citet{miyato2024artificial} and used their official implementation\footnote{\url{https://github.com/autonomousvision/akorn}}, using $N=4$ as the dimension of oscillators. 
We used the Adam optimizer~\citep{kingma2014adam} and trained for $100$ epochs with batch size $100$. We tuned the learning rate across $\{1 \times 10^{-6}, 5 \times 10^{-6}, \dotsc, 1 \times 10^{-3}\}$ for all settings based on the OOD accuracy at the iteration $T=16$.
All experiments were conducted on NVIDIA H200 GPUs, and we run experiments with 5 different random seeds.

We also conducted experiments on the CIFAR-10 dataset~\citep{cifar10}. See~\cref{tab:training_config} for training and model configurations.

