\section{Convergence analysis of the IIM}\label{sect_convergence}

In this section, we present a convergence analysis of the IIM defined in \eqref{eq:mp1} within the framework of inverse problems \cite{Engl_Hanke_Neubauer_1996,Scherzer_Grasmair_Grossauer_Haltmeier_Lenzen_2008}. As noted before, the quasi-static elastography problem is ill-posed, and thus in particular unstable with respect to noise in the measured images $\mI_1$ and $\mI_2$. Hence, in the IIM the regularization functional $\mathcal{R}$ was added in order to stabilize the problem. The resulting functional 
    \begin{equation*}
        \mathcal{T}_\alpha(\af) = \norm{\mI_2 \circ G(\af)- \mI_1}^2_{L_2(\Omega)} + \alpha \mathcal{R}(\af)
    \end{equation*}
closely resembles a classic Tikhonov functional \cite{Engl_Hanke_Neubauer_1996,Scherzer_Grasmair_Grossauer_Haltmeier_Lenzen_2008}. In fact, together with the definition
    \begin{equation}\label{def_F}
        \mathcal{F}(\af) : \, D(\mathcal{F}) =: \mathcal{M} \subseteq X \to Y := L_2(\Omega) \,, \qquad \af \mapsto \F(\af) := \mI_2 \circ G(\af) \,,
    \end{equation}
the functional $\mathcal{T}_\alpha$ in the IIM \eqref{eq:mp1} can be written in the standard form
    \begin{equation*}
        \mathcal{T}_\alpha(\af) = \norm{\F(\af) - \mI_1}^2_{Y} + \alpha \norm{\af - \af_0}_X^2 \,,
    \end{equation*}
to which the classical theory of Tikhonov regularization may be applied \cite{Engl_Hanke_Neubauer_1996,Scherzer_Grasmair_Grossauer_Haltmeier_Lenzen_2008}. However, one key difference to the classical setting is that in our case, both measured images $\mI_1$ and $\mI_2$ are typically contaminated by noise, and thus by definition the operator $\F$ is noisy as well. Fortunately, this setting was already implicitly considered in \cite{Neubauer_Scherzer_1990}, as well as in a more general Banach space setting in \cite{Lu_Fleming_2012}. In this paper, we make use of these results to obtain a convergence analysis of our proposed IIM.

In order to indicate that the measured images contain noise, from now on we write $\mI_1^\delta$ and $\mI_2^\delta$ instead of $\mI_1$ and $\mI_2$, respectively. Furthermore, we also consider the case that the displacement field $\uf(\x,\af)$ is contaminated by noise as well. This may for example be the case if some or all of the involved quantities in \eqref{eq:bvp} are only known inexactly. Correspondingly, we write $\uf^\delta(\x,\af)$, $G^\delta(\af)$, and set
    \begin{equation}\label{def_Fd}
        \F^\delta(\af) : \, D(\F^\delta) =: \mathcal{M} \subseteq X \to Y := L_2(\Omega) \,, \qquad \af \mapsto \F^\delta(\af) := \mI_2^\delta \circ G^\delta(\af) \,.
    \end{equation}   
Furthermore, in the upcoming convergence analysis, we distinguish between two specific noise cases:
    \begin{enumerate}
        \item \textbf{Restricted noise case}: Only the image $\mI_1^\delta$ is contaminated by noise, and thus the IIM reads
            \begin{equation}\label{def_Tad_restricted}
                \min\limits_{\af \in \mathcal{M}} \mathcal{T}_\alpha^\delta(\af) \,, 
                \qquad \text{where} \qquad 
                \mathcal{T}_\alpha^\delta(\af) := \norm{\F(\af) - \mI_1^\delta}^2_{L_2(\Omega)} + \alpha \norm{\af - \af_0}_X^2 \,.
            \end{equation}
        %
        \item \textbf{Full noise case}: Both $\mI_1^\delta$, $\mI_2^\delta$, and $\uf^\delta(x,\af)$ are contaminated by noise, and thus the IIM reads
            \begin{equation}\label{def_Tad_full}
                \min\limits_{\af \in \mathcal{M}} \mathcal{T}_\alpha^\delta(\af) \,, 
                \qquad \text{where} \qquad 
                \mathcal{T}_\alpha^\delta(\af) := \norm{\F^\delta(\af) - \mI_1^\delta}^2_{L_2(\Omega)} + \alpha \norm{\af - \af_0}_X^2 \,.
            \end{equation}
    \end{enumerate}
For both the restricted and full noise case, we require the following minimal set of model assumptions:

\begin{assumption}[Minimal model assumptions for the IIM] \label{ass_model_minimal} \hfill
\begin{enumerate}
    \item The operator $\F(\af) = \mI_2 \circ G(\af)$ as defined in \eqref{def_F} is continuous and weakly sequentially closed.
    %
    \item For a given (noise-free) image $\mI_1$ there exists an $\af_0$-minimum-norm-solution (MNS) $\af^*$, i.e.,
        \begin{equation*}
            \mI_2 \circ G(\af^*) = \mI_1 \,,
            \qquad \text{and} \qquad
            \norm{\af^*-\af_0}_X = \min_{\af\in\mathcal{M}}\Kl{ \norm{\af-\af_0}_X \, \vert \, \mI_2 \circ G(\af^*) = \mI_1 } \,.
        \end{equation*}
    %
    \item There is a noise level $\delta_{\mI_1} > 0$ such that  
        \begin{equation*}
            \norm{ \mI_1 - \mI_1^\delta }_\LtO \leq \delta_{\mI_1} \,.
        \end{equation*}
\end{enumerate}
\end{assumption}

\begin{remark}
Clearly, the restricted noise case is only one specific instance of the full noise case. The main benefit of considering these two separately is that the convergence analysis of the restricted noise case requires less stringent assumptions than that of the full noise case. While in practice both $\mI_1^\delta$ and $\mI_2^\delta$ are contaminated by noise, one typically selects one of them, usually $\mI_1^\delta$, as the reference image. Hence, if in addition the deformation $\uf$ is noise-free, one may informally ascribe the noise in the reference image $\mI_1^\delta$ to $\mI_2^\delta$, and thus approximately transform the full into the restricted noise case.
\end{remark}


% Convergence analysis I: restricted noise case
\subsection{Convergence analysis I: restricted noise case}

First, we consider the restricted noise case \eqref{def_Tad_restricted}, for which we obtain the following convergence result.

\begin{theorem}\label{theorem_convergence_restricted}
Let Assumption~\ref{ass_minimal} and \ref{ass_model_minimal} hold. Furthermore, let $\alpha = \alpha(\delta_{\mI_1})$ be chosen such that
    \begin{equation*}
        \alpha(\delta_{\mI_1}) \to 0 \,,
        \qquad
        \text{and}
        \qquad
        \frac{(\delta_{\mI_1})^2}{\alpha(\delta_{\mI_1})} \to 0 \,,
        \qquad
        \qquad
        \text{for}
        \qquad
        \delta_{\mI_1}\to 0 \,.
    \end{equation*}
Then every sequence $\Kl{\af_k := \af_{\alpha(\delta_k)}^{\delta_k}}_{k\in\N}$ with $\delta_k \to 0$ as $k\to \infty$, and where $\af_k$ is a minimizer of \eqref{def_Tad_restricted} has a convergent subsequence $\boldsymbol{a}_{n_k}$. Furthermore, the limit of every convergent subsequence is an $\af_0$ minimum norm solution. Moreover, if the $\af_0$ minimum norm solution $\af^\dagger$ is unique, then
    \begin{equation*}
        \lim\limits_{\boldsymbol{\delta}_k \to 0} \af_{\alpha(\boldsymbol{\delta}_k)}^{\boldsymbol{\delta}_k} = \af^\dagger\,.
    \end{equation*}
\end{theorem}
\begin{proof}
Using Assumption~\ref{ass_minimal} and \ref{ass_model_minimal}, this follows from classic Tikhonov convergence results \cite{Engl_Hanke_Neubauer_1996}.
\end{proof}

For establishing convergence rates, we require additional differentiability assumptions on $\mI_2$ and $\uf$.

\begin{assumption}[Differentiability assumptions for the IIM] \label{ass_differentiability} \hfill
\begin{enumerate}
    \item The (noise-free) image $\mI_2$ is continuously Fr\'echet differentiable, satisfying $\mI_2 \in W^{1,\infty}(\Omega_2)$ with 
        \begin{equation}\label{Lipschitz_I1}
            C_L := \norm{\mI_2}_{W^{1,\infty}(\Omega_2)} < \infty \,.
        \end{equation}
    %
    \item The function $\uf$ is continuously Fr\'echet differentiable wrt.\ $\af$, and there are $C_1^*, C_2^*,C_3^* > 0$ with
        \begin{align}
            \norm{\uf'(\af^*) \hf}_{L_\infty(\Omega)} &\leq C_1^* \norm{\hf}_X \,, \label{Lipschitz_u_infty}
            \\
            \norm{ \uf(\af^*) - \uf(\af)}_{L_2(\Omega)} &\leq C_2^* \norm{\af^* - \af}_X \,, \label{Lipschitz_u}
            \\
            \norm{\uf'(\af^*)\hf - \uf'(\af)\hf}_{L_2(\Omega)} &\leq C_3^* \norm{\af^*-\af}_X \norm{\hf}_X \,, \label{Lipschitz_Du}
        \end{align}
    for all $\hf \in \mathcal{M}$ and $\af \in \mathcal{M} \cap B_\eps(\af^*)$, where $\af^*$ is an $\af_0$-MNS and $\epsilon>2\norm{\af^* - \af_0}_X$.
\end{enumerate}
\end{assumption}

Using these assumptions, we now establish some necessary derivative estimates for the operator $\mathcal{F}$.

\begin{proposition}\label{prop_differentiability}
Let Assumption~\ref{ass_minimal}, \ref{ass_model_minimal}, and \ref{ass_differentiability} hold. Then the operator $\F$ defined in \eqref{def_F} satisfies
    \begin{equation}\label{F_continuous}
         \norm{\F(\af_1) - \F(\af_2)}_{L_2(\Omega)} \leq C_L \norm{ \uf(\af_1) - \uf (\af_2)}_{L_2(\Omega)}  \,,
        \qquad 
         \forall \, \af_1,\af_2 \in \mathcal{M} \,,
     \end{equation}
and is continuous and continuously Fr\'echet differentiable with
    \begin{equation}\label{F_Frechet}
        \F'(\af) \hf = (\mI_2' \circ G(\af)) \uf'(\af) \hf \,,
        \qquad 
        \forall \, \af \,, \hf \in \mathcal{M} \,.
    \end{equation}
Furthermore, for all $\hf \in \mathcal{M}$ and $\af \in \mathcal{M} \cap B_\eps(\af^*)$ there holds
    \begin{equation}\label{DF_Lipschitz}
        \norm{\F'(\af^*)\hf - \F'(\af)\hf}_{L_2(\Omega)} \leq C \norm{\af^* - \af}_{X} \norm{\hf}_X \,,
    \end{equation}
where $C:= C_L \kl{C_1^*C_2^* + C_3^*}$, $\af^*$ is an $\af_0$-MNS, and $\epsilon>0$ is as in Assumption~\ref{ass_differentiability}.
\end{proposition}
\begin{proof}
First, let $\af_1, \af_2 \in \mathcal{M}$ be arbitrary but fixed. Then together with \eqref{Lipschitz_I1} there follows
    \begin{equation*}
    \begin{split}
        \norm{\F(\af_1) - \F(\af_2)}_{L_2(\Omega)} 
        &= 
        \norm{\mI_2 \circ G(\af_1) - \mI_2 \circ G(\af_2)}_{L_2(\Omega)} 
        \\
        &\overset{\eqref{Lipschitz_I1}}{\leq} 
        C_L \norm{ G(\af_1) - G(\af_2)}_{L_2(\Omega)} 
        =  
        C_L \norm{ \uf(\af_1) - \uf (\af_2)}_{L_2(\Omega)} \,,
        %\overset{\eqref{Lipschitz_u}}{ \leq } 
        %C_L C_\uf \norm{\af_1 - \af_2}_X \,,
    \end{split}
    \end{equation*}
which establishes \eqref{F_continuous}, and thus the continuity of $\uf$ also implies the continuity of $\F$. Next, since both $\mI_2$ and $\uf$ are also assumed to be continuously Fr\'echet differentiable, the Fr\'echet differentiability of $\F$ and \eqref{F_Frechet} follow from the chain rule. Finally, for $\hf \in \mathcal{M}$ and $\af \in \mathcal{M} \cap B_\eps(\af^*)$ we have
    \begin{equation}\label{helper_DF_01}
    \begin{split}
        &\norm{\F'(\af^*)\hf - \F'(\af)\hf}_{L_2(\Omega)}
        =
        \norm{(\mI_2' \circ G(\af^*)) \uf'(\af^*) \hf - (\mI_2' \circ G(\af)) \uf'(\af) \hf}_{L_2(\Omega)}
        \\
        & \qquad 
        \leq 
        \norm{(\mI_2'\circ G(\af^*)) \uf'(\af^*) \hf - (\mI_2' \circ G(\af)) \uf'(\af^*) \hf}_{L_2(\Omega)}
        \\
        & \qquad \qquad 
        +
        \norm{(\mI_2'\circ G(\af)) \uf'(\af^*) \hf - (\mI_2'\circ G(\af)) \uf'(\af) \hf}_{L_2(\Omega)} \,.
    \end{split} 
    \end{equation}
For the first term, we use \eqref{Lipschitz_I1}, \eqref{Lipschitz_u_infty}, and \eqref{Lipschitz_u} to obtain
    \begin{equation*}
    \begin{split}
        &\norm{(\mI_2' \circ G(\af^*)) \uf'(\af^*) \hf - (\mI_2'\circ G(\af)) \uf'(\af^*) \hf}_{L_2(\Omega)}
        =
        \norm{\kl{ \mI_2' \circ G(\af^*) - \mI_2'\circ G(\af)} \uf'(\af^*) \hf}_{L_2(\Omega)}
        \\
        & \qquad 
        \leq
        \norm{ \mI_2' \circ G(\af^*) - \mI_2'\circ G(\af)}_{L_2(\Omega)}
        \norm{\uf'(\af^*) \hf}_{L_\infty(\Omega)}
        \\
        & \qquad 
        \leq
        C_L \norm{ G(\af^*) - G(\af)}_{L_2(\Omega)}
        C_1^* \norm{\hf}_{X}
        \\
        & \qquad 
        =
        C_L C_1^* \norm{ \uf(\af^*) - \uf(\af)}_{L_2(\Omega)} \norm{\hf}_{X}
        \\
        & \qquad 
        \leq
        C_L C_1^* C_2^*  \norm{ \af^* - \af}_{X}
        \norm{\hf}_{X} \,.
    \end{split}
    \end{equation*}
For the second term, we use \eqref{Lipschitz_I1} and \eqref{Lipschitz_Du} to obtain
    \begin{equation*}
    \begin{split}
        &\norm{(\mI_2'\circ G(\af)) \uf'(\af^*) \hf - (\mI_2'\circ G(\af)) \uf'(\af) \hf}_{L_2(\Omega)} 
        =
        \norm{\kl{\mI_2'\circ G(\af)}\kl{\uf'(\af^*) \hf - \uf'(\af) \hf}}_{L_2(\Omega)} 
        \\
        \qquad 
        &\leq 
        \norm{\mI_2'\circ G(\af)}_{L_\infty(\Omega)} \norm{\uf'(\af^*) \hf - \uf'(\af) \hf}_{L_2(\Omega)} 
        \\
        \qquad
        &\leq 
        C_L C_3^* \norm{\af^*-\af}_X \norm{\hf}_X
    \end{split}
    \end{equation*}
Hence, inserting these estimates into \eqref{helper_DF_01} we obtain
    \begin{equation*}
    \begin{split}
        \norm{\F'(\af^*)\hf - \F'(\af)\hf}_{L_2(\Omega)} 
        \leq 
        C_L \kl{C_1^*C_2^* + C_3^*} \norm{\af^*-\af}_X \norm{h}_X
        \,,
    \end{split}
    \end{equation*}
which now yields \eqref{DF_Lipschitz} and thus completes the proof.
\end{proof}

With this, we now obtain the following convergence rate results in the restricted noise case \eqref{def_Tad_restricted}.

\begin{theorem}
Let Assumption~\ref{ass_minimal}, \ref{ass_model_minimal}, and \ref{ass_differentiability} hold, and assume that there is a $w \in L_2(\Omega)$ with
    \begin{equation*}
        \af^\dagger - \af_0  = \mathcal{F}'(\af^\dagger)^*w \,,
        \qquad \text{and} \qquad
        C \norm{w} < 1 \,,
    \end{equation*}
where $C$ is as in Proposition~\ref{prop_differentiability}. Then for $\alpha \sim \delta_{\mI_1}$, a minimizer $\af_\alpha^\delta$ of \eqref{def_Tad_restricted} satisfies
    \begin{equation*}
        \norm{\af_\alpha^\delta - \af^\dagger}_{X} = \mathcal{O}\kl{\sqrt{\delta_{\mI_1}}} \,,
        \qquad \text{and} \qquad 
        \norm{\mI_2\circ G(\af_\alpha^\delta) - \mI_1^{\delta}}_{L_2(\Omega)} = \mathcal{O}\kl{\delta_{\mI_1}} \,.
    \end{equation*}
\end{theorem}
\begin{proof}
Due to Proposition~\ref{prop_differentiability}, all assumptions of the classic convergence rate analysis for nonlinear Tikhonov regularization (see, e.g., \cite[Theorem~10.4]{Engl_Hanke_Neubauer_1996}) are satisfied, which thus yields the assertion.
\end{proof}


% Convergence analysis II: full noise case
\subsection{Convergence analysis II: full noise case}

Next, we consider the full noise case \eqref{def_Tad_full}, for which we require some additional noise assumptions.

\begin{assumption}[Additional noise assumptions for the IIM in the full noise case] \label{ass_noise} \hfill
\begin{enumerate}
    \item There is a function $\xi \in L_\infty(\Omega_2)$ and a noise level $\delta_{\mI_2} > 0$ such that
        \begin{equation}\label{cond_noise_I1}
            \mI_2^\delta = \mI_2 + \delta_{\mI_2} \xi \,, \qquad \text{where} \qquad \norm{\xi}_{L_\infty(\Omega_2)} \leq 1 \,.
        \end{equation}
    % 
    \item There is a noise level $\delta_G > 0$ such that
        \begin{equation}\label{cond_noise_model}
            \sup_{\af \in \mathcal{M} \cap B_\eps(\af^*)} \norm{\uf(\cdot,\af) - \uf^\delta(\cdot, \af)}_{L_2(\Omega)} 
            = 
            \sup_{\af \in \mathcal{M}  \cap B_\eps(\af^*)} \norm{G(\af) - G^\delta(\af)}_{L_2(\Omega)}
            \leq \delta_G \,.
        \end{equation}
    %
    \item There is a noise level $\Bar{\delta} > 0$ such that for all $\delta \leq \Bar{\delta}$ there holds
        \begin{equation}\label{cond_noise_domain}
            \forall \, \af \in \mathcal{M} \cap B_\eps(\af^*) \,\, \forall \, \x \in \Omega \, : \, G^\delta(\af)(\x) \in \Omega_2 \,.
    \end{equation}
\end{enumerate}
\end{assumption}

\begin{remark}
Note that \eqref{cond_noise_domain} is mainly a technical assumption, which is only required to guarantee that the noisy operator $F^\delta(\af) := \mI_2^\delta \circ G^\delta(\af)$ is well defined for sufficiently small noise levels $\delta$. One way to guarantee it is to assume that the noise-free operator $G(\af)$ maps $\Omega$ only onto a subset $\Tilde{\Omega}_2 \subset \Omega_2$ with $\operatorname{dist}(\Tilde{\Omega}_2,\partial \Omega_2) > 0$. Then, if in \eqref{cond_noise_model} the $L_2$ norm is replaced by the $L_\infty$ norm, \eqref{cond_noise_domain} is satisfied with
    \begin{equation*}
        \Bar{\delta} = \operatorname{dist}(\tilde{\Omega}_2,\partial \Omega_2) / \delta_G \,.
    \end{equation*}
\end{remark}

Using the noise Assumption~\ref{ass_noise}, we now derive a noise bound for $\F^\delta$ in the following proposition.

\begin{proposition}\label{prop_noise}
Let Assumption~\ref{ass_minimal}, \ref{ass_model_minimal}, and \ref{ass_noise} hold. Then, for $\F$ and $\F^\delta$ defined in \eqref{def_F} and \eqref{def_Fd}, respectively, and with $\delta_\F = \delta_\F(\delta_{\mI_2},\delta_G) := \delta_{\mI_2} \abs{\Omega} +´C_L \delta_G$ there holds
    \begin{equation*}
        \sup_{\af \in \mathcal{M} \cap B_\eps(\af^*)} \norm{\F(\af) - \F^\delta(\af)}_{L_2(\Omega)} \leq \delta_\F  \,.
    \end{equation*}
\end{proposition}
\begin{proof}
First, we use the definitions of $\F$ and $\F^\delta$ as well as \eqref{cond_noise_I1} to obtain
    \begin{equation*}
    \begin{split}
        \norm{\F(\af) - \F^\delta(\af)}_{L_2(\Omega)} 
        &=
        \norm{\mI_2 \circ G(\af) - \mI_2^\delta \circ G^\delta(\af)}_{L_2(\Omega)} 
        \overset{\eqref{cond_noise_I1}}{=} 
        \norm{\mI_2 \circ G(\af) - (\mI_2 + \delta_{\mI_2} \xi) \circ G^\delta(\af)}_{L_2(\Omega)} 
        \\
        &\leq
        \norm{\mI_2 \circ G(\af) - \mI_2 \circ G^\delta(\af)}_{L_2(\Omega)} + \delta_{\mI_2} \norm{\xi \circ G^\delta(\af)}_{L_2(\Omega)} \,. 
    \end{split}
    \end{equation*}
Hence, using the Lipschitz estimate \eqref{Lipschitz_I1} as well as $\norm{\xi}_{L_\infty(\Omega_2)} \leq 1$ from \eqref{cond_noise_I1}, we find that
    \begin{equation*}
        \norm{\F(\af) - \F^\delta(\af)}_{L_2(\Omega)} 
        \leq
        C_L \norm{G(\af) - G^\delta(\af)}_{L_2(\Omega)} + \delta_{\mI_2} \abs{\Omega} \,, 
    \end{equation*}
which after taking the supremum over $\af \in \mathcal{M} \cap B_\eps(\af^*)$ and using \eqref{cond_noise_model} now yields the assertion.   
\end{proof}


With this estimate, we can now derive the following convergence result in the full noise case \eqref{def_Tad_full}.

\begin{theorem}\label{theorem_convergence}
Let Assumption~\ref{ass_minimal}, \ref{ass_model_minimal}, \ref{ass_differentiability}, and \ref{ass_noise} hold, and define $\boldsymbol{\delta} := (\delta_{\mI_1},\delta_{\mI_2},\delta_G)$. Furthermore, let $\alpha = \alpha(\boldsymbol{\delta})$ be chosen such that for $\boldsymbol{\delta} \to 0$ there holds
    \begin{equation*}
        \alpha(\boldsymbol{\delta}) \to 0 \,,
        \qquad
        \frac{(\delta_{\mI_1})^2}{\alpha(\boldsymbol{\delta})} \to 0 \,,
        \qquad
        \text{and}
        \qquad
        %\frac{(\delta_\F)^2}{\alpha} = \frac{(\delta_{\mI_1} \abs{\Omega} + C_L \delta_G)^2}{\alpha(\boldsymbol{\delta})} 
        \frac{(\delta_{\mI_2} + \delta_G)^2}{\alpha(\boldsymbol{\delta})} \to 0 \,.
    \end{equation*}
Then every sequence $\Kl{\af_k := \af_{\alpha(\boldsymbol{\delta}_k)}^{\boldsymbol{\delta}_k}}_{k\in\N}$ with $\boldsymbol{\delta}_k \to 0$ as $k\to \infty$, and where $\af_k$ is a minimizer of \eqref{def_Tad_full} has a convergent subsequence $\boldsymbol{a}_{n_k}$. Furthermore, the limit of every convergent subsequence is an $\af_0$ minimum norm solution. Moreover, if the $\af_0$ minimum norm solution $\af^\dagger$ is unique, then
    \begin{equation*}
        \lim\limits_{\boldsymbol{\delta}_k \to 0} \af_{\alpha(\boldsymbol{\delta}_k)}^{\boldsymbol{\delta}_k} = \af^\dagger\,.
    \end{equation*}
\end{theorem}
\begin{proof}
Due to Proposition~\ref{prop_differentiability} and \ref{prop_noise}, all assumptions of \cite[Theorem~2.1]{Neubauer_Scherzer_1990} are satisfied, which yields the assertion. Note that while \cite{Neubauer_Scherzer_1990} considers finite-dimensional approximations of Tikhonov functionals, the results and proofs themselves also apply in our infinite dimensional setting with noisy operator.    
\end{proof}

Finally, we also obtain the following convergence rate results in the full noise case \eqref{def_Tad_full}.

\begin{theorem}\label{theorem_rates}
Let Assumption~\ref{ass_minimal}, \ref{ass_model_minimal}, \ref{ass_differentiability}, and \ref{ass_noise} hold, and assume that there is a $w \in L_2(\Omega)$ with
    \begin{equation*}
        \af^\dagger - \af_0 = \mathcal{F}'(\af^\dagger)^*w \,,
        \qquad \text{and} \qquad
        C \norm{w} < 1 \,,
    \end{equation*}
where $C$ is as in Proposition~\ref{prop_differentiability}. Furthermore, assume that $\mathcal{O}(\delta_{\mI_2} + \delta_G) = \mathcal{O}(\delta_{\mI_1})$. Then for $\alpha \sim \delta_{\mI_1}$, a minimizer $\af_\alpha^\delta$ of \eqref{def_Tad_full} satisfies
    \begin{equation*}
        \norm{\af_\alpha^\delta - \af^\dagger}_{X} = \mathcal{O}\kl{\sqrt{\delta_{\mI_1}}} \,.
        %\qquad \text{and} \qquad 
        %\norm{\mI_1\circ G(\af_\alpha^\delta) - \mI_2}_{L_2(\Omega)} = \mathcal{O}\kl{\delta_{\mI_2}} \,.
    \end{equation*}
\end{theorem}
\begin{proof}
Due to Proposition~\ref{prop_differentiability} and \ref{prop_noise}, the assertion follows from \cite[Theorem~2.3(a)]{Neubauer_Scherzer_1990}.
\end{proof}







