The linear elasticity model \eqref{linear_elastic} is commonly used in elastography for uniformly isotropic material samples under the assumption of small deformations (infinitesimal strain). The Lam\'e parameters $\lambda,\mu$ can be directly related to the Young's modulus $E$ and the Poison ratio $\nu$, which have physical or diagnostic value, depending on the application \cite{ZaiMatMatSovHepMowKen21,Singh_Hepburn_Kennedy_Larin_2025}. Our motivation for considering this linear elastic model are quasi-static optical coherence elastography (OCE) experiments such as those conducted in \cite{Krainz_Sherina_Hubmer_Liu_Drexler_Scherzer_2022} and schematically depicted in Figure~\ref{fig_schematic}. There, a rectangular sample is fixed from below and uniformly compressed from above, while the sides of the sample are left to move freely. This corresponds to uniform displacement boundary conditions on the top ($\gfD = \text{const.}$) and bottom ($\gfD = 0$) of the sample, traction free boundary conditions ($\gfT = 0$) on the sides, and no body forces ($\ff = 0$). A set of volumetric OCT scans is acquired both before and after compression, which could already be used as the images $\mI_1^\delta, \mI_2^\delta$ for the IIM. However, due to the symmetry of the samples considered in \cite{Krainz_Sherina_Hubmer_Liu_Drexler_Scherzer_2022}, the OCT scans are first reduced to 2D maximum intensity projections, which has some practical benefits.

In order to apply our theoretical results on the IIM to the linear elastic setting \eqref{linear_elastic}, we have to ensure that \eqref{linear_elastic} has a unique (weak) solution $\uf$ for each parameter $\af = (\lambda,\mu)$ in the admissible set %$\Msm$, defined by
    \begin{equation}\label{def_Msm}
        \Msm := \Kl{ (\lambda,\mu) \in H^s(\Omega_1)^2 \, \vert \, \lambda \geq 0 \,, \mu > \mub > 0 } \subset X := H^s(\Omega_1)^2 \,,
    \end{equation}
where $0 < \mub \in \R$ and $N/2 < s \in \N$, with $N$ being the dimension of the domain $\Omega_1$. For this, we need

\begin{assumption}\label{ass_linear_elastic}
The domain $\Omega_1 \subset \R^N$, $N \in \N$, is nonempty, bounded, open, and connected, with a Lipschitz continuous boundary $\partial \Omega_1$, which has two subsets $\Gamma_D$ and $\Gamma_T$, satisfying $\partial \Omega_1 = \overline{\Gamma_D \cup \Gamma_T}$, $\Gamma_D \cap \Gamma_T = \emptyset$, and $\operatorname{meas}(\Gamma_D) > 0$. Furthermore, $\ff \in H^{-1}(\Omega_1)^{N}$, $\gfD \in H^{\frac{1}{2}}(\Gamma_D)^N$, $\gfT \in H^{-\frac{1}{2}}(\Gamma_T)^N$, and there is a function $\Phi \in H^1(\Omega_1)^N$ such that $\Phi \vert_{\Gamma_D} = \gfD$.
\end{assumption}

Following \cite{Hubmer_Sherina_Kindermann_Raik_2022}, we now homogenize \eqref{linear_elastic} and seek $\uft := \uf - \Phi$ satisfying the homogenized equations
    \begin{equation}\label{linear_elastic_homo}
    \begin{alignedat}{3}
        -\operatorname{div}{\sigma_{\lambda,\mu}(\uft)} & = \ff + \operatorname{div}{\sigma_{\lambda,\mu}(\Phi)} \,, \qquad &&\text{in} \quad \Omega_1 \,, 
        \\ 
        \uft & = 0 \,, \qquad &&\text{on} \quad \Gamma_D  \,,
        \\
        \sigma_{\lambda,\mu}(\uft) \nv &= \gfT - \sigma(\Phi) \nv \,,  \qquad &&\text{on} \quad \Gamma_T \,.
    \end{alignedat}
    \end{equation}
Introducing the bilinear and linear forms
    \begin{equation*}
    \begin{split}
        a_{\lambda,\mu}(\uft,\vf) &:= \int_{\Omega_1} \kl{\lambda \operatorname{div}(\uft) \operatorname{div}(\vf) + 2 \mu \mathcal{E}(\uft):\mathcal{E}(\vf)} \, dx \,,
        \\
        l(\vf) &:= \spr{\ff,\vf}_{H^{-1}(\Omega_1),H^1(\Omega_1)} + \spr{\gfT,\vf}_{H^{-\frac{1}{2}}(\Gamma_T),H^{\frac{1}{2}}(\Gamma_T)} \,,
    \end{split}
    \end{equation*}
it follows that the weak form of the homogenized BVP \eqref{linear_elastic_homo} is given by
    \begin{equation}\label{a=l}
        a_{\lambda,\mu}(\uft,\vf) = l(\vf) - a_{\lambda,\mu}(\Phi,\vf) \,,  
        \qquad
        \forall \, \vf \in V \,,
    \end{equation}
where
    \begin{equation*}
        V:= H_{0,\Gamma_D}^1(\Omega_1)^N \,,
        \qquad
        \text{with}
        \qquad
        H_{0,\Gamma_D}^1(\Omega_1)^N := \Kl{\vf \in H^{1}(\Omega_1) \, \vert \, \vf \vert_{\Gamma_D} = 0} \,.
    \end{equation*}
Concerning the solvability of the variational problem, \eqref{a=l}, we have the following result.

\begin{lemma}\label{lem_existence}
Let Assumption~\ref{ass_linear_elastic} hold and assume that $(\lambda,\mu) \in \Msm \subset X = H^s(\Omega_1)^2$ for some $\mub > 0$ and $s > N/2$. Then there exists a unique solution $\uft \in V$ of \eqref{a=l} and a constant $C > 0$ satisfying
    \begin{equation}\label{uft_bound}
        \norm{\uft}_{H^1(\Omega_1)} 
        \leq
        C \kl{ \norm{\ff}_{H^{-1}(\Omega_1)} + \norm{\gfT}_{H^{-\frac{1}{2}}(\Gamma_T)} 
        + \norm{(\lambda,\mu)}_X \norm{\Phi}_{H^1(\Omega_1)} } \,.
    \end{equation}
\end{lemma}
\begin{proof}
First, note that since $s > N/2$, there exists a constant $c^s_E > 0$ such that \cite{Adams_1970}
    \begin{equation}\label{embedding_inequality}
        \norm{\vf}_{L_\infty(\Omega_1)} \leq c^s_E \norm{\vf}_{H^s(\Omega_1)} \,,
        \qquad \forall \, \vf \in H^s(\Omega_1) \,.
    \end{equation}  
Hence, we have that $\Msm \subset H^s(\Omega_1)^2 \subset L_\infty(\Omega_1)^2$, and thus it follows from \cite[Theorem~2.1]{Hubmer_Sherina_Neubauer_Scherzer_2018} that for any $(\lambda,\mu) \in \Msm$ there exists a unique solution $\uft \in V$ of \eqref{a=l} and a constant $c_{\text{LM}} > 0$ satisfying
    \begin{equation*}
        \norm{\uft}_{H^1(\Omega_1)} 
        \leq
        c_{\text{LM}} \kl{ \norm{\ff}_{H^{-1}(\Omega_1)} + c_T \norm{\gfT}_{H^{-\frac{1}{2}}(\Gamma_T)} + \kl{N\norm{\lambda}_{L_\infty(\Omega_1)} + 2 \norm{\mu}_{L_\infty(\Omega_1)} } \norm{\Phi}_{H^1(\Omega_1)} }
    \end{equation*}
where $c_T$ denotes the constant of the trace inequality. Together with \eqref{embedding_inequality}, this yields the assertion.
\end{proof}

Hence, we have that $\uf = \uft + \Phi \in H^1(\Omega_1)^N$ is well-defined for each $(\lambda,\mu) \in \Msm$, and thus Part~4 of the minimal Assumption~\ref{ass_minimal} is satisfied. Concerning Assumption~\ref{ass_model_minimal}, we have the following result.

\begin{proposition}\label{prop_uft_continuous}
Let Assumption~\ref{ass_linear_elastic} hold and assume that $(\lambda,\mu) \in \Msm$ for some $\mub > 0$ and $s > N/2$. Then $\uft = \uft(\lambda,\mu) \in V$ defined by \eqref{a=l} is continuous wrt.\ $(\lambda,\mu)$, and there is a $C_{\lambda,\mu} > 0$ with
    \begin{equation}\label{uft_continuous}
        \norm{\uft(\lambda,\mu) - \uft(\bar{\lambda},\bar{\mu}) }_V \leq C_{\lambda,\mu} \norm{(\lambda,\mu) - (\bar{\lambda},\bar{\mu})}_X \,,
        \qquad 
        \forall \, (\bar{\lambda},\bar{\mu}) \in \Msm \,. 
    \end{equation}
Furthermore, $\uft$ considered a mapping $\uft: \Msm \to V \,, (\lambda,\mu) \mapsto \uft(\lambda,\mu)$ is weakly sequentially closed.
\end{proposition}
\begin{proof}
First, note that due to \cite[Equation~(3.11)]{Hubmer_Sherina_Neubauer_Scherzer_2018}, there exists a constant $C > 0$ such that
    \begin{equation*}
        \norm{\uft(\lambda,\mu) - \uft(\bar{\lambda},\bar{\mu})}_V \leq C \norm{(\lambda,\mu) - (\bar{\lambda},\bar{\mu})}_{L_\infty(\Omega_1)} \kl{ \norm{\uft(\lambda,\mu)}_{H^1(\Omega_1)} + \norm{\Phi}_{H^1(\Omega_1)}  } \,.
    \end{equation*}
Hence, together with \eqref{embedding_inequality} and $X = H^s(\Omega_1)^2$, this yields \eqref{uft_continuous} and thus the continuity of $\uft$. Furthermore, since the embedding \eqref{embedding_inequality} is compact \cite{Adams_1970}, we have that $\uft: \Msm \to V$ is weakly sequentially closed.
\end{proof}

The above results also transfer to the non-homogenized solution $\uf = \uft + \Phi \in H^1(\Omega_1)^N$. In particular, $\uf$ is continuous, weakly sequentially closed, and with $C_{\lambda,\mu}$ as in Proposition~\ref{prop_uft_continuous} there holds
    \begin{equation}\label{helper_uf_01}
        \norm{\uft(\lambda,\mu) - \uft(\bar{\lambda},\bar{\mu}) }_V \leq C_{\lambda,\mu} \norm{(\lambda,\mu) - (\bar{\lambda},\bar{\mu})}_X \,,
        \qquad 
        \forall \, (\bar{\lambda},\bar{\mu}) \in \Msm \,. 
    \end{equation}
Hence, together with $\Omega \subset \Omega_1$ and $L_2(\Omega_1) \subset V$, we find that \eqref{Lipschitz_u} in Part~2 of Assumption~\ref{ass_differentiability} is satisfied. Furthermore, if $\mI_1$ is continuous, then also Part~1 of Assumption~\ref{ass_model_minimal} holds. This now allows us to transfer the convergence result of Theorem~\ref{theorem_convergence_restricted} to our linear elasticity setting.

\begin{theorem}\label{theorem_convergence_elastic}
Let Assumption~\ref{ass_linear_elastic} hold, and let $0 < \mub \in \R$ and $N/2 < s \in \N$. In addition, assume that the domains $\Omega\,, \Omega_2 \subset \R^N$ are open and bounded with a Lipschitz continuous boundary and that
    \begin{equation}\label{cond_domain_elasticity}
        \forall \, (\lambda,\mu) \in \Msm \,, \forall \, x \in \Omega \, : \, \uf(\lambda,\mu) = \uft(\lambda,\mu) + \Phi \in \Omega_2 \,,
    \end{equation}
where $\uft$ is determined by \eqref{a=l}. Furthermore, let $\mI_1 \in L_2(\Omega_2)$, $\mI_2 \in C(\Omega_1)$, $(\lambda_0,\mu_0) \in \Msm$, assume that there exists an $(\lambda_0,\mu_0)$-MNS $(\lambda^*,\mu^*)$ of the equation $\mI_2 \circ G(\lambda,\mu) = \mI_1$, and that there is a noise level $\delta_{\mI_1} > 0$ such that $\Vert \mI_1 - \mI_1^\delta\Vert \leq \delta_{\mI_1}$ for $\mI_1^\delta \in L_2(\Omega_1)$. Moreover, let $\alpha = \alpha(\delta_{\mI_1})$ be chosen such that
    \begin{equation*}
        \alpha(\delta_{\mI_1}) \to 0 \,,
        \qquad
        \text{and}
        \qquad
        \frac{(\delta_{\mI_1})^2}{\alpha(\delta_{\mI_1})} \to 0 \,,
        \qquad
        \qquad
        \text{for}
        \qquad
        \delta_{\mI_1}\to 0 \,.
    \end{equation*}
Then every sequence $\Kl{(\lambda_k,\mu_k) := (\lambda_{\alpha(\delta_k)}^{\delta_k},\mu_{\alpha(\delta_k)}^{\delta_k})}_{k\in\N}$ where $\kl{\lambda_{\alpha(\delta_k)}^{\delta_k},\mu_{\alpha(\delta_k)}^{\delta_k}}$ is a minimizer of 
    \begin{equation*}
        \norm{\mI_2\circ G(\lambda,\mu) - \mI_1^\delta}_{L_2(\Omega)}^2 + \alpha \norm{(\lambda,\mu) - (\lambda_0,\mu_0)}_{H^s(\Omega_1)}^2 \,,
    \end{equation*}
and with $\delta_k \to 0$ as $k\to \infty$, has a convergent subsequence $(\lambda_{n_k},\mu_{n_k})$. Furthermore, the limit of every convergent subsequence is an $(\lambda_0,\mu_0)$-MNS. Moreover, if the $(\lambda_0,\mu_0)$-MNS $(\lambda^\dagger,\mu^\dagger)$ is unique, then
    \begin{equation*}
        \lim\limits_{\delta_k \to 0} \kl{\lambda_{\alpha(\delta_k)}^{\delta_k},\mu_{\alpha(\delta_k)}^{\delta_k}} = (\lambda^\dagger,\mu^\dagger)\,.
    \end{equation*}
\end{theorem}
\begin{proof}
Due to Lemma~\ref{lem_existence} and Proposition~\ref{prop_uft_continuous}, Theorem~\ref{theorem_convergence_restricted} is applicable and yields the assertion.    
\end{proof}

In order to establish convergence rates in our linear elasticity setting, we have to show the Fr\'echet differentiability of $\uft$ as well as the bounds \eqref{Lipschitz_u_infty} and \eqref{Lipschitz_Du}. For this, we first consider the following result.

\begin{proposition}\label{prop_uft_Frechet}
Let Assumption~\ref{ass_linear_elastic} hold, and let $\mub > 0$ and $s > N/2$. Then $\uft = \uft(\lambda,\mu) \in V$ defined by \eqref{a=l} and considered as a mapping from $\Msm \to V$ is continuously Fr\'echet differentiable for all $(\lambda,\mu) \in \Msm$. Furthermore, $\uft'(\lambda,\mu)(h_\lambda,h_\mu)$ is characterized as the unique solution $\zf \in V$ of 
    \begin{equation}\label{a=l_diff}
        a_{\lambda,\mu}(\zf,\vf) = -a_{h_\lambda,h_\mu}(\uft(\lambda,\mu) + \Phi,\vf) \,,
        \qquad \forall \, \vf \in V\,.
    \end{equation}
Moreover, for each $(\lambda,\mu) \in \Msm$ there exists a $C_{\lambda,\mu} > 0$ such that for all $(\bar{\lambda},\bar{\mu}) \in \Msm$ there holds
    \begin{equation*}
        \norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu) - \uft'(\bar{\lambda},\bar{\mu})(h_\lambda,h_\mu) }_V 
        \leq C_{\lambda,\mu} \norm{(h_\lambda,h_\mu)}_X \norm{(\lambda,\mu) - (\bar{\lambda},\bar{\mu})}_X \,.
    \end{equation*}
\end{proposition}
\begin{proof}
The continuous Fr\'echet differentiability of $\uft$ and the characterization \eqref{a=l_diff} follows directly from \cite[Theorem~3.2]{Hubmer_Sherina_Neubauer_Scherzer_2018}. There, the variational form \eqref{a=l_diff} is expressed in the equivalent form
    \begin{equation*}
        \uft'(\lambda,\mu)(h_\lambda,h_\mu) = - A_{\lambda,\mu}^{-1} \kl{ A_{h_\lambda,h_\mu} \uft(\lambda,\mu) + \tilde{A}_{h_\lambda,h_\mu} \Phi  } \,,
    \end{equation*}
where $A_{\lambda,\mu}:= \tilde{A}_{\lambda,\mu}\vert_V$ and the bounded linear operator $\tilde{A}_{\lambda,\mu}$ is defined by
    \begin{equation*}
        \tilde{A}_{\lambda,\mu} \, : \, H^1(\Omega_1)^N \to V^* \,,
        \qquad 
        \vf \mapsto \kl{ \bar{\vf} \mapsto a_{\lambda,\mu}(\vf,\bar{\vf}) } \,.
    \end{equation*}
Using this equivalent representation, we find that for each $(\bar{\lambda},\bar{\mu}) \in \Msm $ there holds
    \begin{equation*}
        \uft'(\lambda,\mu)(h_\lambda,h_\mu) - \uft'(\bar{\lambda},\bar{\mu})(h_\lambda,h_\mu)  = - A_{\lambda,\mu}^{-1}  \kl{ A_{h_\lambda,h_\mu} \kl{ \uft(\lambda,\mu) -   \uft(\bar{\lambda},\bar{\mu}) } }  \,.
    \end{equation*}
Furthermore, due to \cite[Proposition~3.1]{Hubmer_Sherina_Neubauer_Scherzer_2018}, there exists constants $C_1,C_2 > 0$ such that
    \begin{equation*}
        \norm{A_{\lambda,\mu}^{-1}}_{V^*,V} \leq C_1 \,,
        \qquad \text{and} \qquad
        \norm{A_{\lambda,\mu}}_{V,V^*} \leq C_2 \norm{(\lambda,\mu)}_{L_\infty(\Omega_1)} \leq C_2 c_E^s \norm{(\lambda,\mu)}_X \,,
    \end{equation*}
and thus we obtain
    \begin{equation*}
    \begin{split}
        \norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu) - \uft'(\bar{\lambda},\bar{\mu})(h_\lambda,h_\mu) }_V 
        &= \norm{ A_{\lambda,\mu}^{-1}  \kl{ A_{h_\lambda,h_\mu} \kl{ \uft(\lambda,\mu) -   \uft(\bar{\lambda},\bar{\mu}) } } }_V
        \\
        & \leq
        C_1 C_2 c_E^s \norm{(h_\lambda,h_\mu)}_X \norm{ \uft(\lambda,\mu) -   \uft(\bar{\lambda},\bar{\mu}) }_V\,,
    \end{split}
    \end{equation*}
which together with \eqref{uft_continuous} now yields the assertion.    
\end{proof}

Again, the above results transfer to the non-homogenized solution $\uf = \uft + \Phi \in H^1(\Omega_1)^N$. In particular, $\uf$ is continuously Fr\'echer differentiable with $\uf'(\lambda,\mu)(h_\lambda,h_\mu) = \uft'(\lambda,\mu)(h_\lambda,h_\mu)$, and
    \begin{equation}\label{helper_uf_02}
        \norm{\uf'(\lambda,\mu)(h_\lambda,h_\mu) - \uf'(\bar{\lambda},\bar{\mu})(h_\lambda,h_\mu) }_V 
        \leq C_{\lambda,\mu} \norm{(h_\lambda,h_\mu)}_X \norm{(\lambda,\mu) - (\bar{\lambda},\bar{\mu})}_X \,, 
    \end{equation}
for $C_{\lambda,\mu}$ as in Proposition~\ref{prop_uft_Frechet} and every $(\bar{\lambda},\bar{\mu}) \in \Msm$. Hence, together with $\Omega \subset \Omega_1$ and $L_2(\Omega_1) \subset V$, we find that condition \eqref{Lipschitz_Du} in Part~2 of Assumption~\ref{ass_differentiability} is satisfied for our linear elastic setting as well.

In order to establish the remaining condition \eqref{Lipschitz_u_infty}, note that \eqref{a=l_diff} is the weak form of the BVP
    \begin{equation}\label{BVP_diff}
    \begin{alignedat}{3}
        -\operatorname{div}\kl{\sigma_{\lambda,\mu}(\zf)} & = \operatorname{div}\kl{\sigma_{h_\lambda,h_\mu}(\uft(\lambda,\mu) + \Phi)} \,, \qquad &&\text{in} \quad \Omega_1 
        \\ 
        \zf & = 0 \,, \qquad &&\text{on} \quad \Gamma_D  \,,
        \\
        \sigma_{\lambda,\mu}(\zf) \nv &= -\sigma_{h_\lambda,h_\mu}(\uf(\lambda,\mu)+\Phi) \nv \,,  \qquad &&\text{on} \quad \Gamma_T \,.
    \end{alignedat}    
    \end{equation}
Hence, \eqref{Lipschitz_u_infty} amounts to an interior $L_\infty$-estimate of the weak solution of the above BVP. However, in order to apply standard regularity results for elliptic PDEs \cite{Gilbarg_Trudinger_1998,Necas_2011,McLean_2000}, we first have to ensure that the right hand side in \eqref{BVP_diff}, and thus $\uf(\lambda,\mu)$ is sufficiently regular. For this, we have the following result.

\begin{lemma}\label{lem_regularity}
Let Assumption~\ref{ass_linear_elastic} hold, let $s > N/2 + 1$, $\mub > 0$, $(\lambda,\mu) \in \Msm$, and assume that $\ff \in L_2(\Omega_1)^{N}$, $\gfD \in H^{\frac{3}{2}}(\Gamma_D)^N$, $\Phi \in H^2(\Omega_1)^N$. Then for every bounded, open, connected Lipschitz domain $\Omega_2 \subset \Omega_1$ with $\overline{\Omega_2} \Subset \Omega_1$ the unique solution $\uft(\lambda,\mu)$ of \eqref{a=l} satisfies $\uft\vert_{\Omega_2} \in H^2(\Omega_2)^N$ and $-\operatorname{div}(\sigma_{\lambda,\mu}(\uft)) = f$ pointwise a.e.\ in $\Omega_2$. Furthermore, there is a $c_R = c_R(\lambda,\mu,\Omega_1,\Omega_2) > 0$ such that
    \begin{equation}\label{uft_H2}
        \norm{\uft}_{H^2(\Omega_2)} \leq c_R \kl{\norm{\uft}_{H^1(\Omega_1)} + \norm{\ff}_{L_2(\Omega_1)}} \,. 
    \end{equation}
\end{lemma}
\begin{proof}
This follows directly from \cite[Theorem~4.16]{McLean_2000} observing the regularity of $(\lambda,\mu) \in \Msm$.
\end{proof}

With these preliminaries, we can now establish the following regularity result for $\uft'(\lambda,\mu)$.

\begin{proposition}\label{prop_uft_D_H2}
Let the assumptions of Lemma~\ref{lem_regularity} hold and assume that there exists a bounded, open, connected Lipschitz domain $\Omega' \subset \Omega_1$ with $\overline{\Omega} \Subset \Omega'$ and $\overline{\Omega'} \Subset \Omega_1$. Then the unique solution $\zf = \uft'(\lambda,\mu)(h_\lambda,h_\mu)$ of \eqref{a=l_diff} satisfies $\zf\vert_{\Omega} \in H^2(\Omega)^N$ and $-\operatorname{div}(\sigma_{\lambda,\mu}(\uft)) = \operatorname{div}\kl{\sigma_{h_\lambda,h_\mu}(\uft(\lambda,\mu) + \Phi)}$ pointwise a.e.\ in $\Omega$. Furthermore, there is a constant $c_R' = c_R'(\lambda,\mu,N,s,\Omega,\Omega',\Omega_1) > 0$ such that
    \begin{equation}\label{uft_D_H2}
    \begin{split}
        &\norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{H^2(\Omega)} 
        \\
        & \qquad
        \leq c_R' \norm{(h_\lambda,h_\mu)}_{W^{1,\infty}(\Omega_1)} 
        \kl{
        \norm{\ff}_{L_2(\Omega_1)}  + \norm{\gfT}_{H^{-\frac{1}{2}}(\Gamma_T)} + \kl{1 + \norm{(\lambda,\mu)}_{L_\infty(\Omega_1)} }\norm{\Phi}_{H^2(\Omega_1)} }\,.
    \end{split}    
    \end{equation} 
\end{proposition}
\begin{proof}
First, note that due to Lemma~\ref{lem_regularity} there holds $\uft(\lambda,\mu)\vert_{\Omega'} \in H^2(\Omega')^N$. Furthermore, we have
    \begin{equation}\label{helper_z_02}
        \norm{\operatorname{div}\kl{\sigma_{h_\lambda,h_\mu}(\uft(\lambda,\mu) + \Phi)}}_{L_2(\Omega')}  
        \leq 
        c_G \max\Kl{\norm{h_\lambda}_{W^{1,\infty}(\Omega')},\norm{h_\mu}_{W^{1,\infty}(\Omega')}} \norm{\uft(\lambda,\mu) + \Phi}_{H^2(\Omega')} \,,
    \end{equation} 
for some $c_G = c_G(N)$, which is finite since $(h_\lambda,h_\mu)\in\Msm \subset W^{1,\infty}(\Omega_1)$ for $s > N/2 +1$. Next, we want to apply \cite[Theorem~4.16]{McLean_2000} to obtain the $H^2(\Omega)$ regularity of $\zf := \uft'(\lambda,\mu)(h_\lambda,h_\mu)$. For this, it is formally required that $\ff_1 := \operatorname{div}\kl{\sigma_{h_\lambda,h_\mu}(\uft(\lambda,\mu) + \Phi)} \in L_2(\Omega_1)$. However, a close inspection of the proof shows that $\ff_1 \in L_2(\Omega')$ is sufficient (cf.~also \cite{Necas_2011,Gilbarg_Trudinger_1998,Evans_1998}), and we obtain that $\zf\vert_{\Omega} \in H^2(\Omega)^N$ with
    \begin{equation}\label{helper_z_01}
        \norm{\zf}_{H^2(\Omega)} = \norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{H^2(\Omega)} \leq \tilde{c}_R \kl{\norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{H^1(\Omega_1)} + \norm{\ff_1}_{L_2(\Omega')}} \,. 
    \end{equation}
for some constant $\tilde{c}_R = \tilde{c}_R(\lambda,\mu,\Omega,\Omega_1,\Omega_2)$. Furthermore, as in the proof of Proposition~\ref{prop_uft_Frechet}, we obtain
    \begin{equation*}
    \begin{split}
        \norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{H^1(\Omega_1)}
        &\leq 
        C \norm{(h_\lambda,h_\mu)}_{L_\infty(\Omega_1)} \norm{\uft(\lambda,\mu) + \Phi}_V 
        \\
        &\leq
        C \norm{(h_\lambda,h_\mu)}_{L_\infty(\Omega_1)} \kl{\norm{\uft(\lambda,\mu)}_{H^1(\Omega_1)} + \norm{\Phi}_{H^1(\Omega_1)} }
        \,.
    \end{split}
    \end{equation*}
for some constant $C = C(s)$. Combining this with \eqref{helper_z_01} and \eqref{helper_z_02}, we thus find that
    \begin{equation*}
    \begin{split}
        &\norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{H^2(\Omega)} \leq  
        \tilde{c}_R \kl{\norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{H^1(\Omega_1)} + \norm{\ff_1}_{L_2(\Omega')}}
        \\
        &\qquad\leq
        \tilde{c}_R \Big( C \norm{(h_\lambda,h_\mu)}_{L_\infty(\Omega_1)} \kl{\norm{\uft(\lambda,\mu)}_{H^1(\Omega_1)} + \norm{\Phi}_{H^1(\Omega_1)} }   
        \\
        & \qquad\qquad\qquad +
        c_G \max\Kl{\norm{h_\lambda}_{W^{1,\infty}(\Omega')},\norm{h_\mu}_{W^{1,\infty}(\Omega')}} \norm{\uft(\lambda,\mu) + \Phi}_{H^2(\Omega')}      
        \Big) 
        \\
        & \qquad
        \leq \tilde{c}_R (C+2c_G) \norm{(h_\lambda,h_\mu)}_{W^{1,\infty}(\Omega_1)} \kl{\norm{\uft(\lambda,\mu)}_{H^1(\Omega_1)} + \norm{\uft(\lambda,\mu)}_{H^2(\Omega')} + 2 \norm{\Phi}_{H^2(\Omega_1)} } \,,
    \end{split}    
    \end{equation*}
which together with \eqref{uft_H2} yields
    \begin{equation*}
    \begin{split}
        &\norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{H^2(\Omega)} 
        \\
        & \qquad
        \leq \tilde{c}_R (C+2c_G) \norm{(h_\lambda,h_\mu)}_{W^{1,\infty}(\Omega_1)} \kl{(1+c_R)\norm{\uft(\lambda,\mu)}_{H^1(\Omega_1)} + c_R \norm{\ff}_{L_2(\Omega_1)}  + 2 \norm{\Phi}_{H^2(\Omega_1)} } \,,
    \end{split}    
    \end{equation*}    
Finally, using \eqref{uft_bound} we obtain
    \begin{equation*}
    \begin{split}
        &\norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{H^2(\Omega)} 
        \leq \tilde{c}_R (C+2c_G) \norm{(h_\lambda,h_\mu)}_{W^{1,\infty}(\Omega_1)} 
        \Big( 
        c_R \norm{\ff}_{L_2(\Omega_1)}  + 2 \norm{\Phi}_{H^2(\Omega_1)}
        \\
        & \quad
        + (1+c_R)C \kl{ \norm{\ff}_{H^{-1}(\Omega_1)} + \norm{\gfT}_{H^{-\frac{1}{2}}(\Gamma_T)} 
        + \norm{(\lambda,\mu)}_{L_\infty(\Omega_1)} \norm{\Phi}_{H^1(\Omega_1)} } \Big) \,,
    \end{split}    
    \end{equation*}   
which after rearranging the terms now yields the assertion.
\end{proof}

Using the above interior regularity result, we obtain the following $L_\infty$-estimate for $\uft'(\lambda,\mu)$.

\begin{corollary}\label{cor_Lipschitz}
Let $N \in \Kl{1,2,3}$, $s > N/2 + 1$, and let the assumptions of Proposition~\ref{prop_uft_D_H2} hold. Then
    \begin{equation*}
    \begin{split}
        %&
        \norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{L_\infty(\Omega)} 
        %\\
        %& \qquad
        \leq C_\infty \norm{(h_\lambda,h_\mu)}_{X} 
        \kl{
        \norm{\ff}_{L_2(\Omega_1)}  + \norm{\gfT}_{H^{-\frac{1}{2}}(\Gamma_T)} + \kl{1 + \norm{(\lambda,\mu)}_{X} }\norm{\Phi}_{H^2(\Omega_1)} }\,.
    \end{split}    
    \end{equation*}
for some constant $C_\infty = C_\infty(\lambda,\mu,N,s,\Omega,\Omega',\Omega_1) > 0$.
\end{corollary}
\begin{proof}
Due to the Sobolev embedding inequality \eqref{embedding_inequality} it follows that for $N \in \Kl{1,2,3}$ there holds
    \begin{equation*}
        \norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{L_\infty(\Omega)} \leq c_E^s \norm{\uft'(\lambda,\mu)(h_\lambda,h_\mu)}_{H^2(\Omega)} \,.
    \end{equation*}
which together with \eqref{uft_D_H2} and $X = H^s(\Omega_1) \subset W^{1,\infty}(\Omega_1)$ for $s > N/2 +1$ yields the assertion.
\end{proof}

Since $\uf(\lambda,\mu) = \uft(\lambda,\mu) + \Phi$, and thus $\uf'(\lambda,\mu) = \uft'(\lambda,\mu)$, the above estimate also holds for $\uf'(\lambda,\mu)$, which establishes \eqref{Lipschitz_u_infty}. Hence, all model assumptions on $\uf(\lambda,\mu)$ are satisfied, as we summarize below.

\begin{proposition}\label{prop_elast_u}
Let $N \in \Kl{1,2,3}$, $s > N/2 + 1$, and let the assumptions of Proposition~\ref{prop_uft_D_H2} hold. Furthermore, let $\uf(\lambda,\mu) = \uft(\lambda,\mu) + \Phi$, with $\uft(\lambda,\mu)$ defined by \eqref{a=l}, and for $(\lambda_0,\mu_0) \in \Msm$ let $(\lambda^*,\mu^*)$ be an $(\lambda_0,\mu_0)$-MNS of the equation $\mI_1 \circ G(\lambda,\mu) = \mI_2$. Then $\uf$ satisfies \eqref{Lipschitz_u_infty}, \eqref{Lipschitz_u}, \eqref{Lipschitz_Du} with   
    \begin{equation*}
    \begin{split}
        C_1^* &=  C_\infty 
        \kl{
        \norm{\ff}_{L_2(\Omega_1)}  + \norm{\gfT}_{H^{-\frac{1}{2}}(\Gamma_T)} + \kl{1 + \norm{(\lambda,\mu)}_{X} }\norm{\Phi}_{H^2(\Omega_1)} }  \,,
    \end{split}
    \end{equation*}
and $C_2^* = C_3^* = C_{\lambda^*,\mu^*}$, where $C_{\lambda^*,\mu*}$ is the constant $C_{\lambda,\mu}$ from  Proposition~\ref{prop_differentiability} for $(\lambda,\mu) = (\lambda^*,\mu^*)$.
\end{proposition}
\begin{proof}
This directly follows from the above results and comments. In particular, Proposition~\ref{prop_uft_continuous} and \eqref{helper_uf_01} establish \eqref{Lipschitz_u}, Proposition~\ref{prop_uft_Frechet} and \eqref{helper_uf_02} show \eqref{Lipschitz_Du}, and Corollary~\ref{cor_Lipschitz} yields \eqref{Lipschitz_u_infty}. 
\end{proof}

With this, we obtain the following convergence rate result for the IIM in our linear elastic setting.

\begin{theorem}\label{thm_rates_elastic}
Let $N \in \Kl{1,2,3}$, $s > N/2 +1$, $0 < \mub \in \R$, and let Assumption~\ref{ass_linear_elastic} hold. In addition, assume $\ff \in L_2(\Omega_1)^N$, $g_D \in H^{\frac{3}{2}}(\Gamma_D)^N$, $\Phi \in H^2(\Omega_1)$, and that $\Omega\,, \Omega_2 \subset \R^N$ are open and bounded domains with a Lipschitz continuous boundary. Also, assume that there exists a bounded, open, connected Lipschitz domain $\Omega' \subset \Omega_1$ with $\overline{\Omega} \Subset \Omega'$ and $\overline{\Omega'} \Subset \Omega_1$. Furthermore, let $\uf(\lambda,\mu) := \uft(\lambda,\mu) + \Phi$, where $\uft(\lambda,\mu)$ is defined by \eqref{a=l} for $(\lambda,\mu) \in \Msm$, with $\Msm$ as in \eqref{def_Msm}, and assume that \eqref{cond_domain_elasticity} holds. Moreover, let $\mI_2 \in W^{1,\infty}(\Omega_2)$ and $C_L := \norm{\mI_2}_{W^{1,\infty}(\Omega_2)}$, $\mI_1 \in L_2(\Omega_1)$, $(\lambda_0,\mu_0) \in \Msm$, assume that there exists an $(\lambda_0,\mu_0)$-MNS $(\lambda^*,\mu^*)$ of $\mI_2 \circ G(\lambda^*,\mu^*) = \mI_1$, and that there is a noise level $\delta_{\mI_1} > 0$ such that $\Vert \mI_1 - \mI_1^\delta\Vert \leq \delta_{\mI_1}$ for $\mI_1^\delta \in L_2(\Omega_1)$. Finally, assume that there exists a $\wf \in L_2(\Omega)$ with
    \begin{equation*}
        (\lambda^\dagger,\mu^\dagger) - (\lambda_0,\mu_0)  = \mathcal{F}'(\af^\dagger)^*w \,,
        \qquad \text{and} \qquad
        C \norm{\wf} < 1 \,,
    \end{equation*}
where $C := C_L(C_1^*C_2^* + C_3^*)$ with $C_k^*$ as in Proposition~\ref{prop_elast_u}. Then for $\alpha \sim \delta_{\mI_1}$, a minimizer $(\lambda_\alpha^\delta,\mu_\alpha^\delta)$ of 
    \begin{equation*}
        \norm{\mI_2\circ G(\lambda,\mu) - \mI_1^\delta}_{L_2(\Omega)}^2 + \alpha \norm{(\lambda,\mu) - (\lambda_0,\mu_0)}_{H^s(\Omega_1)}^2 \,,
    \end{equation*}
satisfies
    \begin{equation*}
        \norm{(\lambda_\alpha^\delta,\mu_\alpha^\delta) - (\lambda^\dagger,\mu^\dagger) }_{H^s(\Omega_1)} = \mathcal{O}\kl{\sqrt{\delta_{\mI_1}}} \,,
        \qquad \text{and} \qquad 
        \norm{\mI_2\circ G(\lambda_\alpha^\delta,\mu_\alpha^\delta) - \mI_1^{\delta}}_{L_2(\Omega)} = \mathcal{O}\kl{\delta_{\mI_1}} \,.
    \end{equation*}
\end{theorem}
\begin{proof}
Due to the above results, in particular Proposition~\ref{prop_uft_continuous} and Proposition~\ref{prop_elast_u}, all assumptions of Theorem~\ref{theorem_rates} are satisfied, which now yields the assertion. 
\end{proof}

\begin{remark}
The above result essentially states that in our linear elastic setting, the IIM is an order optimal regularization method when searching for sufficiently regular Lam\'e parameters $\lambda,\mu$, as long as all the involved quantities are sufficiently ``reasonable''. Note that the restriction $s > N/2 + 1$ instead of $s > N/2$, the increased regularity of $\ff$, $\gfD$, and $\Phi$ in Theorem~\ref{thm_rates_elastic} compared to Assumption~\ref{ass_linear_elastic}, and the existence of the intermediate domain $\Omega'$, are only required for establishing the $L_\infty$-estimate \eqref{Lipschitz_u_infty} via the interior regularity of $\uft'(\lambda,\mu)$. However, depending on the concrete setting of the BVP \eqref{linear_elastic}, the estimate \eqref{Lipschitz_u_infty} and thus Theorem~\ref{thm_rates_elastic} may be obtained under weaker assumptions as well.

For example, a close inspection of the proofs of the interior regularity of $\uf(\lambda,\mu)$ and $\uf'(\lambda,\mu)$ shows that $\Phi$ only has to be locally $H^2$ regular, and thus the increased regularity on $\gfD$ can in fact be dropped. The same is true for the Lam\'e parameters $(\lambda,\mu)$, which technically only have to be in $H^s(\Omega'')$ with $s > N/2 + 1$ on a domain $\Omega'' \subset \Omega_1$ satisfying $\overline{\Omega'} \Subset \Omega''$ and $\overline{\Omega''} \Subset \Omega_1$, while outside $\Omega''$ it is sufficient that $s > N/2$ as before. While this could in fact be accommodated for by redefining the admissible set $\Msm$, we have refrained from doing so in this paper to avoid an overly technical exposition.

Furthermore, in certain settings of the BVP \eqref{linear_elastic}, it is possible to obtain full $H^2(\Omega_1)$ regularity for $\uf(\lambda,\mu)$ and thus also for $\uf'(\lambda,\mu)$. In this case, the existence of the intermediary domain $\Omega'$ may be dropped entirely in the above analysis. One example is the case of pure Dirichlet boundary conditions, i.e., $\Gamma_D = \partial \Omega$ and $\Gamma_T = \emptyset$, for which $H^2(\Omega_1)$ regularity follows if $g_D \in H^{\frac{3}{2}}(\Omega_1)$ and $\partial \Omega_1 \in C^{1,1}$; cf.\ \cite[Theorem~4.18]{McLean_2000}. However, for mixed boundary conditions, full $H^2(\Omega_1)$ regularity can typically not be obtained except in very specific circumstances. Nevertheless, if $\Omega$ ``touches'' $\partial \Omega_1$ only on the Dirichlet boundary $\Gamma_D$ sufficiently far away from $\Gamma_T$, then due to \cite[Theorem~4.18]{McLean_2000} one still has $H^2(\Omega)$ regularity assuming $g_D \in H^{\frac{3}{2}}(\Gamma_D)$ and $\partial \Gamma_D \in C^{1,1}$, which is sufficient for establishing \eqref{Lipschitz_u_infty}.
\end{remark}

Finally, we consider the IIM for the full noise case in our linear elastic setting. In particular, we assume that $\ff$, $\gfD$, and $\gfT$ are contaminated by noise, and thus $\uf^\delta$ satisfies the noisy BVP 
    \begin{equation}\label{linear_elastic_noisy}
    \begin{alignedat}{3}
        -\operatorname{div}{\sigma_{\lambda,\mu}(\uf^\delta)} & = \ff^\delta \,, \qquad &&\text{in} \quad \Omega_1 \,, 
        \\ 
        \uf^\delta & = \gfD^\delta \,, \qquad &&\text{on} \quad \Gamma_D  \,,
        \\
        \sigma_{\lambda,\mu}(\uf^\delta) \nv &= \gfT^\delta \,,  \qquad &&\text{on} \quad \Gamma_T \,.
    \end{alignedat} 
    \end{equation}
This situation appears in practice if the applied forces in an elastography experiment are only known (measured) up to a certain accuracy. Concerning the noise bound \eqref{cond_noise_model}, we have the following result.

\begin{proposition}
Let $\ff^\delta \in H^{-1}(\Omega_1)^{N}$, $\gfD^\delta \in H^{\frac{1}{2}}(\Gamma_D)^N$, $\gfT^\delta \in H^{-\frac{1}{2}}(\Gamma_T)^N$, and assume that there is a function $\Phi^\delta \in H^1(\Omega_1)^N$ such that $\Phi^\delta \vert_{\Gamma_D} = \gfD^\delta$. Furthermore, let $\uf$ and $\uf^\delta$ denote the (unique) weak solutions of the BVPs \eqref{linear_elastic} and \eqref{linear_elastic_noisy}, respectively. Then there exists a constant $C > 0$ such that
    \begin{equation}\label{uft_bound_nois}
        \norm{\uf-\uf^\delta}_{H^1(\Omega_1)} 
        \leq
        C \kl{ \norm{\ff-\ff^\delta}_{H^{-1}(\Omega_1)} + \norm{\gfT-\gfT^\delta}_{H^{-\frac{1}{2}}(\Gamma_T)} 
        + \norm{(\lambda,\mu)}_X \norm{\Phi-\Phi^\delta}_{H^1(\Omega_1)} } \,.
    \end{equation}
\end{proposition}
\begin{proof}
First, note that $\uf = \uft + \Phi$ and $\uf^\delta = \uft^\delta + \Phi^\delta$, where $\uft \in V$ is the unique solution of the variational problem \eqref{a=l} and $\uft^\delta \in V$ is the unique weak solution of the variational problem
    \begin{equation*}
        a_{\lambda,\mu}(\uft,\vf) = l^\delta(\vf) - a_{\lambda,\mu}(\Phi^\delta,\vf) \,,  
        \qquad
        \forall \, \vf \in V \,,
    \end{equation*}
where
    \begin{equation*}
        l^\delta(\vf) := \spr{\ff^\delta,\vf}_{H^{-1}(\Omega_1),H^1(\Omega_1)} + \spr{\gfT^\delta,\vf}_{H^{-\frac{1}{2}}(\Gamma_T),H^{\frac{1}{2}}(\Gamma_T)} \,.
    \end{equation*}
Hence, the difference $\zf := (\uft - \uft^\delta) \in V$ is the unique solution of 
    \begin{equation*}
        a_{\lambda,\mu}(\zf,\vf) = \kl{l(\zf) - l^\delta(\zf)} - a_{\lambda,\mu}(\Phi-\Phi^\delta,\vf) \,,  
        \qquad
        \forall \, \vf \in V \,,
    \end{equation*}
and thus it follows as in Lemma~\ref{lem_existence} that there exists a constant $C> 0$ such that
    \begin{equation*}
        \norm{\uft-\uft^\delta}_{H^1(\Omega_1)} 
        \leq
        C \kl{ \norm{\ff-\ff^\delta}_{H^{-1}(\Omega_1)} + \norm{\gfT-\gfT^\delta}_{H^{-\frac{1}{2}}(\Gamma_T)} 
        + \norm{(\lambda,\mu)}_X \norm{\Phi-\Phi^\delta}_{H^1(\Omega_1)} } \,,
    \end{equation*}
which together with $(\uft - \uft^\delta) = (\uf - \uf^\delta)$ now yields the assertion.
\end{proof}

Now in order to establish the noise bound \eqref{cond_noise_model}, assume that there exist $\delta_{G,1},\delta_{G,2},\delta_{G,3}$ such that
    \begin{equation*}
        \norm{\ff-\ff^\delta}_{H^{-1}(\Omega_1)} \leq \delta_{G,1} \,,
        \qquad
        \norm{\gfT-\gfT^\delta}_{H^{-\frac{1}{2}}(\Gamma_T)} \leq \delta_{G,2} \,,
        \qquad
        \norm{\Phi-\Phi^\delta}_{H^1(\Omega_1)} \leq \delta_{G,3} \,.
    \end{equation*}
Then together with \eqref{uft_bound_nois} we obtain
    \begin{equation}
        \norm{\uf-\uf^\delta}_{H^1(\Omega_1)} 
        \leq
        C \kl{ \delta_{G,1} + \delta_{G,2}
        + \norm{(\lambda,\mu)}_X \delta_{G,3} } \,.
    \end{equation}
Hence, for a fixed $(\lambda^*,\mu^*) \in \Msm$ we obtain
    \begin{equation*}
        \sup_{(\lambda,\mu) \in \Msm \cap B_\eps(\lambda^*,\mu^*)} \norm{\uf-\uf^\delta}_{H^1(\Omega_1)} 
        \leq
        C \kl{ \delta_{G,1} + \delta_{G,2}
        + \kl{\norm{(\lambda^*,\mu^*)}_X + \eps} \delta_{G,3} } =: \delta_G   \,, 
    \end{equation*}
which established the noise bound \eqref{cond_noise_model}. With this, we can now transfer the convergence and convergence rates results from Section~\ref{sect_convergence} to our linear elastic setting as well. In particular, assume that $\mI_2^\delta = \mI_2 + \delta_{\mI_2} \xi$ with $\norm{\xi}_{L_\infty(\Omega_2)} < \infty$ and that there is a $\bar{\delta} > 0$ such that for all $\delta \leq \bar{\delta}$ there holds
    \begin{equation*}
        \forall\, (\lambda,\mu) \in \Msm \cap B_\eps((\lambda^*,\mu^*)) \,, \forall \x \in \Omega \, : \, G^\delta(\lambda,\mu)(\x) \in \Omega_2 \,.
    \end{equation*}
Then under the assumptions of Theorem~\ref{theorem_convergence_elastic} and Theorem~\ref{thm_rates_elastic}, the convergence and convergence rate results of Theorem~\ref{theorem_convergence} and Theorem~\ref{theorem_rates} transfer to our considered linear elastic setting, and we obtain that the IIM is a convergent and order optimal regularization method also in the full noise case.



