\section{Proof of Theorem~\ref{thm:main}}
\label{app:proof}

\paragraph{Remark.} We use a unified sequence encoding for all problems.
Let $\mathcal{V}=\{0,1,\dots,n\}$ be the set of node indices, where
$0$ denotes the depot or a special
“dummy symbol” when a position in the sequence is unused.
For a fixed length $L\!\ge\!n$ we encode every candidate tour as a
sequence $\boldsymbol{\tau}=[\tau_1,\dots,\tau_L]\in\mathcal V^{\,L}$:

\begin{itemize}[leftmargin=1.4em]
\item \textbf{Complete‑path problems (TSP, CVRP).}  
  Each node $1,\dots,n$ appears exactly once in~$\boldsymbol{\tau}$, the depot~$0$
  may appear multiple times (CVRP).
  No dummies are present.

\item \textbf{Partial‑path problems (PCTSP, OP).}  
  The same alphabet $\mathcal V$ is used, but positions that are not
  visited in the tour are filled with the dummy symbol~$0$.
  Consequently $0$ may occur multiple times.
\end{itemize}

Because~$0\in\mathcal V$ is treated as an ordinary symbol in both
settings, we obtain

\begin{enumerate}[label=(\roman*),leftmargin=1.6em]
\item a common support
      $\mathcal X=\mathcal V^{\,L}$ for all generation distributions
      $p_k$, irrespective of whether the underlying problem is complete
      or partial;
\item strictly positive one‑step kernels
      $P_k(\tau,\cdot)$, since each genetic operator assigns
      non‑zero probability to every symbol in every position,
      including repetitions of~$0$ when they serve as dummies.
\end{enumerate}

Hence Lemmas~\ref{lem:exp_tv}–\ref{lem:crossover_measurable} and
Theorems~\ref{thm:divergence_k_generation}–\ref{thm:gradient_difference_short}
apply verbatim to both
complete tours (TSP, CVRP) and
partial tours (PCTSP, OP).

\paragraph{Facts (standard).}
Log--Sum, KL‑Convexity, Chain Rule, Data–Processing, Pinsker~\citep{stone2015information}.
%-------------------------------------------------
\begin{lemma}[Expectation–Total Variation Bound]\label{lem:exp_tv}
Let $P,Q$ be probability measures on $(\mathcal X,\mathcal F)$
and $f:\mathcal X\to\mathbb R^d$ be bounded with
$\|f\|_{2,\infty}:=\sup_{x}\|f(x)\|_2<\infty$.
Then
\[
  \bigl\|\mathbb E_Q[f]-\mathbb E_P[f]\bigr\|_2
  \;\le\;
  2\,D_\mathrm{TV}(P,Q)\,\|f\|_{2,\infty}.
\]
\end{lemma}
%-------------------------------------------------
\begin{lemma}[Terminal KL bound via step-wise KL to the initial distribution]
\label{lem:markov_chains_p0}
Let $X_0 \!\to\! X_1 \!\to\! \dots \!\to\! X_T$ be a Markov chain on a common
(measurable) support, and assume all marginal densities are strictly
positive.  Denote the marginals by $p_t := p(X_t)$ and the one–step kernels by
\[
  P_t(x,\cdot)\;:=\;p\bigl(X_t=\cdot \mid X_{t-1}=x\bigr),
  \qquad t=1,\dots,T.
\]
Then
\[
  D_{\mathrm{KL}}\!\bigl(p_T \,\|\, p_0\bigr)
  \;\le\;
  T \;
  \max_{1\le t\le T}
  \mathbb{E}_{p_{t-1}}
    \Bigl[
      D_{\mathrm{KL}}\!\bigl(
        P_t(X_{t-1},\cdot) \,\|\, p_0
      \bigr)
    \Bigr].
\]
\end{lemma}

\begin{proof}
\textbf{Step 1: Construct an independent reference process.}
Define
\[
  q(X_{0:T}) \;:=\; p_0(X_0)\;\prod_{t=1}^{T} p_0(X_t),
\]
so that each $X_t$ under $q$ is an i.i.d. draw from $p_0$ and
$q(X_T)=p_0$ by construction.

\textbf{Step 2: Chain rule for KL divergence.}
Because $p$ is Markov,
\(
  p(X_t\mid X_{0:t-1}) = P_t(X_{t-1},\cdot).
\)
Applying the chain rule,
\[
  D_{\mathrm{KL}}\!\bigl(p(X_{0:T})\,\|\,q(X_{0:T})\bigr)
  \;=\;
  \sum_{t=1}^{T}
    \mathbb{E}_{p_{t-1}}
      \Bigl[
        D_{\mathrm{KL}}\!\bigl(
          P_t(X_{t-1},\cdot)\,\|\,p_0
        \bigr)
      \Bigr].
\]

\textbf{Step 3: Data–processing inequality.}
For the measurable map $f(X_{0:T})=X_T$,
\[
  D_{\mathrm{KL}}\!\bigl(p_T\,\|\,p_0\bigr)
  \;=\;
  D_{\mathrm{KL}}\!\bigl(p\!\circ\!f^{-1}\,\|\,q\!\circ\!f^{-1}\bigr)
  \;\le\;
  D_{\mathrm{KL}}\!\bigl(p(X_{0:T})\,\|\,q(X_{0:T})\bigr).
\]

\textbf{Step 4: Combine the bounds.}
Putting the previous two displays together,
\[
  D_{\mathrm{KL}}\!\bigl(p_T\,\|\,p_0\bigr)
  \;\le\;
  \sum_{t=1}^{T}
    \mathbb{E}_{p_{t-1}}
      \Bigl[
        D_{\mathrm{KL}}\!\bigl(
          P_t(X_{t-1},\cdot)\,\|\,p_0
        \bigr)
      \Bigr].
\]
Let
\(
  c_t :=
  \mathbb{E}_{p_{t-1}}
    \bigl[
      D_{\mathrm{KL}}\bigl(P_t(X_{t-1},\cdot)\,\|\,p_0\bigr)
    \bigr]
\)
and $c_{\max}:=\max_{1\le t\le T} c_t$.
Then $\sum_{t=1}^{T} c_t \le T\,c_{\max}$, yielding the claimed inequality.
\end{proof}
%-------------------------------------------------
\begin{theorem}[KL bound across $K$ GA generations]\label{thm:divergence_k_generation}
Under the elitism update rule
\[
  p(\boldsymbol{\tau}_k\mid\boldsymbol{\tau}_{k-1})
  \;=\;
  \rho\,p^{\mathrm{off}}(\boldsymbol{\tau}_k\mid\boldsymbol{\tau}_{k-1})
  +(1-\rho)\,p_{k-1},
  \qquad 0\le\rho\le1,
\]
we define \( p_k \) as the probability distribution of the \( k \)-th generation solutions, which is equivalent to the probability distribution \( p(\boldsymbol{\tau}_k) \) for any trajectory \( \boldsymbol{\tau}_k \) sampled from this generation. The following holds:
\[
  D_\mathrm{KL}(p_K\|p_0)
  \;\le\;
  \rho\,K\,
  \max_{1\le k\le K}
  \mathbb{E}_{\boldsymbol{\tau}_{k-1}\sim p_{k-1}}
  \Bigl[
    D_\mathrm{KL}\bigl(
      p^{\mathrm{off}}(\boldsymbol{\tau}_k\mid\boldsymbol{\tau}_{k-1})
      \,\|\,p_{k-1}
    \bigr)
  \Bigr].
\]
\end{theorem}

\begin{proof}
\textbf{Step 1: Convexity of KL divergence.}  
\[
  D_\mathrm{KL}\!\bigl(
    p(\boldsymbol{\tau}_k\mid\boldsymbol{\tau}_{k-1})
    \,\|\,p_{k-1}
  \bigr)
  \;\le\;
  \rho\,
  D_\mathrm{KL}\!\bigl(
    p^{\mathrm{off}}(\boldsymbol{\tau}_k\mid\boldsymbol{\tau}_{k-1})
    \,\|\,p_{k-1}
  \bigr).
\]

\textbf{Step~2: Apply Lemma~\ref{lem:markov_chains_p0}.}  
Viewing $\boldsymbol{\tau}_0\!\to\!\dots\!\to\!\boldsymbol{\tau}_K$ as a Markov chain with the above kernel and substituting the bound from Step 1,
\[
  D_\mathrm{KL}(p_K\|p_0)
  \;\le\;
  \rho\,K\,
  \max_{k}
  \mathbb{E}_{\boldsymbol{\tau}_{k-1}\sim p_{k-1}}
  \Bigl[
    D_\mathrm{KL}\bigl(
      p^{\mathrm{off}}(\boldsymbol{\tau}_k\mid\boldsymbol{\tau}_{k-1})
      \,\|\,p_{k-1}
    \bigr)
  \Bigr].
\]
\end{proof}
%-------------------------------------------------
\begin{corollary}[KL between offspring and parents]\label{thm:divergence_offspring_parents}
Let the offspring distribution be the convex mixture
\[
  p^{\mathrm{off}}(\boldsymbol{\tau}_k\mid\boldsymbol{\tau}_{k-1})
  \;=\;
  \alpha\,q^{\mathrm{cross}}(\boldsymbol{\tau}_k)
  +\beta\,q^{\mathrm{mutate}}(\boldsymbol{\tau}_k)
  +\gamma\,q^{\mathrm{elite}}(\boldsymbol{\tau}_k),
  \quad \alpha+\beta+\gamma=1.
\]
If the elite component copies parents verbatim,
\(q^{\mathrm{elite}}=p_{k-1}\),
then
\[
  D_\mathrm{KL}\!\bigl(
    p^{\mathrm{off}}(\boldsymbol{\tau}_k\mid\boldsymbol{\tau}_{k-1})
    \,\|\,p_{k-1}
  \bigr)
  \;\le\;
  \alpha\,D_\mathrm{KL}\!\bigl(
    q^{\mathrm{cross}}\,\|\,p_{k-1}
  \bigr)
  +\beta\,D_\mathrm{KL}\!\bigl(
    q^{\mathrm{mutate}}\,\|\,p_{k-1}
  \bigr).
\]
\end{corollary}

\begin{proof}
By convexity of KL divergence, we have
\[
  D_\mathrm{KL}\bigl(
    p^{\mathrm{off}} \,\|\, p_{k-1}
  \bigr)
  \le
  \alpha\,D_\mathrm{KL}(q^{\mathrm{cross}}\,\|\,p_{k-1})
  +\beta\,D_\mathrm{KL}(q^{\mathrm{mutate}}\,\|\,p_{k-1})
  +\gamma\,D_\mathrm{KL}(q^{\mathrm{elite}}\,\|\,p_{k-1}).
\]
Since \(q^{\mathrm{elite}} = p_{k-1}\), the last term vanishes, yielding the stated bound.
\end{proof}
%-------------------------------------------------

\begin{lemma}[Crossover as a measurable transformation]
    \label{lem:crossover_measurable}
    Let $f$ be a fixed retained fragment selected by the OX crossover operator. Then the transformation from a parental fragment $r$ to the offspring fragment induced by OX defines a deterministic and support-preserving mapping $g_f$ such that
    \[
        q(r \mid f) = p(g_f^{-1}(r) \mid f).
    \]
    In particular, this mapping $g_f$ can be viewed as a measurable transformation over the conditional fragment space $\mathcal R_f$.
\end{lemma}
\begin{proof}
    Our crossover operator selects fixed parent individuals for pairing rather than randomly. Without loss of generality, we focus on parent $p_2$ and offspring $o_1$.

    Given $f = p_1[s:e]$, the OX operator deterministically fills the remaining positions of $o_1$ using nodes from $p_2$, preserving their relative order. That is, the perturbed fragment $r$ of the offspring $o_1$ is constructed by removing the nodes in $f$ from $p_2$ and placing the remaining nodes into the empty positions of $o_1$ in a fixed cyclic order.

    This process defines a transformation from the parental fragment $\text{segment}(p_2, r)$ to the offspring fragment $\text{segment}(o_1, r)$, conditional on $f$. As the transformation preserves the relative order of elements in $r$, it is deterministic and support-preserving.

    Therefore, for a fixed retained fragment $f$, the OX operator can be viewed as inducing a measurable transformation $g_f$ over the space of fragments $r$, such that
    \[
    \text{segment}(o_1, r) = g_f(\text{segment}(p_2, r)),
    \]
    and correspondingly, the induced distribution over offspring fragments satisfies
    \[
    q(r \mid f) = p(g_f^{-1}(r) \mid f).
    \]
    The same reasoning applies symmetrically to $o_2$ and $p_1$.
\end{proof}


%-------------------------------------------------
\begin{theorem}[KL bound for the crossover and mutation operators]
\label{thm:divergence_crossover}
Let each trajectory $\boldsymbol{\tau}$ be decomposed as $[f, r]$, where $f$ is the retained fragment
and $r$ the fragment perturbed via genetic operators (e.g., filled from a partner parent in crossover, or modified in mutation).
If the genetic operator leaves $f$ unchanged and only permutes or perturbs $r$, then
\[
  D_\mathrm{KL}\!\bigl(q(\boldsymbol{\tau})\,\|\,p(\boldsymbol{\tau})\bigr)
  \;\le\;
  \mathbb{E}_{f\sim p}\!
  \Bigl[
    \log\!\frac{\max p(r\mid f)}{\min p(r\mid f)}
  \Bigr].
\]
\end{theorem}

\begin{proof}
\textbf{Step~1: Split by fragments.}  
Since $\boldsymbol{\tau} = [f, r]$ is a unique decomposition,
\[
  D_\mathrm{KL}(q\|p) = \sum_{f,r} q(f, r) \log \frac{q(f, r)}{p(f, r)}.
\]

\textbf{Step~2: Marginal equality on $f$.}  
By construction, the operator (crossover or mutation) preserves $f$, hence $q(f) = p(f)$, so
\[
  D_\mathrm{KL}(q\|p)
  = \mathbb{E}_{f\sim p}
  \Bigl[
    \sum_r q(r\mid f) \log \frac{q(r\mid f)}{p(r\mid f)}
  \Bigr].
\]

\textbf{Step~3: Bounded perturbation on $r$.}  
Whether $q(r \mid f)$ arises via permutation (crossover) or local modification (mutation), it satisfies:
\begin{itemize}
  \item $\sum_r q(r \mid f) = 1$
  \item $q(r \mid f)$ and $p(r \mid f)$ share support
  \item $q(r \mid f)$ is a rearrangement of $p(r \mid f)$
\end{itemize}
Thus, define a measure-preserving transformation $g_f$ so that
$q(r \mid f) = p(g_f^{-1}(r) \mid f)$. Then:
\[
  \sum_{r} q(r\mid f) \log \frac{q(r\mid f)}{p(r\mid f)}
  =
  \sum_r p(r \mid f) \log \frac{p(r \mid f)}{p(g_f(r) \mid f)}
  \le
  \log \frac{M_f}{m_f},
\]
where $M_f = \max p(r \mid f)$ and $m_f = \min p(r \mid f)$.

\textbf{Step~4: Take expectation over $f$.}  
Substitute this bound into Step~2:
\[
  D_\mathrm{KL}(q\|p) \le \mathbb{E}_{f \sim p} \left[ \log \frac{M_f}{m_f} \right],
\]
completing the proof.
\end{proof}

\begin{corollary}[Convex mixture of deterministic transforms]
\label{cor:convex_pushforward}
If, given the retained fragment \(f\), a genetic operator
acts as a convex combination of finitely many
support‑preserving deterministic maps \(g_{f,j}\) (e.g. \ node-replacement mutation),
i.e.\ \(q(r\mid f)=\sum_j w_j p(g_{f,j}^{-1}(r)\mid f)\),
then the bound in Theorem~\ref{thm:divergence_crossover} still holds.
\end{corollary}

\begin{proof}
KL is convex in its first argument, so
\(D_{\mathrm{KL}}(\sum_j w_j q_j\|p)
      \le \sum_j w_j D_{\mathrm{KL}}(q_j\|p)
      \le \log(M_f/m_f)\).
Take expectation over \(f\).
\end{proof}
%-------------------------------------------------

\begin{theorem}[Overall KL bound]
    Summing up aforementioned Thorems, we have:
    \begin{align*}
        & D_{\text{KL}}(p(\boldsymbol{\tau}_K) \| p(\boldsymbol{\tau}_0))\le \\&\rho K \Bigg(\alpha \mathbb{E}_{p(f_{\text{cross}})}\bigg[\log \frac{\max{p(r_{\text{cross}}|f_{\text{cross}})}}{\min p(r_{\text{cross}}|f_{\text{cross}})}\bigg] + \beta \mathbb{E}_{p(f_{\text{mutate}})}\bigg[\log\frac{\max p(r_{\text{mutate}}|f_{\text{mutate}})}{\min p(r_{\text{mutate}}|f_{\text{mutate}})}\bigg]\Bigg)
    \end{align*}
\end{theorem}

\begin{theorem}[Policy Gradient Difference Upper Bound]\label{thm:gradient_difference_short}
If every trajectory gradient is L2‑clipped to~1, i.e.\ If $\|\nabla J(\boldsymbol{\tau})\|_2\le1$ almost surely, then
\[
  \Bigl\|
    \mathbb{E}_{\boldsymbol{\tau}_K\sim p_K}[\nabla J(\boldsymbol{\tau}_K)]
    -\mathbb{E}_{\boldsymbol{\tau}_0\sim p_0}[\nabla J(\boldsymbol{\boldsymbol{\tau}}_0)]
  \Bigr\|_2
  \;\le\;
  \sqrt{2\,D_\mathrm{KL}\!\bigl(p_K\|p_0\bigr)}.
\]
\end{theorem}

\begin{proof}
\textbf{Step~1: Expectation--TV inequality.}  
Apply lemma~\ref{lem:exp_tv} with $f=\nabla J$, $P=p_0$, $Q=p_K$ and
$\|f\|_{2,\infty}\le1$ (In our implementation, we apply L2 gradient clipping) gives
\[
  \Bigl\|\mathbb{E}_{p_K}[f]-\mathbb{E}_{p_0}[f]\Bigr\|_2
  \le2\,D_\mathrm{TV}(p_K\|p_0).
\]

\textbf{Step~2: Convert TV to KL.}  
Pinsker’s inequality yields
$D_\mathrm{TV}(p_K\|p_0)\le\sqrt{\tfrac{1}{2}\,D_\mathrm{KL}(p_K\|p_0)}$.
Substituting into Step~1 produces the claimed bound.
\end{proof}
