\section{Implementation Details of Proposed Method}
\label{app:implement_details}
This section provides detailed information on the implementation of the proposed Evolution Augmentation Mechanism (EAM), including algorithmic structure and hyperparameters configurations.

\subsection{Pseudo Code}
We provide the pseudo code for the proposed Evolution Augmentation Mechanism (EAM), as shown in Algorithm~\ref{alg:eam_framework}. The procedure includes policy initialization, environment sampling, optional application of the genetic algorithm based on pre-defined conditions, and subsequent policy updates using REINFORCE. The red-highlighted areas represent the core part of EAM and are the major differences from the standard RL paradigm, demonstrating how our method extends the current DRL-NCO framework's mainstream training paradigm as a plug-and-play module.

\newcommand{\GeneticAlgorithm}{GeneticAlgorithm}
\newcommand{\REINFORCE}{ApplyREINFORCE}

\begin{algorithm}[H]
\caption{Evolution Augmentation Mechanism}
\label{alg:eam_framework}
\begin{algorithmic}

\Require Base nerual solver $p_\theta$, EA Probs $\epsilon$, EA Epochs $\kappa$, num evolution generations $K$, selection rate $\rho$, crossover rate $\alpha$, mutation rate $\beta$.

\Procedure{Train}{$p_\theta, \epsilon, \kappa, K, \rho, \alpha, \beta$}

    \State Initialize $p_\theta$
    \State $epoch \gets 0$
    \While{not converged}
        \State Randomly initialize environment $E$
        \State $\mathrm{P}_0 \gets p_\theta(E)$ 
        \If{\textcolor{red}{use genetic algorithm}} \Comment{Conditioned on $\epsilon, \kappa$}
            \State \textcolor{red}{$\mathrm{P}_K \gets $ \CommonCall{\GeneticAlgorithm}{$\mathrm{P}_0,K,\rho,\alpha,\beta$}}
            \State \textcolor{red}{\CommonCall{\REINFORCE}{$\mathrm{P}_K, p_\theta$}}
        \EndIf

        \State \CommonCall{\REINFORCE}{$\mathrm{P}_0, p_\theta$}

        \State $epoch \gets epoch + 1$
    \EndWhile

    \State \Return $p_\theta$
\EndProcedure

\Procedure{Test}{$p_\theta$}

    \State Randomly initialize environment $E$
    \State $\mathrm{P}_0 \gets p_\theta(E)$


    \State \Return Cost($\mathrm{P}_0$)
\EndProcedure
\end{algorithmic}
\end{algorithm}

