	\begin{defn}
		\label{def:nu_w}
			Let $W$ be a non-empty set (of {\em possible worlds}), and $R \subseteq W^2$ be an {\em accessibility} relation on $W$. For each $w, w^\prime \in W$ a function $v_w : For(\Sigma) \to A$ is a \textit{swap valuation} for {\DmbC} if every condition below is satisfied, for $\alpha,\beta\in For(\Sigma)$:

			\begin{description}
			  %  \item[1.] $v_w (p) \in A$ is arbitrary, for a propositional variable $p$
				\item[1.] $v_w(\alpha \land \beta) \in v_w(\alpha) \aland v_w(\beta)$				
                \item[2.] $v_w(\alpha \lor \beta) \in v_w(\alpha) \alor v_w(\beta)$
                \item[3.] $v_w(\alpha \to \beta) \in v_w(\alpha) \ato v_w(\beta)$
				\item[4.] $v_w(\neg \alpha) \in \aneg v_w(\alpha)$								
				\item[5.] $v_w(\circ\alpha) \in \acirc v_w(\alpha)$
                \item[6.] $v_w(\obl\alpha) \in \aobl\big(\{v_{w\prim}(\alpha) \ : \ w R w^\prime\}\big)$ 
			\end{description}
	\end{defn}

    \begin{defn} \label{def:swap-Kripke-DmbC}
    Let $W$ be a non-empty set of worlds, $R \subseteq W^2$ be a serial accessibility relation\footnote{Recall that a relation $R \subseteq W^2$ is {\em serial} if, for every $w \in W$, there exists $w'\in W$ such that $wRw'$.} and $\{v_w\}_{w \in W}$ a family of swap valuations for \DmbC.  We say that the triple $\M^{K-S}_{\DmbC} = \langle W,R,\{v_w\}_{w \in W} \rangle$ is a {\em swap Kripke model} for the logic {\DmbC}.
    \end{defn}

   \begin{rmk}
   \label{rmk:notation} Let $i \in \{1,2\}$ and $w \in W$.  We define $\pi_i(v_w(\alpha))$ to be the projection of the pair $v_w(\alpha)$ on its $i$-th coordinate. For the sake of simplicity, we adopt the notation $\alpha_{(i,w)}$ to denote $\pi_i(v_w(\alpha))$. %Whenever $w$ is clear from context, we simply write $\alpha_i$.
    \end{rmk} 

    \begin{lemma}
    \label{lemma:proj-nu_w}
        Let $w \in W$ and $\alpha,\beta \in For(\Sigma)$. Moreover, let $v_w$ be as in \cref{def:nu_w}. Then 
            \begin{description}
                \item[1.] $(\alpha \land \beta)_{(1,w)} = \alpha_{(1,w)} \sqcap \beta_{(1,w)}$
                \item[2.] $(\alpha \lor \beta)_{(1,w)} = \alpha_{(1,w)} \sqcup \beta_{(1,w)}$
                \item[3.] $(\alpha \to \beta)_{(1,w)} = \alpha_{(1,w)} \supset \beta_{(1,w)}$
                \item[4.] $(\neg \alpha)_{(1,w)} = \alpha_{(2,w)}$
                \item[5.] $(\circ \alpha)_{(1,w)} \leq {\sim} (\alpha_{(1,w)} \sqcap \alpha_{(2,w)})$ 
                \item[6.] $(\obl \alpha)_{(1,w)} = \bigsqcap \{\alpha_{(1,w\prim)} \ : \ wRw\prim\}$ %\add{vielleicht $\leq$?}
            \end{description}
   \end{lemma}
    \begin{proof}
        Items 1. through 5. are immediate from the definitions above. For item 6., consider $\aobl\big(\{v_{w\prim}(\alpha) \ : \ w R w^\prime\}\big)$. By \cref{def:swapOperations}, $$\aobl\big(\{v_{w\prim}(\alpha) \ : \ w R w^\prime\}\big) = \{c \in A \ : \ c_1 = \bigsqcap \{x_{(1,w\prim)} \ : \ x \in \{v_{w\prim}(\alpha) \ : \ w R w^\prime\} \}\}$$
        thus our result follows by item 6. of \cref{def:nu_w}.
    \end{proof}

   \begin{rmk}
    \label{prop:designated-dmbc}
        By the very definitions, for any $w \in W$ and for any $\alpha \in For(\Sigma)$, $v_w(\alpha) \in \D$ if and only if $\alpha_{(1,w)} = 1$.
   \end{rmk} 


    \begin{rmk} \label{rem:O-E}
        We can now give a clear picture of what our models will look like. In particular, we show how any model of $\DmbC$ satisfy axiom ($\obl$-E). It is easy to see  that $v_w(\obl\bot_\alpha)=v_w(\bot_\alpha)$. Indeed, by item~6 of Lemma~\ref{lemma:proj-nu_w},  $(\obl \bot_\alpha)_{(1,w)} = \bigsqcap \{(\bot_\alpha)_{(1,w\prim)} \ : \ wRw\prim\} =  \bigsqcap \{0 \ : \ wRw\prim\}=0$, given that $(\bot_\alpha)_{(1,w\prim)}=0$ for every $w\prim  \in W$ (by \cref{lemma:proj-nu_w} items 1, 4 and 5), and $\{w\prim \in W \ : \  w R w\prim\}\neq\emptyset$, since $R$ is serial. 
    \end{rmk}


    \begin{defn}
        \label{def:truth}
		Let $\mathcal{M}^{K-S}_{DmbC} = \langle W, R, \{v_w\}_{w \in W}  \rangle$ be as in \cref{def:swap-Kripke-DmbC}. For any formula $\alpha \in For(\Sigma)$, we say that $\alpha$ is $\mathcal{M}^{K-S}_{DmbC}$-true in a world $w$, denoted $\mathcal{M}^{K-S}_{DmbC}, w \vDash \alpha$, if $v_w(\alpha) \in \mathcal{D}$. 
	\end{defn}


	\begin{defn}
        \label{def:l-cons}
        Let $\Gamma \cup\{\alpha\} \subseteq For(\Sigma)$. We say that $\alpha$ is a logical consequence of $\Gamma$ in \DmbC, denoted $\Gamma \vDash_{\DmbC}  \alpha$, if for all $\mathcal{M}^{K-S}_{DmbC}$ and $w \in W$: $\mathcal{M}^{K-S}_{DmbC}, w \vDash \Gamma$ implies that $\mathcal{M}^{K-S}_{DmbC}, w \vDash \alpha$.
	\end{defn}

    \begin{thm}[Soundness of \DmbC\ w.r.t. swap Kripke models] \ \\
        For every $\Gamma \cup \{\varphi\} \subset For(\Sigma)$, if $\Gamma \vdash_{\DmbC} \varphi$, then $\Gamma \vDash_{\DmbC}  \varphi$.
    \end{thm}

    \begin{proof}
        We first show that the theorem holds for the axioms of {\DmbC}.  The result for the {\cplp} axioms follows from \cref{lemma:proj-nu_w}. 

        For (bc), we must show that $(\circ \alpha)_{(1,w)} \ato (\alpha \to (\neg \alpha \to \beta))_{(1,w)}=1$. If $(\circ \alpha)_{(1,w)}=0$, we are done.  Otherwise, ${\sim}(\alpha_{(1,w)} \land \alpha_{(2,w)})=1$, so either $\alpha_{(1,w)}=0$ or $\alpha_{(2,w)}=0$. The first guarantees that $(\alpha \to (\neg\alpha \to \beta))_{(1,w)} = 1$. The second makes it so that $(\neg \alpha \to \beta)_{(1,w)}=1$, hence $(\alpha \to (\neg\alpha \to \beta))_{(1,w)} = 1$.

        For (\obl-K), assume $(\obl(\alpha \to \beta))_{(1,w)}=1$ and that $(\obl(\alpha))_{(1,w)} = 1$. We then have that $(\alpha \to \beta)_{(1,w\prim)}=1$ and that $\alpha_{(1,w\prim)}=1$ for every $w\prim \in W$ such that $wRw\prim$. Hence, it follows that $\beta_{(1,w\prim)}=1$ for every $w\prim$ such that $wRw\prim$.

        The proof for (\obl-E) follows from Remark~\ref{rem:O-E}.
        %, suppose $(\obl(\bot_\alpha))_{(1,w)}=1$. Then $(\bot_\alpha)_{(1,w\prim)}=1$ for every $w\prim \in W$ such that $wRw\prim$. But this is impossible, by \cref{lemma:proj-nu_w} items 1, 4 and 5.

        For Modus Ponens, it is immediate to see that it satisfies the criteria, by definition of $\tilde{\to}$. For Necessitation, suppose $\alpha$ is a theorem. Then for every $w \in W$, $\alpha_{(1,w)}=1$. In particular, it is the case for every $w\prim \in W$ such that $wRw\prim$,  from which it follows that $(\obl\alpha)_{(1,w)}=1$.
    \end{proof}

    In order to prove completeness for {\DmbC}, we build canonical models based on swap structures. We use the method of $\psi$-saturation for construction of maximal consistent sets, together with the denecessitation for the accessibility relation. This will allow us to create the models for which completeness results will hold. 

     \begin{defn}
         Given a Tarskian and finitary\footnote{A logic {\bf L} is Tarskian if for $\Gamma \subseteq For(\Sigma)$ the following holds:\\
         {\bf (Reflexivity)} for every $\varphi \in \Gamma$, $\Gamma \vdash \varphi$;\\
         {\bf (Monotonicity)} if $\Gamma \vdash \varphi$ and $\Gamma \subseteq \Delta$, then $\Delta \vdash \varphi$;\\
         {\bf (Cut)} if $\Gamma \vdash \varphi$ for every $\varphi \in \Delta$ and $\Delta \vdash \psi$, then $\Gamma \vdash \psi$. \\
         {\bf L} is finitary if it satisfies\\
         {\bf (Finiteness)} $\Gamma \vdash \varphi$ implies $\Gamma_0 \vdash \varphi$, for some finite $\Gamma_0 \subseteq \Gamma$.} logic {\bf L}, a set of formulas $\Delta$ is  $\psi$-saturated in {\bf L} if $\Delta  \nvdash \psi$ and, if $\varphi \notin \Delta$, then $\Delta \cup \{\varphi\} \vdash \psi$.
     \end{defn}

      \begin{rmk}
      \label{prop:phi-sat}
         It is well-known that any  $\psi$-saturated set is a closed theory. Moreover, if $\Gamma \nvdash \psi$ in {\bf L} then there exists a set $\Delta$ which is $\psi$-saturated in {\bf L} and contains $\Gamma$. In particular, this property holds for \DmbC\ and all the other logics to be considered in this paper.
       \end{rmk}

     \begin{defn}
		\label{def:W-can}
		Consider the set $$W_{can} = \{\Delta \subseteq For(\Sigma) \ : \ \Delta \text{ is a } \psi\text{-saturated in \DmbC, for some $\psi \in For(\Sigma)$}\}.$$
	\end{defn}

	\begin{defn}
		Let $Den(\Delta):= \{\varphi \in For(\Sigma) \ : \ O\varphi \in \Delta\}$
	\end{defn}

	\begin{defn}
		\label{def:R-can}
		Let $R_{can}\subseteq W \times W$ be given by:  $$\Delta R_{can} \Theta \text{ iff } Den(\Delta) \subseteq \Theta$$ for $\Delta, \Theta \in W$
	\end{defn}

	\begin{defn}
    \label{def:can-bival-truth}
		For each $\Delta \in W_{can}$, let $v_\Delta: For(\Sigma) \to \A_3$ defined as follows:
        \begin{equation}
            v_\Delta(\alpha) = 
            \begin{dcases}
                T,& \text{if } \alpha \in \Delta, \neg\alpha \notin \Delta\\
                t,& \text{if } \alpha, \neg\alpha \in \Delta\\
                F,& \text{if } \neg\alpha \in \Delta, \alpha \notin \Delta 
            \end{dcases}
        \end{equation}  
	\end{defn}

    \begin{lemma}
        \label{lemma:truth-sat}
        For any $\Delta \in W_{can}$, the following holds:
        \begin{description}
            \item[1.] $\alpha \land \beta \in \Delta$ iff $\alpha,\beta \in \Delta$
            \item[2.]   $\alpha \lor \beta \in \Delta$ iff $\alpha \in \Delta$ or $\beta \in \Delta$
            \item[3.]  $\alpha \to \beta \in \Delta$ iff $\alpha \notin \Delta$ or $\beta \in \Delta$
            \item[4.]  if $\neg \alpha \notin \Delta$ then $\alpha \in \Delta$
            \item[5.]  If $\alpha \in \Delta$ and $\neg \alpha \in \Delta$ then $\circ \alpha \notin \Delta$
            \item[6.]  $\obl \alpha \in \Delta$ iff $\alpha \in \Delta\prim$ for all $\Delta\prim \in W$ such that $\Delta R_{can} \Delta\prim$.
        \end{description}
    \end{lemma}

    \begin{proof}
        Items 1. through 5. are immediate from the definitions and the fact that $\Delta$ is $\varphi$-saturated, hence, by \cref{prop:phi-sat}, it is closed under logical consequences. In particular, it contains any instance of the axioms of \DmbC, and it is closed under Modus Ponens.

        To prove the right-to-left direction for 6., assume that $\obl \alpha \notin \Delta$. Since $\Delta$ is closed under logical consequences, it follows that $\nvdash_{\DmbC} \alpha$, because of the $\obl$-necessitation rule. Suppose, for a contradiction, that $Den(\Delta) \vdash_{\DmbC} \alpha$. By \cref{def:derivations}, there are $\beta_1, \dots, \beta_n \in Den(\Delta)$ (for $n\geq 1$) such that  
        $$\vdash_{\DmbC} \beta \to \alpha,$$ 
        where $\beta=\beta_1 \land \ldots \land \beta_n$. By applying necessitation and \axK, 
        $$\vdash_{\DmbC} \obl \beta \to \obl \alpha.$$ 
        Observe now that $\obl\beta_i \in \Delta$, by definition of  $Den(\Delta)$, hence $\obl\beta_1 \land \ldots \land \obl \beta_n \in \Delta$, by item~1. But 
        $$\vdash_{\DmbC} (\obl\beta_1 \land \ldots \land \obl \beta_n) \to \obl\beta,$$ 
        hence $\obl \beta \in \Delta$. Using again that $\Delta$ is closed under logical consequences, we infer that  $\obl \alpha \in \Delta$, which contradicts our initial assumption. 

        We conclude, therefore, that $Den(\Delta) \nvdash_{\DmbC} \alpha$. But then, there is some $\Delta\prim$ such that $Den(\Delta) \subseteq \Delta\prim$ and $\Delta\prim$ is $\alpha$-saturated. Therefore, there is $\Delta\prim \in W_{can}$ such that $\Delta R_{can} \Delta\prim$ and $\alpha \notin \Delta\prim$.

        The proof of the left-to-right direction for 6. is immediate from the definitions. Indeed, if   $\obl \alpha \in \Delta$  and  $\Delta R_{can} \Delta\prim$ then $\alpha \in \Delta\prim$, given that $\alpha \in  Den(\Delta)$.
    \end{proof}

	\begin{prop}
		\label{prop:TruthLemma}
		The triple  $\M = \langle W_{can}, R_{can}, \{v_\Delta\}_{\Delta \in W_{can}} \rangle$ is a swap Kripke model for {\DmbC} such that $v_\Delta(\varphi) \in \mathcal{D}$ if and only if $\varphi \in \Delta$ if and only if $\alpha_{(1,\Delta)}=1$.
	\end{prop}
    \begin{proof}
		Observe first that $R_{can}$ is serial. To see this, let $\Delta \in W_{can}$. Then, $\Delta$ is $\varphi$-saturated, for some formula $\varphi$. Suppose that $\obl\alpha \in \Delta$, for every formula $\alpha$. Then, $\obl\alpha, \obl\neg\alpha, \obl{\circ}\alpha \in \Delta$ and so, since $\Delta$ is a closed theory, $\obl \bot_\alpha \in \Delta$. This shows that $\bot_\alpha \in \Delta$, by $(\obl-E)$ and so $\varphi \in \Delta$, a contradiction. From this, $\obl\alpha \notin\Delta$ for some $\alpha$. By reasoning as in the proof of item~6. of \cref{lemma:truth-sat}, we infer that $Den(\Delta) \nvdash_{\DmbC} \alpha$ and so there exists  some $\Delta\prim$ such that $Den(\Delta) \subseteq \Delta\prim$ and $\alpha \notin   \Delta\prim$. This shows that  $R_{can}$ is serial. The rest of the proof is an immediate consequence from \cref{prop:designated-dmbc} and \cref{def:can-bival-truth}.
	\end{proof}


    \begin{thm}[Completeness of \DmbC\ w.r.t. swap Kripke models] \ \\
		For any set $\Gamma \cup \{\varphi\} \subseteq For_\Sigma$, if $\Gamma \vDash_{\DmbC} \varphi$, then $\Gamma \vdash_{\DmbC} \varphi$.
	\end{thm}
	\begin{proof}
		Suppose, to the contrary, that $\Gamma \nvdash_{\DmbC} \varphi$. Thus, by \cref{prop:phi-sat}, there is some $\varphi$-saturated $\Delta \in W_{can}$ such that $\Gamma \subseteq \Delta$. Since $\Delta \nvdash_{\DmbC} \varphi$, then $\varphi \notin \Delta$. Let $\mathcal{M}^{K-S}_{DmbC}$ be the canonical swap model for DmbC. Then, $\mathcal{M}^{K-S}_{DmbC}, \Delta \vDash \Gamma$, since $\Gamma \subseteq \Delta$, but $\mathcal{M}^{K-S}_{DmbC}, \Delta \nvDash \varphi$.   This proves that $\Gamma \nvDash_{\DmbC} \varphi$.
	\end{proof}

