\section{Some extensions of {\DmbC}}

\begin{defn}
	\label{def:ciw}
	Consider the following axioms over the signature $\Sigma$:
    \begin{description}
        \item[(ciw)] ${\circ}\alpha \lor (\alpha \land \neg \alpha)$ 
        \item[(ci)]  $\neg {\circ} \alpha \to (\alpha \land \neg \alpha)$
        \item[(cf)] $\neg \neg \alpha \to \alpha$
    \end{description}
    The following systems can be thus defined:
    \begin{itemize}
        \item ${\DmbCciw} \defeq \DmbC\cup\{\textbf{(ciw)}\}$ 
        \item ${\DmbCci} \defeq \DmbC\cup \{\textbf{(ci)}\}$
        \item ${\DbC} \defeq \DmbC\cup\{\textbf{(cf)}\}$
        \item ${\DCi} \defeq \DmbCci \cup \{\textbf{(cf)}\}$
    \end{itemize}
\end{defn}



\begin{rmk}
   This section will talk about results that can be easily adaptable to each of the aforementioned cases. From now on, by $\textbf{L}$ we will refer to any system in the set $\{\DmbCciw,\DmbCci,\DbC,\DCi\}$.
The notion of derivation $\Gamma \vdash_{\bf L}\varphi$ in {\bf L} is as in \cref{def:derivations} (with the corresponding set of axioms of each logic).
\end{rmk}

The multialgebras to accommodate each of the axioms are defined as follows:

\begin{defn} \label{def:swap-negbC}
    Let $\A_3$ be the swap structure for {\DmbC}. The multioperators of the swap structure for {\DbC} are defined as in \cref{def:swapOperations}, with the exception of $\aneg$, which is substituted for $$\aneg_1 a = \{c \in A \ : \  c_1 = a_2 \text{ and } c_2 \leq a_1 \}.$$
\end{defn}

The non-deterministic truth-table for $\aneg_1$ is as follows:

\begin{center}

\begin{tabular}{|l|c|}
\hline
 & $\aneg_1$ \\ \hline
$T$ & $\{F\}$ \\ \hline
$t$ & $\{T,t\}$\\ \hline
$F$ & $\{T\}$\\ \hline
\end{tabular}

\end{center}


\begin{defn}
    \label{def:swapOp-ext}
    Let $\A_3$ be the swap structure for {\DmbC}. The multioperators of the swap structure for {\DmbCciw}, {\DmbCci} and  {\DCi} are defined as in \cref{def:swapOperations}, with exception of the multioperators that are mentioned in this definition, which are substituted accordingly.

    \begin{enumerate}
        \item  In {\DmbCciw}: $\acirc_1 a := \{c \in A \ : \ c_1 = {\sim} (a_1 \sqcap a_2)\}$.
        \item  In {\DmbCci}: $\acirc_2 a = \{({\sim} (a_1 \sqcap a_2), a_1\sqcap a_2) \}$.
        \item In {\DCi}, take $\acirc_2$ from {\DmbCci} and $\aneg_1$ from {\DbC}.
    \end{enumerate}
\end{defn}


The non-deterministic truth-tables for $\acirc_1$ and $\acirc_2$ are as follows:

\begin{center}
\begin{tabular}{|l|c|}
\hline
 & $\acirc_1$ \\ \hline
$T$ & $\{T,t\}$ \\ \hline
$t$ & $\{F\}$\\ \hline
$F$ & $\{T,t\}$\\ \hline
\end{tabular}
\hspace{2cm}
\begin{tabular}{|l|c|}
\hline
 & $\acirc_2$ \\ \hline
$T$ & $\{T\}$ \\ \hline
$t$ & $\{F\}$\\ \hline
$F$ & $\{T\}$\\ \hline
\end{tabular}

\end{center}




\begin{defn}
\label{def:swapval-ext}
       For each $w \in W$, we establish the following:

       \begin{itemize}
           \item The swap valuations for {\DmbCciw}, $\nuciw_w$, are defined  as in \cref{def:nu_w} for all operators, except for $\circ$, which satisfies the following condition:$$\nuciw_w({\circ} \alpha) \in \acirc_1 \nuciw_w (\alpha). $$
           \item The swap valuations for {\DmbCci}, $\nuci_w$, are defined as  in \cref{def:nu_w} for all operators, except for $\circ$, which satisfies the following condition:$$\nuci_w({\circ} \alpha) \in \acirc_2 \nuci_w (\alpha). $$
           \item The swap valuations for {\DbC}, $\nubc_w$, are defined as  in \cref{def:nu_w} for all operators, except for $\neg$, which satisfies the following condition:$$\nubc_w({\neg} \alpha) \in \aneg_1 \nubc_w (\alpha). $$
           \item The swap valuations for {\DCi}, $\nuCi_w$, are  defined as  in \cref{def:nu_w} for all operators, except for $\neg$, which is defined using $\aneg_1$ as in the case of \DbC\ and for $\circ$, which is defined using $\acirc_2$ as in the case of {\DmbCci}.
       \end{itemize}
\end{defn}


\begin{defn}
    The structure $\M = \langle W, R, \{v_w^{\textbf{L}}\}_{w \in W} \rangle$ is a swap Kripke model for the logic $\textbf{L}$.
\end{defn}

We maintain an analogous notation to the one presented in \cref{rmk:notation}. Notice that this implies that $v_w^{\textbf{L}}(\alpha) \in \D$ if and only if $\alpha_{(1,w)} = 1$. We use this fact in the next proof.

\begin{lemma}
    \label{lemma:proj-nu-ext}
    Conditions 1.-6. listed on \cref{lemma:proj-nu_w} hold for $\textbf{L}$. Moreover, consider the following conditions:
    \begin{description}
        \item[5$\prim$.]  $(\circ \alpha)_{(1,w)} = {\sim} (\alpha_{(1,w)} \sqcap \alpha_{(2,w)})$.
        \item[5$^*$.] $(\circ\alpha)_{(1,w)} = {\sim} (\alpha_{(1,w)} \sqcap \alpha_{(2,w)})$ and $(\circ\alpha)_{(2,w)} = (\alpha_{(1,w)} \sqcap \alpha_{(2,w)}) $.
        \item[7.] $(\neg\alpha)_{(2,w)} \leq \alpha_{(1,w)}$.
    \end{description}
    Then, condition $5\prim$ holds in {\DmbCciw}; condition $5^*$ holds in {\DmbCci}; condition $7$ holds in {\DbC}; and conditions $5^*$ and $7$ hold in {\DCi}.
    %Conditions $5\prim$ and $5^*$ substitute condition $5$ in \cref{lemma:proj-nu_w}, while condition $7$ is added to the other ones.
\end{lemma}

\begin{proof}
 For {\DbC},  condition $7$ follows by  \cref{def:swap-negbC} and \cref{def:swapval-ext}: $\nubc_w (\neg\alpha) \in \aneg_1 \nubc_w (\alpha)$, and so $(\neg \alpha)_{(2,w)} \leq \alpha_{(1,w)}$.

    For {\DmbCciw} and  {\DmbCci}, condition $5\prim$ and $5^*$ follow, respectively, by \cref{def:swapOp-ext} and \cref{def:swapval-ext}. 

    The case of {\DCi} follows from  {\DmbCci} and {\DbC}. 
\end{proof}

\begin{defn}
		Let $\mathcal{M}^{K-S}_{\textbf{L}} = \langle W^{\textbf{L}}, R^{\textbf{L}}, \{\nu^{\textbf{L}}_w\}_{w \in W}  \rangle$ be as above. Then, a formula $\alpha \in For_\Sigma$ is said to be $\mathcal{M}^{K-S}_{\textbf{L}}$-true in a world $w$, denoted by $\mathcal{M}^{K-S}_{\textbf{L}}, w \vDash \alpha$, if it is the case that $\nu^{\textbf{L}}_w(\alpha) \in \mathcal{D}$.
	\end{defn}


	\begin{defn}
		Let $\Gamma \cup\{\alpha\} \subseteq For_\Sigma$. We say that $\alpha$ is a logical consequence of $\Gamma$ in {\bf L}, denoted by $\Gamma \vDash_{\bf L} \alpha$, if for all $\mathcal{M}^{K-S}_{\textbf{L}}$ and $w \in W$:  $\mathcal{M}^{K-S}_{\textbf{L}}, w \vDash \Gamma$ implies that $\mathcal{M}^{K-S}_{\textbf{L}}, w \vDash \alpha$.
	\end{defn}


    \begin{thm}[Soundness]
        For every $\Gamma \cup \{\varphi\} \subseteq For(\Sigma)$, $$\text{if }\Gamma \vdash_{\textbf{L}} \varphi \text{, then } \Gamma \vDash_{\textbf{L}} \varphi$$
    \end{thm}

    \begin{proof} Consider first \DmbCciw. Given a valuation $v_w$ and a formula $\alpha$, it must be shown that $(\circ\alpha \vee (\alpha \land \neg \alpha))_{(1,w)}=1$. By the  definition of the multioperator $\tilde{\vee}$ in \cref{def:swapOperations}, the latter is equivalent to prove that either $(\circ\alpha)_{(1,w)}=1$ or $(\alpha \land \neg \alpha)_{(1,w)}=1$. But this is immediate, by property $5\prim$ of $v_w$ given in \cref{lemma:proj-nu-ext} and the fact that $(\alpha \land \neg \alpha)_{(1,w)}=\alpha_{(1,w)} \sqcap \alpha_{(2,w)}$.

        In {\DmbCci}, it must be shown that \textbf{(ci)} is valid. Given $v_w$, assume that $(\neg{\circ}\alpha)_{(1,w)}=1$. Thus, we have $$(\neg{\circ}\alpha)_{(1,w)} = (\circ\alpha)_{(2,w)} = (\alpha_{(1,w)} \sqcap \alpha_{(2,w)}) =1,$$ 
    by property $5^*$ of $v_w$. This shows that $v_w$ satisfies any instance of axiom  \textbf{(ci)}.

       For \DbC, the case  for \textbf{(cf)} is immediate from  property $7$ in \cref{lemma:proj-nu-ext}.

       Clearly, soundness of {\DCi} follows from soundness of {\DmbCci} and {\DbC}.
    \end{proof}


    For every logic in $\textbf{L}$, we define $W^\textbf{L}_{can}, R^\textbf{L}_{can}$ and $\nu^\textbf{L}_{\Delta}$ following the definitions for {\DmbC} and adapting to each \textbf{L} accordingly. Notice that each $\Delta$ is now a $\psi$-saturated set in $W^\textbf{L}_{can}$ This allows us to state the following lemma:  

    \begin{lemma}
        \label{lemma:truth-sat-ext}
        For any $\Delta \in W^\textbf{L}_{can}$, all statements 1. through 6. in \cref{lemma:truth-sat} hold.

        For \DmbCciw, we have the following strengthening of statement 5.:
        \begin{description}
            \item[5$^+_1$.]  $\alpha \in \Delta$ and $\neg \alpha \in \Delta$ iff $\circ \alpha \notin \Delta$
        \end{description}

        For \DmbCci, we have an additional condition for $\circ$: 
        \begin{description}
            \item[5$^+_2$.]  If $\neg{\circ}\alpha \in \Delta$, then $\alpha \in \Delta$ and $\neg \alpha \in \Delta$.
        \end{description}

        For \DbC, we have an additional condition for $\neg$: 
        \begin{description}
            \item[5$^+_3$.]  If $\neg \neg \alpha \in \Delta$, then $\alpha \in \Delta$.
        \end{description}

        For \DCi, both conditions $5^+_2$ and $5^+_3$ are added.
    \end{lemma}

    \begin{proof}
       All conditions  are easily proved by using the respective new axiom of {\bf L}, and the fact that $\Delta$ is saturated (hence it is a closed theory). 
    \end{proof}

    \begin{prop}
		\label{prop:TruthLemma-ext}
		The triple  $\M_\textbf{L} = \{W^\textbf{L}_{can}, R^\textbf{L}_{can}, \{\nu^\textbf{L}_\Delta\}_{\Delta \in W_{can}}\}$ is a swap Kripke model for \textbf{L} such that $\nu^{\textbf{L}}_\Delta(\varphi) \in \mathcal{D}$ if and only if $\varphi \in \Delta$ if and only if $\alpha_{(1,\Delta)}=1$.
	\end{prop}

    \begin{proof}
		It is an immediate consequence from \cref{lemma:truth-sat-ext} and \cref{def:can-bival-truth}. For instance, in order to prove that $\nu^{\DmbCci}_\Delta(\circ\alpha) \in \acirc_2 \nu^{\DmbCci}_\Delta(\alpha)$, let $z:=\nu^{\DmbCci}_\Delta(\alpha)$. Suppose first that  $z \in \{T,F\}$. By \cref{def:can-bival-truth}, either $\alpha \notin \Delta$ or $\neg\alpha \notin \Delta$. By 5$^+_1$ and  5$^+_2$ of  \cref{lemma:truth-sat-ext}, $\circ\alpha  \in \Delta$ and $\neg {\circ}\alpha  \notin \Delta$. From this, $\nu^{\DmbCci}_\Delta(\circ\alpha)=T \in \{T\}= \acirc_2 z$. Now, if  $z =t$ then $\alpha,\neg\alpha \in \Delta$ and so, by 5$^+_1$, $\circ\alpha  \notin \Delta$. Hence, $\nu^{\DmbCci}_\Delta(\circ\alpha)=F \in \{F\}= \acirc_2 z$. In turn, in order to prove that  $\nu^{\DbC}_\Delta(\neg\alpha) \in \aneg_1 \nu^{\DbC}_\Delta(\alpha)$, let $z:=\nu^{\DbC}_\Delta(\alpha)$. If $z=T$ then $\alpha \in \Delta$ and $\neg\alpha \notin\Delta$. From this, $\nu^{\DbC}_\Delta(\neg\alpha)=F \in \{F\}= \aneg_1 z$.  If $z=t$ then $\alpha, \neg\alpha \in\Delta$. From this, $\nu^{\DbC}_\Delta(\neg\alpha) \in \{T,t\}= \aneg_1 z$. Finally, if  $z=F$ then $\alpha \notin \Delta$ and $\neg\alpha \in\Delta$. By 5$^+_3$ of  \cref{lemma:truth-sat-ext}, $\neg\neg\alpha  \notin \Delta$ and so $\nu^{\DbC}_\Delta(\neg\alpha)=T \in \{T\}= \aneg_1 z$. The other cases are treated analogously.
	\end{proof}


    \begin{thm}[Completeness]
		For any set $\Gamma \cup \{\varphi\} \subseteq For(\Sigma)$, if $\Gamma \vDash_\textbf{L} \varphi$, then $\Gamma \vdash_\textbf{L} \varphi$
	\end{thm}
	\begin{proof}
		This is proved in analogous way as to the {\DmbC} case.
	\end{proof}


