\section{The da Costa axiom: the case of \DmbCcl}

In this section, as well as in Sections~\ref{sect:DCila}, \ref{sect:C1D} and~\ref{sect:DCn}, we will consider axiomatic extensions of  \DmbC\ which include, among others, the so-called {\em da Costa axiom}
$$\textbf{(cl)}  \ \  \neg (\alpha \land \neg \alpha) \to {\circ} \alpha $$
This move has strong consequences: as it was shown by Avron in~\cite[Theorem~11]{Avron2007a}, the logic  \mbCcl\ obtained by adding \textbf{(cl)} to \mbC, a well as other extensions of  \mbCcl\ (including \Cila, the version of da Costa's system $C_1$ in a signature with $\circ$) cannot be semantically characterized by a single finite $N$matrix. As shown by Coniglio and Toledo in~\cite{ConiglioToledo2022}, this issue can be overcome by considering, for each of such systems, a suitable (finite--valued)  Nmatrix and restrict the set  of permitted valuations by a (decidable) criterion, through the notion of {\em restricted Nmatrices}  (or RNmatrices).

We will adapt this technique to our swap Kripke models, in order to deal with the deontic expansion of (some of) such systems. 

This section starts our analysis by considering \DmbCcl. The logic {\DmbCcl} is the extension of \DmbC\ by adding axiom \textbf{(cl)}. It is easy to show that \DmbCcl\ is a proper extension of {\DmbCciw}: this follows from the fact that the system {\mbCcl} is a proper extension of the system {\mbCciw}, which is obtained from \mbC\ by adding \textbf{(ciw)} \cite[Corollary~3.3.30]{Carnielli2016}. 
We thus present a swap Kripke semantics for {\DmbCcl} as the corresponding one for  {\DmbCciw}, together with a restriction on their valuations.
%This approach closely follows the proposal given in~\cite{ConiglioToledo2022}, in which  $RN$matrices were introduced as a way to overcome the uncharacterizability of {\mbCcl} and da Costa systems $C_n$ by means of finite-valued $N$matrices.

%    In the sequel, we follow~\cite{ConiglioToledo2022} in restricting our valuations and show that the results shown there can also be applied to modal extensions of \mbCcl.


   \begin{defn}
        \label{def:nu_cL}
    A swap Kripke model $\M^{K-S}_{\DmbCcl} = \langle W,R,\{\nucL_w\}_{w \in W}\rangle$ for \DmbCcl\ is a swap Kripke model  for \DmbCciw\ such that each valuation $\nucL_w$ satisfies, in addition, the following condition:
    $$\text{If }\nucL_w(\alpha) = t \text{, \ then \ } \nucL_w(\alpha \land \neg \alpha) = T.$$ 
  \end{defn}


    \begin{defn}
		Let $\mathcal{M}^{K-S}_{DmbCcl} = \langle W, R, \{\nucL_w\}_{w \in W}  \rangle$ be a  swap Kripke model for \DmbCcl. We say that a formula $\alpha \in For(\Sigma)$ is $\mathcal{M}^{K-S}_{\DmbCcl}$-true in a world $w$, denoted by $\mathcal{M}^{K-S}_{\DmbCcl}, w \vDash \alpha$, if $\nucL_w(\alpha) \in \mathcal{D}$.
	\end{defn}

\begin{defn}
		Let $\Gamma \cup \{\alpha\ \subseteq For(\Sigma)$. We say that $\alpha$ is a logical consequence of $\Gamma$ in \DmbCcl, denoted by $\Gamma \vDash_{\DmbCcl} \alpha$, if for all $\mathcal{M}^{K-S}_{\DmbCcl}$ and all $w \in W$: $\mathcal{M}^{K-S}_{\DmbCcl}, w \vDash \Gamma$ implies that $\mathcal{M}^{K-S}_{\DmbCcl}, w \vDash \alpha$.
\end{defn}


    The following lemma will be useful for showing soundness of  \DmbCcl\ w.r.t. swap Kripke models semantics.

    \begin{lemma}
        \label{lemma:proj-nu-c}
        Given the notation on \cref{rmk:notation}, let $\nucL_w$ be a valuation in a swap Kripke model $\M^{K-S}_{\DmbCcl}$ for \DmbCcl. Then, the following holds, for every formula $\alpha$:
        \begin{description}
            \item[5$^{**}$.] $({\circ}\alpha)_{(1,w)} = (\alpha \land \neg \alpha)_{(2,w)}$
        \end{description}
        Hence, any instance of axiom \textbf{(cl)} is true in any world of any swap Kripke model for \DmbCcl.
    \end{lemma}

    \begin{proof}
        By \cref{lemma:proj-nu-ext},  $(\circ \alpha)_{(1,w)} = {\sim} (\alpha_{(1,w)} \sqcap \alpha_{(2,w)})$. Suppose that  $({\circ}\alpha)_{(1,w)} =1$. Then, $\alpha_{(1,w)} \sqcap \alpha_{(2,w)}=(\alpha \land \neg\alpha)_{(1,w)}=0$. By definition of $A$, it follows that  $(\alpha \land \neg\alpha)_{(2,w)}=1=({\circ}\alpha)_{(1,w)}$. Now, suppose that $({\circ}\alpha)_{(1,w)} = 0$. Then, $\alpha_{(1,w)} \sqcap \alpha_{(2,w)}=\alpha_{(1,w)} \sqcap (\neg\alpha)_{(1,w)}=(\alpha \land \neg\alpha)_{(1,w)}=1$. From this, $\alpha_{(1,w)} = \alpha_{(2,w)}=1$, which means that $\nucL_w(\alpha) = (1,1)=t$. By \cref{def:nu_cL}, $\nucL_w(\alpha \land \neg \alpha) =T= (1,0)$. Hence, $(\alpha \land \neg\alpha)_{(2,w)}=0=({\circ}\alpha)_{(1,w)}$.

        The latter shows that any instance of axiom \textbf{(cl)} is true in any world of any swap Kripke model for \DmbCcl.
    \end{proof}

\begin{thm}[Soundness of \DmbCcl\ w.r.t. swap Kripke models] \ \\
        For every $\Gamma \cup \{\varphi\} \subset For(\Sigma)$, $$\text{if }\Gamma \vdash_{\DmbCcl} \varphi \text{, then } \Gamma \vDash_{\DmbCcl} \varphi.$$
\end{thm}

    \begin{proof}
        It follows from soundness of $\DmbCciw$ and \cref{lemma:proj-nu-c}.
    \end{proof}

In order to prove completeness for {\DmbCcl}, we will use the canonical model once again, to be constructed as in the case for {\DmbCciw}. Since the restriction occurs only on the valuations, we take only those valuations that are restricted appropriately. Hence, $W^{\DmbCcl}_{can}, R^{\DmbCcl}_{can}$ and $\nu^{\DmbCcl}_{\Delta}$ are defined as in {\DmbCciw}. Now, each $\Delta \in W^{\DmbCcl}_{can}$ is a $\psi$-saturated set in ${\DmbCcl}$. Thus we have:

 \begin{lemma}
        \label{lemma:truth-sat-cl}
        For any $\Delta \in W^{\DmbCcl}_{can}$, all statements for {\DmbCciw} stated in \cref{lemma:truth-sat-ext} hold. Besides, we add the following statement:
        \begin{description}
            \item[7.] If $\neg (\alpha \land \neg \alpha) \in \Delta$, then $\circ\alpha \in \Delta$.
        \end{description}
    \end{lemma}
    \begin{proof}
        Given that \DmbCcl\ extends \DmbCciw, it is an immediate consequence of \cref{lemma:truth-sat-ext}, axiom \textbf{(cl)}, and the fact that $\Delta$ is a closed theory.
    \end{proof}

    \begin{prop}
		\label{prop:TruthLemma-cl}
		The triple  $\M = \{W^{\DmbCcl}_{can}, R^{\DmbCcl}_{can}, \{\nu^{\DmbCcl}_\Delta\}_{{\Delta \in W}^{\DmbCcl}_{can}}\}$, constructed as in the case of \DmbC, is a swap Kripke model for {\DmbCcl} such that $\nu^{{\DmbCcl}}_\Delta(\varphi) \in \mathcal{D}$ if and only if $\varphi \in \Delta$ if and only if $\alpha_{(1,\Delta)}=1$.
	\end{prop}
    \begin{proof}
      Observe that each valuation $\nu^{\DmbCcl}_\Delta$ is defined according to \cref{def:can-bival-truth}. Since  \DmbCcl\ extends \DmbCciw, it follows that $\M$ is a swap  Kripke model for {\DmbCciw} such that $\nu^{{\DmbCcl}}_\Delta(\varphi) \in \mathcal{D}$ if and only if $\varphi \in \Delta$ if and only if $\alpha_{(1,\Delta)}=1$. In order to show that each  $\nu^{\DmbCcl}_\Delta$  satisfies the additional condition of \cref{def:nu_cL}, suppose that  $\nu^{{\DmbCcl}}_\Delta(\alpha)=t$. By \cref{def:can-bival-truth}, $\alpha, \neg\alpha \in \Delta$ and so $\alpha \land \neg\alpha \in \Delta$. Suppose that $\neg(\alpha \land \neg\alpha) \in \Delta$. By \cref{lemma:truth-sat-cl}, $\circ\alpha \in \Delta$. But then, by axiom \textbf{(bc)}, $\beta \in \Delta$, for every formula $\beta$, a contradiction. From this, $\neg(\alpha \land \neg\alpha) \notin \Delta$, therefore $\nu^{{\DmbCcl}}_\Delta(\alpha\land \neg\alpha)=T$, by \cref{def:can-bival-truth}. This shows that $\M$ is, in fact, a swap Kripke model for \DmbCcl.      
	\end{proof}

From the previous results and the construction above, it is easy to show that completeness holds for \DmbCcl.

\begin{thm}[Completeness of \DmbCcl\ w.r.t. swap Kripke models] \ \\
	For any set $\Gamma \cup \{\varphi\} \subseteq For(\Sigma)$, if $\Gamma \vDash_{\DmbCcl} \varphi$, then $\Gamma \vdash_{\DmbCcl} \varphi$
\end{thm}



