\section{Swap Kripke models for \DCila} \label{sect:DCila}


Consider the following axiom schemas for {\em consistency propagation}:
    \begin{description}
        \item[(ca$_{\#}$)] $({\circ} \alpha \land {\circ} \beta) \to {\circ}(\alpha \# \beta)$,  where $\# \in \{\land, \lor, \to\}$
    \end{description}

We now add to {\DmbC} the axioms {\bf (ci)}, {\bf (cl)}, {\bf (cf)} and {\bf (ca$_\#$)}, obtaining a logic called \DCila. Equivalently, \DCila\ is obtained from \DmbCcl\ by adding axioms  {\bf (ci)}, {\bf (cf)} and {\bf (ca$_\#$)}. The non-modal fragment of \DCila\ is called \Cila, and corresponds to da Costa logic $C_1$ presented over the signature with $\circ$  (see~\cite[Section~5.2]{Marcos2007}). Indeed,  \Cila\ is a conservative expansion of da Costa's ${C}_1$. As proved in~\cite[Theorem~11 and Corollary~6]{Avron2007a},  \Cila\ and $C_1$ are not characterizable by a single finite $N$matrix.


Based on the results presented in the previous section, as well as the characterization of \Cila\ in terms of a 3-valued $RN$matrix found in~\cite{ConiglioToledo2022}, in the sequel we will characterize  \DCila\ by means of swap Kripke models based on a suitable 3-valued  $RN$matrix for \Cila.


\begin{defn}
        \label{def:nu_Cila}
    A swap Kripke model $\M^{K-S}_{\DCila} = \langle W,R,\{\nucila_w\}_{w \in W}\rangle$ for \DCila\ is a swap Kripke model  for \DCi\ such that each valuation $\nucila_w$ satisfies, in addition, the following conditions, for $\# \in \{\land, \lor, \to\}$:
    $$\text{If }\nucila_w(\alpha) = t \text{, \ then \ } \nucila_w(\alpha \land \neg \alpha) = T$$
    $$\text{If } \nucila_w(\alpha), \nucila_w(\beta) \in \{T,F\} \text{, then } \nucila_w(\alpha \# \beta) \in \{T,F\}.$$   
  \end{defn}

Note that the first condition on  $\nucila_w$ coincides with the one for  $\nucL_w$.

The notions of satisfaction of a formula $\alpha$ in a  world $w$ of a  swap Kripke model $\mathcal{M}^{K-S}_{DCila}$ for \DCila, denoted by $\mathcal{M}^{K-S}_{\DCila}, w \vDash \alpha$, as well as the semantical consequence  of \DCila\ w.r.t.  swap Kripke models, denoted by $\vDash_{\DCila}$, are defined as in the previous cases.

The above definitions guarantee that the axioms   $\textbf{(cl)}$ and {\bf (ca$_{\#}$)}  hold. Indeed:

\begin{lemma}
        \label{lemma:proj-nu-cila}
        Any instance of the axioms   $\textbf{(cl)}$ and {\bf (ca$_{\#}$)} are true in any world of any swap Kripke model for \DCila.
    \end{lemma}
    \begin{proof} Concerning   $\textbf{(cl)}$, the result holds by \cref{lemma:proj-nu-c} and \cref{def:nu_Cila}. Fix now $\# \in \{\land, \lor, \to\}$ and $\nucila_w$. Observe that, for any $\alpha$, $\nucila_w(\alpha) \in \{T,F\}$ iff $\alpha_{(1,w)} \neq \alpha_{(2,w)}$ iff $\alpha_{(1,w)} \sqcap \alpha_{(2,w)}=0$  iff $(\circ \alpha)_{(1,w)}={\sim} (\alpha_{(1,w)} \sqcap \alpha_{(2,w)})=1$. From this, $\nucila_w({\circ} \alpha \land {\circ} \beta) \in  \mathcal{D}$ implies that $({\circ} \alpha \land {\circ} \beta)_{(1,w)}=1$, which implies that  $({\circ} \alpha)_{(1,w)}= ({\circ} \beta)_{(1,w)}=1$. As observed above, the latter implies that $\nucila_w(\alpha), \nucila_w(\beta) \in \{T,F\}$, and so $\nucila_w(\alpha \# \beta) \in \{T,F\}$, by \cref{def:nu_Cila}. But this implies that $({\circ} (\alpha \# \beta))_{(1,w)}=1$, that is, $\nucila_w({\circ}(\alpha \# \beta)) \in  \mathcal{D}$. This shows that any instance of axiom {\bf (ca$_{\#}$)} is true in any world of any swap Kripke model for \DCila.
    \end{proof}

    As shown in \cite{ConiglioToledo2022}, the above characterization of \Cila\ by means of a 3-valued $RN$matrix induces a decision procedure for this logic. Given that SDL is decidable (for instance, by tableaux systems), so is  its modal extension \DCila.

    Now,  soundness of  {\DCila} w.r.t. swap Kripke models  follows easily from the previous results.

    \begin{thm}[Soundness of \DCila\ w.r.t. swap Kripke models] \ \\
        For every $\Gamma \cup \{\varphi\} \subseteq For(\Sigma)$, if $\Gamma \vdash_{\DCila} \varphi$, then $\Gamma \vDash_{\DCila} \varphi$.
    \end{thm}

    \begin{proof}
        It follows from soundness of $\DCi$ and \cref{lemma:proj-nu-cila}.
    \end{proof}

    The proof of completeness is a straightforward adaptation of the case for $\DmbCcl$, by building the canonical model as in the case for {\DCi}, and by imposing suitable restrictions on the valuations. Thus, $W^{\DCila}_{can}, R^{\DCila}_{can}$ and $\nu^{\DCila}_{\Delta}$are defined as in {\DCi}, but now each $\Delta \in W^{\DCila}_{can}$ is a $\psi$-saturated set in ${\DCila}$. 

 \begin{lemma}
        \label{lemma:truth-sat-cila}
        For any $\Delta \in W^{\DCila}_{can}$, all statements for {\DCi} stated in \cref{lemma:truth-sat-ext} hold. Besides, $\Delta$ satisfies the following statements:
        \begin{description}
            \item[7.] If $\neg (\alpha \land \neg \alpha) \in \Delta$, then $\circ\alpha \in \Delta$.
            \item[8.] If ${\circ} \alpha, {\circ} \beta \in \Delta$, then ${\circ}(\alpha \# \beta) \in \Delta$,  where $\# \in \{\land, \lor, \to\}$.
        \end{description}
    \end{lemma}
    \begin{proof}
        \DmbCcl\ extends \DCi. From this, the result is an immediate consequence of \cref{lemma:truth-sat-ext}, axioms \textbf{(cl)} and  {\bf (ca$_\#$)}, and the fact that $\Delta$ is a closed theory.
    \end{proof}

    \begin{prop}
		\label{prop:TruthLemma-cila}
		The triple  $\M = \{W^{\DCila}_{can}, R^{\DCila}_{can}, \{\nu^{\DCila}_\Delta\}_{{\Delta \in W}^{\DCila}_{can}}\}$, constructed as in the case of \DmbC, is a swap Kripke model for {\DCila} such that $\nu^{{\DCila}}_\Delta(\varphi)
 \in \mathcal{D}$ if and only if $\varphi \in \Delta$ if and only if $\alpha_{(1,\Delta)}=1$.
	\end{prop}
    \begin{proof}
      Notice that each valuation $\nu^{\DCila}_\Delta$ is defined according to \cref{def:can-bival-truth}. Given that  \DCila\ extends \DCi, it follows that $\M$ is a swap  Kripke model for {\DCi} such that $\nu^{{\DCila}}_\Delta(\varphi) \in \mathcal{D}$ if and only if $\varphi \in \Delta$ if and only if $\alpha_{(1,\Delta)}=1$. Let us prove now that every  $\nu^{\DCila}_\Delta$  satisfies the additional conditions of \cref{def:nu_Cila}. The first condition is proved analogously to the case for \DmbCcl\ (see the proof of \cref{prop:TruthLemma-cl}). In order to prove the second condition  of \cref{def:nu_Cila}, observe first the following:\\[1mm]
      {\bf Fact:}  $\nu^{\DCila}_\Delta(\alpha) \in \{T,F\}$ if and only if  $\circ\alpha \in \Delta$.\\[1mm]
      Indeed, suppose first that  $\nu^{\DCila}_\Delta(\alpha) \in \{T,F\}$. By  \cref{def:can-bival-truth}, either $\alpha \notin \Delta$ or  $\neg\alpha \notin \Delta$. In both cases, $\alpha \land \neg \alpha \notin \Delta$, hence  $\neg(\alpha \land \neg \alpha) \in \Delta$. By axiom {\bf (cl)} and the properties of $\Delta$, $\circ\alpha \in \Delta$. Conversely, suppose that $\circ\alpha \in \Delta$.  By axiom {\bf (bc)} and the properties of $\Delta$, either $\alpha \notin \Delta$ or $\neg\alpha \notin \Delta$. By \cref{def:can-bival-truth}, $\nu^{\DCila}_\Delta(\alpha) \in \{T,F\}$.

      Fix now  $\# \in \{\land, \lor, \to\}$, and suppose that $ \nucila_\Delta(\alpha), \nucila_\Delta(\beta) \in \{T,F\}$. By the {\bf Fact}, ${\circ} \alpha, {\circ} \beta \in \Delta$. By axiom  {\bf (ca$_{\#}$)} and by taking into account that $\Delta$ is a closed theory, ${\circ}(\alpha \# \beta) \in \Delta$. By the {\bf Fact} once again, we infer that $\nucila_\Delta(\alpha \# \beta) \in \{T,F\}$.

      This shows that $\M$ is, in fact, a swap Kripke model for \DCila.      
	\end{proof}

From the previous results and the construction above, it is easy to show that completeness holds for \DCila.

    \begin{thm}[Completeness of \DCila\ w.r.t. swap Kripke models] \ \\
	For any set $\Gamma \cup \{\varphi\} \subseteq For(\Sigma)$, if $\Gamma \vDash_{\DCila} \varphi$, then $\Gamma \vdash_{\DCila} \varphi$.
    \end{thm}


    \section{The pioneering system ${C}^D_1$} \label{sect:C1D}

   We highlight the fact that {\Cila} is a conservative expansion of ${C}_1$ by adding the connective $\circ$. While {\Cila} has $\circ$ in its signature, ${C}_1$ defines consistency in terms of non-contradictoriness. That is to say, $C_1$ is defined over the  signature $\Sigma^{C_1} = \{\to , \neg, \lor, \land\}$ such that $\alpha^\circ := \neg (\alpha \land \neg \alpha)$, for any $\alpha \in For(\Sigma^{C_1})$. However, it is easy to show that if we substitute any appearance of $\circ \alpha$ in the axioms or rules for {\Cila} for $\alpha^\circ$, we get ${C}_1$. Moreover, the valid inferences in \Cila\  in the signature $\Sigma^{C_1}$ coincide with the ones in $C_1$ (see~\cite[Theorem~110]{Marcos2007}). Also noticeable is the treatment of strong negation in ${C}_1$, usually defined as $\cneg \alpha := \neg \alpha \land \alpha^\circ$. Let $\Sigma^{C_1}_D := \{\to , \neg, \lor, \land, \obl\}$. Because of the close relationship between  \Cila\ and $C_1$, the $\Sigma^{C_1}_D$-reduct of the swap Kripke models for \DCila\ characterize the deontic expansion \DCone\ of $C_1$, defined over $\Sigma^{C_1}_D$ by adding to $C_1$ the modal deontic axioms of \cref{def:DmbC},  but now by considering $\bot_\alpha:=(\alpha \land  \neg \alpha) \land \alpha^\circ$.
   Observe that, in $C_1$, axioms {\bf (bc)} and {\bf (ca$_{\#}$)} are now replaced  by the following:


	\begin{description}
		\item[(bc)'] $\alpha^\circ \to (\alpha \to (\neg \alpha \to \beta))$
		\item[(ca$_{\#}$)'] $(\alpha^\circ \land \beta^\circ) \to (\alpha \# \beta)^\circ$,  where $\# \in \{\land, \lor, \to\}$
	\end{description}



   In turn, axioms  {\bf (cl)} and {\bf (ci)} are not considered in $C_1$ (since they hold by the very definition of $(\cdot)^\circ$, as well as by axiom {\bf (cf)}).

   One other striking fact is that the pioneering paraconsistent deontic system  ${C}^D_1$ (also defined over $\Sigma^{C_1}_D$) proposed in~\cite{CostaCarnielli1986} has one more axiom in addition to the ones of \DCone, namely

	\begin{description}
		\item[(ca$_{\obl}$)'] $\alpha^\circ \to (\obl\alpha)^{\circ}$
	\end{description}


   Hence, we should be able to accommodate axiom {\bf  (ca$_{\obl}$)'} in our system. However, the system proposed so far does not account for it. Consider the following possible model of ${C}^D_1$. Each node $x$ shows a set $\Gamma$ as a label. This indicates that for every $\varphi \in \Gamma$, $v^{{C}_1}_{\Gamma}(\varphi) \in \D$. We will use an analogous notation in a few more examples: 
    \begin{figure}[H]
    \centering
   \begin{tikzpicture}
       \begin{scope}%
        \node[vertex, label=above: {$\{\alpha^\circ,\obl \alpha, \neg \obl\alpha\}$}] (0) at (0,0) {$w$};
        \node[vertex] (2) at (2,0) {$w\prim$};
        \draw [->] (0) -- (2);
        \node (5) at (4,0) {};
        \path (2) -- (5) node [midway] {$\dots$};
  \end{scope}
   \end{tikzpicture}
   \caption{A representation of a counterexample to {\bf (ca$_{\obl}$)'}, when not adding the suitable restrictions to the models.}
    \end{figure}

   According to this model, $(\alpha^\circ)_{(1,w)} = 1$. But this does not say anything about any of the worlds $w\prim$ accessible to $w$. Notice that $v^{\DCone}_w((\obl \alpha)^{\circ}) \notin \D$ if and only if $v^{\DCone}_w(\obl \alpha) \in \D$ and $v^{\DCone}_w(\neg \obl \alpha) \in \D$. But this is perfectly possible, since when assigning a truth value for $\obl \alpha$, only the first coordinate of the snapshot is determined. Since the first coordinate of $v^{\DCone}_w(\neg \obl \alpha)$ is given by reading the second coordinate of $v^{\DCone}_w(\obl \alpha)$, then $v^{\DCone}_w(\obl \alpha) = (1,1)=t$ is the value that falsifies the formula correspondent to the axiom. Hence, in order to give a proper semantics for the original ${C}^D_1$, we need one more restriction. 

   From now on, for ease of notation, we will write $\nucone_w$ instead of $v^{C^D_1}_w$.%\add{Exemplo}


\begin{defn}
        \label{def:restriction-c1}
    A swap Kripke model $\M^{K-S}_{C^D_1} = \langle W,R,\{\nucone_w\}_{w \in W}\rangle$ for ${C}^D_1$ is a swap Kripke model  for \DCila\ (over the $\Sigma^{C_1}_D$-reduct) such that each valuation $\nucone_w$ satisfies, in addition, the following condition, for $\# \in \{\land, \lor, \to\}$:
%     $$\text{If } \nucone_w(\alpha), \nucone_w(\beta) \in \{T,F\} \text{, then } \nucone_w(\alpha \# \beta) \in \{T,F\};$$
     $$\text{If } \nucone_w(\alpha) \in \{T,F\} \text{, then } \nucone_w(\obl \alpha) \in \{T,F\}.$$ 
  \end{defn}

\begin{rmk} \label{rem:val-C1D}
    Observe that a family of maps $\nucone_w:For(\Sigma^{C_1}_D) \to A$ satisfies \cref{def:restriction-c1} iff it  satisfies the following conditions, for every $\alpha,\beta \in For(\Sigma^{C_1}_D)$ and $\# \in \{\land, \lor, \to\}$:
\begin{enumerate}
    \item items 1.-3. and 6. of \cref{def:nu_w};
    \item $\nucone_w({\neg} \alpha) \in \aneg_1 \nucone_w (\alpha)$, where $\aneg_1$ is as in \cref{def:swap-negbC};
    \item if $\nucone_w(\alpha) = t$, then $\nucone_w(\alpha \land \neg \alpha) = T$;  
    \item if  $\nucone_w(\alpha), \nucone_w(\beta) \in \{T,F\}$, then $\nucone_w(\alpha \# \beta) \in \{T,F\}$;
    \item if  $\nucone_w(\alpha) \in \{T,F\}$, then $\nucone_w(\obl \alpha) \in \{T,F\}$.
\end{enumerate}
\end{rmk}

    \begin{thm}[Soundness of ${C}^D_1$  w.r.t. swap Kripke models] \ \\
        For every $\Gamma \cup \{\varphi\} \subseteq For(\Sigma^{C_1}_D)$, if $\Gamma \vdash_{C^D_1} \varphi$, then $\Gamma \vDash_{C^D_1} \varphi.$
    \end{thm}  
    \begin{proof} Let $\nucone_w$ be as in \cref{def:restriction-c1}. Let us start by showing the following: \\[1mm]
   {\bf Fact:}  $\nucone_w(\alpha^\circ) \in \D$ if and only if   $\nucone_w(\alpha) \in \{T,F\}$.\\[1mm]
   Indeed, suppose that $\nucone_w(\alpha^\circ) \in \D$. Then,  $(\alpha^\circ)_{(1,w)}=1$. Recalling that $\alpha^\circ=\neg(\alpha \land \neg\alpha)$, it follows that $(\alpha \land \neg\alpha)_{(2,w)}=1$, and so  $\nucone_w(\alpha \land \neg \alpha) \neq T$. By the first condition in  \cref{def:nu_Cila} we infer that $\nucone_w(\alpha) \neq t$, hence $\nucone_w(\alpha) \in \{T,F\}$. Conversely, if $\nucone_w(\alpha) \in \{T,F\}$ then  $\alpha_{(1,w)} \sqcap \alpha_{(2,w)}=(\alpha \land \neg\alpha)_{(1,w)}=0$. From this, $(\alpha^\circ)_{(1,w)}=(\alpha \land \neg\alpha)_{(2,w)}=1$ and so $\nucone_w(\alpha^\circ) \in \D$.

   Now, assume that $\nucone_w(\alpha^\circ) \in \D$. By the {\bf Fact},  $\nucone_w(\alpha) \in \{T,F\}$. By the  condition in \cref{def:restriction-c1}, $\nucone_w(\obl \alpha) \in \{T,F\}$. Using the {\bf Fact} once again, we infer that  $\nucone_w((\obl\alpha)^\circ) \in \D$, and so axiom  {\bf  (ca$_{\obl}$)'} is valid w.r.t. swap Kripke models  for  ${C}^D_1$. 

   The validity of axiom {\bf (bc)'} follows immediately from the {\bf Fact}. In turn, the validity of  axiom {\bf (ca$_{\#}$)'} is a consequence of the first condition stated in \cref{def:nu_Cila} and  the {\bf Fact}.
   The validity of the other axioms of ${C}^D_1$ follows from the soundness of \DCila\ w.r.t. swap Kripke models.        
    \end{proof}

In order to prove completeness of ${C}^D_1$ w.r.t. swap Kripke models, some adaptations are required in the construction of the canonical  swap Kripke model and the canonical valuations.

First, observe that the $\varphi$-saturated sets in ${C}^D_1$ are subsets of $For(\Sigma^{C_1}_D)$ ($\circ$ is now a defined connective).

 \begin{lemma}
        \label{lemma:truth-sat-C1D} Let $\Delta \subseteq For(\Sigma^{C_1}_D)$ be a $\varphi$-saturated set in ${C}^D_1$. Then, it satisfies  the following properties, for every $\alpha,\beta \in For(\Sigma^{C_1}_D)$:
        \begin{description}
            \item[I.] items 1.-4. and 6. of \cref{lemma:truth-sat};
            \item[II.]  item 5$^+_3$. of \cref{lemma:truth-sat-ext};
            \item[III.]  $\alpha^\circ \in \Delta$  iff $\alpha \notin \Delta$ or $\neg\alpha \notin \Delta$;
            \item[IV.]  if $\alpha^\circ, \beta^\circ \in \Delta$, then $(\alpha \# \beta)^\circ \in \Delta$,  where $\# \in \{\land, \lor, \to\}$;
            \item[V.] if $\alpha^\circ \in \Delta$, then $(\obl\alpha)^\circ \in \Delta$.
        \end{description}
    \end{lemma}
\begin{proof}
    Items I. and II. are immediate, given that ${C}^D_1$ contains all the schemas of \DmbC\ and \DbC\ over signature $\Sigma^{C_1}_D$.\\[1mm]
    Item III.: The `only if' part is a consequence of axiom {\bf (bc)'}. Now, suppose that  $\alpha^\circ \notin \Delta$. By property 4. of item I., $\neg(\alpha^\circ) \in \Delta$. That is, $\neg\neg(\alpha \land \neg\alpha) \in \Delta$ and so $\alpha \land \neg\alpha \in \Delta$, by item II. By property 1. of item I., $\alpha, \neg\alpha \in \Delta$.\\[1mm]
    Item IV. and V. follow immediately from axioms {\bf (ca$_{\#}$)'} and  {\bf  (ca$_{\obl}$)'}.
\end{proof}


Define now $W^{{C}_1}_{can}, R^{{C}_1}_{can}$ and $\nucone_{\Delta}$  as in {\DCila}, but now each $\Delta \in W^{{C}_1}_{can}$ is a $\varphi$-saturated set in ${C}^D_1$. Observe that each valuation $\nucone_\Delta:For(\Sigma^{C_1}_D) \to A$ is defined according to \cref{def:can-bival-truth}.


    \begin{prop}
        The structure $\M_{{C}^D_1} = \langle W^{{C}_1}_{can}, R^{{C}_1}_{can}, \{v^{C_1}_\Delta\}_{\Delta \in W^{{C}_1}_{can}} \rangle$ is a swap Kripke model for ${C}^D_1$ such that, for every $\alpha \in For(\Sigma^{C_1}_D)$, $\nucone_\Delta(\alpha) \in \D$ iff $\alpha \in \Delta$.
    \end{prop}
\begin{proof} 

		It is an immediate consequence of \cref{lemma:truth-sat-C1D} and \cref{def:can-bival-truth}, taking into account \cref{rem:val-C1D}. Indeed, by adapting the proofs for the previous systems, it follows that $v^{C_1}_\Delta(\alpha \# \beta) \in v^{C_1}_\Delta(\alpha) \tilde{\#} v^{C_1}_\Delta(\beta)$ (for $\# \in \{\land,\vee,\to\}$) and $v^{C_1}_\Delta(\neg\alpha) \in \aneg_1 v^{C_1}_\Delta(\alpha)$. In order to prove that $v^{C_1}_\Delta$ satisfies the requirements 3.-5. of \cref{rem:val-C1D}, suppose first that  $v^{C_1}_\Delta(\alpha)=t$. Then, $\alpha,\neg\alpha \in \Delta$ and so $\alpha \land \neg\alpha \in \Delta$ and $\neg(\alpha \land \neg\alpha)=\alpha^\circ \not\in\Delta$, by items I. and III. of \cref{lemma:truth-sat-C1D}. This means that 
        $v^{C_1}_\Delta(\alpha \land \neg\alpha)=T$, validating requirement 3. For 4., observe first that  $v^{C_1}_\Delta(\alpha) \in \{T,F\}$ iff either  $\alpha\notin \Delta$ or  $\neg\alpha \notin \Delta$ iff, by III., $\alpha^\circ \in \Delta$. Now, let  $\# \in \{\land, \lor, \to\}$ and suppose that $\nucone_\Delta(\alpha), \nucone_\Delta(\beta) \in \{T,F\}$. By the previous observation, it follows that $\alpha^\circ, \beta^\circ \in \Delta$.  By IV. of \cref{lemma:truth-sat-C1D},  $(\alpha \# \beta)^\circ \in \Delta$. Using the observation above once again, this implies that $\nucone_\Delta(\alpha \# \beta) \in \{T,F\}$. The proof for 5{.} is analogous. By the very definitions, $\nucone_\Delta(\alpha) \in \D$ iff $\alpha \in \Delta$.
\end{proof}    

   Completeness follows immediately, with slight adaptations, from the lemma above and completeness for \DCila.


   \begin{prop}[Completeness of $C_1^D$  w.r.t. swap Kripke models] \ \\
	For any set $\Gamma \cup \{\varphi\} \subseteq For(\Sigma^{C_1}_D)$, if $\Gamma \vDash_{{C}^D_1} \varphi$ then $\Gamma \vdash_{{C}^D_1} \varphi$.
    \end{prop}


\section{Swap Kripke models for ${C}^D_n$} \label{sect:DCn}

We start this section by defining extensions of notions presented in the previous section  for the rest of the hierarchy ${C}_n$, for $n\geq 2$. For this, consider once again the signatures $\Sigma^{C_1}$ for $C_n$ and $\Sigma^{C_1}_D$ for the calculi $C^D_n$. We define the following  notation over $For(\Sigma^{C_1}_D)$:

\begin{itemize}
    \item $\alpha^0 = \alpha$
    \item $\alpha^{n+1} = \neg (\alpha^n \land \neg \alpha^{n})$
    \item $\alpha^{(n)}= \alpha^1 \land \dots \land \alpha^n$
\end{itemize}

We also follow the presentation of ${C}_n$ given in \cite{ConiglioToledo2022}. This comprises of all axioms for \cplp, plus (EM), (cf) and the following axioms:

\begin{description}
    \item[(bc$_n$)] $\alpha^{(n)} \to (\alpha \to  (\neg \alpha \to \beta))$ 
    \item[(P$_n$)] $(\alpha^{(n)} \land \beta^{(n)}) \to ((\alpha \to \beta)^{(n)} \land (\alpha \lor \beta)^{(n)} \land (\alpha \land \beta)^{(n)})$ 
\end{description}

Observe that the classical negation is represented in $C_n$ by means of the formula $\cneg^{(n)} \alpha := \neg \alpha \land \alpha^{(n)}$. From this, the new version of $\axD$ reads 


\begin{description}
    \item[(D$_n$)] $\obl \alpha \to \cneg^{(n)} \obl \cneg^{(n)}\alpha$. 
\end{description}

We have to also highlight that, in order for a modal system to be constructed upon such logics in the way we have been presenting them, some decisions must be made. If we want to follow the presentation of $C^D_1$ on \cite{CostaCarnielli1986} and extend the ideas presented there, as we did in the previous section, we need to reformulate the classicality propagation axiom, namely, $\alpha^\circ \to (\obl \alpha)^\circ$, as follows: 

\begin{description}
    \item[(P$\obl_n$)] $\alpha^{(n)} \to (\obl \alpha)^{(n)}$. 
\end{description}

\noindent We call it the \textit{general classicality propagation} axiom in $C_n$. Notice that when $n = 1$, $\alpha^{(n)} = \alpha^\circ = \alpha^1 = \neg (\alpha \land \neg \alpha)$. Also notice that this has an influence on how strong a negation has to be in order to recover classicality. For $n = 1$, strong negation is already sufficient to introduce deontic explosion back into the system, but taking $n=2$, we have, besides $\neg$ and ${\sim}$, one more negation. We are in fact dealing with an increasing number of negations, or, more precisely, for each $n$, $C^{D}_n$ has $n+1$ negations.\footnote{Although the fact is easy to observe, the argument that each one of them is, in fact, a negation will be discussed in a future paper.}

We are now a position to characterize the family of systems  ${C}^D_n$, for $n \geq 1$. Also notice that the case where $n=1$ was already studied in the previous section. We also refrain in this from deeply investigating the philosophical considerations tied to these systems.  We opt for a technical development of a semantics for the systems proposed, with the general propagation of classicality and a distinct version of $\axD$. We attempt to maintain the general spirit of the system originally presentation in the paper by da Costa and Carnielli, while presenting a mix between RNmatrices and Kripke semantics.\footnote{It is possible to construct such a system by means of swap structures only, following the technique shown in \cite{ConPawSku2024}. The modal operator could then be assigned one dimension in the tuple, hence its truth value being fully nondeterministic. This permits to semantically characterize logics in which the modal operator does not satisfy any of the standard inference rules or axioms assumed for such an operator.}

We thus follow the presentation given in \cite{ConiglioToledo2022} to define the base system. So for each $n \geq 2$, the multialgebra for ${C}_n$ will have domain $A_n$ of size $n + 2$, where each element of $A_n \subseteq \textbf{2}^{n+1}$ is an ${n+1}$-tuple. Hence, the swap structures for ${C}_n$ is one where the set of \textit{snapshots} is: $$A_n = \{z \in \textbf{2}^{n+1} : (\bigwedge_{i \leq k} z_i) \lor z_{k + 1} = 1 \ \text{ for every } 1 \leq k \leq n \}$$  

This produces exactly the following $n+2$ truth values:
\begin{itemize}
    \item $T_n = (1, 0, 1, \dots, 1)$
    \item $t^n_0 = (1,1,0,1, \dots, 1)$
    \item $t^n_1 = (1,1,1,0,1,\dots, 1)$\\
    \vdots
    \item $t^n_{n-2} = (1,1,1,1,\dots,0)$
    \item $t^n_{n-1} = (1,1,1,1,\dots,1)$
    \item $F_n = (0,1,1,\dots,1)$.
\end{itemize}


\begin{defn}
    let $A_n$ be as in the definition above. We define the following subsets of $A_n$:
    \begin{description}
        \item[1.] $D_n \defeq A_n \setminus \{F_n\}$ (designated values)
        \item[2.] $U_n \defeq A_n \setminus D_n = \{F_n\}$  (undesignated values)
        \item[3.] $I_n \defeq A_n \setminus \{T_n, F_n\}$ (inconsistent values)
        \item[4.] $Boo_n = A_n \setminus I_n= \{T_n, F_n\}$ (Boolean or classical values)
    \end{description}
\end{defn}

Now we can introduce the multiagebra $\A_{{C}^D_n}$:

\begin{defn}
    \label{def:Cnop}
    Let $\A_{{C}^D_n} = (A_n, \aland, \alor, \ato, \aneg, \aobl)$ be the multialgebra over $\Sigma^{C_1}_D$ defined as follows, for any $a,b \in A_n$:
    \begin{description}
        \item[1.] $\aneg a = \{ c \in A_n \ : \ c_1 = a_2 \text{ and } c_2 \leq a_1\}$
        \item[2.] $a \aland b = \begin{dcases}
            \{c \in Boo_n \ : \ c_1 = a_1 \sqcap b_1\} & \text{ if } a, b \in Boo_n\\
            \{c \in A_n \ : \ c_1 = a_1 \sqcap b_1\} & \text{ otherwise } \\
        \end{dcases}$ %\{c \in A_n \ : \ c_1 = a_1 \sqcap b_1\}$
        \item[3.] $a \alor b = \begin{dcases}
            \{c \in Boo_n \ : \ c_1 = a_1 \sqcup b_1\} & \text{ if } a, b \in Boo_n\\
            \{c \in A_n \ : \ c_1 = a_1 \sqcup b_1\} & \text{ otherwise }\\
        \end{dcases}$
        \item[4.] $a \ato b = \begin{dcases}
            \{c \in Boo_n \ : \ c_1 = a_1 \supset b_1\} & \text{ if } a, b \in Boo_n\\
            \{c \in A_n \ : \ c_1 = a_1 \supset b_1\} & \text{ otherwise }\\
        \end{dcases}$
        \item[5.] $\aobl(X) = \{c \in A_n \ : \ c_1 = \bigsqcap \{x_1 : x \in X\}\}$, where $X \neq \emptyset$ and $X \subseteq A_n$.
    \end{description}
\end{defn}

