\begin{defn}
    \label{def:Cnval}
    Let $W\neq \emptyset$ be a set of worlds, $R \subseteq W \times W$ be a serial relation and $v^n_w = For(\Sigma^{C_1}_D) \to A_n$ for each $w \in W$, such that, for any $\alpha, \beta \in For(\Sigma^{C_1}_D)$, the following holds:
    \begin{description}
        \item[1.] $v_w^n (\neg \alpha) \in \aneg (v_w^n (\alpha))$
        \item[2.] $v_w^n (\alpha \# \beta) \in v_w^n(\alpha) \tilde{\#} v_w^n (\beta)$, for $\# \in \{\land, \to \neg\}$
        \item[3.] $v_w^n (\obl \alpha) \in \aobl \big(\{v_{w\prim}^n(\alpha) \ : \ w R w\prim\}\big)$.
    \end{description}
\end{defn}

\begin{defn}
    \label{def:pre-swqp-Cn}
A  structure $\M = (W, R, \{v^n_w\}_{w \in W})$ with properties as in \cref{def:Cnval} is said to be a {\em swap Kripke pre-model} for ${C}^D_n$. A formula $\alpha \in For(\Sigma^{C_1}_D)$ is {\em true in a world $w$} of $\M$, denoted by $\M,w \vDash \alpha$, if $v^n_w(\alpha) \in D_n$. A formula $\alpha$  is {\em valid} in a pre-model $\M$, denoted by  $\M \vDash \alpha$, if  $\M,w \vDash \alpha$ for every $w \in W$. As it was done before, given a non-empty set $\Gamma$ of formulas we will write $\M,w \vDash \Gamma$ to denote that $\M,w \vDash \alpha$ for every $\alpha \in \Gamma$.
\end{defn}



We recall the fact that for any $\alpha \in For(\Sigma^{C_1}_D)$, $w \in W$ and $v^n_w$, $v^n_w(\alpha) \in D_n$ if and only if $v^n_{(1,w)}(\alpha) = 1$, given a natural adaptation of the notation presented in \cref{rmk:notation} and the definitions above.

In order to characterize ${C}^D_n$ we add first the following restrictions, thus simulating the behavior of the $RN$matrix for $C_n$:

\begin{defn}
    \label{def:Cnrest} Given a swap Kripke pre-model for ${C}^D_n$, consider the following additional restrictions on the valuations $v^n_w$: 
    \begin{description}
        \item[1.] $v^n_w(\alpha) = t^n_0$ implies $v^n_w(\alpha \land \neg \alpha) = T_n$
        \item[2.] $v_w^n(\alpha) = t^n_k$ implies $v^n_w(\alpha \land \neg \alpha) \in I_n$ and $v^n_w(\alpha^1)=t^n_{k-1}$,\\ for every $1\leq k \leq n-1$. 
    \end{description}

\end{defn}


\begin{rmk}
\label{val=sound-Cn}
We observe that the additional restrictions in \cref{def:Cnrest} only consider valuations in which the values of $\alpha^{(n)}$ are in $Boo_n$, such as shown in \cite[pp. 621--622]{ConiglioToledo2022}, for each world $w \in W$. Moreover, in any  swap Kripke pre-model  for ${C}^D_n$ as in \cref{def:Cnrest}, and for a fixed $w \in W$, each valuation $v^n_w$ belongs to the set of valuations of the $RN$matrix characterizing $C_n$ introduced in~\cite{ConiglioToledo2022}. From this, all the results concerning the non-modal operators of $C_n^D$ will hold w.r.t. the valuations of such a  swap Kripke pre-models.
\end{rmk}

