(i) $p =a.p'$ or
%    \item 
(ii) $p =p_1+p_2$, for some $p_1,p_2$, and $p_1\myarrowa p'$ or $p_2\myarrowa p'$ holds.
%\end{enumerate}
% We use the notation $\sum_{i=1}^k p_i$ to represent the process $p_1+\cdots+p_k$, adopting the convention that an empty sum of processes stands for $\mathtt{0}$.

We consider $n$-nested simulation for $n\geq 1$, and bisimilarity, which are defined below. 

\begin{definition}[\cite{Milner89,DBLP:journals/iandc/GrooteV92}]\label{Def:beh-preorders}
We define each of the following preorders as the largest binary relation over $\proc$ that satisfies the corresponding condition.
\begin{enumerate}[(a)]
    \item \emph{Simulation preorder (S):} $p\curle_{S} q$ iff for all $p\myarrowa p'$ there exists some $q\myarrowa q'$ such that $p'\curle_S q'$.
    \item \emph{$n$-Nested simulation ($n$S)}, where $n\geq 1$, is defined inductively as follows: The $1$-nested simulation preorder $\curle_{1S}$ is $\curle_S$, and the $n$-nested simulation preorder $\curle_{nS}$ for $n > 1$ is the largest relation such that $p\curle_{nS} q$ iff
    %\begin{enumerate}[(i)]
       % \item 
      (i) for all $p\myarrowa p'$ there exists some $q\myarrowa q'$ such that $p'\curle_{nS} q'$, and
       % \item 
      (ii) $q\curle_{(n-1)S} p$. 
        %and $p\curle_{i-1} q$.        
   % \end{enumerate}
   \item  \emph{Bisimilarity (BS):} $\curle_{BS}$ is the largest symmetric relation satisfying the condition defining $\curle_{S}$. %the simulation preorder.
\end{enumerate}
\end{definition}

It is well known that bisimilarity is an equivalence relation and all the relations $\curle_{nS}$ %the other relations 
are preorders~\cite{Milner89, DBLP:journals/iandc/GrooteV92}. We sometimes write $p\sim q$ instead of $p\curle_{BS}q$. Moreover, we have that 
${\sim}\subsetneq{\curle_{nS}}$  and ${\curle_{(n+1)S}}\subsetneq {\curle_{nS}}$ for every $n\geq 1$---see~\cite{Glabbeek01}. We say that $p$ is $n$-nested-simulated by $q$ when $p\curle_{nS} q$.

\begin{definition}[Kernels of the preorders]
    For each $n\geq 1$,  the kernel $\equiv_{nS}$ of $\curle_{nS}$ is the equivalence relation defined thus: for every $p,q\in \proc$, $p\equiv_{nS} q$ iff $p\curle_{nS} q$ and $q\curle_{nS} p$. We say that $p$ and $q$ are $n$-nested-simulation equivalent if $p\equiv_{nS} q$.
\end{definition}

