%     For every two processes $p$ and $q$, if $p\curle_{2S} q$, then $\traces(p)=\traces(q)$.
% \end{proposition}

Each relation $\curle_{nS}$, where $n\geq 1$, is characterized by a fragment $\mathL_{nS}$ of Hennessy-Milner logic, \hml, defined as follows.
%~\cite{Glabbeek01}.

\begin{definition}\label{def:mathlx}
For $X\in\{BS\} \cup \{nS\mid n\geq 1\}$, 
%where $n\geq 1$, 
$\mathL_X$ is defined by the corresponding grammar given below ($a\in \act$):
\begin{enumerate}[(a)] 
\item $\mathL_S$ ($\mathL_{1S}$): 
$\varphi_S::= ~ \true ~ \mid ~ \ff ~ \mid ~ \varphi_S\wedge \varphi_S~ \mid ~\varphi_S\vee \varphi_S~ \mid ~ \langle a \rangle\varphi_S.$
\item $\mathL_{nS}$, $n\geq 2$: 
$\varphi_{nS}::= ~ \true ~ \mid ~ \ff ~ \mid ~ \varphi_{nS}\wedge \varphi_{nS} ~ \mid ~\varphi_{nS}\vee \varphi_{nS}
~ \mid ~ \langle a \rangle\varphi_{nS} ~ \mid ~ \neg\varphi_{(n-1)S}.$
\item $\hml$ ($\mathL_{BS}$):
    $\varphi_{BS}::= ~ \true ~ \mid ~ \ff ~ \mid ~ \varphi_{BS}\wedge \varphi_{BS} ~ \mid ~\varphi_{BS}\vee \varphi_{BS}~ \mid ~ \langle a \rangle\varphi_{BS} ~ \mid ~ [a]\varphi_{BS} ~ \mid ~ \neg\varphi_{BS}.$
\end{enumerate}
\end{definition}

Note that the explicit use of negation in the grammar for $\mathL_{BS}$ is unnecessary. However, we included the negation operator explicitly so that $\mathL_{BS}$ extends syntactically each of the other modal logics presented in Definition~\ref{def:mathlx}. 

Given a formula $\varphi\in\mathL_{BS}$, the \emph{modal depth} of $\varphi$, denoted  $\md(\varphi)$, is the maximum nesting of modal operators in $\varphi$. We define the \emph{size} of formula $\varphi$, denoted  $|\varphi|$, to be the number of symbols in $\varphi$. Finally, $\sub(\varphi)$ denotes the set of subformulae of formula $\varphi$.

Truth in an LTS $\mathS=(\proc,\act,\longrightarrow)$ is defined via the satisfaction relation $\models$ as follows, where we omit the standard clauses for the Boolean operators:
$$\begin{aligned}
%    &p\models\true \text{ and } p\not\models\ff;\\
%    &p\models \neg\varphi \text{ iff } p\not\models \varphi;\\
%    &p\models \varphi\wedge \psi \text{ iff both } p\models \varphi \text{ and } p\models \psi;\\
%    &p\models \varphi\vee \psi \text{ iff } p\models \varphi \text{ or } p\models \psi;\\
    &p\models \langle a\rangle\varphi \text{ iff there is 
 some } p\myarrowa q \text{ such that } q\models\varphi;\\
    &p\models [a]\varphi \text{ iff for all } p\myarrowa q \text{ it holds that } q\models\varphi  .
\end{aligned}$$
If $p\models \varphi$, we say that $\varphi$ is true, or satisfied, in $p$. A formula $\varphi$ is \emph{satisfiable} if there is a process that satisfies it. 
%If $\varphi$ is satisfied in every process in every LTS, we say that $\varphi$ is \emph{valid}.  
 Formula $\varphi_1$ \emph{entails} $\varphi_2$, denoted  $\varphi_1\models \varphi_2$, if every process
that satisfies  $\varphi_1$ also satisfies   $\varphi_2$. Moreover, $\varphi_1$ and $\varphi_2$ are \emph{logically equivalent}, denoted  $\varphi_1\equiv\varphi_2$, if $\varphi_1\models \varphi_2$ and $\varphi_2\models \varphi_1$. For example, 
%\[
$\varphi_1\wedge(\varphi_2\vee\varphi_3)\equiv (\varphi_1\wedge\varphi_2)\vee(\varphi_1\wedge\varphi_3)$, 
%\]
for every $\varphi_1,\varphi_2,\varphi_3\in\mathL_{BS}$.
Given a formula $\varphi\in\mathL_{BS}$, if we distribute conjunctions over disjunctions using the equivalence above, then we obtain a formula that is logically equivalent to $\varphi$.
\begin{lemma}\label{lem:DF-equiv}
    Let $\varphi\in\mathL_{BS}$ and $\varphi_\vee$ be the result of distributing conjunctions over disjunctions in $\varphi$. Then, $\varphi\equiv\varphi_\vee$. 
\end{lemma}
\iffalse
