\begin{theorem}
[Hennessy-Milner theorem~\cite{HennessyM85}]
%[\cite{HennessyM85}]
\label{Thm:HMT}
    For all processes $p,q$ in a finite LTS, $p\sim q$ iff $\mathL_{BS}(p)=\mathL_{BS}(q)$.
\end{theorem}

\begin{proposition}[\cite{DBLP:journals/iandc/GrooteV92}]\label{logical_characterizations}
     For all processes $p,q$ in a finite LTS, $p\curle_{nS} q$ iff $\mathL_{nS}(p)\subseteq \mathL_{nS}(q)$.
\end{proposition}

\begin{definition}[\cite{BoudolL92,AFEIP11}]\label{def:prime-formula}
Let $\mathL\subseteq \mathL_{BS}$. 
A formula $\varphi\in \mathL_{BS}$ is \emph{prime in $\mathL$} if  $\varphi\models\varphi_1 \vee \varphi_2$ implies $\varphi\models \varphi_1$ or  $\varphi\models \varphi_2$, for all $\varphi_1,\varphi_2\in \mathL$. 
\end{definition}

When the logic $\mathL$ is clear from the context, we say that $\varphi$ is prime. Note that every unsatisfiable formula is trivially prime in $\mathL$, for every $\mathL$.

\begin{example}\label{ex:prime}
    The formula $\langle a\rangle \true$ is prime in $\mathL_S$. Indeed, let $\varphi_1,\varphi_2\in\mathL_S$ and assume that $\langle a\rangle \true\models\varphi_1\vee\varphi_2$. Since $a.\mathtt{0} \models\langle a\rangle \true$, without loss of generality, we have that $a.\mathtt{0} \models\varphi_1$. We claim that $\langle a\rangle\true\models\varphi_1$. To see this, let $p$ be some process such that $p\models\langle a\rangle\true$---that is, a process such that $p \myarrowa p'$ for some $p'$. It is easy to see that $a.\mathtt{0}\curle_S p$. Since $a.\mathtt{0} \models \varphi_1$, Proposition~\ref{logical_characterizations} yields that $p\models\varphi_1$, proving our claim and the primality of $\langle a\rangle\true$. On the other hand, the formula $\langle a\rangle\true\vee\langle b\rangle\true$ is not prime in $\mathL_S$. Indeed, $\langle a\rangle\true\vee\langle b\rangle\true\models \langle a\rangle\true\vee\langle b\rangle\true$, but neither $\langle a\rangle\true\vee\langle b\rangle\true \models\langle a\rangle\true$  nor $\langle a\rangle\true\vee\langle b\rangle\true \models\langle b\rangle\true$ hold. 
\end{example}

Characteristic formulae are defined next, with two distinct definitions: within logic \mathL, and another modulo an equivalence relation.

\begin{definition}[\cite{AILS07,GrafS86a,SteffenI94}]\label{def:characteristic}
Let $\mathL\subseteq \mathL_{BS}$. 
A formula  $\varphi\in\mathL$ is \emph{characteristic  for $p\in \proc$ within $\mathL$} iff, for all $q \in \proc$, it holds that $q \models \varphi\Leftrightarrow\mathL(p) \subseteq \mathL(q)$. 
%We denote by $\chi(p)$ the unique characteristic formula for $p$ with respect to logical equivalence.
\end{definition}

\begin{proposition}[\cite{AcetoMFI19}]\label{prop:charact-via-primality}
For every $n\geq 1$, $\varphi\in \mathL_{nS}$ is characteristic for some process within $\mathL_{nS}$ iff $\varphi$ is satisfiable and prime in $\mathL_{nS}$.
\end{proposition}

