\begin{definition}\label{def:proptableau}
Let $T$ be a set of \hml formulae. 
%Then, $T$ is
\begin{enumerate}[(a)]
    \item $T$ is \emph{propositionally inconsistent} if 
    %either $\psi\in T$ and $\neg\psi\in T$ for some formula $\psi$ or 
    $\ff\in T$, or $\psi\in T$ and $\neg\psi\in T$ for some formula $\psi$. Otherwise, $T$ is \emph{propositionally consistent}.
    \item  $T$ is a \emph{propositional tableau} if the following conditions are met:
    \begin{enumerate} [(i)]
     %   \item if $\neg\neg\psi\in T$, then $\psi\in T$,
        \item if $\psi\wedge\psi'\in T$, then $\psi,\psi'\in T$,
        \item if $\psi\vee\psi'\in T$, then either $\psi\in T$ or $\psi'\in T$, and
        \item $T$ is propositionally consistent. 
    \end{enumerate}
    %\item $T$ is \emph{fully expanded} if for every $\psi\in\sub(T)$, either $\psi\in T$ or $\neg\psi\in T$.
\end{enumerate}
\end{definition}

\begin{definition}\label{def:hmltableau}
Let $\act=\{a_1,\dots,a_k\}$. An \hml tableau is a tuple $T=(S,L,R_{a_1},\dots,R_{a_k})$, where $S$ is a set of states, $L$ is a labelling function that maps every $s\in S$ to a set $L(s)$ of formulae, and  $R_{a_i}\subseteq S\times S$, for every $1\leq i\leq k$, such that
\begin{enumerate}[(i)]
    \item $L(s)$ is a propositional tableau for every $s\in S$,
    \item if $[a_i] \psi\in L(s)$ and $(s,t)\in R_{a_i}$, then $\psi\in L(t)$, and
    \item if $\langle a_i\rangle\psi\in L(s)$, then there is some $t$ such that $(s,t)\in R_{a_i}$ and $\psi\in L(t)$.
\end{enumerate}
\end{definition}

\noindent An \hml tableau for $\varphi$ is an \hml tableau such that $\varphi\in L(s)$ for some $s\in S$.

%A tuple $T=(S,L,R_{a_1},\dots,R_{a_k})$ is an \hml tableau for $\varphi$ if it is an \hml tableau and $\varphi\in L(s)$ for some $s\in S$.

\begin{proposition}[\cite{HalpernM92}]\label{tableausat}
An \hml formula $\varphi$ is satisfiable iff there is an \hml tableau for $\varphi$.
\end{proposition}

\begin{remark}\label{rem:tableausat}
    The proof of the ``right-to-left'' direction of Proposition~\ref{tableausat} constructs an LTS corresponding to a process satisfying $\varphi$ from an \hml tableau for $\varphi$ in a straightforward way: given an \hml tableau $T=(S,L,R_{a_1},\dots,R_{a_k})$ for $\varphi$, define the LTS $\mathS=(P,\myarrowasubone,\dots,\myarrowasubk)$, where $P=S$ and every $\myarrowasubi$ coincides with $R_{a_i}$. Note that $T$ and $\mathS$ have the same size and depth.
