\begin{center}
\begin{tabular}{ | p{15cm} | } 
\hline
\textbf{$\mathbf{1}^{\text{st}}$ round.} 
 $B$ plays moves $B(\wedge)$ and $B(\vee)$ on $p_i$, for both $i=1,2$, until no formula can be replaced in $L_i(p_i)$. 
 If $\bigwedge L_i(p_i)$ becomes unsatisfiable, then $B$ loses.

\textbf{$\mathbf{l}^{\text{th}}$ round, $\mathbf{l\geq 2}$.} 
\begin{enumerate}
    \item For every $a_j\in \act$, $B$ plays as follows. He plays move $B(\Diamond)$ on $p_i$ for both $i=1,2$, and move $B(\Box)$ only on $p_1$. Then, for both $i=1,2$, $B$ plays moves $B(\wedge)$ and $B(\vee)$  on every $p_i'$ such that $(p_i,p_i')\in R_{a_j}^i$ until no formula can be replaced in $L_i(p_i')$. If $\bigwedge L_i(s)$ becomes unsatisfiable for some $i=1,2$ and $s\in S_i$, then $B$ loses. 
