% The Formula Primality problem for $\mathL_{2S}$ is \conp-complete.
% \end{restatable}

% \begin{restatable}{corollary}{twoschardp}\label{cor:2S-char-dp}
%   Let $|\act|>1$.  Deciding whether a formula in $\mathL_{2S}$ is characteristic for a process within $\mathL_{2S}$ is in \dpc.
% \end{restatable}

% \begin{restatable}{corollary}{twoscharconp}\label{cor:2S-char-conp}
% Let $|\act|>1$. Deciding whether a formula $\varphi\in\mathL_{2S}$ is characteristic for a process modulo $\equiv_{2S}$ is \conp-complete.
% \end{restatable}



We introduce two algorithms, namely $\mathtt{ConPro}$ in Algorithm~\ref{alg:process-construction}, and $\mathtt{Prime_{2S}}$ in Algorithm~\ref{alg:prime-twosim}. Let $\varphi\in\mathL_{2S}$ be an input to the first algorithm. Lines 1--19 of $\mathtt{ConPro}$ are an implementation of the tableau construction for $\varphi$---see~\cite{HalpernM92} or Appendix~\ref{appendix:tableau-construction}. If $\varphi$ is unsatisfiable, then $\mathtt{ConPro}(\varphi)$ stops without returning an output because it stops at lines 12 or 18. In the case that $\mathtt{ConPro}(\varphi)$ returns an output, then its output is an LTS corresponding to a process that satisfies $\varphi$. If there are $r_1,r_2$ satisfying $\varphi$ such that $r_1\not\curle_S r_2$, the tableau construction cannot guarantee the generation of two processes that are not simulation equivalent. This is precisely the role of lines 20--30 in $\mathtt{ConPro}$. Given such processes $r_1, r_2$, when run twice, the algorithm can choose two processes $p_1,p_2$ based on $r_1,r_2$. During construction of $p_1$, lines 20--30 can be used to add  to $p_1$ up to $|\varphi|$ states that witness the failure of $r_1\curle_S r_2$. Note that in the case of the \simequiv game, player $B$ could follow a similar strategy by using move B($\square$) and introducing a trace that witnesses $r_1\not\curle_S r_2$. In the case of $\mathL_{2S}$, since the full tableau is constructed, the algorithm needs only to construct a ``small'' process that serves as a witness to the same fact. 

Algorithm $\mathtt{Prime_{2S}}$ decides whether its input $\varphi\in\mathL_{2S}$ is prime: $\varphi$ is prime iff every execution of $\mathtt{Prime_{2S}}(\varphi)$ accepts. This algorithm runs $\mathtt{ConPro}(\varphi)$ twice. If $\mathtt{ConPro}(\varphi)$ fails to return an output, $\mathtt{Prime_{2S}}(\varphi)$  rejects at line 5---this line deals with unsatisfiability. For every two processes $p_1,p_2$ that satisfy $\varphi$, at line 7, $\mathtt{Prime_{2S}}(\varphi)$ constructs their maximal lower bound, denoted $\grcd_{\curle_{2S}}(p_1,p_2)$, which is a process $g$ that is 2-nested-simulated by both $p_i$'s and $r\curle_{2S} g$, for every process $r$ such that $r\curle_{2S} p_i$. Processes $p_1,p_2$ have a maximal lower bound iff $p_1\equiv_S p_2$.
%and $\grcd_{\curle_{2S}}(p_1,p_2)$ can be constructed in polynomial time. 
In case $\grcd_{\curle_{2S}}(p_1,p_2)$ does not exist, the algorithm discovers two processes satisfying $\varphi$ such that there is no process that is 2-nested-simulated by both of them and it rejects the input---$\varphi$ is not prime. On the other hand, if $\grcd_{\curle_{2S}}(p_1,p_2)$ exists, then there is a process that is 2-nested simulated by both $p_i$'s and it can be constructed in polynomial time. It remains to check whether $\grcd_{\curle_{2S}}(p_1,p_2)$ satisfies $\varphi$. If so, then the second condition described above is met, and the algorithm accepts. If $\grcd_{\curle_{2S}}(p_1,p_2)\not\models\varphi$ it can be shown that there is no process $r$ satisfying $\varphi$ that is 2-nested-simulated by both $p_i$'s, and the algorithm rejects at line 10. This establishes Theorem~\ref{prop:2S-primality-conpc}. By slightly adjusting  $\mathtt{Prime_{2S}}$, we can show that deciding whether all processes satisfying a formula in $\mathL_{2S}$ are 2-nested-simulation equivalent is in \conp. By these results and the \NP-completeness of the satisfiability problem for $\mathL_{2S}$, we obtain the upper bound given in Corollary~\ref{cor:2S-char-dp}.
%With slight modifications to the $\mathtt{Prime_{2S}}$ algorithm, we can also show that the problem of deciding whether a formula is characteristic—both within $\mathL_{2S}$ and modulo $\equiv_{2S}$---lies in \conp. Combining this result with known lower bounds from Proposition~\ref{prop:char-ns-complexity}(a), we obtain Corollary~\ref{cor:2S-char-dp}.


