\subsubsection{Concurrency theory and logic}

Let $p\in\proc$. We define the set of \emph{initials} of $p$, denoted $I(p)$, as the set $\{a \in \act \mid  p\myarrowa p' \text{ for some } p'\in \proc\}$. We write $p\myarrowa$ if $a\in I(p)$ and $p\notmyarrowa$ if $a\not\in I(p)$. An infinite process is an LTS $\mathS=(P,\act,\rightarrow)$, where $P$ is an infinite set of states. We use the notation $\sum_{i=1}^k p_i$ to represent the process $p_1+\cdots+p_k$, adopting the convention that an empty sum of processes stands for $\mathtt{0}$.

We formally define the modal depth of a formula $\varphi\in\mathL_{BS}$ as follows.

\begin{definition}\label{def:modal_depth}
Given a formula $\varphi\in\mathL_{BS}$, the modal depth of $\varphi$, denoted  $\md(\varphi)$, is defined inductively as follows:
\begin{itemize}
    \item $\md(\true)=\md(\ff)=0$,
    \item $\md(\langle a\rangle\varphi)=\md([a]\varphi)=\md(\varphi)+1$,
    \item $\md(\varphi_1\wedge\varphi_2)=\md(\varphi_1\vee\varphi_2)=\max\{\md(\varphi_1),\md(\varphi_2)\}$,
    \item $\md(\neg\varphi)=\md(\varphi)$.
\end{itemize}
\end{definition}

For a formula $\varphi\in\mathL_{BS}$, we define the negation of $\varphi$, denoted  $\neg\varphi$, inductively as follows: $\neg\true=\ff$, $\neg\ff=\true$, $\neg (\varphi\wedge\psi)=\neg\varphi\vee\neg\psi$, $\neg (\varphi\vee\psi)=\neg\varphi\wedge\neg\psi$, $\neg [a]\varphi=\langle a\rangle \neg \varphi$, $\neg \langle a\rangle\varphi=[a] \neg \varphi$, and $\neg\neg\varphi = \varphi$. It is not hard to see that  $p\models \neg\varphi$ iff $p\not\models\varphi$, for every process $p$.

\begin{corollary}\label{cor:characteristic}
    Let $\varphi\in\mathL_X$, where $X\in\{nS,BS\}$ with $n\geq 1$, be characteristic for $p$ within $\mathL_X$. For every $\psi\in\mathL_X$, if $p\models\psi$, then $\varphi\models\psi$.
\end{corollary}

\begin{corollary}\label{cor:char-disj-form}
    Let $\varphi\in\mathL_{BS}$ be prime and $\varphi\equiv\bigvee_{i=1}^m\varphi_i$, $m\in\mathbb{N}$. Then, there is $1\leq j\leq m$ such that $\varphi\equiv\varphi_j$ and $\varphi_j$ is prime.
\end{corollary}

