\begin{definition}\label{def:fully-expanded}
Let $T$ be a set of \hml formulae. 
Then, $T$ is  \emph{fully expanded} if for every $\psi\in\sub(T)$, either $\psi\in T$ or $\neg\psi\in T$.
\end{definition}

If a set $T$ of formulae is not a propositional tableau, then $\psi$ is a witness to this if $\psi\in T$ and one of clauses (b)(i)--(iii) in Definition~\ref{def:proptableau} does not apply to $\psi$. Similarly, if $T$ is not fully expanded, $\psi$ is a witness to this if $\psi\in\sub(T)$ and neither $\psi\in T$ nor $\neg\psi\in T$. We assume that formulae are ordered in some way, so when there is a witness to one of the above facts, we can choose the least witness.

Let $\varphi\in \hml$. The following procedure constructs a labelled tree from which an \hml tableau for $\varphi$ can be extracted when $\varphi$ is satisfiable.
The \hml tableau construction for $\varphi$ consists of the following steps:
\begin{enumerate}
    \item Construct the node $s_0$ with $L(s_0)=\{\varphi\}$ which is called ``the root''.
    \item Repeat (a)--(d) until none of them applies:
    \begin{enumerate}[a.]
        \item \emph{Forming a propositional tableau:} if $s$ is a leaf, $L(s)$ is propositionally consistent, and $L(s)$ is not a propositional tableau and $\psi$ is the least witness to this fact, then:
        \begin{enumerate}[i.]
           % \item if $\psi=\neg\neg\psi'$ for some $\psi'$, then add a successor $s'$ of $s$ (i.e.\ add a node $s'$ to the tree and an edge from $s$ to $s'$) and set $L(s')=L(s)\cup\{\psi'\}$,
            \item if $\psi=\psi_1\wedge\psi_2$ for some $\psi_1,\psi_2$, then add a successor $s'$ of $s$ and set $L(s')=L(s)\cup\{\psi_1,\psi_2\}$,
            \item if $\psi=\psi_1\vee\psi_2$ for some $\psi_1,\psi_2$, then add two successors $s_1$ and $s_2$ of $s$ and set $L(s_i)=L(s)\cup\{\psi_i\}$, $i=1,2$.
        \end{enumerate}
        \item \emph{Forming a fully expanded propositional tableau:} if $s$ is a leaf, $L(s)$ is propositionally consistent, and $L(s)$ is not a fully expanded propositional tableau and $\psi$ is the least witness to this fact, then add two successors $s_1$ and $s_2$ of $s$ and set $L(s_1)=L(s)\cup\{\psi\}$, $L(s_2)=L(s)\cup\{\neg\psi\}$.
        \item \emph{Adding $i$-successor nodes:} if $s$ is a leaf, $L(s)$ is propositionally consistent, and $L(s)$ is a fully expanded propositional tableau, then for every formula of the form $\langle a_i\rangle\psi\in L(s)$ add an $i$-successor node $s'$ (i.e.\ add a node $s'$ to the tree and an edge from $s$ to $s'$ labelled $i$) and let $L(s')=\{\psi\}\cup\{\phi ~ | ~ [a_i]\phi\in L(s)\}$. 
        \item \emph{Marking nodes ``satisfiable'':} if $s$ is not marked  ``satisfiable'', then mark $s$ ``satisfiable'' if one of the following conditions is met:
        \begin{enumerate}[i.]
            \item $L(s)$ is not a fully expanded propositional tableau and $s'$ is marked ``satisfiable'' for some successor $s'$ of $s$, 
            \item $L(s)$ is a fully expanded propositional tableau, $L(s)$ is propositionally consistent, and it does not contain any formula of the form $\langle a_i\rangle \psi$,
            \item $L(s)$ is a fully expanded propositional tableau, $s$ has successors, and all of them are marked ``satisfiable''.
        \end{enumerate}
    \end{enumerate}
\end{enumerate}

\begin{proposition}[\cite{HalpernM92}]\label{prop:tableau-construction}
    There is an \hml tableau for $\varphi$ iff the tableau construction for $\varphi$ marks the root $s_0$ ``satisfiable''.
\end{proposition}

We just describe here how an \hml tableau $T=(S,L,R_{a_1},\dots,R_{a_k})$ for $\varphi$ can be extracted from the tree $T'=(S',L',\longrightarrow,\myarrowone,\dots,\myarrowk)$ constructed by the tableau construction in the case that the root of $T'$ is marked ``satisfiable''. The tableau $T$ is defined as follows:
\begin{itemize}
    \item $s\in S$ if $s\in S'$, $s$ is marked ``satisfiable'',  and $L'(s)$ is a fully expanded propositional tableau;
    \item $(s,t)\in R_{a_i}$ if $s\myarrowi t$ (that is,  $t$ is an $i$-successor of $s$ in $T'$);
    \item $L(s)=L'(s)$,  for every $s\in S$.
\end{itemize}

 \subsubsection{Complexity}

 For formulae in $\mathL_{BS}$, model checking is tractable.

\begin{proposition}[\cite{HalpernM92}]\label{model-checking-complexity}
    Given a formula $\varphi\in\mathL_{BS}$ and a process $p$, there is an algorithm to check if $p$ satisfies $\varphi$ that runs in time $\mathcal{O}(|p|\cdot |\varphi|)$.
\end{proposition}

\begin{proposition}[~\cite{DBLP:journals/iandc/GrooteV92, ShuklaRHS96}]\label{prop:2s-equiv-polytime}
    Given two processes $p,q\in\proc$, checking whether $p\equiv_{2S} q$ holds can be done in polynomial time.
\end{proposition}

