\textbf{The \simequiv game}\\

\noindent We first prove that if every two processes that satisfy $\varphi$ are equivalent with respect to $\equiv_S$, then $A$ has a winning strategy for the \simequiv game on $\varphi$. 

\begin{lemma}\label{lem:steps-Bab-first}
    Let $p$ be a state of $T_i$, $i=1,2$. The formulae in $\finlabeli(p)$ are either $\true$, $\ff$, or formulae that start with either $\langle a\rangle$ or $[a]$, $a\in \act$.
    %If $B$ applies steps B(a)--(b) on $p$ until no formula can be replaced in $L_i(p)$, then the formulae in $L_i(p)$ are either $\true$, $\ff$, or formulae that start with either $\langle a\rangle$ or $[a]$, $a\in \act$.
\end{lemma}
\begin{proof}
  This is immediate from the definition of moves B($\wedge$) and B($\vee$).
\end{proof}



\begin{definition}\label{def:disj_form}
    Let $\varphi\in\mathL_{\ell S}$, $\ell\geq 1$. The disjunctive form of $\varphi$, denoted  $DF(\varphi)$, is the formula obtained by applying distributivity of conjunction over disjunction to all outermost conjunctions in $\varphi$. A conjunction is said to be outermost if it is not within the scope of any $\langle a\rangle$ or $[a]$, $a\in\act$.
\end{definition}

 For example, $DF(\langle a\rangle (\langle b\rangle \true \wedge (\langle c\rangle \true\vee \langle a\rangle \true)) \wedge ([b]\ff \vee \langle b\rangle \true))=(\langle a\rangle (\langle b\rangle \true \wedge (\langle c\rangle \true\vee \langle a\rangle \true)) \wedge [b]\ff) \vee (\langle a\rangle (\langle b\rangle \true \wedge (\langle c\rangle \true\vee \langle a\rangle \true)) \wedge \langle b\rangle \true)$.


\begin{lemma}\label{lem:steps-Bab-second}
Let $p$ be a state of $T_i$, where $i=1,2$, and $\bigvee_{1\leq i\leq m}\varphi_i$ be the disjunctive form of $\bigwedge \inlabeli(p)$. Then $\bigwedge \finlabeli(p)=\varphi_j$ for some $1\leq j\leq m$. Conversely, for every $\varphi_j$, $1\leq j\leq m$, there is a sequence of choices in the application of B($\wedge$) and B($\vee$) such that $\bigwedge \finlabeli=\varphi_j$.
% Let $p$ be a state of $T_i$, where $i=1,2$, and $\bigvee_{1\leq i\leq m}\varphi_i$ be the disjunctive form of $\bigwedge L_i(p)$. If steps B(a)--(b) are applied on $p$ until no formula can be replaced in $L_i(p)$, then $\bigwedge L_i(p)=\varphi_j$ for some $1\leq j\leq m$. Inversely, for every $\varphi_j$, $1\leq j\leq m$, there is a sequence of choices in the application of B(a)--(b) such that after no formula can be replaced in $L_i(p)$, $\bigwedge L_i(p)=\varphi_j$.
\end{lemma}
\begin{proof}
    This is immediate from the definition of moves B($\wedge$) and B($\vee$).
\end{proof}

\begin{lemma}\label{lem:final-initial-label}
Let $p$ be a state of $T_i$, where $i=1,2$. For every $r\in\proc$, if $r\models\bigwedge\finlabeli(p)$, then $r\models \bigwedge \inlabeli(p)$.
\end{lemma}
\begin{proof}
    Let $r\in\proc$ and $\bigvee_{1\leq i\leq m}\varphi_i=DF(\bigwedge \inlabeli(p))$. Lemma~\ref{lem:DF-equiv} implies that $\bigwedge \inlabeli(p)\equiv \bigvee_{1\leq i\leq m}\varphi_i$. Moreover, from Lemma~\ref{lem:steps-Bab-second}, $\bigwedge \finlabeli(p)=\varphi_j$ for some $1\leq j\leq m$. If $r\models \varphi_j$, then $r\models\bigvee_{1\leq i\leq m}\varphi_i$, and equivalently $r\models\bigwedge \inlabeli(p)$.
\end{proof}

