\begin{definition}\label{def:mapB}
  Assume that the \simequiv game is played on $\varphi\in\mathL_{\ell S}$, $\ell\geq 1$, and $B$ constructs $T_i$, $i=1,2$, such that $\bigwedge \finlabeli(p)$ is satisfiable for every state $p$ added to $S_i$, $i=1,2$. We inductively define the mapping $map_B:S_1\cup S_2\rightarrow \proc$ such that:
  \begin{itemize}
      \item $map_B(p)=\sum_{(p,p')\in R^1_{a_j}} a_j.map_B(p')$, if $p\in S_1$ and $B$ chooses $p$ at step 2 of some round;
      \item $map_B(p)=\sum_{(p,p')\in R^2_{a_j}} a_j.map_B(p')$, if $p\in S_2$ and $A$ chooses $p$ at step 3 of some round;
      \item $map_B(p)=r_p$, where $r_p$ is the least process (w.r.t.\ to depth and size) such that $r_p\models\bigwedge \finlabeli(p)$, otherwise.
  \end{itemize}
\end{definition}

Note that in Definition~\ref{def:mapB}, $map_B$ is well-defined because $\bigwedge \finlabeli(p)$ is satisfiable for every $p\in S_i$ and $i=1,2$. 


\begin{lemma}\label{lem:mapping-r-simulation}
 Assume that the \simequiv game is played on  $\varphi\in\mathL_{\ell S}$, $\ell\geq 1$ and $B$ constructs $T_i$, $i=1,2$, such that $\bigwedge \finlabeli(p)$ is satisfiable for every state $p$ added to $S_i$, $i=1,2$. Then, $B$ plays $T_i$ consistently on $map_B(p_0^i)$ and $map_B(p_0^i)\models\varphi$, where $i=1,2$.
\end{lemma}
\begin{proof}
We prove the lemma for $i=1$; the case  $i=2$ follows by analogous arguments. To this end, we prove that $B$ plays $T_1$ consistently on $map_B(p_0^1)$ by showing that conditions 1 and 2 of Definition~\ref{def:B-plays-consistently} hold for $map_B$ and every $p\in S_1$. Note that condition 3 is trivially true. Let $p\in S_1$. 
\begin{description}
    \item[Condition 2.] For every $(p,p')\in R^1_{a_j}$, condition 2 is satisfied by the definition of $map_B(p)$.
    \item[Condition 1.] We show by induction on the structure of $map_B(p)$ that for every formula $\phi\in \finlabelone(p)$,  $map_B(p)\models\phi$.  If $B$ does not choose $p$ at step 2 of some round, then this is immediate from the definition of $map_B$. Let $p$ be a state chosen by $B$ at step 2 of some round. Since $B$ does not create any state $s$ such that $\bigwedge \finlabelone(s)$ is unsatisfiable, $\ff\not\in \finlabelone(p)$.
    %after steps B(a)--(b) have been applied on $p$. 
    From Lemma~\ref{lem:steps-Bab-first}, every $\phi\in \finlabelone(p)$ is of the form $\true$, $\langle a\rangle \psi$, or $[a]\psi$, $a\in \act$.
    %after steps B(a)--(b) have been applied on $p$.
    Let $\langle a_j\rangle \psi\in \finlabelone(p)$. Then, there is some $p'$ such that $(p,p')\in R^1_{a_j}$ and $\inlabelone(p')=\{\psi\}\cup\{\psi'\mid [a_j]\psi'\in \finlabelone(p)\}$.
    %before steps B(a)--(b) are applied on $p'$. 
    By the inductive hypothesis, $map_B(p')\models\finlabelone(p')$, and from Lemma~\ref{lem:final-initial-label}, $map_B(p')\models\inlabelone(p')$, which implies that $map_B(p')\models \psi$. Therefore, $map_B(p)\models \langle a_j\rangle\psi$.
    % Let $\Psi$ denote  $\bigwedge \inlabelone(p')$ and
    % %Let $S_{p'}$ denote $\inlabelone(p')$ and $\Psi=\bigwedge S_{p'}$;
    % $DF(\Psi)=\bigvee_{i=1}^m\Psi_i$. From Lemma~\ref{lem:steps-Bab-second}, 
    % %after B(a)--(b) is applied on $p'$ (until no formula can be replaced in $L_1(p')$), 
    % $\bigwedge \finlabelone(p')=\Psi_j$ for some $1\leq j\leq m$. This means that 
    % %after steps B(a)--(b) have been applied on $p'$, 
    % $\bigwedge \finlabelone(p')\models\Psi$ and by the inductive hypothesis, $map_B(p')\models\bigwedge \finlabelone(p')$. Therefore, $map_B(p')\models\Psi$ and so $map_B(p')\models \psi$. Thus, $map_B(p)\models \langle a_j\rangle\psi$.
    For $[a_j]\psi\in L_1(p)$, we can prove in a similar way that $map_B(p)\models [a_j]\psi$. It trivially holds that $map_B(p)\models\true$.
\end{description}
Finally, we show that $map_B(p_0^1)\models\varphi$. We have that $map_B(p_0^1)\models \bigwedge \finlabelone(p_0^1)$ because condition 1 holds for $p_0^1$. From Lemma~\ref{lem:final-initial-label}, $map_B(p_0^1)\models \bigwedge \inlabelone(p_0^1)$, where $\inlabelone(p_0^1)=\{\varphi\}$.
% Let $DF(\varphi)=\bigvee_{i=1}^m \varphi_i$. From Lemma~\ref{lem:steps-Bab-second}, $\bigwedge L_1(p_0^1)=\varphi_i$ for some $1\leq i\leq m$, which implies that $\bigwedge L_1(p_0^1)\models\varphi$ and therefore, $map_B(p_0^1)\models\varphi$.
\end{proof}

\begin{lemma}\label{lem:bounded-depth}
    Let $\varphi\in\mathL_{\ell S}$, $\ell\geq 1$, and $p_1,p_2$ be such that $p_1\models\varphi$ and $p_2\models\varphi$. If for every $p,q$, $p\models\varphi$ and $q\models\varphi\Rightarrow p\equiv_S q$, then $\depth(p_1)=\depth(p_2)\leq\md(\varphi)$.
\end{lemma}
\begin{proof}
    % Let $\varphi$ be as in the hypothesis of the lemma. Then, from Propositions~\ref{tableausat} and~\ref{prop:tableau-construction} and the tableau construction described in Subsection~\ref{subsec:tableau-construction}, there is a finite process that satisfies $\varphi$. Let $p_1,p_2$ be two finite processes that satisfy $\varphi$. Using the definition of $\curle_S$, it is not hard to see that  $\depth(p_1)>\depth(p_2)\Rightarrow p_1\not\curle_S p_2$, contradiction.
    We start with the following claim, which is straightforward from the definition of $\curle_S$.
    \begin{claim}\label{claim:not-sim}
      If $\depth(r_1)>\depth(r_2)$, then $r_1\notcurle_S r_2$.
    \end{claim}
    \begin{claimproof}
      Immediate from the definition of $\curle_S$.
    \end{claimproof}
    Thus, $\depth(p_1)=\depth(p_2)$ follows imediately from the hypothesis of the lemma and Claim~\ref{claim:not-sim}. Assume toward contradiction that $\depth(p_i)>\md(\varphi)$ for both $i=1,2$. In the sequel, we need to be able to trim a process $r$ up to depth $d$, i.e.\ we discard the processes reachable from $r$ that have depth greater than $d$, where $d$ is to be determined. To this end, we define process $\trim(r,d)$ for every process $r$ and $d\in\mathbb{N}$, as follows.
   $$\trim(r,d)=\begin{cases}
       r, &\text{if } d\geq \depth(r),\\
       \mathtt{0}, &\text{if } d=0,\\
       \sum_{\substack{a\in\act\\r\myarrowa r'}} a.\trim(r',d-1), &\text{otherwise.}
   \end{cases}$$
  We prove the following claims and use them to show the lemma.
  \begin{claim}\label{claim:trim-depth}
   If $\depth(r) > d$, then $\depth(\trim(r,d))=d$.
  \end{claim}
  \begin{claimproof}
      Immediate from the definition of $\trim(r,d)$.
  \end{claimproof}
  \begin{claim}\label{claim:trim-models-phi}
      If $r\models\varphi$, then $\trim(r,d)\models\varphi$, for every $d\geq \md(\varphi)$.
  \end{claim}
  \begin{claimproof}
     If $\depth(r)\leq d$, then by definition, $\trim(r,d)=r$ and the claim is true. Let $\depth(r)> d$. We prove the lemma by induction on $\varphi$.
      \begin{itemize}
          \item If $\varphi=\true$, then $\trim(r,d)\models\varphi$.
          \item If $\varphi=[a]\varphi'$ for some $a\in\act$, then 
          \begin{itemize}
              \item If $\trim(r,d)\notmyarrowa$, then $\trim(r,d)\models [a]\varphi'$.
              \item Let $\trim(r,d)\myarrowa p$. Then, $p=\trim(r',d-1)$, for some $r\myarrowa r'$, and $d-1\geq \md(\varphi')$. From the inductive hypothesis, $\trim(r',d-1)\models \varphi'$. Therefore, $\trim(r,d)\models [a]\varphi'$.
          \end{itemize}
          \item If $\varphi=\langle a\rangle\varphi'$ for some $a\in\act$, then the proof is similar to the case $\varphi=[a]\varphi'$.
          \item If $\varphi=\varphi_1\wedge\varphi_2$ or $\varphi=\varphi_1\vee\varphi_2$, the claim follows immediately from the inductive hypothesis. \claimqedhere
      \end{itemize}
      \end{claimproof}
  From Claims~\ref{claim:trim-depth} and~\ref{claim:trim-models-phi}, $\trim(p_1,\md(\varphi))\models\varphi$ and $\depth(\trim(p_1,\md(\varphi)))=\md(\varphi)$.  This implies that $\depth(p_1)\neq \depth(\trim(p_1,\md(\varphi)))$, which contradicts the fact that $p_1\equiv_S \trim(p_1,\md(\varphi))$ and so $\depth(p_1)$ $= \depth(\trim(p_1,\md(\varphi)))$ from Claim~\ref{claim:not-sim}.
\end{proof}


\begin{lemma}\label{lem:B-stops}
     Let $\varphi\in\mathL_{\ell S}$, $\ell\geq 1$, be satisfiable and assume that for every processes $p_1,p_2$ that satisfy $\varphi$, it holds that $p_1\equiv_S p_2$. Then,  $B$ stops generating states after  at most $\md(\varphi)+1$ rounds
     %a finite number of rounds 
     in the \simequiv game on $\varphi$.
\end{lemma}
\begin{proof}
   If $B$ generates a state $p\in S_i$, $i=1,2$, such that $\bigwedge \finlabelone(p)$ is unsatisfiable, the game stops and the lemma is trivially true. If $B$ does not generate any state $p\in S_i$ with an unsatisfiable $\bigwedge \finlabelone(p)$, then the lemma is immediate from Lemmas~\ref{lem:mapping-r-simulation} and~\ref{lem:bounded-depth}.
\end{proof}

\begin{proposition}\label{prop:simulation-right-to-left}
    Let $\varphi\in\mathL_{\ell S}$, $\ell\geq 1$. Assume that for every $p_1,p_2$ such that $p_1\models\varphi$ and $p_2\models\varphi$, it holds that $p_1\equiv_S p_2$. Then, $A$ has a winning strategy for the \simequiv game on $\varphi$.
\end{proposition}
\begin{proof}
  Assume that the \simequiv game is played on $\varphi$ and consider the processes $map_B(p_0^1)$ and $map_B(p_0^2)$. From Lemma~\ref{lem:mapping-r-simulation}, $B$ plays $T_i$ consistently on $map_B(p_0^i)$ and $map_B(p_0^i)\models\varphi$, for both $i=1,2$. We prove that $A$ can play in such a way that the following condition is true for every round $l\geq 1$.
    \begin{center}
        \textit{Condition C:} ``The round starts with $p_1$, $p_2$ such that $map_B(p_1)\curle_S map_B(p_2)$ and unless $B$ loses, it ends with $p_1'$, $p_2'$ such that $map_B(p_1')\curle_S map_B(p_2')$.''
    \end{center}
    Note that $map_B(p_0^i)\models\varphi$ for both $i=1,2$, and so from the hypothesis of the proposition, $map_B(p_0^1)\equiv_S map_B(p_0^2)$. The first round starts and ends with $p_0^1$ and $p_0^2$ so condition C is true for $l=1$. Let $l\geq 2$ and assume that condition C is true for round $l-1$. Then, round $l$ starts with the states that round $l-1$ ended with, so the first part of the condition is true for round $l$. If $B$ does not lose at round $l$, then he successfully chooses a state $p_1'$ such that $(p_1,p_1')\in R^1_{a_j}$ at step 2. From Lemma~\ref{lem:mapping-r-simulation}, $map_B(p_1)\myarrowasubj map_B(p_1')$. Since $map_B(p_1)\curle_S map_B(p_2)$, there is $r_{p_2}$ such that $map_B(p_2)\myarrowasubj r_{p_2}$ and $map_B(p_1')\curle_S r_{p_2}$. From Definition~\ref{def:mapB}, there is $p_2'\in S_2$ such that $(p_2, p_2')\in R^2_{a_j}$ and $map_B(p_2')=r_{p_2}$. Player $A$ chooses $p_2'$ and the round ends as the condition describes.

    Since $A$ can play in such a way that every round satisfies condition C, $A$ can play in such a way that the game stops only if $B$ loses. From Lemma~\ref{lem:B-stops}, after at most $\md(\varphi)+1$ rounds,
    %a finite number of rounds 
    $B$ will not generate any successors at moves B($\Diamond$) and B($\square$) and so he will lose.
\end{proof}

%simulation-left-to-right
Next we prove that if there are two processes $r_1, r_2$ such that $r_1\models\varphi$, $r_2\models\varphi$, and $r_1\not\curle_S r_2$, then $B$ has a winning strategy for the \simequiv game on $\varphi$.

\begin{lemma}\label{lem:B-can-play-consistently}
    Assume that the \simequiv game is played on $\varphi\in\mathL_{\ell S}$, $\ell\geq 1$. Let $r$ be a process that satisfies $\varphi$ and $i\in\{1,2\}$. Then, there is a strategy of $B$ that allows him to play $T_i$ consistently on $r$.
\end{lemma}
\begin{proof} 
When we refer to conditions 1--3, we mean conditions 1--3 of  Definition~\ref{def:B-plays-consistently}. Let $map:S_i\rightarrow \proc$ be such that $map(p_0^i)=r$, and so  condition 3 is satisfied. We prove that $B$ can play such that (a) condition 1 is true for  $p_0^i$ and (b) if condition 1 is true for $p\in S_i$, then for every $(p,p')\in R^i_{a_j}$ conditions 1--2 are true for $p'$.
    \begin{enumerate}[(a)]
        \item Condition 1 holds for $p_0^i$: When the game starts, $\inlabeli(p_0^i)=\{\varphi\}$. Let $DF(\varphi)=\bigvee_{i=1}^m\varphi_i$, $m\in\mathbb{N}$. From Lemma~\ref{lem:DF-equiv}, $\varphi\equiv\bigvee_{i=1}^m\varphi_i$, and so $r\models\varphi_j$ for some $1\leq j\leq m$. From Lemma~\ref{lem:steps-Bab-second}, $B$ can apply moves B($\wedge$) and B($\vee$) on $p_0^i$ such that
        %after no formula can be replaced in $L_i(p_0^i)$, 
        $\bigwedge \finlabeli(p_0^i)=\varphi_j$. Then, $map(p_0^i)=r\models\bigwedge \finlabeli(p_0^i)$.
        %where $L_i(p_0^i)$ is the label set of $p_0^i$ after steps B(a)--(b) have been applied on $p_0^i$. 
        \item Assume that $p\in S_i$ and condition 1 holds for $p$. Then, $B$  generates successors of $p$ only when he applies move B($\Diamond$) on $p$ and not during move B($\square$) on $p$.
        %at step 1(c) and chooses not to generate any successor at step 1(d). 
        We show that for every $(p,p')\in R^i_{a_j}$, $map(p)\myarrowasubj map(p')$ and condition 1 is true for $p'$. Let $(p,p')\in R^i_{a_j}$. Then, there is some formula $\langle a_j\rangle \psi\in \finlabeli(p)$, 
        %where $L_i(p)$ is the label set of $p$ after steps B(a)--(b) have been applied on $p$ (or just before the successors of $p$ are generated by $B$), 
        such that $\inlabeli(p')=\{\psi\}\cup\{\psi'\mid [a_j]\psi'\in \finlabeli(p)\}$.
        %when $p'$ is generated.
        Let
        %$\psi\wedge\bigwedge_{[a_j]\psi'\in L_2(p)}\psi'$
        $DF(\bigwedge\inlabeli(p'))=\bigvee_{i=1}^n\Psi_i$. From Lemma~\ref{lem:DF-equiv}, we know that $\bigwedge\inlabeli(p')\equiv \bigvee_{i=1}^n\Psi_i$. Since condition 1 holds for $p$, $map(p)\models \bigwedge \finlabeli(p)$, which implies that $map(p)\models\langle a_j\rangle\bigwedge\inlabeli(p')$, and so there is $map(p)\myarrowasubj r_p$ such that $r_p\models \bigwedge\inlabeli(p')$. Therefore,  $r_p\models\Psi_j$ for some $1\leq j\leq n$. Then, $B$ can apply moves B($\wedge$) and B($\vee$) on $p'$ in such a way that $\bigwedge \finlabeli(p')=\Psi_j$ 
        %after no formula can be replaced in $L_i(p')$. 
        Thus, we can set $map(p')=r_p$ and condition 1 holds for $p'$.
    \end{enumerate}
From (a) and (b) above, $B$ can play in such a way that there is a mapping $map:S_i\rightarrow \proc$ which satisfies conditions 1--3.
\end{proof}

\begin{lemma}\label{lem:B-on-first-process}
 Assume that the \simequiv game is played on $\varphi\in\mathL_{\ell S}$, $\ell\geq 1$. Let $r$ be a process that satisfies $\varphi$ and $r\myarrowasubone r^1\myarrowasubtwo r^2\dots\myarrowasubm r^m$, $m\in\mathbb{N}$, be a trace. Then, there is a strategy of $B$ that allows him to choose state $p_l^1\in S_1$ at step 2 of round $l+1$, for every $1\leq l\leq m$, such that 
