\noindent\textbf{The \nsimeq game, $n\geq 2$}\\

\noindent The following propositions and corollaries are adaptations of Propositions~\ref{prop:simul-game} and~\ref{prop:sim-win-algo}, as well as Corollaries~\ref{cor:simul-game} and~\ref{cor:simul-game-complexity}, to the case of \nsimeq game. The \nsimeq game is correct since these statements hold.

\begin{restatable}{proposition}{nsimulgame}\label{prop:twosimul-game}
  Let $\varphi\in\mathL_{\ell S}$, where $\ell\geq n$, be a satisfiable formula. Player $A$ has a winning strategy for the \nsimeq game on $\varphi$ iff for every two processes $r_1,r_2$ that satisfy $\varphi$, $r_1\equiv_{nS} r_2$.
\end{restatable}
%\nsimulgame*
\noindent\textcolor{darkgray}{\textit{\textbf{Proof sketch.}}}
    %Similarly to the \simequiv game on $\varphi$ and
    Because of the correctness of the \nmosimeq game, if every $r_1,r_2$ that satisfy $\varphi$ are equivalent modulo $\equiv_{nS}$, and so equivalent modulo $\equiv_{(n-1)S}$, then $A$ has a winning strategy for the \nmosimeq game on $\varphi$ that is played at the beginning of the game. Similarly to the \simequiv game on $\varphi$, in every round, $A$ can always choose a state $p_2'$ such that the process corresponding to $p_1'$ is $n$-nested-simulated by the process corresponding to $p_2'$ where these processes are defined through the mapping $map_B$ exactly as in the proof of Lemma~\ref{lem:mapping-r-simulation}. From the assumption that the \nmosimeq game is correct, player $A$ also has a winning strategy for the two versions of the \nmosimeq game played at step 5 of each round. So, the game continues until $B$ loses. For the converse, analogously to the proof of Proposition~\ref{prop:simulation-left-to-right}, if there are $r_1,r_2$ that satisfy $\varphi$ and $r_1\not\curle_{nS} r_2$, we can show that $B$ has a strategy that allows him, in every round, to choose a state $p_1'$  such that the process corresponding to $p_1'$ is not $n$-nested-simulated by the process corresponding to $p_2'$, until $A$ loses.
\hfill$\blacktriangleleft$

