\subsubsection{The \nsimpre game, \texorpdfstring{$n>2$}{n>2}}

Let $n\geq 3$ and consider the \nsimeq game on a satisfiable $\varphi\in\mathL_{nS}$. We use the same notation introduced for the \simequiv game. For every $p\in S_i$, where $i=1,2$, we denote by $\inlabeli(p)$ and $\finlabeli(p)$ the initial and final labels of $p$ before and after moves B($\wedge$) and B($\vee$) are applied on $p$ respectively. For every $p\in S_3$, we denote by $\inlabelthree(p)$ the initial label of $p$ before move A(sub) is applied on $p$, $\starlabelthree(p)$ the label of $p$ after move A(sub) has been applied on $p$, and $\finlabelthree(p)$ the final label of $p$ after moves A($\wedge$) and A($\vee$) have been applied on $p$.

First, we  show that if $\varphi$ is satisfiable and prime, then $A$ has a winning strategy for the \nsimpre game on $\varphi$.

\begin{lemma}\label{lem:extend-prime-set}
 Let $\varphi\in\mathL_{nS}$ be a prime formula.  If $\varphi\models\psi$, where $\psi\in\mathL_{nS}$, then $\varphi\wedge\psi$ is prime.
\end{lemma}
\begin{proof} If $\varphi\models\psi$, then $\varphi$ is logically equivalent to $\varphi\wedge \psi$, and so the latter is also prime. 
% If $\varphi$ is not satisfiable, then the lemma trivially holds. If $\varphi$ is satisfiable, let $p_{min}$ be a process for which $\varphi$ is characteristic within $\mathL_{3S}$. To show that $\varphi\wedge\psi$ is prime, let $\varphi\wedge \psi\models\psi_1\vee\psi_2$. Then $p_{min}\models\varphi\wedge\psi$ because $\varphi\models\psi$. Thus, $p_{min}\models\psi_1\vee\psi_2$, which in turn implies that $p_{min}\models \psi_i$ for some $i=1,2$. From Corollary~\ref{cor:characteristic}, $\varphi\models \psi_i$ and $\varphi\wedge \psi\models\psi_i$. 
\end{proof}

\begin{lemma}\label{lem:step-Aastar-prime}
Assume that the \nsimpre game is played on $\varphi\in\mathL_{nS}$ and $q$ is a state of $T_3$ such that $\bigwedge \inlabelthree(q)$ is prime. Let $A$ apply move A(sub) on $q$ such that for every $\psi\in\sub(\varphi)$, she adds $\psi$ to $L_3(q)$ if $\bigwedge L_3(q)\models \psi$. Then, $\bigwedge \starlabelthree(q)$ is prime.
%after A($a^*$) is applied.
\end{lemma}
\begin{proof}
 Let $q$ be as described in the lemma. From Lemma~\ref{lem:extend-prime-set}, if $\bigwedge L_3(q)\models\psi$, then $\bigwedge L_3(q)\wedge\psi$ is prime. Therefore, if $\bigwedge L_3(q)$ is prime, after the addition of some $\psi$ to $L_3(q)$ as described in the lemma, $\bigwedge L_3(q)$ remains prime.
\end{proof}

\begin{lemma}\label{lem:steps-Aab-first}
    Let $q$ be a state of $T_3$. Then the formulae in $\finlabelthree(q)$  are either $\true$, $\ff$, or formulae that start with either $\langle a\rangle$ or $[a]$, $a\in \act$.
    %If $A$ applies steps A(a)--(b) on $q$ until no formula can be replaced in $L_3(q)$, then the formulae in $L_3(q)$  are either $\true$, $\ff$, or formulae that start with either $\langle a\rangle$ or $[a]$, $a\in \act$.
\end{lemma}
\begin{proof}
  This is immediate from the definition of moves A($\wedge$) and A($\vee$).
\end{proof}


\begin{lemma}\label{lem:steps-Aab-second}
    Let $q$ be a state of $T_3$ and $\bigvee_{1\leq i\leq m}\varphi_i$, $m\in\mathbb{N}$, be the disjunctive form of $\bigwedge \starlabelthree(q)$. 
    %If steps A(a)--(b) are applied on $q$ until no formula can be replaced in $L_3(q)$, 
    Then $\bigwedge \finlabelthree(q)=\varphi_j$ for some $1\leq j\leq m$. Conversely, for every $\varphi_j$, $1\leq j\leq m$, there is a sequence of choices in the application of A($\wedge$) and A($\vee$) on $q$ such that
    %after no formula can be replaced in $L_3(q)$, 
    $\bigwedge \finlabelthree(q)=\varphi_j$.
\end{lemma}
\begin{proof}
    This is immediate from the definition of moves A($\wedge$) and A($\vee$).
\end{proof}

\begin{remark}\label{rem:steps-Bab}
The results of Lemmas~\ref{lem:steps-Aab-first} and~\ref{lem:steps-Aab-second} hold for a state $p_i$ in $T_i$, where $i=1,2$, after moves B($\wedge$) and B($\vee$) are applied on $p_i$. For Lemma~\ref{lem:steps-Aab-second}, $\starlabelthree(q)$ has to be replaced by $\inlabeli(p_i)$ in this case.
\end{remark}

\begin{lemma}\label{lem:final-initial-label-two}
Let $p$ be a state of $T_i$, where $i=1,2,3$. For every $r\in\proc$, if $r\models\bigwedge\finlabeli(p)$, then $r\models \bigwedge \inlabeli(p)$.
\end{lemma}

\begin{lemma}\label{lem:steps-Aab-prime}
 Let $q$ be a state of $T_3$ such that $\bigwedge \starlabelthree(q)$ is prime. There is a sequence of choices that $A$ can make when applying moves A($\wedge$) and A($\vee$) on $q$ such that $\bigwedge \finlabelthree(q)$ is prime.
 %after no other formula can be replaced in $L_3(q)$.
\end{lemma}
\begin{proof}
    Let $\bigvee_{1\leq i\leq m}\varphi_i$, $m\in\mathbb{N}$, be the disjunctive form of $\bigwedge \starlabelthree(q)$. From Lemma~\ref{lem:DF-equiv}, we have that $\bigwedge \starlabelthree(q)\equiv \bigvee_{1\leq i\leq m}\varphi_i$. From Corollary~\ref{cor:char-disj-form}, there is some $1\leq j\leq m$ such that $\varphi_j$ is prime and $\bigwedge \starlabelthree(q)\equiv\varphi_j$.   From Lemma~\ref{lem:steps-Aab-second}, when $A$ applies A($\wedge$) and A($\vee$) on $q$, there is a sequence of choices that she can make such that $\bigwedge \finlabelthree(q)=\varphi_j$.
    %after no formula can be replaced in $L_3(q)$.
\end{proof}


\begin{corollary}\label{cor:steps-Aastarab-prime}
   Assume that the \nsimpre game is played on $\varphi\in\mathL_{nS}$ and $q\in S_3$ such that $\bigwedge \inlabelthree(q)$ is characteristic within $\mathL_{3S}$. Let $A$ apply moves A(sub), A($\wedge$), and A($\vee$) on $q$ as follows. 
    \begin{itemize}
        \item $A$ applies move A(sub) on $q$ such that for every $\psi\in\sub(\varphi)$, she adds $\psi$ to $L_3(q)$ if $\bigwedge L_3(q)\models \psi$.
        \item Let $DF(\starlabelthree(q))=\bigvee_{1\leq i\leq m}\phi^*_i$, $m\in\mathbb{N}$. $A$ applies moves A($\wedge$) and A($\vee$) on $q$ in such a way that $\bigwedge \finlabelthree(q)=\phi^*_j$, for some $1\leq j\leq m$ such that $\phi^*_j$ is prime and $\starlabelthree(q)\equiv\phi^*_j$. 
    \end{itemize}
    Then,  $\bigwedge\inlabelthree(q)\models\bigwedge \finlabelthree(q)$ and $\bigwedge \finlabelthree(q)$ is characteristic within $\mathL_{nS}$.
\end{corollary}

\begin{lemma}\label{lem:step-Ad-prime}
Let $q$ be a state of $T_3$ such that $\bigwedge \finlabelthree(q)$ is characteristic within $\mathL_{nS}$, and $\finlabelthree(q)$ contains only $\true$ or formulae that start with either $\langle a\rangle$ or $[a]$, $a\in \act$. If player $A$ can construct some $j$-successor of $q$ at move A($\Diamond$), she can also construct at least one $j$-successor $q'$ of $q$ such that $\bigwedge \inlabelthree(q')$ is characteristic within $\mathL_{nS}$.
\end{lemma}
\begin{proof}  Let $\langle a_j \rangle\phi_1,\dots, \langle a_j \rangle\phi_{n_j}$  and $[a_j] \psi_1,\dots, [a_j]\psi_{m_j}$ be all the formulae in $\finlabelthree(q)$ that start with $\langle a_j\rangle$ and $[a_j]$ respectively. Let also $\Phi_i=\phi_i\wedge\bigwedge_{k=1}^{m_j}\psi_k$, $1\leq i\leq n_j$. Then, $A$ generates one $j$-successor $q_i$ of $q$ for each $\Phi_i$ and $\bigwedge \inlabelthree(q_i)=\Phi_i$. It is not hard to see that $\langle a_j\rangle\phi_i\wedge\bigwedge_{k=1}^{m_j} [a_j]\psi_k\models \langle a_j\rangle (\phi_i\wedge\bigwedge_{k=1}^{m_j}\psi_k)$ or equivalently, $\langle a_j\rangle\phi_i\wedge\bigwedge_{k=1}^{m_j} [a_j]\psi_k\models \langle a_j\rangle \Phi_i$. This means that if some $\Phi_i$ is not satisfiable, then $\bigwedge \finlabelthree(q)$ is not satisfiable, which contradicts the hypothesis of the lemma. Thus, every $\Phi_i$ is satisfiable, and we show that at least one of the $\Phi_i$'s is prime. Assume, towards a contradiction, that every $\Phi_i$, $1\leq i\leq n_j$, is not prime. Let $p_{min}$ be a process for which $\bigwedge \finlabelthree(q)$ is characteristic within $\mathL_{nS}$. From the fact that $\langle a_j\rangle\phi_i\wedge\bigwedge_{k=1}^{m_j} [a_j]\psi_k\models \langle a_j\rangle \Phi_i$ for every $1\leq i\leq n_j$, there is $p_{min}\myarrowasubj p_i$ such that $p_i\models\Phi_i$ for every $1\leq i\leq n_j$. Let $\Psi_i$ be the characteristic formula for $p_i$ within $\mathL_{nS}$. We prove the following three claims.
     \begin{claim} \label{claim:psi-phi-one}
     For every $1\leq i\leq n_j$, $\Psi_i\models\Phi_i$.
     \end{claim}
     \begin{claimproof}
         It holds that $p_{min}\models \langle a_j\rangle\Psi_i$ and so, from Corollary~\ref{cor:characteristic}, $\bigwedge \finlabelthree(q)\models \langle a_j\rangle\Psi_i$. Moreover, for every process $p$ such that $p\models\Psi_i$, $\mathL_{nS}(p_i)\subseteq\mathL_{nS}(p)$, which implies $p\models \Phi_i$. So, $\Psi_i\models\Phi_i$. \claimqedhere
     \end{claimproof}
     \begin{claim} \label{claim:psi-phi-two}
     For every $1\leq m\leq n_j$ there is some $1\leq i\leq n_j$ such that $\Phi_i\models\Psi_m$.
     \end{claim}
     \begin{claimproof}
        Suppose that there is some $\Psi_{m_0}$ such that for every $1\leq i\leq n_j$, $\Phi_i\not\models \Psi_{m_0}$. Then, there are processes $q_1,\dots,q_{n_j}$  such that for every $1\leq i\leq n_j$, $q_i\models\Phi_i$ and $q_i\not\models\Psi_{m_0}$. Define the process $q =\sum_{i=1}^{n_j} a_j.q_i$. It is not hard to see that $q\models\bigwedge \finlabelthree(q)$ and $q\not\models\langle a_j\rangle \Psi_{m_0}$. However, since for every $1\leq i\leq n_j$,  $p_{min}\models \Psi_i$, we have from Corollary~\ref{cor:characteristic} that $\bigwedge \finlabelthree(q)\models\langle a_j\rangle \Psi_i$ for every $1\leq i\leq n_j$, and so $q\models\langle a_j\rangle\Psi_i$ for every $1\leq i\leq n_j$, which contradicts the fact that $q\not\models\langle a_j\rangle \Psi_{m_0}$. 
       \end{claimproof}
      \begin{claim} \label{claim:psi-phi-three}
          There is at least one $1\leq i\leq n_j$ such that $\Phi_i\models\Psi_i$.
      \end{claim}
      \begin{claimproof}
      Let $i_1\in\{1,\dots,n_j\}$. From Claim~\ref{claim:psi-phi-one}, $\Psi_{i_1}\models\Phi_{i_1}$ and from Claim~\ref{claim:psi-phi-two}, there is some $i_2\in\{1,\dots,n_j\}\setminus\{i_1\}$ such that $\Phi_{i_2}\models\Psi_{i_1}$. By repeating this argument we can take the following logical implications:\\
    $$\begin{aligned}
        \Phi_{i_2}\models&\Psi_{i_1}\models \Phi_{i_1}, ~ i_2\neq i_1\\
        \Phi_{i_3}\models&\Psi_{i_2}\models \Phi_{i_2}, ~ i_3\neq i_2\\
                         &\vdots\\
        \Phi_{i_{(n_j+1)}}\models&\Psi_{i_{n_j}}\models\Phi_{i_{n_j}}, ~ i_{(n_j+1)}\neq i_{n_j}
    \end{aligned}$$
    If $\Phi_{i_2},\dots,\Phi_{i_{(n_j+1)}}$ are pairwise distinct, then  $\Phi_{i_{(n_j+1)}}=\Phi_{i_1}$. In this case, $\Phi_{i_{(n_j+1)}}\models\Psi_{i_{n_j}}\models\Phi_{i_{n_j}}\models\Psi_{i_{(n_j-1)}}\models\Phi_{i_{(n_j-1)}}\models\dots\models\Psi_{i_1}\models\Phi_{i_1}$, which implies that $\Phi_{i_1}\models\Psi_{i_1}$. If there are $i_m,i_k\in\{i_2,\dots,i_{(n_{j+1})}\}$ with $k>m$ such that $\Phi_{i_m}=\Phi_{i_k}$, then $\Phi_{i_k}\models\Psi_{i_{(k-1)}}\models\Phi_{i_{(k-1)}}\models\dots\models\Phi_{i_{(m+1)}}\models\Psi_{i_{m}}\models\Phi_{i_m}$, which implies that $\Phi_{i_m}\models\Psi_{i_m}$.
      \end{claimproof} 
    From Claims~\ref{claim:psi-phi-one} and~\ref{claim:psi-phi-three}, there is some $1\leq i\leq n_j$ such that $\Phi_i\equiv \Psi_i$, which is impossible as $\Psi_i$ is prime and $\Phi_i$ is not prime. Consequently, there is at least one $\Phi_i$ that is prime.
\end{proof}

\begin{lemma}\label{lem:step-Ad-prime-second}
   Assume that $q\in S_3$ such that $\bigwedge\finlabelthree(q)$ is characteristic within $\mathL_{nS}$ and $A$ has just applied move A($\Diamond$). Then, for every $j$-successor $q'$ of $q$ such that $\bigwedge \inlabelthree(q')$ is not prime, there is a $j$-successor $q''$ of $q$ such that $\bigwedge \inlabelthree(q'')\models\bigwedge \inlabelthree(q')$ and $\bigwedge \inlabelthree(q'')$ is characteristic within $\mathL_{nS}$, where $1\leq j\leq k$.
\end{lemma}
\begin{proof}
     The proof is similar to the proof of Lemma~\ref{lem:step-Ad-prime}.  Let $\langle a_j \rangle\phi_1,\dots, \langle a_j \rangle\phi_{n_j}$  and $[a_j] \psi_1,\dots,$ $ [a_j]\psi_{m_j}$ be all the formulae in $\finlabelthree(q)$ that start with $\langle a_j\rangle$ and $[a_j]$ respectively. Let also $\Phi_i=\phi_i\wedge\bigwedge_{k=1}^{m_j}\psi_k$, $1\leq i\leq n_j$. Then, $A$ generates one $j$-successor $q_i$ of $q$ for each $\Phi_i$ and $\bigwedge \inlabelthree(q_i)=\Phi_i$. We also see that every $\Phi_i$ is satisfiable as we observed in the proof of Lemma~\ref{lem:step-Ad-prime}. Define $X =\{\Phi_i \mid \not\exists~ \Phi_j \text{ such that } \Phi_j \text{ is prime and } \Phi_j\models\Phi_i\}=\{\Phi_1,\dots,\Phi_t\}$, where $t\leq n_j$. Note that $X$ contains non-prime formulae, and it suffices to show that $X$ is empty. Let $p_{min}$ be a process for which $\bigwedge \finlabelthree(q)$ is characteristic within $\mathL_{nS}$. From the fact that $\langle a_j\rangle\phi_i\wedge\bigwedge_{k=1}^{m_j} [a_j]\psi_k\models \langle a_j\rangle \Phi_i$ for every $1\leq i\leq n_j$, there is $p_{min}\myarrowasubj p_i$ such that $p_i\models\Phi_i$ for every $1\leq i\leq n_j$. Let $\Psi_i$ be the characteristic formula for $p_i$ within $\mathL_{nS}$.  Claims~\ref{claim:psi-phi-one} and~\ref{claim:psi-phi-two} allow us to take the following logical implications.
     $$\begin{aligned}
        \Phi_{j_1}\models&\Psi_1\models \Phi_1, \\
        \Phi_{j_2}\models&\Psi_2\models \Phi_2,\\
                         &\vdots\\
        \Phi_{j_t}\models&\Psi_t\models\Phi_t.
    \end{aligned}$$
     Note that if $\Phi_{j_i}\not\in X$ for some $1\leq i\leq t$, then there is some $\Phi_k$ such that $\Phi_k$ is prime and $\Phi_k\models \Phi_{j_i}\models\Psi_i\models\Phi_i$, which contradicts the fact that $\Phi_i\in X$. As a result, $\Phi_{j_i}\in X$ for every $1\leq i\leq t$. By applying the same argument as in the proof of Lemma~\ref{claim:psi-phi-three}, we can show that there is some $1\leq i\leq t$ such that $\Phi_i\equiv \Psi_i$, which contradicts the fact that $\Phi_i$ is not prime and $\Psi_i$ is  prime. Consequently, $X$ must be empty.
\end{proof}

\begin{lemma}\label{lem:step-Adastarabe-prime}
    Assume that $q\in S_3$ such that $\bigwedge L_3(q)$ is characteristic within $\mathL_{nS}$ and $A$ has just applied move A($\Diamond$). Let $1\leq j\leq k$. There is a strategy of $A$ such that for every $j$-successor $q'$ of $q$,
    \begin{itemize}
        \item if $\bigwedge \inlabelthree(q')$ is not prime, $q'$ is removed from $T_3$ when move A(rem) is applied on $q$, and
        \item if $\bigwedge \inlabelthree(q')$ is prime, then $\bigwedge \finlabelthree(q')$ is also prime.
    \end{itemize} 
\end{lemma}
\begin{proof}
    To prove the first statement, let  $q'$ be a $j$-successor of $q$ such that $\bigwedge \inlabelthree(q')$ is not prime. From Lemma~\ref{lem:step-Ad-prime-second}, there is a $j$-successor $q''$ of $q$ such that $\bigwedge \inlabelthree(q'')\models\bigwedge \inlabelthree(q')$ and $\bigwedge \inlabelthree(q'')$ is characteristic within $\mathL_{nS}$.  It suffices to describe a sequence of choices that $A$ can make when applying A(sub), A($\wedge$), and A($\vee$) on $q',q''$ such that $\finlabelthree(q')\subseteq \finlabelthree(q'')$. Then, $q'$ will be removed from $T_3$ when A(rem) is applied on $q$.  Assume that the \nsimpre game is played on $\varphi\in\mathL_{nS}$. 
    \begin{description}
        \item[Application of A(sub), A($\wedge$), and A($\vee$) on $q''$.]  The choices of $A$ on $q''$ are the ones described in Corollary~\ref{cor:steps-Aastarab-prime}. At move A(sub), for every $\psi\in\sub(\varphi)$, $A$ adds $\psi$ to $L_3(q'')$ if $\bigwedge L_3(q'')\models\psi$. Let $DF(\bigwedge \starlabelthree(q''))=\bigvee_{i=1}^l\varphi^{q''}_i$, $l\in\mathbb{N}$. $A$ applies A($\wedge$) and A($\vee$) on $q''$ such that $\bigwedge \finlabelthree(q'')=\varphi^{q''}_j$ for some $1\leq j\leq l$, such that $\varphi^{q''}_j$ is prime and $\bigwedge \starlabelthree(q'')\equiv\varphi^{q''}_j$. This is possible from Lemma~\ref{lem:steps-Aab-prime}. 
        \item[Application of A(sub), A($\wedge$), and A($\vee$) on $q'$.] When $A$ applies A(sub) on $q'$, she does not add any $\psi\in\sub(\varphi)$ to $\inlabelthree(q')$. Note that after A(sub) is applied on $q''$, $\inlabelthree(q')\subseteq\starlabelthree(q'')$, since $\bigwedge\inlabelthree(q'')\models \psi$ for every $\psi\in\inlabelthree(q')$. When $A$ applies moves A($\wedge$) and A($\vee$) on $q'$, for every $\psi\in L_3(q')$, she makes the same choices she made for formula $\psi$, when she applied A($\wedge$) and A($\vee$) on $q''$. In this way, $\finlabelthree(q')\subseteq\finlabelthree(q'')$.
         \end{description}
    If for every $j$-successor $q''$ of $q$ such that $\bigwedge\inlabelthree(q'')$ is prime,  moves A(sub), A($\wedge$), and A($\vee$) are applied as described above for $q''$, then $\bigwedge\finlabelthree(q'')$ is prime and the second statement also holds.
\end{proof}

\begin{lemma}\label{lem:2s-equiv-processes}
    Let $\varphi,\psi\in\mathL_{nS}$ such that $\psi$ is prime and $\varphi\models\psi$. Then for every two processes $p,q$, if $p\models\varphi$ and $q\models\psi$, then $p\equiv_{(n-1)S} q$.
\end{lemma}
\begin{proof}
   Let $p,q$ be two processes such that $p\models\varphi$ and $q\models\psi$. Then, $\psi$ is satisfiable and hence, characteristic for a process $p_{min}$ within $\mathL_{nS}$. From $p\models \varphi$ and $\varphi\models\psi$, it holds that $p\models \psi$. From Definition~\ref{def:characteristic} and Proposition~\ref{logical_characterizations}, $p_{min}\curle_{nS} p$ and $p_{min}\curle_{nS} q$, and so by the definition of $\curle_{nS}$, $p_{min}\equiv_{(n-1)S} p\equiv_{(n-1)S} q$.
   %note: if $\varphi,\psi$ are satisfiable, then $\varphi$ is prime.
\end{proof}

\begin{lemma}\label{lem:modal-depth-prime}
    Let $\varphi\in\mathL_{nS}$ be characteristic within $\mathL_{nS}$. Then, all processes that satisfy $\varphi$ have the same depth $d'$, where $d'\leq \md(\varphi)$.
\end{lemma}
\begin{proof}
    Let $q_1,q_2$ be two processes that satisfy $\varphi$. From Definition~\ref{def:characteristic} and Proposition~\ref{logical_characterizations}, there is $p$ such that $p\curle_{nS} q_i$ for both $i=1,2$. As a result, $q_1\equiv_S q_2$. From Lemma~\ref{lem:bounded-depth}, $\depth(q_1)=\depth(q_2)\leq\md(\varphi)$. 
\end{proof}

\begin{proposition}\label{prop:right-to-left}
     Let $\varphi\in\mathL_{nS}$ be characteristic within $\mathL_{nS}$. Then, $A$ has a winning strategy for the \nsimpre game on $\varphi$.
\end{proposition}
\begin{proof}
Let $d$ denote the modal depth of $\varphi$. We will show that $A$ has a strategy that allows her to continue the game until $B$ loses at round $m$, for some $1\leq m\leq d+2$. Consider the following condition.
\begin{quote}
    \textit{Condition C:} ``In the beginning of the round,  $\bigwedge \finlabelthree(q)$  is characteristic within  $\mathL_{3S}$ and  $\bigwedge \finlabeli(p_i)\models \bigwedge \finlabelthree(q)$, for both $i=1,2$.''
\end{quote}
We show that $A$ can play such that the second round satisfies condition C, and if round $l$, where $l\geq 2$, satisfies condition C, she can complete the $l$-th round without losing. In case $B$ does not lose at the $l$-th round, the $l+1$-th round satisfies condition C. Moreover, we show that the game does not last more than $d+1$ rounds.
Note that the first round starts with $L_1(p_1)=L_2(p_2)=L_3(q)=\{\varphi\}$, where $\varphi$ is characteristic within $\mathL_{nS}$.


\begin{claim}\label{claim:cond-c}
    $A$ can make a sequence of choices such that the second round satisfies condition C. Moreover, if round $l$, where $2\leq l\leq d$, satisfies condition C, then player $A$ can make a sequence of choices such that round $l+1$ satisfies condition C.
\end{claim}
\begin{claimproof}
\begin{description}
    \item[The second round can start satisfying condition C.] $A$ can apply moves A(sub), A($\wedge$), and A($\vee$) as described in Corollary~\ref{cor:steps-Aastarab-prime} so that $\bigwedge \finlabelthree(q)$ is prime and $\varphi\models\bigwedge \finlabelthree(q)$ at the end of the round. Thus, $\bigwedge \finlabelthree(q)$ will be satisfiable. Regardless of  $B$'s choices, $\bigwedge \finlabeli(p_i)\models\varphi$ at the end of the round from Lemma~\ref{lem:final-initial-label-two}.
    %from Lemmas~\ref{lem:steps-Aab-second} and~\ref{lem:disjunction_lemma}.
    Therefore,  $\bigwedge \finlabeli(p_i)\models\bigwedge \finlabelthree(q)$ for both $i=1,2$, and the second round starts with the label sets of $p_i$'s and $q$ satisfying condition C.
    \item[The $(l+1)$-th round, $l\geq 2$, can start satisfying condition C.] Let the $l$-th round satisfy condition C. In round $l$, $A$ generates $q_1,\dots,q_{n_j}$. From Lemmas~\ref{lem:step-Ad-prime-second} and~\ref{lem:step-Adastarabe-prime}, there is a sequence of choices that $A$ can make when applying moves A(sub), A($\wedge$), and A($\vee$) on $q_i$'s such that if $\bigwedge \inlabelthree(q_i)$ is not prime, then $q_i$ is removed from $T_3$, and for every $q_i$ that remains in $T_3$, $\bigwedge\finlabelthree(q_i)$ is prime. Therefore, if $B$ chooses some $q'$ at step 3 of the round, then $\bigwedge \finlabelthree(q')$ is characteristic within $\mathL_{nS}$. When $q'$ was created by $A$, $\inlabelthree(q')=\{\phi\}\cup\{\phi'\mid [a_j]\phi'\in \finlabelthree(q)\}$ for some $\langle a_j\rangle\phi\in \finlabelthree(q)$ and  $\bigwedge \finlabelthree(q)\models\langle a_j\rangle\bigwedge \inlabelthree(q')$. After moves A(sub), A($\wedge$), and A($\vee$) are applied on $q'$ as described in Lemma~\ref{lem:step-Adastarabe-prime} and Corollary~\ref{cor:steps-Aastarab-prime}, $\bigwedge\inlabelthree(q')\models \bigwedge \finlabelthree(q')$,
    %$\phi\wedge\bigwedge_{[a_j]\phi'\in L_3(q)}\phi'\models \bigwedge L_3(q')$, 
    so $\bigwedge \finlabelthree(q)\models \langle a_j\rangle \bigwedge \finlabelthree(q')$. From this last fact
    %fact that $\bigwedge L_3(q)\models \langle a_j\rangle \bigwedge L_3(q')$ 
    and since round $l$ satisfies condition C, in the beginning of round $l$, $\bigwedge  \finlabeli(p_i)\models\langle a_j\rangle \bigwedge \finlabelthree(q')$, for both $i=1,2$. From Lemma~\ref{lem:steps-Aab-first} and Remark~\ref{rem:steps-Bab}, it holds that $\finlabeli(p_i)$ contains formulae that start either with $\langle a\rangle$ or $[a]$ (and maybe formula $\true$) and so there is some $\langle a_j\rangle\psi_i\in \finlabeli(p_i)$ such that $\psi_i\wedge\bigwedge_{[a_j]\psi\in \finlabeli(p_i)} \psi\models \finlabelthree(q')$. Consequently, there is a $j$-successor $p_i'$ of $p_i$ such that $\bigwedge \inlabeli(p_i')\models\bigwedge \finlabelthree(q')$. 
    %From Lemmas~\ref{lem:steps-Aab-first} and~\ref{lem:steps-Aab-second} and Remark~\ref{rem:steps-Bab}, 
    From Lemma~\ref{lem:final-initial-label-two}, $\bigwedge\finlabeli(p_i')\models\bigwedge\inlabeli(p_i')$, and so 
    %after steps B(a)--(b) are applied on $p_i'$, 
    $\bigwedge \finlabeli(p_i')\models\bigwedge \finlabelthree(q')$. Thus, given a state $q'$ chosen by $B$ at step 3, $A$ chooses these two states $p_1',p_2'$, whose existence was just proven, and $A$ does not lose at step 4. From Lemma~\ref{lem:2s-equiv-processes}, for every two processes $p,q$ such that $p\models\bigwedge \finlabeli(p_i')$ and $q\models\bigwedge \finlabelthree(q')$, $p\equiv_{2S} q$. From Corollary~\ref{cor:twosimul-game}, $A$ wins all versions of the \nmosimeq game at step 5. The round $l+1$ starts with $p_1',p_2'$, and $q'$, which implies that it satisfies condition C.\claimqedhere
\end{description} 
\end{claimproof}
Finally,  we prove that if $A$ plays according to the strategy described above, after at most $d+1$ rounds, she will not create $j$-successors at step 2, and $B$ will lose at step 3. Let $T_3$ be constructed by $A$ according to the strategy described in the proof of Claim~\ref{claim:cond-c}. From Proposition~\ref{tableausat} and Remark~\ref{rem:tableausat}, we can construct a process  $p$ that satisfies $\varphi$ and has the same depth as $T_3$. Then, from Lemma~\ref{lem:modal-depth-prime}, the depth of  $T_3$ can be at most $d$ and from the definition of the game, $d+1$ rounds suffice to construct any path of $T_3$. After that, at round $d+2$, $A$ will not create any new $j$-successors of $q$ and $B$ will lose. 
%In the case that round $d+2$ is completed without $B$ loosing, it means that $\varphi$ is not prime and the game ends with $B$ winning.
\end{proof}

%left-to-right-direction

Let $\varphi\in\mathL_{nS}$ be satisfiable. Next, we prove that if $A$ has a winning strategy for the \nsimpre game on $\varphi$, then $\varphi$ is prime.
First, recall Definition~\ref{def:B-plays-consistently} where we defined when $B$ plays $T_i$  consistently on a process $r$, where $i=1,2$.

\begin{lemma}\label{lem:Bs-play}
  Assume that the \nsimpre game is played on $\varphi\in\mathL_{nS}$. Let $r_1,r_2$ be two processes that satisfy $\varphi$. Then, there is a strategy of $B$ that allows him to play $T_i$ on $r_i$, where $i=1,2$.
\end{lemma}
\begin{proof}
  The proof is exactly the same as the proof of Lemma~\ref{lem:B-can-play-consistently}.

  We show the lemma for $r_1$. When we refer to conditions 1--3, we mean conditions 1--3 of  Definition~\ref{def:B-plays-consistently}. Let $map:S_1\rightarrow \proc$ be such that $map(p_0^1)=r_1$. We prove that $B$ can play such that (a) condition 1 is true for $p_0^1$ and (b) if condition 1 is true for $p\in S_1$, then for every $(p,p')\in R^1_{a_j}$, conditions 1--2 are true for $p'$. 
    \begin{enumerate}[a.]
        \item Condition 1 holds for $p_0^1$: When the game starts, $\inlabelone(p_0^1)=\{\varphi\}$. Let $DF(\varphi)=\bigvee_{i=1}^m\varphi_i$, $m\in\mathbb{N}$. From Lemma~\ref{lem:DF-equiv}, $\varphi\equiv \bigvee_{i=1}^m\varphi_i$, and so $r_1\models\varphi_j$ for some $1\leq j\leq m$. From Lemma~\ref{lem:steps-Aab-second} and Remark~\ref{rem:steps-Bab}, $B$ can apply moves B($\wedge$) and B($\vee$) on $p_0^1$ such that 
        %after no formula can be replaced in $L_1(p_0^1)$,
        $\bigwedge \finlabelone(p_0^1)=\varphi_j$. Then, $map(p_0^1)=r_1\models\bigwedge \finlabelone(p_0^1)$.
        %where $L_1(p_0^1)$ is the label set of $p_0^1$ after steps B(a)--(b) have been applied on $p_0^1$. 
        \item Assume that $p\in S_1$ for which condition 1 holds. We show that for every $(p,p')\in R^1_{a_j}$, $map(p)\myarrowasubj map(p')$ and condition 1 is true for $p'$. Let $(p,p')\in R^1_{a_j}$. Then, there is some formula $\langle a_j\rangle \psi\in \finlabelone(p)$,
        %where $L_1(p)$ is the label set of $p$ after steps B(a)--(b) have been applied on $p$ (or just before the successors of $p$ are generated by $B$), 
        and $\inlabelone(p')=\{\psi\}\cup\{\psi'\mid [a_j]\psi'\in L_1(p)\}$. Let  $DF(\bigwedge \inlabelone(p'))=\bigvee_{i=1}^n\Psi_i$. Since $map(p)\models \bigwedge \finlabelone(p)$, $map(p)\models\langle a_j\rangle\bigwedge\inlabelone(p')$, and so there is $map(p)\myarrowasubj r_p$ such that $r_p\models \bigwedge\inlabelone(p')$, which implies that $r_p\models\Psi_j$ for some $1\leq j\leq n$, since $\bigwedge \inlabelone(p')\equiv\bigvee_{i=1}^n\Psi_i$ from Lemma~\ref{lem:DF-equiv}.  Then, $B$ can apply moves B($\wedge$) and B($\vee$) on $p'$ in such a way that $\finlabelone(p')=\Psi_j$. Therefore, we can set $map(p')=r_p$ and condition 1 holds for $p'$.
    \end{enumerate}
From (a) and (b) above, $B$ can play in such a way that there is a mapping $map:S_1\rightarrow \proc$ that satisfies conditions 1--3.
The proof for $r_2$ is completely analogous.
\end{proof}

\begin{lemma}\label{lem:As-play}
Assume that $A$ has a winning strategy for the \nsimpre game on $\varphi$. Then, for every two processes $r_1,r_2$ that satisfy $\varphi$, there is a process $t$ such that 
\begin{itemize}
    \item $t\models\varphi$,
    \item $t\curle_{nS} r_1$ and $t\curle_{nS} r_2$,
    \item $|t|\leq (2m+1)^{m+1}$, where $m=|\varphi|$.
\end{itemize} 
\end{lemma}
\begin{proof}
    Let $A$ play according to her winning strategy and $r_1, r_2$ be two processes that satisfy $\varphi$. From Lemma~\ref{lem:Bs-play}, we can assume that $B$ plays $T_1, T_2$ consistently on $r_1,r_2$, respectively; let also $map:S_1\cup S_2\rightarrow\proc$ be the mapping described in Definition~\ref{def:B-plays-consistently}. Assume that when the $l$-th round starts, where $l\geq 2$, $A$ plays on $q$ and $B$ plays on $p_1,p_2$.
    %Since the first and second round start with the same states, it is sufficient to consider $l>1$.
    Let $B$ generate states $p_1^i,\dots,p_{k_i}^i$ that are $j^i_1,\dots,j^i_{k_i}$-successors of $p_i$, $i=1,2$, when he applies move B($\Diamond$) on $p_i$, and $A$ generate $q_1,\dots,q_{k_3}$, which are $j_1,\dots, j_{k_3}$-successors of $q$, when she applies move A($\Diamond$) on $q$. We inductively define  process $t(q,p_1,p_2)$ as follows:
    \begin{itemize}
        \item $t(q,p_1,p_2)=\mathtt{0}$ if $A$ generates no $j$-successor of $q$ when she plays move A($\Diamond$) on $q$.
        \item $t(q,p_1,p_2)=\sum_{i=1}^{k_3}a_{j_i}.t(q_i,p_1(q_i),p_2(q_i))$, where for every $1\leq i\leq k_3$, $p_1(q_i)$, $p_2(q_i)$ are the $j_i$-successors of $p_1,p_2$, respectively, that $A$ chooses at step 4 if $B$ has chosen $q_i$ at step 3.
    \end{itemize}
    Consider the states $q_0$ and $p_0^1,p_0^2$ that $A$ and $B$, respectively, start the game. Let $dt$ denote the depth of $t(q_0,p_0^1,p_0^2)$ and $m$ be the size of $\varphi$. By definition, $dt$ is the length of the maximum trace $q_0, q_1,\dots, q_s$ (for every $1\leq i\leq s$ there is a $1\leq j\leq k$ such that $q_i$ is a $j$-successor of $q_{i-1}$) that $A$ constructs during a play of the game where $B$ plays $T_1, T_2$ consistently on $r_1,r_2$, respectively, and $A$ follows her winning strategy. Since $A$ always wins, we know that $B$ does not win at step 6, and so round $\md(\varphi)+2$ never reaches step 6. Moreover, $A$ starts round $2$ with state $q_0$ and at every round $l$, $2\leq l\leq \md(\varphi)+2$, the length of the path constructed by $A$ is increased by 1. At the end, $A$ constructs a path of length at most $\md(\varphi)+1\leq m+1$. Therefore, the depth of $t(q_0,p_0^1,p_0^2)$ is at most $m+1$.

    We show that 
    \begin{itemize}
        \item $t(q,p_1,p_2)\models \bigwedge \finlabelthree(q)$ (Claim~\ref{claim:process-t-one}),
        \item $t(q,p_1,p_2)\curle_{nS} map(p_1)$ and $t(q,p_1,p_2)\curle_{nS} map(p_2)$ (Claim~\ref{claim:process-t-two}), and 
        \item $|t(q,p_1,p_2)|\leq (2m+1)^{dt}$ (Claim~\ref{claim:process-t-three}).
    \end{itemize}  
    \begin{claim}\label{claim:process-t-one}
        $t(q,p_1,p_2)\models \bigwedge \finlabelthree(q)$.
    \end{claim}
    \begin{claimproof}
    From Lemma~\ref{lem:steps-Aab-first} and the fact that $A$ plays according to her winning strategy, $\finlabelthree(q)$ contains only formulae that start with either $\langle a\rangle$ or $[a]$, $a\in \act$ (and maybe formula $\true$). We show the claim by induction on the depth of $t(q,p_1,p_2)$.
    \begin{itemize}
        \item If $t(q,p_1,p_2)=\mathtt{0}$, then $q$ has no $j$-successors for any $1\leq j \leq k$, which means that all formulae in $\finlabelthree(q)$ start with $[a]$, where $a\in \act$, or they are the formula $\true$. It holds that $\mathtt{0}\models [a]\psi$ for every $a\in \act$ and $\psi\in\mathL_{nS}$, and $\mathtt{0}\models\true$. Therefore, $t(q,p_1,p_2)\models\bigwedge \finlabelthree(q)$.
        \item Let $t(q,p_1,p_2)=\sum_{i=1}^{k_3}a_{j_i}.t(q_i,p_1(q_i),p_2(q_i))$ and $\langle a_j\rangle \psi\in L_3(q)$ for some $1\leq j\leq k$ and $\psi\in\mathL_{nS}$. Then, there is some $q\myarrowasubj q_i$ such that $\psi\in \inlabelthree(q_i)$. By the inductive hypothesis, $t(q_i,p_1(q_i),$ $p_2(q_i))$ $\models\bigwedge \finlabelthree(q_i)$ and so from Lemma~\ref{lem:final-initial-label-two}, $t(q_i,p_1(q_i),p_2(q_i))\models\bigwedge \inlabelthree(q_i)$. This implies that $t(q_i,p_1(q_i),p_2(q_i))\models\psi$. Therefore, $t(q,p_1,p_2)\models \langle a_j\rangle\psi$. Let  $[a_j]\psi\in \finlabelthree(q)$ for some $1\leq j\leq k$ and $\psi\in\mathL_{nS}$. Then, for every $q\myarrowasubj q_i$ it holds that $\psi\in \inlabelthree(q_i)$ and again, by the inductive hypothesis and Lemma~\ref{lem:final-initial-label-two}, $t(q_i,p_1(q_i),p_2(q_i))\models\psi$. Thus, $t(q,p_1,p_2)\models [a_j]\psi$. Consequently, $t(q,p_1,p_2)\models \bigwedge \finlabelthree(q)$.\claimqedhere
    \end{itemize}
     \end{claimproof}
    \begin{claim}\label{claim:process-t-two}
        $t(q,p_1,p_2)\curle_{nS} map(p_1)$ and $t(q,p_1,p_2)\curle_{nS} map(p_2)$.
    \end{claim}
    \begin{claimproof}
       We show by induction on the depth of $t(q,p_1,p_2)$ that if $A$ has a winning strategy on $q,p_1,p_2$, then $t(q,p_1,p_2)\curle_{nS} map(p_1)$ and $t(q,p_1,p_2)\curle_{nS} map(p_2)$. 
    \begin{itemize}
        \item If $t(q,p_1,p_2)=\mathtt{0}$, then $q$ has no $j$-successors for any $1\leq j\leq k$. We have that  $map(p_i)\models\bigwedge \finlabeli(p_i)$, $i=1,2$, from Lemma~\ref{def:B-plays-consistently}(1) and $t(q,p_1,p_2)\models \bigwedge \finlabelthree(q)$ from Claim~\ref{claim:process-t-one}. Since $A$ has a winning strategy on $q,p_1,p_2$, she can play such that she wins all versions of the \nmosimeq game played on $q$, $p_1$, $p_2$ at step 5 of round $l-1$ (or step 1 of the first round if $l=2$) and so, from Corollary~\ref{cor:twosimul-game}, $t(q,p_1,p_2)\equiv_{(n-1)S} map(p_1)\equiv_{(n-1)S} map(p_2)$. This implies that $map(p_i)=\mathtt{0}$ for $i=1,2$, which in turn implies that $t(q,p_1,p_2)\curle_{nS} map(p_1)$ and $t(q,p_1,p_2)\curle_{nS} map(p_2)$.
        \item Let $t(q,p_1,p_2)\myarrowasubj t'$ for some $1\leq j\leq k$. As in the case of $t(q,p_1,p_2)=0$, $t(q,p_1,p_2)\equiv_{(n-1)S} map(p_1)\equiv_{(n-1)S} map(p_2)$. By the definition of $t(q,p_1,p_2)$, there is $q\myarrowasubj q_i$ such that $t'=t(q_i,p_1(q_i),p_2(q_i))$.  By the definition of $p_1(q_i),p_2(q_i)$, it also holds that $p_1\myarrowasubj p_1(q_i)$ and $p_2\myarrowasubj p_2(q_i)$, which together with Definition~\ref{def:B-plays-consistently}(2) implies that $map(p_1)\myarrowasubj map(p_1(q_i))$ and $map(p_2)\myarrowasubj map(p_2(q_i))$. Moreover, by the definition of $p_1(q_i),p_2(q_i)$, $A$ has a winning strategy on $q_i,p_1(q_i),$ $p_2(q_i)$. By the inductive hypothesis, $t(q_i,p_1(q_i),p_2(q_i))\curle_{nS} map(p_1(q_i))$ and $t(q_i,p_1(q_i),p_2(q_i))$ $\curle_{nS} map(p_2(q_i))$, which completes the proof of this case. \claimqedhere
    \end{itemize}
    \end{claimproof}
    \begin{claim}  \label{claim:process-t-three}
 $|t(q,p_1,p_2)|\leq (2m+1)^{dt}$, where $dt$ denotes the depth of $t(q,p_1,p_2)$. 
 \end{claim}
\begin{claimproof}  By induction on $dt$. If $t(q,p_1,p_2)=\mathtt{0}$, the claim is trivial. If $t(q,p_1,p_2)=\sum_{i=1}^{k_3}a_{j_i}.t(q_i,$ $p_1(q_i),p_2(q_i))$, then $|t(q,p_1,p_2)|\leq m\cdot \max_{1\leq i\leq k_3}\{|t(q_i,p_1(q_i),p_2(q_i))|\}+1+m$, where we bounded the number of successors of $q$ by $m$, the plus $1$ is due to the root, and the plus $m$ comes from adding the number of edges to the size.  
Then, $|t(q,p_1,p_2)|\leq (2m+1)\cdot \max_{1\leq i\leq k_3}\{|t(q_i,p_1(q_i),p_2(q_i))|\}$ is an immediate implication of the above inequality. Therefore, we have that $|t(q,p_1,p_2)|\leq (2m+1)^{dt}$.
\end{claimproof}

Claim~\ref{claim:process-t-two} implies that $t(q_0,p_0^1,p_0^2)\curle_{nS} map(p_0^1)$ and $t(q_0,p_0^1,p_0^2)\curle_{nS} map(p_0^2)$. Moreover, $map(p_0^i)=r_i$, $i=1,2$, from Definition~\ref{def:B-plays-consistently}(3), and so $t(q_0,p_0^1,p_0^2)\curle_{nS} r_1$ and $t(q_0,p_0^1,p_0^2)\curle_{nS} r_2$. Claim~\ref{claim:process-t-one} says that $t(q_0,p_0^1,p_0^2)\models \bigwedge \finlabelthree(q_0)$. From Lemma~\ref{lem:final-initial-label-two}, $t(q_0,p_0^1,p_0^2)\models \bigwedge \inlabelthree(q_0)$, and since $\inlabelthree(q_0)=\{\varphi\}$, $t(q_0,p_0^1,p_0^2)\models \varphi$.
Finally, from Claim~\ref{claim:process-t-three} and the observation that $dt\leq m+1$, we have that $|t(q_0,p_0^1,p_0^2)|\leq (2m+1)^{m+1}$. We conclude that process $t(q_0,p_0^1,p_0^2)$ satisfies all three conditions of the lemma.
\end{proof}


\begin{definition}\label{def:expphi}
 We say that a process $p$ is in \expphi if $p\models\varphi$ and $|p|\leq (2m+1)^{m+1}$, where $m=|\varphi|$.
\end{definition}

\begin{corollary}\label{cor:for-every-two-there-is}
 Assume that $A$ has a winning strategy for the \nsimpre game on $\varphi\in\mathL_{nS}$. Then, for every two processes $r_1,r_2\in\expphi$ there is a process $t\in\expphi$ such that $t\curle_{nS} r_1$ and $t\curle_{nS} r_2$.
\end{corollary}
\begin{proof}
     Immediate from Lemma~\ref{lem:As-play}.
\end{proof}

\begin{corollary}\label{cor:for-every-there-is-small}
 Assume that $A$ has a winning strategy for the \nsimpre game on $\varphi\in\mathL_{nS}$. Then, for every process $r$ that satisfies $\varphi$, there is $t\in\expphi$ such that $t\curle_{nS} r$.
\end{corollary}
\begin{proof}
 Immediate from Lemma~\ref{lem:As-play}.
\end{proof}

\begin{lemma}\label{lem:there-is-for-every-small}
    Assume that $A$ has a winning strategy for the \nsimpre game on $\varphi\in\mathL_{nS}$. Then, there is a process $t\in \expphi$ such that for every process $r\in\expphi$, $t\curle_{nS} r$.
\end{lemma}
\begin{proof}
      Let $m\in\{2,\dots,|\expphi|\}$. We prove that for every $m$ processes $r_1, \dots,r_m\in\expphi$ there is some process $t\in\expphi$ such that $t\curle_{nS} r_1,\dots,r_m$. The proof is by strong induction on $m$.
\begin{description}
    \item[Base case.] For $m=2$, the argument holds from Corollary~\ref{cor:for-every-two-there-is}.
    \item[Inductive step.] Let the argument be true for every $2\leq m\leq \ell-1$, where $\ell\geq 3$. We show that it is true for $m=\ell$. Assume w.l.o.g.\ that $\ell$ is even. Let $r_1,\dots,r_\ell$ be processes in \expphi. Consider the pairs $(r_1,r_2)$, $(r_3,r_4),$ $\dots,$
    $(r_{\ell-1},r_\ell)$. From the inductive hypothesis, there are $t_1,\dots, t_{\ell/2}\in\expphi$ such that $t_1\curle_{nS} r_1,r_2$, $t_2\curle_{nS} r_3,r_4$, $\dots$, $t_{\ell/2}\curle_{nS} r_{\ell-1},r_\ell$. From the inductive hypothesis, there is $t\in\expphi$ such that $t\curle_{nS} t_1,\dots,t_{\ell/2}$. By transitivity of $\curle_{nS}$, $t\curle_{nS} r_1,\dots,r_\ell$.  \qedhere
\end{description}
\end{proof}


\begin{corollary}\label{cor:there-is-for-every}
    Assume that $A$ has a winning strategy for the \nsimpre game on $\varphi\in\mathL_{nS}$. Then, there is $t\in\expphi$ such that for every process $r$ that satisfies $\varphi$, $t\curle_{nS} r$.
\end{corollary}
\begin{proof}
    Let $t\in\expphi$ be such that for every $r\in\expphi$, $t\curle_{nS} r$, the existence of which is guaranteed by Lemma~\ref{lem:there-is-for-every-small}. Let $r'$ be a process that satisfies $\varphi$. From Corollary~\ref{cor:for-every-there-is-small}, there is $r''\in\expphi$ such that $r''\curle_{nS} r'$. As a result, $t\curle_{nS} r''\curle_{nS} r'$ which was to be shown.
\end{proof}

\begin{proposition}\label{prop:left-to-right}
  Let $\varphi\in\mathL_{nS}$ be satisfiable. Assume that $A$ has a winning strategy for the \nsimpre game on $\varphi$. Then, $\varphi$ is characteristic for some within $\mathL_{nS}$.
\end{proposition}
\begin{proof}
   From Definition~\ref{def:characteristic}, it suffices to show that there is a process $t$ such that for every process $r$, $r\models \varphi$ iff $\mathL_{nS}(t)\subseteq\mathL_{nS}(r)$. Let $t$ be as described in Corollary~\ref{cor:there-is-for-every} and let $r$ be any process. If $r\models\varphi$, then from Corollary~\ref{cor:there-is-for-every}, $t\curle_{nS} r$, which together with Proposition~\ref{logical_characterizations} implies that $\mathL_{nS}(t)\subseteq\mathL_{nS}(r)$. If  $\mathL_{nS}(t)\subseteq\mathL_{nS}(r)$, then $r\models\varphi$ because $t\models\varphi$.
    \end{proof}

\Awinsprime*
\begin{proof}
     Immediate from Propositions~\ref{prop:right-to-left} and~\ref{prop:left-to-right}. 
\end{proof}

\nprimepspace*
\begin{proof}
  The problem is \pspace-hard from Corollary~\ref{cor:n-sat}. Let $n\geq 3$ and $\varphi\in\mathL_{nS}$. We describe a Turing machine $M$ that runs in polynomial space and decides whether $\varphi$ is prime. First, $M$ checks whether $\varphi$ is satisfiable, which can be done in polynomial space from Corollary~\ref{cor:n-sat}. If $\varphi$ is not satisfiable, then $M$ accepts. If $\varphi$ is satisfiable, than $M$ simulates a polynomial-space algorithm to decide whether $A$ has a winning strategy for the \nsimpre game on $\varphi$. Such an algorithm exists from Corollary~\ref{cor:pspace-games}, since the \nsimpre is a two-player, perfect-information, polynomial-depth game with a \pspace oracle.
\end{proof}

\ncharpspace*
\begin{proof}
   Deciding characteristic formulae within $\mathL_{nS}$ for $n\geq 3$, is \pspace-hard from Proposition~\ref{prop:char-ns-complexity}(b). 
   %In more detail, \pspace hardness of this problem is a corollary of~\cite[Theorem 28]{AcetoACI25}.
   Since the characteristic formulae within $\mathL_{nS}$ are the satisfiable and prime ones---see Proposition~\ref{prop:charact-via-primality}--- the problem is in \pspace from Corollary~\ref{cor:n-sat} and Theorem~\ref{prop:3S-char-in-pspace}.
\end{proof}

\subsection{The complexity of deciding characteristic formulae within \texorpdfstring{$\mathL_{2S}$}{L2S}}\label{appendix:2s-char}

In this subsection, we provide detailed proofs of Theorem~\ref{prop:2S-primality-conpc} and Corollary~\ref{cor:2S-char-dp}.

Given two processes $p,q$, their maximal lower bound is defined below.

\begin{definition}\label{def:gcd}
    Let $p,q\in\proc$. We say that $g$ is  
    %greatest simulated process
    a maximal lower bound of $p$ and $q$ w.r.t.\ a preorder $\leq$
    %denoted  $\grcd_\leq(p,q)$,
    if $g\leq p$ and $g\leq q$, and for every $g'$ such that  $g'\leq p$ and $g'\leq q$, it holds that $g'\leq g$. 
\end{definition}


\begin{remark}\label{rem:gcd-uniqueness}
 Let $p\equiv q$ iff $p\leq q$ and $q\leq p$. Then, for two processes $p,q$, either $p, q$ do not have a maximal lower bound w.r.t.\ $\leq$ or a maximal lower bound of $p$ and $q$ w.r.t.\ $\leq$ exists and is unique up to $\equiv$. In the latter case, we write $\grcd_\leq(p,q)$ for the unique  maximal lower bound of $p$ and $q$ modulo $\equiv$.
\end{remark}

\begin{lemma}\label{lem:sim-equiv-processes}
    Let $p,q\in\proc$  such that $p\equiv_S q$. Then,
    \begin{enumerate}[(a)]
        \item $I(p)=I(q)$ and for every $a\in I(p)$ there are $p^*,q^*$ such that  $p\myarrowa p^*$, $q\myarrowa q^*$, and $p^*\equiv_S q^*$. 
        \item For every $p\myarrowa p'$, either there is some $q\myarrowa q'$ and $p'\equiv_S q'$, or there are $p^*,q^*$ such that  $p\myarrowa p^*$, $q\myarrowa q^*$, $p^*\equiv_S q^*$, and $p'\curle_S p^*$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    (b) Let $p\myarrowa p^{(1)}$ and assume that there is no $q\myarrowa q'$ such that $p^{(1)}\equiv_S q'$; let also $n=|\{p'\mid p\myarrowa p'\}|$, i.e.\ $n$ is the number of processes reachable from $p$ through an $a$-transition. Since $p\equiv_S q$, we have that there are $q^{(1)},p^{(2)},q^{(2)},\dots,p^{(n)},q^{(n)}, p^{(n+1)}$ such that, for every $2\leq i\leq n+1$ and $1\leq j\leq n$,
    $p\myarrowa p^{(i)}$, $q\myarrowa q^{(j)}$, and 
    \[
    p^{(1)}\curle_S q^{(1)}\curle_S p^{(2)}\curle_S q^{(2)}\curle_S\cdots\curle_S p^{(n)}\curle_S q^{(n)}\curle_S p^{(n+1)}. 
    \]
    From the pigeonhole principle, there are some $m_1$ and $m_2$ such that $1 \leq m_1 < m_2 \leq n+1$ and $p^{(m_1)}=p^{(m_2)}$.
    Then, $p^{(m_1)}\curle_S q^{(m_1)}\curle_S p^{(m_2)}$, which implies that $p^{(m_1)}\equiv_S q^{(m_1)}$. Moreover, $p^{(1)}\curle_S p^{(m_1)}$. 
    So, $p^*, q^*$ of the lemma are $p^{(m_1)}, q^{(m_1)}$, respectively.

    (a) This is immediate from (b).
\end{proof}

\begin{lemma}\label{lem:gcd-2s-poly-time}
Let $p,q\in\proc$. We can decide whether $\grcd_{\curle_{2S}}(p,q)$ exists in polynomial time. Moreover, if $\grcd_{\curle_{2S}}(p,q)$ exists, its size is at most $2|p||q|$\footnote{Here, we mean that there is a process $g$ that satisfies the properties of Definition~\ref{def:gcd} and is of size at most $2|p||q|$. In the sequel, we use the notation $\grcd_{\curle_{2S}}(p,q)$ in the same way.} and it can be computed in polynomial time.
\end{lemma}
\begin{proof} 
In case $p\not\equiv_{S} q$, there is no $r\in\proc$ such that $r\curle_{2S} p$ and $r\curle_{2S} q$, and so $\grcd_{\curle_{2S}}(p,q)$ does not exist. For $p,q\in\proc$ such that $p\equiv_S q$, we define $(p,q)$ as follows.
\[
(p,q)=\sum \{ a.(p',q') \mid a\in \act,~p\myarrowa p',~q\myarrowa q'\text{ and } p'\equiv_S q' \}.
\]
%$$(p,q)=\sum_{\substack{a\in \act\\ p\myarrowa %p'\\q\myarrowa q'\\ p'\equiv_S q'}} a.(p',q').$$
Intuitively, for every $p'\in\reach(p)$ and $q'\in\reach(q)$, we form a pair $(p',q')$ only if $p'\equiv_S q'$. Then, we connect two pairs $(p',q')$ and $(p'',q'')$ through transition $a$, if $p'\myarrowa p''$ and $q'\myarrowa q''$. We prove that for every $p,q\in\proc$, process $(p,q)$ satisfies the conditions of Definition~\ref{def:gcd}.
    % Consider the LTSs $\mathS_{p_1}=(P_1,\act,\longrightarrow_1)$ and $\mathS_{p_2}=(P_2,\act,\longrightarrow_2)$ that correspond to $p_1$ and $p_2$, respectively. We construct LTS $\mathS_{p_1\times p_2}=(P,\act,\longrightarrow_{1\times 2})$ by starting with empty $P$ and $\longrightarrow_{1\times 2}$ and applying the following steps.
    % \begin{description}
    %     \item[Step 1: Add states.] For every $p\in P_1$, $q\in P_2$, such that $p\equiv_S q$, add $(p,q)$ to $P$.
    %     \item[Step 2: Add transitions.] For every $(p,q), (p',q')\in P$ and $a\in \act$, if $p\myarrowa p'$ and $q\myarrowa q'$, then add $((p,q),a, (p',q'))$ to $\longrightarrow_{1\times 2}$.
    %     \item[Step 3. Remove non-reachable states.] For every $(p,q)\in P$, if $(p,q)\not\in\reach((p_1,p_2))$, then remove $(p,q)$ from $P$.
    % \end{description}
    %  We show that if $\mathS_{p_1\times p_2}$ is not empty, then it is the unique $\grcd_{\curle_{2S}}(p_1,p_2)$ up to $\equiv_{2S}$. 
     \begin{claim}\label{claim:gcd-one}
     For every $(p,q)$, it holds that $(p,q)\curle_{2S} p$ and $(p,q)\curle_{2S} q$.
     \end{claim}
     \begin{claimproof}
     We prove the claim by induction on the size of $(p,q)$.
      \begin{description}
        \item[Let $(p,q)=\mathtt{0}$.] From the definition of $(p,q)$, we have that $p\equiv_S q$. Assume, towards a contradiction, that $I(p)\neq\emptyset$ and $a\in I(p)$ for some $a\in\act$. Then, Lemma~\ref{lem:sim-equiv-processes}(a) implies that there are $p\myarrowa p^*$ and $q\myarrowa q^*$ such that $p^*\equiv_S q^*$. By the definition of $(p,q)$, we have that $(p,q)\myarrowa (p^*,q^*)$, which contradicts the proviso for this case. 
        %We conclude the same contradiction if we assume %that $I(q)\neq\emptyset$. 
        Therefore, $I(p)=\emptyset$ and, by symmetry, $p=q=\mathtt{0}$. Finally, $(p,q)\curle_{2S} p$ and $(p,q)\curle_{2S} q$. 
        \item[Let $(p,q)\myarrowa (p',q')$ for some $a\in\act$.] Then, there are $p',q'\in\proc$, such that $p'\equiv_S q'$, $p\myarrowa p'$, and $q\myarrowa q'$. From the inductive hypothesis, $(p',q')\curle_{2S} p'$ and $(p',q')\curle_{2S} q'$. We also show that $p\curle_S (p,q)$ and $q\curle_S (p,q)$. Let $p\myarrowa p'$. From Lemma~\ref{lem:sim-equiv-processes}(b), one of the following holds.
        \begin{itemize}
            \item There is $q\myarrowa q'$ and $p'\equiv_S q'$, which means that $(p,q)\myarrowa (p',q')$. From the inductive hypothesis, $p'\curle_S (p',q')$.
            \item There are $p^*,q^*$ such that $p\myarrowa p^*$, $q\myarrowa q^*$, $p^*\equiv_S q^*$, and $p'\curle_S p^*$. From the inductive hypothesis, $p^*\curle_S (p^*,q^*)$ and therefore, $p'\curle_S (p^*,q^*)$.
        \end{itemize}
        We can show that $q\curle_S (p,q)$ in an analogous way.\claimqedhere
        \end{description}
         \end{claimproof}
   \begin{claim}\label{claim:gcd-two}
       For every $p,q\in\proc$ and $r\in\proc$ such that $r\curle_{2S} p$ and $r\curle_{2S} q$, it holds that $r\curle_{2S} (p,q)$.
   \end{claim}
    \begin{claimproof}
        Assume that there is a process $r$ such that $r\curle_{2S} p$ and $r\curle_{2S} q$. We prove the claim by induction on $p$ and $q$.
        \begin{itemize}
            \item If $p=q=\mathtt{0}$, then $r=\mathtt{0}$ and the claim trivially holds.
            \item Let $I(p)\neq \emptyset$ or $I(q)\neq\emptyset$. From the hypothesis of the claim, $r\equiv_S p \equiv_S q$.
            From Claim~\ref{claim:gcd-one}, $(p,q)\equiv_S p\equiv_S q$ and therefore, $(p,q)\equiv_S r$. Let $r\myarrowa r'$. From the hypothesis of the claim, there are $p\myarrowa p'$ and $q\myarrowa q'$ such that $r'\curle_{2S} p'$ and $r'\curle_{2S} q'$. Hence, $p'\equiv_S q'$, and from the definition of $(p,q)$, $(p,q)\myarrowa (p',q')$. From the inductive hypothesis, $r'\curle_{2S} (p',q')$.\claimqedhere
        \end{itemize} 
        \end{claimproof}
    \begin{claim}\label{claim:gcd-three}
    For every $p,q\in\proc$, $\grcd_{\curle_{2S}}(p,q)$ exists iff $p\equiv_S q$. 
    \end{claim}
    \begin{claimproof}
        Let $p,q\in\proc$ and $g$ denote $\grcd_{\curle_{2S}}(p,q)$. If $g$ exists, then $g\curle_{2S} p$ and $g\curle_{2S} q$, which implies that $g\equiv_S p\equiv_S q$. Conversely, if $p\equiv_S q$, then from Claim~\ref{claim:gcd-one}, $(p,q)\curle_{2S} p$ and $(p,q)\curle_{2S} q$. From Claim~\ref{claim:gcd-two}, if there is $r\in\proc$ such that $r\curle_{2S} p$ and $r\curle_{2S} q$, then $r\curle_{2S} (p,q)$. So $(p,q)$ satisfies the conditions of Definition~\ref{def:gcd}.
    \end{claimproof} 

Claim~\ref{claim:gcd-three} implies that the existence of $\grcd_{\curle_{2S}}(p,q)$, $p,q\in\proc$, can be decided in polynomial time, since $p\equiv_S q$ can be checked in polynomial time~\cite{HT94, KS90}.
    \begin{claim}\label{claim:gcd-four}
       If $\grcd_{\curle_{2S}}(p,q)$ exists, then $(p,q)\equiv_{2S} \grcd_{\curle_{2S}}(p,q)$.
    \end{claim}
    \begin{claimproof}
     This is immediate from the proof of Claim~\ref{claim:gcd-three} and Remark~\ref{rem:gcd-uniqueness}.   
    \end{claimproof} 

    Claim~\ref{claim:gcd-four} says that $(p,q)$ is the unique $\grcd_{\curle_{2S}}(p,q)$ modulo $\equiv_{2S}$. From Claim~\ref{claim:gcd-four}, the definition of $(p,q)$,  and the fact that $p\equiv_S q$ can be checked in polynomial time, computing and returning $(p,q)$ can be done in polynomial time. In particular, the number of processes reachable from $(p,q)$ is bounded by the number of pairs $(p',q')$ such that $p'\in\reach(p)$ and $q'\in\reach(q)$. Therefore, $|(p,q)|\leq 2 |p| |q|$, where the factor of 2 accounts for both the pairs reachable from $(p,q)$ and the transitions between them.
    \end{proof}

     Procedure \gcd{$p,q$} in Algorithm~\ref{alg:procedures} computes the unique $\grcd_{\curle_{2S}}(p,q)$ modulo $\equiv_{2S}$ as was described in the proof of Lemma~\ref{lem:gcd-2s-poly-time}, and so \gcd{$p,q$} runs in polynomial time.

