\begin{lemma}\label{lem:gcd-satisfies-phi}
Let $\varphi\in\mathL_{2S}$ and $p,q\in\proc$ such that $p\models\varphi$ and $q\models\varphi$. Then, the following are equivalent.
\begin{enumerate}
    \item $\grcd_{\curle_{2S}}(p,q)$ exists and $\grcd_{\curle_{2S}}(p,q)\models\varphi$.
    \item There is a process $r$ such that $r\models\varphi$, $r\curle_{2S} p$ and $r\curle_{2S} q$.
\end{enumerate}
\end{lemma}
\begin{proof}
    Let $g$ denote  $\grcd_{\curle_{2S}}(p,q)$.\\
    $(1)\Rightarrow (2)$ If $g\models\varphi$, then (2) is true by the definition of $g$.\\
    $(2)\Rightarrow (1)$ If there is a process $r$ as described in (2), then by the definition of $g$, $r\curle_{2S} g$, and from Proposition~\ref{logical_characterizations}, 
    $g\models \varphi$.
\end{proof}

%We introduce a non-deterministic algorithm, called $\mathtt{ConPro}$, which decides satisfiability in  $\mathL_{2S}$. In addition, it includes a subroutine (lines 21--30) that will later be used to detect whether there exist two processes $p$ and $q$ that both satisfy a given formula $\varphi$ but $p\not\equiv_S q$. The algorithm is described in detail in Algorithm~\ref{alg:process-construction}. Note that if $\mathtt{ConPro}(\varphi)$ halts at line 12, 18, or 28, it does so without returning an output. Nevertheless, we prove that for every satisfiable formula $\varphi \in \mathL_{2S}$, there exists at least one execution path of the algorithm that successfully produces an output.

\begin{lemma}\label{lem:phi-sat}
Let $\varphi\in\mathL_{2S}$ be a satisfiable formula. There is a sequence of non-deterministic choices that $\mathtt{ConPro}(\varphi)$ can make such that it outputs some $(S,R_{a_1},\dots,R_{a_k})$. 
\end{lemma}
\begin{proof}
   Let $s\in S$ and $L_{12}(s)$ denote the set of formulae that $L(s)$ contains after line 12 of Algorithm~\ref{alg:process-construction} is completed. The following two claims follow directly from the operations performed in lines 8--12 of the algorithm.
   \begin{claim}\label{claim:line-eleven}
       After lines 8--12 of Algorithm~\ref{alg:process-construction} are executed and if the algorithm does not stop at line 12, $L_{12}(s)$ contains formulae that are either the formula $\true$ or start with $\langle a\rangle$ or $[a]$, for some $a\in\act$.
   \end{claim}
   \begin{claim}\label{claim:lines-seven-to-eleven}
       Assume that $\mathtt{ConPro}(\varphi)$ is at line 6 and starts examining a state $s$ and $DF(\bigwedge L(s))=\bigvee_{i=1}^m\Phi_i$. After executing lines 8--11, $\bigwedge L_{12}(s)=\Phi_n$ for some $1\leq n\leq m$. Conversely, for every $1\leq n\leq m$, there is a sequence of non-deterministic choices that $\mathtt{ConPro}(\varphi)$ can make, when executing lines 8--11, such that $\bigwedge L_{12}(s)=\Phi_n$.
   \end{claim}
   We show that there is a sequence of non-deterministic choices of $\mathtt{ConPro}(\varphi)$ such that the algorithm does not stop at lines 12, 18, and 28, and it outputs some $(S, R_{a_1}, \dots, R_{a_k})$. 
  \begin{claim}\label{claim:line-25}
     There is a sequence of non-deterministic choices such that $\mathtt{ConPro}(\varphi)$ does not stop at line 28.
  \end{claim}
  \begin{claimproof}
      When $\mathtt{ConPro}(\varphi)$ executes line 20, non-deterministically chooses to go to line 6, and so lines 21--30 are not executed.
  \end{claimproof}
\begin{claim}\label{claim:lines-11-25}
Assume that $\mathtt{ConPro}(\varphi)$ is at line 7 and starts examining a state $s$ such that $\bigwedge L(s)$ is satisfiable. Then, there is a sequence of non-deterministic choices that $\mathtt{ConPro}(\varphi)$ can make at lines 8--11 such that it does not stop at lines 12 and 18. Moreover, for every $1\leq j\leq k$ and $(s,s')$ that is added to $R_{a_j}$ at line 17, $\bigwedge L(s')$ is satisfiable.
\end{claim}
\begin{claimproof}
    Let $DF(\bigwedge L(s))=\bigvee_{i=1}^m\Phi_i$. From Lemma~\ref{lem:DF-equiv}, $\bigwedge L(s)\equiv\bigvee_{i=1}^m\Phi_i$. Assume that $\mathtt{ConPro}(\varphi)$ examines $s$ and executes lines 8--12. Since $\bigwedge L(s)$ is satisfiable and $\bigwedge L(s)\equiv\bigvee_{i=1}^m\Phi_i$, there is some satisfiable $\Phi_n$, $1\leq n\leq m$. From Claim~\ref{claim:lines-seven-to-eleven}, $\mathtt{ConPro}(\varphi)$ can make such non-deterministic choices while executing lines 8--11 so that $\bigwedge L_{12}(s)=\Phi_n$. Since $\Phi_n$ is satisfiable,  $L_{12}(s)$ does not contain $\ff$ and $\mathtt{ConPro}(\varphi)$ does not stop at line 12. Let $1\leq j\leq k$ and $\langle a_j\rangle\psi_1,\dots,\langle a_j\rangle\psi_t,[a_j]\psi_1',\dots,[a_j]\psi'_{t'}$ be all formulae in $L_{12}(s)$ that start with $\langle a_j\rangle$ or $[a_j]$. Then, since $\Phi_n$ is satisfiable, for every $1\leq i\leq t$, $\langle a_j\rangle\psi_i\wedge\bigwedge_{l=1}^{t'} [a_j]\psi'_l$ is satisfiable. As a result, $\psi_i\wedge\bigwedge_{l=1}^{t'}\psi'_l$ is satisfiable, which implies that for every $(s,s')$ that is added to $R_{a_j}$ at line 17, $\bigwedge L(s')$ is satisfiable. In particular, $L(s')$ does not contain $\ff$ and the algorithm does not stop at line 18.
\end{claimproof}

\begin{claim}\label{claim:output}
    Assume that $\mathtt{ConPro}(\varphi)$ makes the non-deterministic choices described in Claims~\ref{claim:line-25} and~\ref{claim:lines-11-25}. Then, $\mathtt{ConPro}(\varphi)$ outputs some $(S,R_{a_1},\dots, R_{a_k})$.
\end{claim}
\begin{claimproof}
    Immediate from Claims~\ref{claim:line-25} and~\ref{claim:lines-11-25} and the fact that the algorithm starts with $L(s_0)=\{\varphi\}$, where $\varphi$ is satisfiable.
\end{claimproof}

Claim~\ref{claim:output} guarantees that the algorithm returns an output when the input is a satisfiable formula in $\mathL_{2S}$.
\end{proof}

Next, we prove that in case $\mathtt{ConPro}(\varphi)$ returns an output, then $\varphi\in\mathL_{2S}$ is satisfiable. The next lemma uses procedure \process{$S,s,R_{a_1},\dots, R_{a_k}$}, which takes as input a set of states $S$, a designated state $s\in S$, and the  binary relations $R_{a_1},\dots, R_{a_k}$ over $S$, and returns the process that naturally corresponds to its input. It is described in Algorithm~\ref{alg:procedures}.

\begin{lemma}\label{lem:model-of-phi-and-phi-unsat}
Let $\varphi\in\mathL_{2S}$, $(S,R_{a_1},\dots,R_{a_k})$ be an output of $\mathtt{ConPro}(\varphi)$, and $r$ denote \process{$S,s_0,R_{a_1},\dots,R_{a_k}$}, where  $s_0$ is the first state added to $S$ by the algorithm. Then, $|r|\leq\md(\varphi)+1$ and $r\models\varphi$.
\end{lemma}
\begin{proof}
Note that a state $s$ is added to the queue $Q$ at lines 19 and 29 only if $d(s)\leq \md(\varphi)$ and is examined by the algorithm during a future iteration. When $s$ is examined, if a new state $s'$ is added to $S$, then $d(s')=d(s)+1$. Given that the initial state $s_0$ has $d(s_0)=0$, and a state $s'$ can be also added to $S$ when examining a state $s$ with $d(s)=\md(\varphi)$, it follows that, upon completion of the algorithm, every $s\in S$ satisfies $d(s)\leq\md(\varphi)+1$. It is immediate from the structure of the procedure \process{$\cdot$} described in Algorithm~\ref{alg:procedures}, that \process{$S,s_0,R_{a_1},\dots,R_{a_k}$} is a process of depth bounded by $\md(\varphi)+1$. We show that \process{$S,s_0,R_{a_1},\dots,R_{a_k}$}$\models\varphi$.

\begin{claim}\label{claim:modal-depth}
    For every $s\in S$, $\max\{\md(\psi)\mid \psi\in L_{12}(s)\}=\begin{cases}
        \md(\varphi)-d(s), &\text{if } d(s)\leq\md(\varphi),\\
        0, &\text{otherwise}
    \end{cases}$.
\end{claim}
\begin{claimproof}
    By an easy induction on $d(s)$.
\end{claimproof}

  \begin{claim}\label{claim:process}
      For every $s\in S$, \process{$S,s, R_{a_1}, \dots, R_{a_k}$}$\models \bigwedge L_{12}(s)$.
  \end{claim}
  \begin{claimproof}
    By induction on $\max\{\md(\psi)\mid \psi\in L_{12}(s)\}$. In the base case, $L_{12}(s)$ either contains formula $\true$ or is empty, and so the claim trivially holds. It is not hard to show the inductive step.
    \end{claimproof}

 The following claim is straightforward from Claim~\ref{claim:process}.
\begin{claim}\label{claim:pzero}
    \process{$S,s_0, R_{a_1}, \dots, R_{a_k}$}$\models\varphi$.
\end{claim}
\begin{claimproof}
 Let $DF(\varphi)=\bigvee_{i=1}^n\varphi_i$. From Lemma~\ref{lem:DF-equiv}, $\varphi\equiv \bigvee_{i=1}^n\varphi_i$.  From Claim~\ref{claim:process}, when the algorithm examines $s_0$ and after lines 8--11 have been executed, $\bigwedge L_{12}(s_0)=\varphi_j$ for some $1\leq j\leq n$. Consequently, $\bigwedge L_{12}(s_0)\models\varphi$, and, \process{$S,s_0, R_{a_1}, \dots, R_{a_k}$}$\models\varphi$.
\end{claimproof}
The lemma follows directly from the observations of the first paragraph of this proof and Claim~\ref{claim:pzero}.
\end{proof}

\begin{lemma}\label{lem:model-of-phi-size}
  Let $\varphi\in\mathL_{2S}$, $(S,R_{a_1},\dots,R_{a_k})$ be an output of $\mathtt{ConPro}(\varphi)$, and $r$ denote $\mathtt{Process}(S,s_0,R_{a_1},\dots,$ $R_{a_k})$, where  $s_0$ is the first state added to $S$ by the algorithm. Then, $|r|\leq 4|\varphi|$.
\end{lemma}
\begin{proof}
 If lines 21--30 of $\mathtt{ConPro}$ are omitted, then the algorithm constructs a tableau for $\varphi$, which is of polynomial size as was shown in~\cite[Proposition 77]{AACI24}. In particular, if the algorithm did not contain lines 21--30, the number of states added to $S$ would be bounded by $|\varphi|$.  Since a new pair is added to $R_{a_j}$, for some $1\leq j\leq k$, every time a fresh state is added to $S$, the number of pairs added to all $R_{a_j}$, $1\leq j\leq k$, would also be at most $|\varphi|$. 
 In the worst case, lines 23--30, i.e.\ the last for-loop of the algorithm, will be executed at most $|\varphi|$ times: variable $BoxCount$ is increased by one every time these lines are completed and the number of iterations of the for-loop, namely $N$, is chosen to be at most $|\varphi|-BoxCount$ at line 21. Consequently, the execution of lines 21--30 can add at most $|\varphi|$ states to $S$ and at most $|\varphi|$ pairs to all $R_{a_j}$. Note also that if a state $s$ is added to $S$ at line 24, then $L(s)$ consists of formulae that do not contain $\langle a \rangle$ for any $a\in \act$, because $\varphi\in\mathL_{2S}$. Consequently, when $s$ is examined, the for-loop starting at line 13 will be skipped. So, state $s$ can only lead to the addition of more states to $S$ at line 24, and we already argued that no more than $|\varphi|$ can be added to $S$ because of that line.
  As a result, there are at most $2|\varphi|$ states in $S$ and $2|\varphi|$ pairs in all $R_{a_j}$ when the algorithm returns the output $(S, R_{a_1},\dots, R_{a_k})$.   
 Given the structure of \process{$\cdot$} and the fact that $(S, R_{a_1}, \dots, R_{a_k})$ forms a directed tree when interpreted as a graph, it follows that \process{$S, s_0, R_{a_1}, \dots, R_{a_k}$} is of size at most $4|\varphi|$.
\end{proof}

