We now examine $\mathtt{Prime_{2S}}$, which decides primality in the logic $\mathL_{2S}$. As shown in Algorithm~\ref{alg:prime-twosim}, $\mathtt{Prime_{2S}}(\varphi)$ uses $\mathtt{ConPro}(\varphi)$ as a subroutine, as well as procedures \process{$\cdot$} and \gcd{$\cdot$} that are presented in Algorithm~\ref{alg:procedures}. Previously, in Lemma~\ref{lem:phi-sat}, our focus was on the existence of an execution of $\mathtt{ConPro}(\varphi)$ that returns an output when $\varphi$ is satisfiable. In contrast, our current analysis concerns whether every execution of $\mathtt{Prime_{2S}}(\varphi)$ results in acceptance. This shift in perspective leads us to examine the behavior of all possible executions of $\mathtt{ConPro}$ within $\mathtt{Prime_{2S}}$.

\begin{algorithm}
\caption{Procedure 
$\mathtt{Process}(S,s_0,R_{a_1},\dots,R_{a_k})$
returns the process that naturally corresponds to its input. Procedure 
$\mathtt{MLB}(p,q)$ 
returns  
$\grcd_{\curle_{2S}}(p,q)$.}
\label{alg:procedures}
\DontPrintSemicolon
  \SetKwFunction{process}{Process}
  \SetKwProg{Fn}{procedure}{:}{}
  \Fn{\process{$S,s_0,R_{a_1},\dots,R_{a_k}$}}{
  {return $\displaystyle\sum_{\substack{a\in\act\\(s, s')\in R_{a}}}a.\process{$S,s',R_{a_1},\dots,R_{a_k}$}$}}
  \;
   \SetKwFunction{gcd}{MLB}
  \SetKwProg{Fn}{procedure}{:}{}
  \Fn{\gcd{$p,q$}}{
     \lIf{$p\not\equiv_S q$}{stop}
     %\lIf{$p=q=\mathtt{0}$}{return $\mathtt{0}$}
     \lElse{return $\displaystyle\sum_{\substack{a\in \act\\ p\myarrowa p'\\q\myarrowa q'\\ p'\equiv_S q'}} a.$\gcd{$p',q'$}}}
\end{algorithm}

We show that $\varphi\in\mathL_{2S}$ is prime iff every execution of $\mathtt{Prime_{2S}}(\varphi)$ accepts, thus establishing that the problem lies in \conp.

\begin{proposition}\label{prop:prime-implies-accept}
    If $\varphi\in\mathL_{2S}$ is prime, then every sequence of non-deterministic choices that $\mathtt{Prime}_{2S}(\varphi)$ makes leads to acceptance.
\end{proposition}
\begin{proof}
    If $\varphi$ is unsatisfiable and prime, then from Lemma~\ref{lem:model-of-phi-and-phi-unsat}, $\mathtt{ConPro}$ does not return an output and $\mathtt{{Prime}_{2S}}(\varphi)$ accepts at line 5. Assume that $\varphi$ is satisfiable and prime and $\mathtt{ConPro}(\varphi)$ returns an output at both lines 1 and 3 of $\mathtt{{Prime}_{2S}}(\varphi)$. From Lemma~\ref{lem:model-of-phi-and-phi-unsat}, $p_1\models\varphi$ and $p_2\models\varphi$. From Proposition~\ref{prop:charact-via-primality}, $\varphi$ is characteristic for a process within $\mathL_{2S}$. Let $p$ denote the process for which $\varphi$ is characteristic within $\mathL_{2S}$. Then, because of Definition~\ref{def:characteristic}, $p\models\varphi$, and $\mathL_{2S}(p)\subseteq \mathL_{2S}(p_i)$, or from Proposition~\ref{logical_characterizations}, $p\curle_{2S} p_i$ for $i=1,2$. Therefore, from the definition of $\curle_{2S}$, $p\equiv_S p_1\equiv_S p_2$ and from Claim~\ref{claim:gcd-three}, $\grcd_{\curle_{2S}}(p_1,p_2)$ exists and \gcd{$p_1,p_2$} returns $\grcd_{\curle_{2S}}(p_1,p_2)$ at line 7. Since there is a process, namely $p$, such that satisfies $\varphi$ and is 2-nested simulated by both $p_1$ and $p_2$, Lemma~\ref{lem:gcd-satisfies-phi} guarantees that $\grcd_{\curle_{2S}}(p_1,p_2)\models\varphi$, and so $\mathtt{Prime_{2S}}$ accepts at line 9.
\end{proof}


Conversely, we show that if $\mathtt{Prime_{2S}}(\varphi)$ always accepts, then $\varphi$ is prime. To this end, we first prove that if every execution of $\mathtt{Prime_{2S}}(\varphi)$ leads to acceptance, then every two processes that satisfy $\varphi$ are equivalent modulo $\equiv_S$.

\begin{definition}\label{def:a-witness}
Let $r_1, r_2$ be two processes such that $r_1\not\curle r_2$. We say that $r_1'$ is an $a$-witness of $r_1\not\curle r_2$ if $r_1\myarrowa r_1'$ and for all $r_2\myarrowa r_2'$, $r_1'\not\curle_S r_2'$. When we write $r_1'=\wit(r_1,r_2,a)$ we mean that $r_1'$ is an $a$-witness of $r_1\not\curle r_2$.
\end{definition}

\begin{lemma}\label{lem:wit-existence}
If $r_1\not\curle_S r_2$ and $a\in I(r_1)\Rightarrow a\in I(r_2)$ for every $a\in \act$, then there is $b\in\act$ and $r_1\myarrowb r_1'$ such that $r_1'=\wit(r_1,r_2,b)$.    
\end{lemma}
\begin{proof}
    Immediate from the definition of $\curle_S$.
\end{proof}

\begin{definition}\label{def:witness-process}
    Let $r_1, r_2$ be two processes such that $r_1\not\curle r_2$. We inductively define the witness process of $r_1\not\curle_S r_2$, denoted $\witproc(r_1,r_2)$, as follows.
    \begin{itemize}
        \item $\witproc(r_1,r_2)=a.\mathtt{0}$ if $r_1\myarrowb$ and $r_2\notmyarrowb$ for some $b\in\act$, and $a$ is the first such action in $\{a_1,\dots,a_k\}$;
        \item $\displaystyle\witproc(r_1,r_2)= a.\sum_{r_2\myarrowa r_2'} \witproc(r_1',r_2')$, where $a$ is the first action in $\{a_1,\dots,a_k\}$ such that there is an $a$-witness of $r_1\not\curle_S r_2$ and $r_1'=\wit(r_1,r_2,a)$, otherwise.
    \end{itemize}
\end{definition}

Note that $\witproc(r_1,r_2)$ is well-defined when $r_1\not\curle_S r_2$, because of Lemma~\ref{lem:wit-existence}.

\begin{lemma}\label{lem:witproc-properties}
    Let $r_1,r_2$ be two processes such that $r_1\not\curle_S r_2$. Then, $\witproc(r_1,r_2)\curle_S r_1$, $\witproc(r_1,r_2)\not\curle_S r_2$, $\depth(\wit(r_1,r_2))\leq \depth(r_1)$, and $|\witproc(r_1,r_2)|\leq |r_2|$.
\end{lemma}
\begin{proof}
  It is straightforward from the definition of $\wit(p_1,p_2)$.
\end{proof}

In what follows $S^\square$ (resp.\ $S^\Diamond$) denotes the subset of $S$ consisting of the states added when lines 21--30 (resp.\ 13--19) are executed by $\mathtt{ConPro}$. Similarly, $R_{a_j}^\square$ (resp.\ $R_{a_j}^\Diamond$) denotes the subset of $R_{a_j}$ consisting of the pairs added when lines 21--30 (resp.\ 13--19) are executed by $\mathtt{ConPro}$.
The following lemma is the analogue of Lemma~\ref{lem:B-can-play-consistently}, which guaranteed that player $B$ can play consistently on a process that satisfies $\varphi$ when playing the \simequiv game on $\varphi$.

\begin{lemma}\label{lem:algo-chooses-consistently}
    Let $\varphi\in\mathL_{2S}$ and $r\in\proc$ such that $r\models\varphi$. There is a sequence of non-deterministic choices that $\mathtt{ConPro}(\varphi)$ can make such that there is a mapping $map: S^\Diamond\rightarrow \proc$ satisfying the following conditions.
    \begin{enumerate}
        \item for every $s\in S^\Diamond\cup \{s_0\}$, $map(s)\models\bigwedge L_{12}(s)$,
        \item for every $(s,s')\in R_{a_j}^\Diamond$, $map(s)\myarrowasubj map(s')$, and
        \item $map(s_0)=r$, where $s_0$ is the first state added to $S$ by $\mathtt{ConPro}(\varphi)$.
    \end{enumerate}
    In the case that $\mathtt{ConPro}(\varphi)$ makes these non-deterministic choices, we say that $\mathtt{ConPro}(\varphi)$ chooses its output $(S,R_{a_1},\dots,R_{a_k})$ consistently on $r$.
\end{lemma}
\begin{proof}
    The proof is completely analogous to the proof of Lemma~\ref{lem:B-can-play-consistently}, where we replace moves B($\wedge$) and B($\vee$) with the execution of lines 8--11 of Algorithm~\ref{alg:process-construction}, move B($\Diamond$) with the execution of lines 13--19, and move B($\square$) with the execution of lines 21--30. Note that no state is added to $S$ during the execution of lines 21--30 when $\mathtt{ConPro}$ makes the non-deterministic choices described in the proof of Lemma~\ref{lem:B-can-play-consistently}. Therefore, $S=\{s_0\}\cup S^\Diamond$ and $R_{a_j}=R^\Diamond_{a_j}$ for every $1\leq j\leq k$.
\end{proof}

\begin{lemma}\label{lem:choose-cons-simulation}
 Let $\varphi\in\mathL_{2S}$ and $r\in\proc$ such that $r\models\varphi$. Assume that $\mathtt{ConPro}(\varphi)$ chooses its output $(S,R_{a_1},\dots,R_{a_k})$ consistently on $r$ and $p=$~\process{$S,R_{a_1},\dots,R_{a_k}$}. Then, 
 \begin{enumerate}[(a)]
\item  $p\curle_S r$, and
\item if, in addition, every two processes that satisfy $\varphi$ are simulation-equivalent, then $p\curle_{2S} r$.
 \end{enumerate}
\end{lemma}
\begin{proof}
   Immediate from the definitions of $\curle_S$ and $\curle_{2S}$, the existence of a mapping $map:S\rightarrow\proc$ satisfying conditions 1--3 of Lemma~\ref{lem:algo-chooses-consistently}, and the definition of procedure \process{$\cdot$}. The proof of part (b) relies also on Lemma~\ref{lem:model-of-phi-and-phi-unsat}, which implies that $r\equiv_S p$.
\end{proof}

\begin{lemma}\label{lem:box-2s}
    Let $S\subseteq\mathL_{2S}$ such that it contains only formula $\true$ and formulae that start with either $\langle a\rangle$ or $[a]$, $a\in\act$. Then, for every  $\phi\in\{\psi\mid [b]\psi\in S \text{ for some } b\in\act\}$, $\neg\phi\in\mathL_S$.
\end{lemma}
\begin{proof}
    Immediate from the definitions of $\mathL_S$ and $\mathL_{2S}$.
\end{proof}



\begin{lemma}\label{lem:cons-on-subprocess}
    Let $\varphi\in\mathL_{2S}$, $r\in\proc$ such that $r\models \varphi$. Let $p\in\proc$ be a process satisfying the following conditions: (1) $p\curle_S r$, (2) $\depth(p)\leq\md(\varphi)+1$, (3) $|\reach(p)|\leq |\varphi|$ and $|p|\leq 2|\reach(p)|$, and (4) every $p',p''\in\reach(p)$ are connected through exactly one transition. Then, there is a sequence of non-deterministic choices that $\mathtt{ConPro}(\varphi)$ can make such that there is a surjective mapping $\cop:S^\square\cup\{s_0\}\rightarrow \reach(p)$ satisfying the following conditions.
    \begin{enumerate}[i.]
        \item $\cop(s_0)=p$,
        \item $(s,s')\in R^\square_{a_j}\Leftrightarrow \cop(s)\myarrowasubj \cop(s')$,
        \item $\cop(s)\models\bigwedge L_{12}(s)$ for every $s\in S^\square$.
    \end{enumerate}
    If $\mathtt{ConPro}(\varphi)$ makes these non-deterministic choices, we say that $\mathtt{ConPro}(\varphi)$ adds a copy of $p$ to its output $(S,R_{a_1},\dots,R_{a_k})$.
\end{lemma}
\begin{proof}
    $\mathtt{ConPro}(\varphi)$ chooses its output consistently on $r$, i.e.\ it makes the non-deterministic choices described in the proof of Lemma~\ref{lem:cons-on-subprocess}. As a result, there is a mapping $map:S^\Diamond\cup\{s_0\}\rightarrow\proc$ as described in Lemma~\ref{lem:cons-on-subprocess}, which implies that $r\models\bigwedge L_{12}(s_0)$. Note that the algorithm always skips the execution of lines 21--30 when it chooses its output consistently on $r$. In this proof, we describe how the algorithm can complement these choices by sometimes executing lines 21--30 such that a surjective mapping $\cop:S^\square\cup\{s_0\}\rightarrow \reach(p)$ satisfying conditions i--iii exists. 
    %We also describe what choices it makes during the execution of lines 21--30 if they are reached. 
    We start by setting $\cop(s_0)=p$, and we will demonstrate that the algorithm can proceed in such a way that $\cop$ can be extended to ultimately satisfy the conditions of the lemma.
    \begin{itemize}
        \item When $\mathtt{ConPro}(\varphi)$ examines state $s_0$ and reaches line 20, it decides to go to line 21. Then, it chooses $N=|\{p'\mid p\myarrowa p' \text{ where } a\in\act\}|$, and it makes one iteration of the for-loop for each $p\myarrowa p'$. Let $p\myarrowasubi p'$ for some $a_i\in\act$ and $p'\in\proc$. During the iteration that corresponds to this $a_i$-transition, the algorithm chooses $j=i$, adds state $s'$ to $S^\square$ and $(s_0,s')$ to $R^\square_{a_i}$ at lines 23, 24, and 27, respectively. We show that the algorithm does not stop at line 28 and $p'\models \bigwedge L_{12}(s')$, and so we can set $\cop(s')=p'$. Recall that $L(s')=\{\psi\mid [a_i]\psi\in L_{12}(s)\}$. Since $p\curle_S r$, there is $r\myarrowasubi r'$ such that $p'\curle_S r'$. Thus, $r\not\models [a_i]\ff$. As we noted above, $r\models \bigwedge L_{12}(s_0)$, which implies $[a_i]\ff\not\in L_{12}(s_0)$, $\ff\not\in L(s')$, and the algorithm does not stop at line 28. From the fact that $r\models\bigwedge L_{12}(s_0)$, we have also that $r'\models\bigwedge L(s')$. Let $DF(\bigwedge L(s'))=\bigvee_{i=1}^m\Psi_i$, $m\in\mathbb{N}$. From Lemma~\ref{lem:DF-equiv}, $\bigwedge L(s')\equiv \bigvee_{i=1}^m\Psi_i$ and so $r'\models\Psi_t$ for some $1\leq t\leq m$. From Claim~\ref{claim:lines-seven-to-eleven}, $\mathtt{ConPro}$ can execute lines 8--11 so that $\bigwedge L_{12}(s')=\Psi_t$. Since $\varphi\in\mathL_{2S}$, Claim~\ref{claim:line-eleven} and Lemma~\ref{lem:box-2s} imply that for every formula $\phi\in L(s')$, $\neg\phi\in\mathL_S$. As a result,$\neg\Psi_t\in\mathL_S$. If $p'\models\neg\Psi_t$, then from Proposition~\ref{logical_characterizations} and the fact that $p'\curle_S r'$, $r'\models\neg\Psi_t$, contradiction. We conclude that $p'\models\Psi_t$, or $p'\models \bigwedge L_{12}(s')$.
        \item Assume that $\mathtt{ConPro}(\varphi)$ examines some $s'\in S^\square$ for which we have set $\cop(s')=p'$ and $p'\models\bigwedge L_{12}(s')$ holds. Then, the algorithm chooses to go to line 21, picks $N=|\{p''\mid p'\myarrowa p'' \text{ where } a\in\act\}|$, and makes one iteration of the for-loop for each $p'\myarrowa p''$. Let $p'\myarrowasubi p''$ for some $a_i\in\act$ and $p''\in\proc$. As in the previous case, during the iteration that corresponds to this $a_i$-transition, the algorithm chooses $j=i$, adds state $s''$ to $S^\square$ and $(s',s'')$ to $R^\square_{a_i}$ at lines 23, 24, and 27, respectively. Similarly to the above, we can show that the algorithm does not terminate at line 28 and that $p''\models\bigwedge L_{12}(s'')$. So, we can set $\cop(s'')=p''$.
        \item In the case that $\mathtt{ConPro}(\varphi)$ examines a state $s\in S^\Diamond$ and reaches line 20, it chooses to go to line 6, and so lines 21--30 are not executed.
    \end{itemize}
    Note that if $\mathtt{ConPro}(\varphi)$ follows the non-deterministic choices described above, it adds exactly $|\reach(p)|$ states to $S^\square$. 
    %This is feasible because  (1) $\depth(p)\leq\md(\varphi)+1$ and for every $s$ added to $S$, $d(s)$ can be up to $\md(\varphi)+1$, and (2) $|\reach(p)| \leq |\varphi|$, and the constraints on $N$ ensure that the for-loop can be executed at most $|\varphi|$ times overall. 
    Given the four conditions satisfied by $p$ and the choices that $\mathtt{ConPro}(\varphi)$ makes which were described in the three cases above, we have that mapping $\cop:S^\square\cup\{s_0\}\rightarrow \reach(p)$ is surjective and satisfies conditions i--iii. Moreover, $\mathtt{ConPro}(\varphi)$ is able to add all states to $S^\square$ and pairs to $R_{a_j}$'s in order to follow these choices.
\end{proof}

\begin{lemma}\label{lem:not-equiv-algo-rejects}
    Let $\varphi\in\mathL_{2S}$ be a satisfiable formula. If $\mathtt{Prime_{2S}}(\varphi)$ always accepts, then every two processes $r_1,r_2$ that satisfy $\varphi$ are equivalent with respect to $\equiv_S$.
\end{lemma}
\begin{proof} We prove the contrapositive of the lemma. Assume that there are $r_1,r_2\in\proc$ that satisfy $\varphi$ and $r_1\not\curle_S r_2$. From Lemma~\ref{lem:finite_processes}, we assume w.l.o.g.\ that $\depth(r_i)\leq\md(\varphi)+1$ for both $i=1,2$. We show that there is an execution of $\mathtt{Prime_{2S}}(\varphi)$ that rejects. Let $\mathtt{Prime_{2S}}(\varphi)$ play as follows. $\mathtt{ConPro}(\varphi)$ chooses its output $(S_2,R_{a_1}^2,\dots, R_{a_k}^2)$ consistently on $r_2$, when it is called at line 3. From Lemma~\ref{lem:choose-cons-simulation}, $p_2\curle_S r_2$. Consequently, $r_1\not\curle_S p_2$. When $\mathtt{ConPro}(\varphi)$ is called at line 1, it chooses its output $(S_1,R_{a_1}^1,\dots, R_{a_k}^1)$ consistently on $r_1$ and adds a copy of $\witproc(r_1,p_2)$ to its output, which is possible from Lemmas~\ref{lem:witproc-properties}, \ref{lem:algo-chooses-consistently},  \ref{lem:cons-on-subprocess} and the fact that $\witproc(r_1,p_2)$ satisfies all five conditions of Lemma~\ref{lem:cons-on-subprocess}. It is not hard to see that \process{$S_1,R_{a_1}^1,\dots, R_{a_k}^1$} is process $p_1=\witproc(r_1,p_2)+p_1'$, where $p_1'$ is the result of $\mathtt{ConPro}(\varphi)$ choosing its output consistently on $r_1$. From Lemma~\ref{lem:witproc-properties}, $\witproc(r_1,p_2)\not\curle_S p_2$, and so $p_1\not\curle_S p_2$. From Claim~\ref{claim:gcd-three}, $\grcd_{\curle_{2S}}(p_1,p_2)$ does not exist, procedure \gcd{$p_1,p_2$} does not generate a process because of line 5 in Algorithm~\ref{alg:procedures}, and $\mathtt{Prime_{2S}}(\varphi)$ rejects at line 8.
% The proof is similar to the proof of Proposition~\ref{prop:simulation-left-to-right}. We describe the basic idea here, and we refer the reader to the aforementioned proof for the details. We prove the contrapositive of the lemma. Assume that there are $r_1,r_2\in\proc$ that satisfy $\varphi$ and $r_1\not\curle_S r_2$. We show that there is an execution of $\mathtt{Prime_{2S}}(\varphi)$ that rejects. From Lemma~\ref{lem:finite_processes}, we assume w.l.o.g.\ that $\depth(r_i)\leq\md(\varphi)+1$ for both $i=1,2$. There is a sequence of non-deterministic choices that $\mathtt{ConPro}$ can make such that there is a mapping $map:\reach(p_2)\rightarrow\reach(r_2)$ for which conditions 1--3 of Definition~\ref{def:B-plays-consistently} hold. This can be done as described in the proof of Lemma~\ref{lem:B-can-play-consistently}. Moreover, $\mathtt{ConPro}(\varphi)$ can make non-deterministic choices such that $p_1$ at line 2 contains a copy of a trace of $r_1$ that witnesses the fact that $r_1\not\curle_S r_2$ as described in the proofs of Lemma~\ref{lem:B-on-first-process} and Proposition~\ref{prop:simulation-left-to-right}.
% This execution of $\mathtt{Prime_{2S}}(\varphi)$  constructs  $p_1,p_2$ such that $p_1\not\curle_S p_2$. From Claim~\ref{claim:gcd-three}, $\grcd_{\curle_{2S}}(p_1,p_2)$ does not exist, procedure \gcd{$p_1,p_2$} does not generate a process because of line 5 in Algorithm~\ref{alg:procedures}, and $\mathtt{Prime_{2S}}(\varphi)$ rejects at line 8.
\end{proof}

For the following lemmas, let $p\in \mathrm{Bounded}(|\varphi|)$ denote that $p\models\varphi$ and $|p|\leq 16|\varphi|^2$.

\begin{lemma}\label{lem:for-every-two-there-is}
    Let $\varphi\in\mathL_{2S}$ be a satisfiable formula and assume that $\mathtt{Prime_{2S}}(\varphi)$ always accepts. Then, for every $r_1,r_2$ that satisfy $\varphi$, there is a process $g$ such that $g\in \mathrm{Bounded}(|\varphi|)$, $g\curle_{2S} r_1$, and $g\curle_{2S} r_2$.
\end{lemma}
\begin{proof}
    Let $r_1,r_2\in\proc$ such that $r_i\models\varphi$ for both $i=1,2$; let also the two calls of $\mathtt{ConPro}(\varphi)$ make non-deterministic choices such that the two outputs at lines 1 and 3 are chosen consistently on $r_1,r_2$ respectively. We denote by 
    $map$ the mapping described in Lemma~\ref{lem:algo-chooses-consistently} and $g$ the $\grcd_{\curle_{2S}}(p_1,p_2)$ computed by $\mathtt{Prime_{2S}}(\varphi)$ at line 7. Since $\mathtt{Prime_{2S}}(\varphi)$ always accepts, $g\models\varphi$ because of lines 8 and 9. From Lemma~\ref{lem:gcd-2s-poly-time}, $|g|\leq 2|p_1||p_2|$ and thus, from Lemma~\ref{lem:model-of-phi-size}, $|g|\leq 16|\varphi|^2$. Since $\mathtt{Prime_{2S}}(\varphi)$ always accepts, Lemma~\ref{lem:not-equiv-algo-rejects} implies that every two processes that satisfy $\varphi$ are simulation-equivalent, and so from Lemma~\ref{lem:choose-cons-simulation}(b), we have that $p_1\curle_{2S} r_1$ and $p_2\curle_{2S} r_2$. Since, from Claim~\ref{claim:gcd-one}, $g\curle p_i$ for both $i=1,2$, we have that $g\curle_{2S} r_i$ for both $i=1,2$.
    % We show that $g\curle_{2S} map(s_0^i)$, where $map(s_0^i)=r_i$, $i=1,2$, by induction on $g$. Note that from Lemma~\ref{lem:model-of-phi-and-phi-unsat}, $p_i\models\varphi$ for both $i=1,2$. This implies that $p_1\equiv_S p_2\equiv_S r_1\equiv_S r_2$ because of Lemma~\ref{lem:not-equiv-algo-rejects}. Since $g\curle_{2S} p_i$, we also have that $g\equiv_S r_1\equiv_S r_2$.
    % \begin{itemize}
    %     \item Let $g=\mathtt{0}$. From the fact that $g\equiv_S r_1\equiv_S r_2$, $r_1=r_2=\mathtt{0}$ and $g\curle_{2S} r_i$ for both $i=1,2$.
    %     \item Let $g\myarrowa g'$. Then, from the construction of $g$ there are $p_1',p_2'$ such that $p_1\myarrowa p_1'$, $p_2\myarrowa p_2'$, and from Claims~\ref{claim:gcd-one} and~\ref{claim:gcd-two}, $g'$ is  $\grcd_{\curle_{2S}}(p_1',p_2')$. From condition 2 of Definition~\ref{def:B-plays-consistently}, there are also $map(p_1)\myarrowa map(p_1')$ and $map(p_2)\myarrowa map(p_2')$. From the inductive hypothesis, $g'\curle_{2S} map(p_i')$, $i=1,2$. Therefore, $g\curle_{2S}  map(p_i)$, $i=1,2$.\qedhere
    % \end{itemize} 
\end{proof}

\begin{corollary}\label{cor:2S-for-every-two-there-is}
Let $\varphi\in\mathL_{2S}$ be a satisfiable formula and assume that $\mathtt{Prime_{2S}}(\varphi)$ always accepts.  Then, for every two processes $r_1,r_2$ such that $r_i\in \mathrm{Bounded}(|\varphi|)$ for both $i=1,2$, there is a process $g$ such that $g\in \mathrm{Bounded}(|\varphi|)$, $g\curle_{2S} r_1$, and $g\curle_{2S} r_2$.
\end{corollary}
\begin{proof}
     Immediate from Lemma~\ref{lem:for-every-two-there-is}.
\end{proof}

\begin{corollary}\label{cor:2S-for-every-there-is-small}
 Let $\varphi\in\mathL_{2S}$ be a satisfiable formula and assume that $\mathtt{Prime_{2S}}(\varphi)$ always accepts. Then, for every process $r$ such that $r\models\varphi$, there is $g$  such that $g\in \mathrm{Bounded}(|\varphi|)$ and $g\curle_{2S} r$.
\end{corollary}
\begin{proof}
 Immediate from Lemma~\ref{lem:for-every-two-there-is}.
\end{proof}



\begin{lemma}\label{lem:2S-there-is-for-every-small}
    Let $\varphi\in\mathL_{2S}$ be a satisfiable formula and assume that $\mathtt{Prime_{2S}}(\varphi)$ always accepts. Then, there is a process $g$ such that $g\in \mathrm{Bounded}(|\varphi|)$ and for every process $r$ such that $r\in \mathrm{Bounded}(|\varphi|)$, $g\curle_{2S} r$.
\end{lemma}
\begin{proof}
The proof is similar to the proof of Lemma~\ref{lem:there-is-for-every-small}.
\end{proof}


\begin{corollary}\label{cor:2S-there-is-for-every}
    Let $\varphi\in\mathL_{2S}$ be a satisfiable formula and assume that $\mathtt{Prime_{2S}}(\varphi)$ always accepts. Then, there is $g$ such that $g\in \mathrm{Bounded}(|\varphi|)$ and for every process $r$ such that $r\models\varphi$, $g\curle_{2S} r$.
\end{corollary}
\begin{proof}
This is immediate from Lemma~\ref{lem:2S-there-is-for-every-small} and Corollary~\ref{cor:2S-for-every-there-is-small}.
\end{proof}


\begin{proposition}\label{prop:accept-implies-prime}
   Let $\varphi\in\mathL_{2S}$. If $\mathtt{Prime}_{2S}(\varphi)$ always accepts, then $\varphi$ is prime.
\end{proposition}
\begin{proof}
   If  $\mathtt{Prime_{2S}}(\varphi)$ always accepts at line 5, then $\varphi$ is unsatisfiable from Lemma~\ref{lem:phi-sat}, and so it is prime. In the case that there is an execution of $\mathtt{Prime_{2S}}(\varphi)$ that accepts at line 9, two processes that satisfy $\varphi$ are returned at lines 2 and 4, and $\varphi$ is satisfiable from Lemma~\ref{lem:phi-sat}. Then, we can prove that $\varphi$ is prime similarly to the proof of Proposition~\ref{prop:left-to-right} using Corollary~\ref{cor:2S-there-is-for-every}.
\end{proof}
