% \end{proof}

\begin{corollary}\label{cor:2s-prime-algo-correct}
     Let $\varphi\in\mathL_{2S}$. Then, $\varphi$ is prime iff $\mathtt{Prime_{2S}}(\varphi)$ always accepts.
\end{corollary}
\begin{proof}
 Immediate  from Propositions~\ref{prop:prime-implies-accept} and~\ref{prop:accept-implies-prime}.
\end{proof}


\twosprimeconp*
% \begin{restatable}{proposition}{twosprimeconp}\label{prop:2S-primality-conpc}
% The Formula Primality problem for $\mathL_{2S}$ is \conp-complete.
% \end{restatable}
\begin{proof}
    The problem is \conp-hard from Proposition~\ref{prop:primality}. To prove that it is also in \conp, let $\varphi\in\mathL_{2S}$. From Corollary~\ref{cor:2s-prime-algo-correct}, it suffices to show that every execution of $\mathtt{Prime_{{2S}}}(\varphi)$ runs in polynomial time.
     From Lemma~\ref{lem:model-of-phi-size}, every execution of $\mathtt{ConPro}(\varphi)$ needs polynomial time and from Lemma~\ref{lem:gcd-2s-poly-time}, the construction of $\grcd_{\curle_{2S}}(p_1,p_2)$ can be done in polynomial time. Model checking at line 7 also requires polynomial time from Proposition~\ref{model-checking-complexity}. Therefore, deciding prime formulae in $\mathL_{2S}$ is in \conp.
\end{proof}

\begin{proposition}\label{prop:2s-equivalent-processes-conp}
    Let $\varphi\in\mathL_{2S}$. The problem of deciding whether every two processes satisfying $\varphi$ are 2-nested-simulation equivalent is in \conp.
\end{proposition}
\begin{proof}
    Consider the algorithm $\mathtt{EquivProc_{2S}}$, which on input $\varphi$ proceeds as follows: it executes lines 1--5 of $\mathtt{Prime_{2S}}(\varphi)$. If $\mathtt{EquivProc_{2S}}(\varphi)$ does not accept at line 5, it continues by checking whether $p_1$ and $p_2$ are 2-nested-simulation equivalent.  This equivalence check can be performed in polynomial time, by Proposition~\ref{prop:2s-equiv-polytime}. Using reasoning similar to the correctness proof of the $\mathtt{Prime_{2S}}$ algorithm, we can show that every execution of $\mathtt{EquivProc_{2S}}$ accepts iff every two processes satisfying $\varphi$ are $2$-nested-simulation equivalent. Moreover, each execution of $\mathtt{EquivProc_{2S}}$  needs polynomial time in $|\varphi|$ since $|p_i|\leq 4|\varphi|$ from Lemma~\ref{lem:model-of-phi-size}. Thus, the problem belongs to \conp.
\end{proof}



