\section{Pseudocode Listings}
\label{app:pseudocode}

\subsection{Quality-Weighted Marginal-Incentive Auction (Q-MIA)}

\begin{algorithm}[H]
\caption{Q-MIA}
\label{alg:qmia}
\begin{algorithmic}[1]
\Require Budget $B$, parameters $(\eta,\gamma,\kappa)$, \\
\hfill\phantom{Require }agents’ reports $\{\hat c_i, q_i, \widehat{\phi}_i\}_{i=1}^n$
\Ensure Winner set $S^\star$, payments $\{p_i\}$
\State Compute $\psi_i\leftarrow\hat c_i\,/\,\bigl(q_i^\eta(\widehat{\phi}_i+\kappa)^\gamma\bigr)$
\State Sort agents by ascending $\psi_i$
\Statex \textit{Greedy selection}
\State $S^\star\leftarrow\emptyset$, $C\leftarrow0$
\For{agent $i$ in sorted order}
    \If{$C+\hat c_i\le B$}
        \State $S^\star\leftarrow S^\star\cup\{i\}$; $C\leftarrow C+\hat c_i$
    \Else
        \State \textbf{break}
    \EndIf
\EndFor
\Statex \textit{Critical payments}
\For{$i\in S^\star$}
    \State Find smallest $\tilde c$ s.t.\ $i$ would still be selected
    \State $p_i\leftarrow \rho\,\tilde c + (1-\rho)\,U\cdot s_i$ \Comment{$\rho{=}1$ in pure Q-MIA}
\EndFor
\end{algorithmic}
\end{algorithm}

\subsection{Mixed-MIA Allocation of Hybrid Rewards}

\begin{algorithm}[H]
\caption{Mixed-MIA (high-level)}
\label{alg:mixed}
\begin{algorithmic}[1]
\Require Budget $B$, utility pool $U$, liquidity $\rho$
\State Run Algorithm~\ref{alg:qmia} with $\rho=1$ to obtain $\{p_i^{Q}\}$
\State Compute $s_i=\dfrac{q_i\widehat{\phi}_i}{\sum_{j\in S^\star}q_j\widehat{\phi}_j}$
\For{$i\in S^\star$}
    \State $p_i\leftarrow\rho\,p_i^{Q}+(1-\rho)\,U\,s_i$
\EndFor
\end{algorithmic}
\end{algorithm}

\section{Quality Metric Implementation Details}
\label{app:quality}

\paragraph{Cleanliness.}  
Count character-level corruption and dictionary mismatches after normalisation; compute $\mathrm{Clean}=1-\min(1,k\!\cdot\!\text{error\_rate})$ with $k=50$.

\paragraph{Diversity.}  
Embed each document with a pretrained MiniLM;
cluster using $k$-means ($k=50$) and evaluate
$H=\!-\,\sum_{j=1}^{k}p_j\log p_j$; normalise to $[0,1]$.

\paragraph{Novelty.}  
Compute cosine similarity $\sigma$ between each sentence and a 5-million-sentence public corpus.  
$\mathrm{Novelty}=1-\mathrm{mean}(\sigma)$; clipped to $[0,1]$.

\paragraph{Metadata Richness.}  
\(
\text{Meta}= \frac{\text{\# filled fields}}{\text{\# required fields}}.
\)


The final score is $q_i=w_1\mathrm{Clean}+w_2 H+w_3\mathrm{Novelty}+w_4\text{Meta}$ with $(w_1,w_2,w_3,w_4)=(0.25,0.25,0.25,0.25)$ unless otherwise stated.

\section{Marginal Utility Estimation Pipeline}
\label{app:marginal}

\begin{enumerate}
\item Train base LLM for $e_0$ epochs on public seed corpus.
\item \textbf{Influence-Function Approximation:}\\
For each $i$, compute $\widehat{\phi}_i\approx -g_i^\top H^{-1}\bar g$ where  
$g_i$ is the gradient of loss w.r.t.\ parameters on $D_i$ and
$H^{-1}\bar g$ is pre-computed with Hutchinson trace estimation.
\item Rescale $\widehat{\phi}_i$ linearly to $[0,1]$ and set floor $10^{-3}$.
\item Log intermediate tensors and random seeds for auditability.
\end{enumerate}


\section{Ethical and Societal Impact Statement}
\label{app:ethics}

Our mechanisms seek to democratise access to LLM training by rewarding diverse data owners.  Nevertheless, selection biases in $q_i$ or $\widehat{\phi}_i$ might disadvantage low-resource languages or under-represented domains.  
To mitigate this risk we (i) publish scoring code, (ii) allow community veto on metric weights, and (iii) reserve 10 \% of budget for a \emph{diversity tranche} prioritising under-served providers.

\vspace{.5em}
\noindent\textbf{Privacy.}  All quality evaluation can be executed under differential privacy or homomorphic hashing; raw data remain encrypted until a binding contract is signed.  


