\title{On Rational Recursion for Holonomic Sequences}
%\thanks{Supported by UKRI Frontier Research Fellowship %EP/X033813/1}}

\author{Bertrand Teguia Tabuguia\orcidlink{0000-0001-9199-7077} and James Worrell}


\institute{Department of Computer Science\\
