	\section{Convergence Analysis}
	The convergence rate of {\fontfamily{lmtt}\selectfont QMLHFL} is presented in the next theorem. The analysis is based on minimal standard assumptions that cover non-convex loss functions, which are commonly encountered in the literature, as outlined below.

	\textbf{Assumption 2 (Lipschitz-Continuous Gradient):} The gradient of the loss function $F(\mathbf{w})$ is characterized by Lipschitz continuity with a non-negative constant $L > 0$. This implies that for any pair of model vectors $\mathbf{w}_1$ and $\mathbf{w}_2$, we have
	\begin{align}
		&F(\mathbf{w}_2) \leq F(\mathbf{w}_1) + \nabla F(\mathbf{w}_1)^T (\mathbf{w}_2-\mathbf{w}_1) + \frac{L}{2} \|\mathbf{w}_2 - \mathbf{w}_1\|^2,\\
		&\|\nabla F(\mathbf{w}_2)-\nabla F(\mathbf{w}_1)\| \leq L \|\mathbf{w}_2 - \mathbf{w}_1\|.
	\end{align}


	\textbf{Assumption 3 (Gradient Variance Bound):} The local stochastic gradient $\nabla F(\mathbf{w},\boldsymbol \xi)$ serves as an unbiased estimator of the actual gradient $\nabla F(\mathbf{w})$, with its variance bounded as follows.
	\begin{align}
		\mathbb{E}\left\{\|\nabla F(\mathbf{w},\boldsymbol \xi) - \nabla F(\mathbf{w})\|^2\right\} \leq {\sigma^2}.
	\end{align}

	\begin{theorem}
		Assume that the learning rate $\mu$ satisfies the following condition:
		\begin{align}
			\label{convergence_condition}
			&1-{L^2\mu^2}\Biggl[\frac{\tau_1(\tau_1-1)}{2}+\sum_{n=2}^{N}\frac{\tau_n (\tau_n-1)}{2} \prod_{m=1}^{n-1}\tau_m^2 +q_1 \tau_2 \tau_1^2\nonumber\\&+\sum_{n=1}^{N-2}\prod_{m=1}^{n+2}\tau_{m} \max_{}{\cal A}_{n}\Biggr]-{L} {\mu} \Biggl[\prod_{n=1}^{N}\tau_n +\frac{1}{N_\text{tot}} \max_{} {\cal A}_{N-1}\Biggr]\nonumber\\&\geq 0,
		\end{align}
		where ${\cal A}_n$ is a recursive function defined as
		\begin{align}
			{\cal A}_{n} &= |{\cal C}_{n}^{i_n}|\left(q_{n+1} \prod_{m=1}^{n+1}\tau_m + \frac{{|{\cal C}_{n-1}^{i_{n-1}}|}}{|{\cal C}_{n}^{i_n}|}(1+q_{n+1}){\cal A}_{n-1} \right), \nonumber\\&n \in \left\{2,\ldots, N-1\right\},
		\end{align}
		with
		\begin{align}
			{\cal A}_1 = {|{\cal C}_{1}^{i_1}|}\left(q_2 \tau_1 \tau_2+\frac{1}{|{\cal C}_{1}^{i_1}|} q_1 (1+q_2)\tau_1 \right).
		\end{align}
		The $\max$ operation is conducted with respect to the device counts. Then, the convergence rate of {\fontfamily{lmtt}\selectfont QMLHFL} after $T$ global iterations is bounded as
		\begin{align}
			\label{convergence_rate_asl}
			&\frac{1}{T}\sum_{t=0}^{T-1} \mathbb{E}\left\{\|\nabla F( {\mathbf{w}}_{t})\|^2\right\} \leq \frac{2(F(\mathbf{w}_0)-F(\mathbf{w}^*))}{\mu T\prod_{n=1}^{N}\tau_n}+\frac{L^2\mu^2}{2}\nonumber\\&\Biggl[ {(\tau_1-1)}+\sum_{n=1}^{N-1}\frac{C_{n}}{N_\text{tot}}{(\tau_{n+1}-1)}\prod_{m=1}^{n}(1+q_{m})\prod_{m=1}^{n}\tau_{m} \Biggr]\sigma^2\nonumber\\&+{L}\mu\frac{\sigma^2}{N_\text{tot}}\prod_{n=1}^{N}(1+q_{n}).
		\end{align}
	\end{theorem}
	\begin{IEEEproof}
		See Appendix A.
	\end{IEEEproof}
	\begin{remark}
		The convergence rate bound in~\eqref{convergence_rate_asl} consists of two components: the first term characterizes the speed of convergence, while the remaining terms represent the post-convergence error. As the number of layers and intra-layer iteration counts $\tau_n, \forall n$ increase, the convergence speed improves; however, this also leads to a rise in the error term.
	\end{remark}
	\begin{remark}
		The convergence speed increases with $\prod_{n=1}^{N}\tau_n$, reflecting the effectiveness of the nested approach in leveraging the full hierarchical potential provided by multiple layers.
	\end{remark}
	\begin{remark}
		The condition in~\eqref{convergence_condition} defines the requirement on the learning rate $\mu$ necessary to guarantee convergence for {\fontfamily{lmtt}\selectfont QMLHFL}. This condition is influenced by the hierarchical architecture in its entirety, including the total number of devices and all device counts $|C_n^{i_n}|,\forall n$ associated with each edge server at every layer. However, the convergence rate itself depends only on two abstract characteristics of the architecture: the total number of devices and the number of edge servers per layer.
	\end{remark}
	\begin{remark}
		The condition in~\eqref{convergence_condition} involves several multiplicative terms composed of intra-layer iteration counts. These terms reveal that iteration counts in lower layers have a disproportionately larger effect on the convergence behavior, since they appear repeatedly and recursively in product terms involving deeper layers. As a result, increasing lower-layer \( \tau_n \) values can rapidly tighten the condition~\eqref{convergence_condition}. Therefore, any increase in intra-layer iteration counts must be accompanied by a corresponding decrease in the learning rate to ensure that the condition remains satisfied.
	\end{remark}
	\begin{remark}
		The recursive function ${\cal A}_n$ arises due to quantization and the nested aggregation structure inherent in {\fontfamily{lmtt}\selectfont QMLHFL}.
	\end{remark}
	\begin{remark}
		With a constant number of devices, an increased number of edge servers in any layer amplifies the error term in the convergence rate, resulting in diminished learning accuracy. While assigning devices or lower-layer edge servers to fewer upper-layer servers can improve performance at each global iteration, the overall hierarchical architecture, including the number of edge servers per layer, is often constrained by physical network limitations. Moreover, reducing the number of edge servers may increase the latency per iteration, as devices become farther from the servers, or servers from their corresponding higher-layer servers.
	\end{remark}
	\begin{remark}
		The impact of quantization is more pronounced in lower layers compared to higher layers. Opting for more accurate quantization in the lower layers, especially at the device layer, can significantly enhance performance.
	\end{remark}

	We now highlight two noteworthy \textit{special cases}.

	a) When quantization is not a factor, and model parameters at each device or edge server in any layer are transmitted perfectly, i.e., $q_n = 0, \forall n=1,\ldots,N$, the convergence rate is simplified as follows.
	\begin{corollary}
		Assume no quantization is employed, and the learning rate $\mu$ satisfies the following condition:
		\begin{align}
			&1-{L^2\mu^2}\Biggl[\frac{\tau_1(\tau_1-1)}{2}+\sum_{n=2}^{N}\frac{\tau_n (\tau_n-1)}{2} \prod_{m=1}^{n-1}\tau_m^2\Biggr]\nonumber\\&-{L} {\mu} \prod_{n=1}^{N}\tau_n\geq 0.
		\end{align}
		Then, the convergence rate of {\fontfamily{lmtt}\selectfont QMLHFL} is bounded as
		\begin{align}
			&\frac{1}{T}\sum_{t=0}^{T-1} \mathbb{E}\left\{\|\nabla F( {\mathbf{w}}_{t})\|^2\right\} \leq \frac{2(F(\mathbf{w}_0)-F(\mathbf{w}^*))}{\mu T\prod_{n=1}^{N}\tau_n}+\frac{L^2\mu^2}{2}\nonumber\\&\Biggl[ {(\tau_1-1)}+\sum_{n=1}^{N-1}\frac{C_n}{N_\text{tot}}(\tau_{n+1} - 1) \prod_{m=1}^{n}\tau_m\Biggr]\sigma^2+{L}\mu\frac{1}{N_\text{tot}}\sigma^2.  
		\end{align}	
	\end{corollary}
	Although the non-quantized case of {\fontfamily{lmtt}\selectfont QMLHFL} is idealized, it has not been previously investigated. Therefore, the findings in this setting hold foundational value in research, aligning with prevailing trends in the field that consider perfect, non-quantized transmissions as a theoretical baseline~\cite{advanceFL}.
