	\vspace{0pt}
	\section{Learning Optimization}
	The intra-layer iteration counts \( \tau_n \), for all \( n = 1, \ldots, N \), which are fundamental parameters in {\fontfamily{lmtt}\selectfont QMLHFL}, can be selected to minimize the convergence rate bound in~\eqref{convergence_rate_asl}, thereby improving the overall learning performance. Convergence rate bounds have also been employed for optimization in prior FL studies (e.g., \cite{conv2, conv3, conv4}). However, obtaining accurate values for \( F(\mathbf{w}^*) \), \( L \), and \( \sigma^2 \) in~\eqref{convergence_rate_asl} generally requires prior statistical knowledge of the local learning models---information that may not be readily available in many practical scenarios. To overcome this limitation and ensure universal applicability, we propose a weighted objective function that combines the first term in~\eqref{convergence_rate_asl} (representing convergence speed) and the second term (associated with the post-convergence error), moderated by a scaling parameter \( 0 \leq \alpha \leq 1 \). Both terms are normalized with respect to their reference values to ensure unit consistency, although for simplicity, the normalization factors are omitted in the subsequent expressions. The parameter \( \alpha \) is treated as a hyperparameter, allowing the trade-off between faster convergence and lower post-convergence error to be tuned based on application requirements.

	Meanwhile, the run-time required to complete $T$ global iterations of {\fontfamily{lmtt}\selectfont QMLHFL} is given by $Tt_\text{d}$, where the latency per global iteration is 
	\begin{align}
		\label{latency}
		t_\text{d} = &\prod_{n=1}^{N}\tau_n t_{\text{CP}}+\prod_{n=2}^{N}\tau_n t_\text{DE}+\sum_{n=2}^{N-1}\prod_{m=n+1}^{N}\tau_m t_{\text{E}_{n-1,n}}+\nonumber\\& t_{\text{E}_{N-1,N}}.
	\end{align}
	In~\eqref{latency}, $t_\text{CP}$ represents the computational time at each device, while $t_\text{DE}$ and $t_{\text{E}_{n-1,n}}$ denote the communication times between each device and its respective edge server in layer 1 and between each edge server in layer $n-1$ and its respective edge server in layer $n$, respectively. From~\cite{letaief}, these parameters can be obtained as
	$
	t_\text{CP} = {cD}/{f},
	$
	$
	t_\text{DE} = {d_\text{b}}/{\bigl(B\log_2\bigl(1+\frac{ph}{N_0}\bigr)\bigr)},
	$
	where $c$ is the number of CPU cycles to
	execute one sample of data, $f$ is the CPU cycle frequency, $D$ is the number of data bits involved in one local iteration, $d_\text{b}$ is the model size in bits, $B$ is the channel bandwidth, $h$ is the channel gain, $p$ is the transmission power, and $N_0$ is the noise power. 

	Thus, ensuring task completion within a predefined deadline $T_{\text{d}}$ is essential. This requirement leads to the following optimization problem formulation.
	\begin{align}
		\label{main_opt}
		&\min_{\tau_1,\cdots,\tau_N}\alpha \prod_{n=1}^{N}{\tau_n^{-1}} + (1-\alpha)\Biggl[ {(\tau_1-1)}+\nonumber\\
		&\sum_{n=1}^{N-1}\frac{C_{n}}{N_\text{tot}}{(\tau_{n+1}-1)}\prod_{m=1}^{n}(1+q_{m})\prod_{m=1}^{n}\tau_{m} \Biggr],
	\end{align}
	subject to
	\begin{align}
		&\prod_{n=1}^{N}\tau_n t_{\text{CP}}+\prod_{n=2}^{N}\tau_n t_\text{DE}+\sum_{n=2}^{N-1}\prod_{m=n+1}^{N}\tau_m t_{\text{E}_{n-1,n}}+ t_{\text{E}_{N-1,N}} \nonumber\\
		&\leq \frac{T_{\text{d}}}{T}. \nonumber
	\end{align}
	This is a nonlinear optimization problem, which can be reformulated as 
	\begin{align}
		\label{GP}
		&\min_{\boldsymbol \tau} J^+ (\boldsymbol \tau) - J^- (\boldsymbol \tau),
	\end{align}
	subject to
	\begin{align}
		G(\boldsymbol{\tau}) \leq 1,\nonumber
	\end{align}
	where $\boldsymbol{\tau} = [\tau_1,\ldots,\tau_N]^\top$, and
	\begin{align}
		&J^+(\boldsymbol{\tau}) = \alpha \prod_{n=1}^{N}{\tau_n^{-1}} + (1-\alpha)\nonumber\\&\Biggl[\tau_1+\sum_{n=1}^{N-1}\frac{C_{n}}{N_\text{tot}}\prod_{m=1}^{n}(1+q_{m})\prod_{m=1}^{n+1}\tau_{m}\Biggr],
	\end{align}
	\begin{align}
		\label{Jminus}
		&J^-(\boldsymbol{\tau}) = (1-\alpha)\Biggl[1+\sum_{n=1}^{N-1}\frac{C_{n}}{N_\text{tot}}\prod_{m=1}^{n}(1+q_{m})\prod_{m=1}^{n}\tau_{m}\Biggr],
	\end{align}
	\begin{align}
		\label{Gconstraint}
		G(\boldsymbol{\tau}) &= \frac{T}{T_\text{d}}\biggl(\prod_{n=1}^{N}\tau_n t_{\text{CP}}+\prod_{n=2}^{N}\tau_n t_\text{DE}+\sum_{n=2}^{N-1}\prod_{m=n+1}^{N}\tau_m t_{\text{E}_{n-1,n}}\nonumber\\&+ t_{\text{E}_{N-1,N}}\biggr).
	\end{align}
	Problem~\eqref{GP} is a complementary
	geometric programming~\cite{cgp}. One approach to solve~\eqref{GP} is to convert it into a
	sequence of standard geometric programming problems that can be efficiently solved
	to achieve a global solution~\cite{chiang}. This
	means that the variables in the optimization problem should
	be all positive, and the objective function and the constraints
	should be posynomials. For this, using an auxiliary
	variable $\delta$, we reformulate~\eqref{GP} as
	\begin{align}
		\label{posy}
		&\min_{\boldsymbol \tau, \delta} \delta,
	\end{align}
	subject to
	\begin{align}
		&J(\boldsymbol\tau, \delta) = \frac{J^+ (\boldsymbol \tau)}{ J^- (\boldsymbol \tau)+\delta} \leq 1,\nonumber\\&
		G(\boldsymbol{\tau}) \leq 1.\nonumber
	\end{align}
	In~\eqref{posy}, $G(\boldsymbol{\tau})$ is posynomial, whereas $J(\boldsymbol\tau, \delta)$ is non-posynomial. The arithmetic-geometric mean approximation (AGMA) can
	be applied to transform $J(\boldsymbol\tau, \delta)$ to
	a posynomial function~\cite{chiang}. The approximated posynomial function is given by
	\begin{align}
		\label{Jtilde}
		\tilde J(\boldsymbol\tau, \delta) = \frac{J^+ (\boldsymbol \tau)}{\tilde J^- (\boldsymbol \tau,\delta)},
	\end{align}
	where
	\begin{align}
		&\tilde J^- (\boldsymbol \tau,\delta) = \left(\frac{1-\alpha+\delta}{\beta_0}\right)^{\beta_0}\nonumber\\&\prod_{k=1}^{N-1} \left(\frac{(1-\alpha)\frac{C_{k}}{N_\text{tot}}\prod_{m=1}^{k}(1+q_{m})\prod_{m=1}^{k}\tau_{m} }{\beta_k}\right)^{\beta_k}.
	\end{align}
	Thus, we can convert~\eqref{posy} into the subsequent problems, where in each iteration $l$, the initial step involves solving the following geometric programming problem.
	\begin{align}
		\label{posy2}
		&\min_{\boldsymbol \tau^l, \delta^l} \delta^l,
	\end{align}
	subject to
	\begin{align}
		&\tilde J(\boldsymbol\tau^l, \delta^l) \leq 1,\nonumber\\&
		G(\boldsymbol{\tau}^l) \leq 1,\nonumber
	\end{align}
	and in the second step, the following update is considered.
	\begin{align}
		\label{beta0}
		\beta_0^{l+1} = \frac{1-\alpha+\delta^l}{J^- (\boldsymbol \tau^l)+\delta^l},
	\end{align}
	\begin{align}
		\label{betak}
		\beta_k^{l+1} = \frac{(1-\alpha)\frac{C_{k}}{N_\text{tot}}\prod_{m=1}^{k}(1+q_{m})\prod_{m=1}^{k}\tau_{m}^l}{J^- (\boldsymbol \tau^l)+\delta^l}, \forall k \geq 1.
	\end{align}

	\begin{algorithm}[t]
		\caption{Proposed Intra-Layer Iteration Count Optimization}
		\label{alg:tau_opt}
		\begin{algorithmic}[0]
			\State \textbf{Input:} Hyperparameter $\alpha$, time parameters $t_\text{CP}$, $t_\text{DE}$, $t_{\text{E}_{n-1,n}}$, deadline $T_d$, maximum iteration count $L_{\max}$, tolerance $\epsilon$
			\State \textbf{Initialize:} Set $\boldsymbol{\tau}^{0} \succ \mathbf{0}$, $\delta^{0} > 0$, $l \gets 0$
			\Repeat
			\State Compute $J^{-}(\boldsymbol{\tau}^{l})$ as in~\eqref{Jminus}
			\State Update coefficients $\beta_0^{l+1}$ and $\beta_k^{l+1}$ as in~\eqref{beta0} and~\eqref{betak}
			\State Compute $\tilde J (\boldsymbol \tau^l,\delta^l)$ and $G(\boldsymbol\tau^l)$ as in~\eqref{Jtilde} and~\eqref{Gconstraint}
			\State Solve the geometric program~\eqref{posy2} to obtain $(\boldsymbol{\tau}^{l+1},\delta^{l+1})$
			\State $l \gets l + 1$
			\Until{convergence: $|\delta^{l} - \delta^{l-1}| < \epsilon$ or $l = L_{\max}$}
		\end{algorithmic}
	\end{algorithm}

