  \centering
  \begin{tabular}{lrrr}
    \toprule
    Alliances & Votes & MPs in Parliament & Global SHAP Value \\
    \midrule
    Metabolic\_Body & 14,950,619 & 90 & 0.5780 \\
    Diabetes\_Symptoms & 60,007,287 & 361 & 1.2156 \\
    Skin\_Infection & 14,392,427 & 86 & 0.3778 \\
