\title{Orchestrating Agents and Data for Enterprise:\\ A Blueprint Architecture for Compound AI}


\author{
\IEEEauthorblockN{Eser Kandogan, Nikita Bhutani, Dan Zhang, Rafael Li Chen, Sairam Gurajada, Estevam Hruschka}
\IEEEauthorblockA{\textit{Megagon Labs, USA} \\
Mountain View, CA, U.S.A \\
