% i^{t}_{u,f,\mathrm{est}} \approx \mathrm{argmax} [\hat{\mathbf{I}}_{u}^t] \cdot a_{u,\mathrm{argmax} [\hat{\mathbf{I}}_{u}^t]}^t.
% \end{equation}

\noindent 
\textbf{Statistics-based cache placement (\textbf{StaBC})}: Content stored at \ac{es}' cache based on historical global content popularity.

\noindent 
\textbf{Least recently used (\textbf{LRU})}: The \ac{es} tracks all users' historical requests up to cache placement slot $\tau-1$. Requested content during $[n\tau-n, n\tau-1]$ but absent from the cache will be stored, replacing the least recently used content\footnote{Note the definition of \ac{lru} and \ac{mru} may be different from other work.}.

\noindent
\textbf{Most recently used (\textbf{MRU})}: The \ac{es} tracks all users' historical requests up to cache placement slot $\tau-1$. Requested content during $[n\tau-n, n\tau-1]$ but absent from the cache will be stored, replacing the most recently used content.


