\section{Local convergence of Lazy ESPI}

\begin{proof}

Provided that we have previous $i-1$ eigenvector approximation $U\in \mathbb{R}^{n\times i-1}$, and we move update the $i$-th eigenvector. For notation simplicity, we use $u_{q}, u_{q+1}$ instead of $u^i_q,u^i_{q+1}$.

Denote $\hat{T}=\lambda_{i} I-(I-UU^\top)\hat A(I-UU^\top)$. For $(\lambda_i I-A)u_{q+1}=(\lambda_i I-A)u_{q}-(\lambda_{i} I-A)(\lambda_{i} I-(I-UU^\top)\hat A(I-UU^\top))^{-1}(\lambda_{i} I-A)u_q$, we have
\begin{align}
\label{decompose2}
    (\lambda_{i} I-\Lambda^2)V_2^\top u_{q+1} &= (\lambda_{i} I-\Lambda_2)V_2^\top u_q-(\lambda_{i} I-\Lambda_2)V_2^\top \hat{T}^{-1}(\lambda_{i} I-A)u_q\notag\\
    &= (\lambda_{i} I-\Lambda_2)V_2^\top u_q-(\lambda_{i} I-\Lambda_2)V_2^\top \hat{T}^{-1}(V_1(\lambda_{i} I-\Lambda_1)V_1^\top +V_2(\lambda_{i} I-\Lambda_2)V_2^\top )u_q\notag\\
    &= \underbrace{(\lambda_{i} I-\Lambda_2)V_2^\top u_q-(\lambda_{i} I-\Lambda_2)V_2^\top \hat{T}^{-1}V_2(\lambda_{i} I-\Lambda_2)V_2^\top u_q}_{\texttt{term}\ 1}\notag\\
    &- \underbrace{(\lambda_{i} I-\Lambda_2)V_2^\top \hat{T}^{-1}V_1(\lambda_{i} I-\Lambda_1)V_1^\top u_q}_{\texttt{term}\ 2}.
\end{align}
We aim to bound \texttt{term} 1 and \texttt{term} 2 separately in following analysis.

Firstly, we aim to show that \texttt{term} 1 can be bounded as (\ref{eq:term1results}). With assumption $\|V_{i+1:n}^\top U\|\leq \epsilon$, by \cite[Lemma B.2]{allen2016lazysvd} (for completeness we restate as Lemma \ref{tildeT}), we have $\|(I-UU^\top)A(I-UU^\top)-(I-V_{1:i-1}V_{1:i-1}^\top)A(I-V_{1:i-1}V_{1:i-1}^\top)\|\leq 13\lambda_1\epsilon$. 

\begin{lemma}[\cite{allen2016lazysvd} Lemma B.2]
\label{tildeT}
    Let \( M \) be a PSD matrix with eigenvalues \( \lambda_1 \geq \cdots \geq \lambda_d \) and the corresponding eigenvectors \( u_1, \dots, u_d \in \mathbb{R}^d \). For every \( k \geq 1 \), define 
\[
U^\perp = (u_1, \dots, u_k) \in \mathbb{R}^{d \times k} \quad \text{and} \quad U = (u_{k+1}, \dots, u_d) \in \mathbb{R}^{d \times (d-k)}.
\]
For every \( \varepsilon \in (0, \frac{1}{2}) \), let \( V_s \in \mathbb{R}^{d \times s} \) be an orthogonal matrix such that \( \| V_s^\top U \|_2 \leq \varepsilon \). Define \( Q_s \in \mathbb{R}^{d \times s} \) to be an arbitrary orthogonal basis of the column span of \( U^\perp (U^\perp)^\top V_s \). Then we have:
\[
\left\| \left( I - Q_s Q_s^\top \right) M \left( I - Q_s Q_s^\top \right) - \left( I - V_s V_s^\top \right) M \left( I - V_s V_s^\top \right) \right\|_2 \leq 13 \lambda_1 \varepsilon.
\]
\end{lemma}


This indicates
{\footnotesize
\begin{align*}
    (I-V_{1:i-1}V_{1:i-1}^\top)A(I-V_{1:i-1}V_{1:i-1}^\top)-13\lambda_1\epsilon I
    \preceq (I-UU^\top)A(I-UU^\top)
    \preceq (I-V_{1:i-1}V_{1:i-1}^\top)A(I-V_{1:i-1}V_{1:i-1}^\top)+13\lambda_1\epsilon I.
\end{align*}}

With assumption $\epsilon\leq \frac{\eta}{26(\lambda_1-\eta)}$, we can guarantee that $\hat{T}$ is positive definite (thus invertible)  via
\begin{align*}
    &\lambda_{i} I-(I-UU^\top)\hat A(I-UU^\top)
    \succeq \lambda_{i} I-(I-UU^\top)(A-\eta I)(I-UU^\top)\\
    \succeq& \lambda_{i} I-(I-V_{1:i-1}V_{1:i-1}^\top)(A-\eta I)(I-V_{1:i-1}V_{1:i-1}^\top)-13(\lambda_1-\eta)\epsilon I\\
    \succeq& \lambda_{i} I-V_{i:n}(\Lambda_{i:n}-\eta I) V_{i:n}^\top-13(\lambda_1-\eta)\epsilon I\succeq 0,
\end{align*}  
$\Lambda_{i:n}$ in last line denotes a diagonal matrix, whose contains $i$ to $n$ diagonal elements of $\Lambda$.

% which is in a form as
% \begin{align*}
%     \hat{\Sigma}_{i:n} = 
%     \begin{pmatrix}
%         0&0\\
%         0&\Sigma_{i:n,i:n}\\
%     \end{pmatrix}.
% \end{align*}
Similarly we have $\lambda_{i} I-(I-UU^\top)\hat A(I-UU^\top)\preceq \lambda_{i} I-V_{i:n}(\Lambda_{i:n}-3\eta I) V_{i:n}^\top+13(\lambda_1-\eta)\epsilon$. Thus 
\begin{align}
\label{order1}\scriptsize
    \notag&(\lambda_{i} I-(I-UU^\top)\hat A(I-UU^\top))^{-1}\succeq (\lambda_{i} I-V_{i:n}(\Lambda_{i:n}-3\eta I) V_{i:n}^\top+13(\lambda_1-\eta)\epsilon I)^{-1}\\
    &(\lambda_{i} I-(I-UU^\top)\hat A(I-UU^\top))^{-1}\preceq (\lambda_{i} I-V_{i:n}(\Lambda_{i:n}-\eta I) V_{i:n}^\top-13(\lambda_1-\eta)\epsilon I)^{-1},
\end{align}
and thus $\|\hat T^{-1}\|\leq \frac{1}{\eta-13(\lambda_1-\eta)\epsilon}\leq \frac{2}{\eta}$.

By \eqref{order1} we can bound term $(\lambda_{i} I-\Lambda_2)-(\lambda_{i} I-\Lambda_2)V_2^\top \hat{T}^{-1}V_2(\lambda_{i} I-\Lambda_2)$ by 
\begin{align*}
    &(\lambda_{i} I-\Lambda_2)-(\lambda_{i} I-\Lambda_2)V_2^\top (\lambda_{i} I-(I-UU^\top)\hat A(I-UU^\top))^{-1}V_2(\lambda_{i} I-\Lambda_2)\\
    \preceq & (\lambda_{i} I-\Lambda_2)-(\lambda_{i} I-\Lambda_2)V_2^\top(\lambda_{i} I-V_{i:n}(\Lambda_{i:n}-3\eta I) V_{i:n}^\top+13(\lambda_1-\eta)\epsilon I)^{-1}V_2(\lambda_{i} I-\Lambda_2)\\
    =&(\lambda_{i} I-\Lambda_2)-(\lambda_{i} I-\Lambda_2)((\lambda_{i}+3\eta+13(\lambda_1-\eta)\epsilon) I-\Lambda_{2})^{-1}(\lambda_{i} I-\Lambda_2)\\
    &(\lambda_{i} I-\Lambda_2)-(\lambda_{i} I-\Lambda_2)V_2^\top (\lambda_{i} I-(I-UU^\top)\hat A(I-UU^\top))^{-1}V_2(\lambda_{i} I-\Lambda_2)\\
    \succeq &(\lambda_{i} I-\Lambda_2)-(\lambda_{i} I-\Lambda_2)((\lambda_{i}+\eta-13(\lambda_1-\eta)\epsilon) I-\Lambda_{2})^{-1}(\lambda_{i} I-\Lambda_2).
\end{align*}
Note that $\|(\lambda_{i} I-\Lambda_2)-(\lambda_{i} I-\Lambda_2)((\lambda_{i}+3\eta+13(\lambda_1-\eta)\epsilon) I-\Lambda_{2})^{-1}(\lambda_{i} I-\Lambda_2)\|=\max_{\lambda_{j}\leq \lambda_{i}}(\lambda_{i}-\lambda_{j})-\frac{(\lambda_{i}-\lambda_{j})^2}{\lambda_{i}+3\eta+13(\lambda_i-\eta)\epsilon-\lambda_{j}}\leq 3\eta+13(\lambda_i-\eta)\epsilon\leq 3.5\eta$ for some small constant $c$, thus we have
\begin{align}
\label{eq:term1results}
    \|(\lambda_{i} I-\Lambda_2)-(\lambda_{i} I-\Lambda_2)V_2^\top (\lambda_{i} I-(I-UU^\top)\hat A(I-UU^\top))^{-1}V_2(\lambda_{i} I-\Lambda_2)\|\leq  3.5\eta.
\end{align}

 Secondly, we provide upper bound of \texttt{term} 2. We decompose $(\lambda_{i} I-\Lambda_2)V_2^\top \hat{T}^{-1}V_1$ by
\begin{align}
\label{decompose1}
    (\lambda_{i} I-\Lambda_2)V_2^\top \hat{T}^{-1}V_1  = & (\lambda_{i} I-\Lambda_2)V_2^\top \tilde{T}^{-1}V_1+(\lambda_{i} I-\Lambda_2)V_2^\top (\hat{T}^{-1}-\tilde{T}^{-1})V_1\notag\\
    &=\underbrace{(\lambda_{i} I-\Lambda_2)V_2^\top \tilde{T}^{-1}V_1}_{\text{using true singular vectors}}+\underbrace{(\lambda_{i} I-\Lambda_2)V_2^\top \tilde{T}^{-1}(\tilde{T}-\hat{T})\hat{T}^{-1}V_1}_{\text{error made by estimated singular vectors}},
\end{align}
where $\tilde{T}=\lambda_{i} I-(I-V_{1:i-1}V_{1:i-1}^\top)\hat A(I-V_{1:i-1}V_{1:i-1}^\top)$ which similar to the power iteration matrix $\hat T$ but using the true singular vectors $V_{1:i-1}$ rather than the estimated one $U$.  Denote $T = \lambda_{i} I-(I-V_{1:i-1}V_{1:i-1}^\top)(A-2\eta I)(I-V_{1:i-1}V_{1:i-1}^\top)$, then the first term of \eqref{decompose1} becomes
\begin{align*}
    (\lambda_{i} I-\Lambda_2)V_2^\top \tilde{T}^{-1}V_1&=(\lambda_{i} I-\Lambda_2)V_2^\top (\tilde{T}^{-1}-T^{-1})V_1= (\lambda_{i} I-\Lambda_2)V_2^\top \tilde{T}^{-1}(T-\tilde{T})T^{-1}V_1,
\end{align*}
for the eigenvector of $T^{-1}$ is exactly that of $A$, thus $V_2^\top T^{-1}V_1=0$. 

Recall that $(I-V_{1:i-1}V_{1:i-1}^\top)\hat A(I-V_{1:i-1}V_{1:i-1}^\top)$ is a perturbation of $ (I-V_{1:i-1}V_{1:i-1}^\top)(A-2\eta I)(I-V_{1:i-1}V_{1:i-1}^\top)$, so the $k-i+2$ to $n-i+1$ eigenvectors of $\tilde{T}$ is approximately close to $V_2$. We rearrange the sequence of eigenvalue of $\tilde T$ and $T$, such that $\tilde{T}$ has SVD $\tilde{T} = U_T\Lambda_TU_T^\top$, where 
\begin{align*}
\Lambda_T=\Lambda(\tilde T)\approx \Lambda(T)= diag(\lambda_i-\lambda_i+2\eta,\lambda_i-\lambda_{i-1}+2\eta,\cdots,\lambda_i-\lambda_n+2\eta,\underbrace{\lambda_i,\cdots,\lambda_i}_{i-1})  .
\end{align*}
This means the $k-i+2$-th to $n-i+1$-th eigenvector of $T$ is exactly $V_2$ and then $(U_T)_{k-i+2:n-i+1}\approx V_2$.  Consequently $(\lambda_{i} I-\Lambda_2)V_2^\top\tilde{T}^{-1} U_T = (\lambda_{i} I-\Lambda_2)V_2^\top U_T\Lambda_T^{-1}$ can be decomposed as 
\begin{align}
\label{decomT}
    (\lambda_{i} I-\Lambda_2)V_2^\top U_T\Lambda_T^{-1}=(\lambda_{i} I-\Lambda_2)V_2^\top (U_{T,1}U_{T,1}^\top+U_{T,2}U_{T,2}^\top)U_T\Lambda_T^{-1},
\end{align}
 where $U_{T,1}$ is $(U_T)_{k-i+2:n-i+1}$ and $U_{T,2}$ is the rest $k$ columns of $U_T$. 

 We first give the bound of $(\lambda_{i} I-\Lambda_2)V_2^\top U_{T,1}U_{T,1}^\top U_T\Lambda_T^{-1}$ in \eqref{decomT}. Note that $\tilde{T}\succeq \lambda_i I-(I-V_{1:i-1}V_{1:i-1}^\top)(A-\eta I)(I-V_{1:i-1}V_{1:i-1}^\top)$ yields $\Lambda_T^{-1}(j,j)\leq \frac{1}{\lambda_i-\lambda_{i+j-1}+\eta}$ for $j\leq n-i+1$. Thus 
\begin{align}
\label{decompT1}
    \|(\lambda_{i} I-\Lambda_2)V_2^\top U_{T,1}U_{T,1}^\top U_T\Lambda_T^{-1}\|_F^2&\leq \sum_{s=1}^{n-k}(\sum_{t=1}^{k-i+1} (\frac{\lambda_{i}-\lambda_{k+s}}{\lambda_{i}-\lambda_{i+t-1}+\eta} v_s^\top u_t)^2+\sum_{t=n-i+2}^{n} (\frac{\lambda_{i}-\lambda_{k+s}}{\lambda_{i}} v_s^\top u_t)^2),
\end{align}
where $v_s$ is s-th eigenvector of $V_2$ and $u_t$ is t-th eigenvector of $U_T$. 

To bound $v_s^\top u_t$, we are using the fact that $(I-V_{1:i-1}V_{1:i-1}^\top)\hat A(I-V_{1:i-1}V_{1:i-1}^\top)$ is a perturbation of $ (I-V_{1:i-1}V_{1:i-1}^\top)(A-2\eta I)(I-V_{1:i-1}V_{1:i-1}^\top)$, whose eigenvectors are exactly $v_s$. By Davis-kahan theorem, when $k+1>i+t-1$ and thus $\lambda_{k+s}< \lambda_{i+t-1}$, for any $l>0$ we have
\begin{align}
\label{DK}
    \|(V_2)_{s:s+l}^\top u_t\|& \leq \frac{\|V_{i:n}V_{i:n}^\top\hat AV_{i:n}V_{i:n}^\top-V_{i:n} (\Lambda_{i:n}-2\eta I)V_{i:n}^\top\|}{gap}\notag\\
    &\leq \frac{\eta }{\lambda_{i+t-1}-3\eta-(\lambda_{k+s}-2\eta)}= \frac{\eta }{\lambda_{i+t-1}-\lambda_{k+s}-\eta},
\end{align}
where the second inequality comes form the fact that 
$-\eta I\preceq V_{i:n}^\top\hat AV_{i:n}-(\Lambda_{i:n}-2\eta I)\preceq \eta I$, and $gap\geq \lambda_{i+t-1}-3\eta-(\lambda_{k+s}-2\eta)$, because $v_s$'s corresponding eigenvalue is $\lambda_{k+s}-2\eta$ and $u_t$'s corresponding eigenvalue satisfies $\lambda_{i+t-1}-3\eta \leq \lambda\leq \lambda_{i+t-1}-\eta$.

Inequality \eqref{DK} indicates $\sum_{s=s_0}^{n-k}(v_s^\top u_t)^2\leq (\frac{\eta }{\lambda_{i+t-1}-\lambda_{k+s_0}-\eta})^2$. Then the problem 
$$\max_{v_s}\sum_{s=1}^{n-k} (\frac{\lambda_{i}-\lambda_{k+s}}{\lambda_{i}-\lambda_{i+t-1}+\eta} v_s^\top u_t)^2,\quad \text{subject to}\ \sum_{s=s_0}^{n-k}(v_s^\top u_t)^2\leq (\frac{\eta }{\lambda_{i+t-1}-\lambda_{k+s_0}-\eta})^2, \text{$\forall 1\leq s_0\leq n-k$}$$ 
can be viewed as a linear optimization $\max_{x_s}\sum_sa_sx_s$ with restriction $\sum_{s=s_0}^{n-k} x_s\leq b_{s_0}$, where $x_s = (v_s^\top u_t)^2$, $a_s=(\frac{\lambda_{i}-\lambda_{k+s}}{\lambda_{i}-\lambda_{i+t-1}+\eta})^2$ and $b_{s_0} = (\frac{\eta }{\lambda_{i+t-1}-\lambda_{k+s_0}-\eta})^2$. Since $a_s$ is ascending and $b_{s_0}$ is descending, the solution of the linear optimization problem is $x_j=b_j-b_{j+1}$ for $j\neq n$ and $x_n=b_n$. Thus we have
\begin{align*}
    &\sum_{t=1}^{k-i}\sum_s(\frac{\lambda_{i}-\lambda_{k+s}}{\lambda_{i}-\lambda_{i+t-1}+\eta} v_s^\top u_t)^2\\
    \leq& \sum_{t=1}^{k-i}(\frac{\eta}{\lambda_{i}-\lambda_{i+t-1}+\eta})^2(\sum_{s=1}^{n-k-1}(\lambda_{i}-\lambda_{k+s})^2(\frac{1}{(\lambda_{i+t-1}-\lambda_{k+s}-\eta)^2}-\frac{1}{(\lambda_{i+t-1}-\lambda_{k+s+1}-\eta)^2})).\\
\end{align*}

Note that the above summation $\sum_{s=1}^{n-k-1}(\lambda_{i}-\lambda_{k+s})^2(\frac{1}{(\lambda_{i+t-1}-\lambda_{k+s}-\eta)^2}-\frac{1}{(\lambda_{i+t-1}-\lambda_{k+s+1}-\eta)^2})$ can be viewed as the discretization of integral $\int_{\lambda_{i+t-1}-\lambda_{n}-\eta}^{\lambda_{i+t-1}-\lambda_{k+1}-\eta}(x+\lambda_{i}-\lambda_{t+i-1}+\eta)^2d\frac{1}{x^2}$, and the integral is actually larger. Thus a further analysis gives
\begin{align}
\label{longterm}
\scriptsize
    \notag&\sum_{t=1}^{k-i}(\frac{\eta}{\lambda_{i}-\lambda_{i+t-1}+\eta})^2(\sum_{s=1}^{n-k-1}(\lambda_{i}-\lambda_{k+s})^2(\frac{1}{(\lambda_{i+t-1}-\lambda_{k+s}-\eta)^2}-\frac{1}{(\lambda_{i+t-1}-\lambda_{k+s+1}-\eta)^2}))\\\notag
    \leq& \sum_{t=1}^{k-i}(\frac{\eta}{\lambda_{i}-\lambda_{i+t-1}+\eta})^2\int_{\lambda_{i+t-1}-\lambda_{n}-\eta}^{\lambda_{i+t-1}-\lambda_{k+1}-\eta}(x+\lambda_{i}-\lambda_{t+i-1}+\eta)^2d\frac{1}{x^2}\\\notag
    \leq& \sum_{t=1}^{k-i}(\frac{\eta}{\lambda_{i}-\lambda_{i+t-1}+\eta})^2(2\log(\frac{\lambda_{i+t-1}-\lambda_n-\eta}{\lambda_{i+t-1}-\lambda_{k+1}-\eta}))\\  \notag  
    + &\sum_{t=1}^{k-i}(\frac{\eta}{\lambda_{i}-\lambda_{i+t-1}+\eta})^2\biggl(4(\frac{\lambda_{i}-\lambda_{i+t-1}+\eta}{\lambda_{i+t-1}-\lambda_{k+1}-\eta}-\frac{\lambda_{i}-\lambda_{i+t-1}+\eta}{\lambda_{i+t-1}-\lambda_{n}-\eta})\\\notag
    +&((\frac{\lambda_{i}-\lambda_{i+t-1}+\eta}{\lambda_{i+t-1}-\lambda_{k+1}-\eta})^2-(\frac{\lambda_{i}-\lambda_{i+t-1}+\eta}{\lambda_{i+t-1}-\lambda_{n}-\eta})^2)\biggr)\\
    \leq& (k-i+1)(2\log(\frac{\lambda_{i}-\lambda_n-\eta}{\lambda_{i}-\lambda_{k+1}-\eta})+4(\frac{\eta}{\lambda_{k}-\lambda_{k+1}-\eta}-\frac{\eta}{\lambda_{k}})+(\frac{\eta}{\lambda_{k}-\lambda_{k+1}-\eta})^2-(\frac{\eta}{\lambda_{k}})^2)\\\notag
    \leq& k(2\log(\frac{\lambda_{i}-\lambda_n-\eta}{\lambda_{i}-\lambda_{k+1}-\eta})+c_{gap,\eta}),
\end{align}
Where $c_{gap,\eta}=c\frac{\eta}{\lambda_k-\lambda_{k+1}}$ for some small constant $c$, which bound the last two term in \eqref{longterm} since $constant \cdot \eta<\lambda_k-\lambda_{k+1}$ for some constant. The third inequality comes from the fact that
\begin{align*}
    \max_{\lambda_{i}\geq \lambda_{i+t-1}\geq\lambda_{k}\geq(1+\eta)\lambda_k}(\frac{\eta}{\lambda_{i}-\lambda_{i+t-1}+\eta})^2\log(\frac{\lambda_{i+t-1}-\lambda_n-\eta}{\lambda_{i+t-1}-\lambda_{k+1}-\eta})\leq \log(\frac{\lambda_{i}-\lambda_n-\eta}{\lambda_{i}-\lambda_{k+1}-\eta}).
\end{align*}

Back to \eqref{decompT1}, with $\sum_{t=n-i+1}^{n-1}\sum_s(\frac{\lambda_{i}-\lambda_{k+s}}{\lambda_{i}} v_s^\top u_t)^2\leq (i-1)\frac{\lambda_{i}-\lambda_{k+s}}{\lambda_{i}}\leq i-1$ we have $\|(\lambda_{i} I-\Lambda_2)V_2^\top U_{T,1}U_{T,1}^\top U_T\Lambda_T\|\leq \sqrt{2k(\log(\frac{(1-\eta)\lambda_{i}}{(1-\eta)\lambda_{i}-\lambda_{k+1}})+c_{gap,\eta})}$ with a little abuse of notation $c_{gap,\eta}$, which differs from previous ones with only $\frac{i-1}{2k}$.

Back to \eqref{decomT} we now have
\begin{align}
\label{pre1}
    \|(\lambda_{i} I-\Lambda_2)V_2^\top U_T\Lambda_T\|&\leq \|(\lambda_{i} I-\Lambda_2)V_2^\top U_{T,1}U_{T,1}^\top U_T\Lambda_T\|+\|(\lambda_{i} I-\Lambda_2)V_2^\top U_{T,2}U_{T,2}^\top U_T\Lambda_T\|\notag\\
    &\leq \sqrt{2k(\log(\frac{\lambda_{i}-\lambda_n-\eta}{\lambda_{i}-\lambda_{k+1}-\eta})+c_{gap,\eta})}+\frac{\lambda_{i}-\lambda_n}{\lambda_{i}-\lambda_{k+1}+\eta}\notag\\
    &\leq c_1\frac{\lambda_{i}-\lambda_n}{\lambda_{i}-\lambda_{k+1}},
\end{align}
where $c_1$ is a small constant that depends on $\sqrt{k}$.

Finally combining \eqref{decompose1} with \eqref{pre1}, and recall that we have proved $\|\hat T^{-1}\|\leq \frac{2}{\eta}$ and $\|\hat T-\tilde T\|\leq 13\lambda_1\epsilon$, we get 
\begin{align*}
    \|(\lambda_{i} I-\Lambda_2)V_2^\top \hat{T}^{-1}V_1\|&\leq  \|(\lambda_{i} I-\Lambda_2)V_2^\top \tilde{T}^{-1}V_1\|
    +\|(\lambda_{i} I-\Lambda_2)V_2^\top (\hat{T}^{-1}-\tilde{T}^{-1})V_1\|\\
    & =\|(\lambda_{i} I-\Lambda_2)V_2^\top \tilde{T}^{-1}V_1\|
    +\|(\lambda_{i} I-\Lambda_2)V_2^\top \tilde{T}^{-1}(\tilde{T}-\hat{T})\hat{T}^{-1}V_1\|\\
    & \leq  \frac{c_1 (\lambda_i-\lambda_n)}{\lambda_{i}-\lambda_{k+1}}+\|(\lambda_{i} I-\Lambda_2)V_2^\top \tilde{T}^{-1}\|\|(\tilde{T}-\hat{T})\hat{T}^{-1}V_1\|\\
    & \leq  \frac{c_1 (\lambda_i-\lambda_n)}{\lambda_{i}-\lambda_{k+1}}+\frac{c_1 (\lambda_i-\lambda_n)}{\lambda_{i}-\lambda_{k+1}}\frac{26\lambda_1\epsilon }{\eta}.
\end{align*}

With assumption $\epsilon\leq \frac{\eta}{26(\lambda_1-\eta)}$ and bound of term 1 in \eqref{eq:term1results}, combining two terms in \eqref{decompose2} gives
\begin{align*}
    \|V_2^\top (\lambda_i I-\Lambda^2)u_{q+1}\|&\leq 3.5\eta\|V_2^\top u_q\|+\frac{c_1(\lambda_i-\lambda_n)}{\lambda_i-\lambda_{k+1}}\|(\lambda_i I-\Lambda_1)V_1^\top u_q\|\\
    \|V_2^\top u_{q+1}\|&\leq \frac{3.5\eta}{\lambda_i-\lambda_{k+1}}\|V_2^\top u_q\|+\frac{c_1(\lambda_i-\lambda_n)}{(\lambda_i-\lambda_{k+1})^2}\|(\lambda_i I-\Lambda_1)V_1^\top u_q\|.
\end{align*}

Similar to proof in 1-svd, we bound $\|u_{q+1}\|$ by
\begin{align*}
    \|u_{q+1}\| &= \|u_q+\hat T^{-1}(A-\lambda_i I)u_q\|\\
    &\geq \|u_q\|-\|\hat T^{-1} \|\| (\Lambda_1-\lambda_iI)V_1^\top u_q+(\Lambda_2-\lambda_i I)V_2^\top u_q\|
\end{align*}
Denote $U_q = [u_q^1,u_q^2,\cdots,u_q^k]$, then by lemma \ref{correction} we have $\|(\Lambda_1-\lambda_iI)V_1^\top u_q\|\leq 17\lambda_1\|V_2^\top U_q\|^2$. And $\|(\Lambda_2-\lambda_i I)V_2^\top u_q\|\leq (\lambda_i-\lambda_{k+1})\|V_2^\top u_q\|$. Thus $\|u_{q+1}\|\geq 1-\frac{2(\lambda_i-\lambda_{k+1})}{\eta}\|V_2^\top u_q\|-\frac{34\lambda_1}{\eta}\|V_2^\top U_q\|^2$ for some constant $c$ suppose that $u_q$ is normalized such that $\|u_q\|=1$. 

Thus if $\epsilon_0 = max\{\frac{4(\lambda_i-\lambda_{k+1})}{\eta}\|V_2^\top u_q\|,\frac{68\lambda_1}{\eta}\|V_2^\top U_q\|^2\}$, we have
\begin{align*}
    \frac{\|V_2^\top u_{q+1}\|}{\|u_{q+1}\|}\leq \frac{1}{1-\epsilon_0}( \frac{3.5\eta}{\lambda_i-\lambda_{k+1}}\frac{\|V_2^\top u_q\|}{\|u_q\|}+\frac{c_1(\lambda_i-\lambda_n)}{(\lambda_i-\lambda_{k+1})^2}\frac{\|(\lambda_i I-\Lambda_1)V_1^\top u_q\|}{\|u_q\|}).
\end{align*}
\end{proof}

