For soundness, we assume that the semantics of basic functions is sound w.r.t.\, the operational semantics, i.e.
$f(v) \rightarrow v' \implies \sem{f}(\sem{v}) = \sem{v'}$.
%
We have small-step soundness:
\begin{theorem} [Small-step Soundness] 
\label{thm:smallsound} 
%
%
Suppose  $e\type \sigma\etype \epsilon$ and  $\myg \type \sigma \to \real\etype \epsilon_1$ with $\epsilon_1 \subseteq \epsilon$. Then:
%
{\small \[\myg \vdash_\epsilon e \xrightarrow{r} e' \;\; \implies \;\; 
    \ssem{e}\lsem{\myg} = r\cdot(\ssem{e'}\lsem{\myg})\]}
\end{theorem}

and that implies evaluation (big-step) soundness:
\begin{theorem} [Evaluation soundness] 
\label{thm:sound} For all %
$e\type \sigma\etype \epsilon$ and  %
$\myg \type \sigma \to \real\etype \epsilon'$ with $\epsilon' \subseteq \epsilon$ we have:
%
{\small \begin{enumerate}
\item If $\myg \vdash_\epsilon e \xRightarrow{r} v$ then $ 
    \ssem{e}\lsem{\myg} = (r,\vsem{v})$.
%
\item If $
\myg \vdash_\epsilon e \xRightarrow{r} K[\op(v)]$ then
$ \ssem{e}\lsem{\myg} = r\cdot \ssem{K[\op(v)]}\lsem{\myg}$


%
%
 %
  %
     \end{enumerate}}
%
%
%
%
%
%
%
%
%
%
%
\end{theorem}
%
%
%
%
%
%
%
%
%
%
%
%
%
Combining soundness and termination (Theorem~\ref{thm:term}) 
we obtain adequacy:
%
\begin{theorem} [Adequacy] 
\label{thm:adequate} For all %
$e\type \sigma\etype \epsilon$ and %
$\myg \type \sigma \to \real\etype \epsilon'$ with $\epsilon' \subseteq \epsilon$ we have:
%
{\small \begin{enumerate}

\item
If $ \ssem{e}\lsem{\myg} = (r,a)$ then, for some $v$,
    $\myg \vdash_\epsilon e \xRightarrow{r} v$ and $\vsem{v} = a$.
%
\item
%
If $
\ssem{e}\lsem{\myg} = \varphi^{\R \times \ssem{\sigma}}_{\ell,\op,\epsilon(\ell)} (a,f)$
then, for some $K[\op(v)]$,  $\myg \vdash_\epsilon e \xRightarrow{r} K[\op(v)]$, 
$a = \vsem{v}$,\\ and $f = \lambda b \in \ssem{\inn}.\,
    r\cdot \ssem{K[x]}(x \mapsto b)\lsem{\myg}
 $.
\end{enumerate}}
%
%
%
%
%
%
%
%
%
 %
  %
 %
%
%
%
%
%
%
%
%
%
%
\end{theorem}

\gcut{\begin{proof}
Suppose that $\ssem{e}\lsem{\myg} = (r,a)$. By the termination theorem, Theorem~\ref{thm:term}, either there are $r'$ and $v$ such that
$\myg \vdash_\epsilon e \xRightarrow{r'} v$ or else there are $r'$ and $K[\op(v)]$ such that
$\myg \vdash_\epsilon e \xRightarrow{r'} K[\op(v)]$. 
Using the second part of Theorem~\ref{thm:sound}, we see that the latter cannot happen, as then $\ssem{e}\lsem{\myg}$ would not have the form $(r,a)$.
So there are $r'$ and $v$ such that
$\myg \vdash_\epsilon e \xRightarrow{r'} v$.
Then, by evaluation soundness, we have $\ssem{e}\lsem{\myg} = (r',\vsem{v})$. So $(r,\vsem{v}) = (r',a)$ and the conclusion follows.

The second part is proved similarly.
\end{proof}}
As usual, if $\sigma$ is first-order and the 
denotation map $\sem{c}$ of constants is 1-1, 
we have the corollary:\\[-1em]
%
\[\myg \vdash_\epsilon e \xRightarrow{r} v \;\; \iff \;\; 
\ssem{e}\lsem{\myg} = (r,\vsem{v})\]
%


Fixing $\sigma$ and $\epsilon$, set $E = \{e:\sigma\etype\epsilon\}$, and let 
 $\EV$, the set of \textit{effect values},
be the least set such that:
{\small \[\EV\;\; = \;\; 
%
\sum_{\ell \in \epsilon, \op: \outt \xrightarrow{\ell} \inn} 
 \hspace{-15pt} V_\outt \times \EV^{V_\inn}  %
  \;+ \;(R \times V_\sigma) \]}%
%
%
%
%
where, for any $\tau$,  $V_\tau \eqdef \{v|v\type\tau\}$. Following~\cite{plotkin2001adequacy,plotkin2009adequacy}, 
%
we  evaluate  expressions as far as effect values.
%
Fixing $\myg\type \sigma \to \loss\etype \epsilon'$ (with $\epsilon'\subseteq\epsilon$)
define (using the evident $R$-action on $\EV$) a \textit{giant step} evaluation function
$\mathrm{Eval}: \mathrm{E} \rightharpoonup \EV$ (shown total via computability)  by:
%
{\small \[\mathrm{Eval}(e) = 
   \left \{
   \begin{array}{ll}
      (r,v)  & (\myg \vdash_\epsilon e \xRightarrow{r} v) \\
       ((\ell,\op),(v, \lambda w \in \V_{\inn}.\, r\cdot\mathrm{Eval}(K[w])) & 
        (\myg \vdash_\epsilon e \xRightarrow{r} K[\op(v)], \op: \outt \xrightarrow{\ell} \inn)
   \end{array}
   \right .\]}
   %
%
%
%
%
%
%
%
 %
Next let $\mysim$ be the least relation between $\EV$ and $W_\epsilon(\ssem{\sigma})$
such that
(1) $(r,v) \mysim (r,\vsem{v})$
and
(2)$((\ell,\op),(v,f)) \mysim ((\ell,\op,\epsilon(\ell)),(\vsem{v},g))$ if
$\forall w \in V_\inn. f(w) \mysim g(\vsem{w})$.

%
%
%
%
\begin{theorem}[Giant Step Adequacy] \label{thm:giant} For all $e\type \sigma\etype \epsilon$ we have: $\mathrm{Eval}(e) \mysim \ssem{e}\lsem{\myg}$.
\end{theorem}

