\begin{theorem} \label{Athm:dps}
\myskip
\begin{enumerate}
    \item (\textit{Termination}) If  $e$ is terminal, then it can make no transition, i.e., $\myg \vdash_{\epsilon} e \xrightarrow{r} e'$ holds for no $\myg, r, \epsilon$, and $e'$. 
   \item (\textit{Determinism}) If  $~\myg \vdash_{\epsilon} e \evalto{r} e'$ and  $\myg \vdash_{\epsilon} e \evalto{r'} e''$ then $r = r'$ and $e' = e''$.
   \item (\textit{Progress})  If $e\type \sigma\etype \epsilon_1$ is non-terminal, then
     $\myg \vdash_{\epsilon_1} e \evalto{r} e'$  holds for some $r$ and $e'$ for any $~\myg\type \sigma \to \real\etype \epsilon_2$ with $\epsilon_2 \subseteq \epsilon_1$.
   \item (\textit{Type safety})  If $~\myg\type \sigma \to \real\etype \epsilon_2$,  
        $\myg \vdash_{\epsilon_1} e \evalto{r} e'$, with $\epsilon_2 \subseteq \epsilon_1$,
       and $e\type \sigma\etype \epsilon_1$ then $e'\type \sigma\etype \epsilon_1$.
\end{enumerate}

\end{theorem}
\begin{proof}
 We first prove termination. The proof is by induction on $e$. By the analysis lemma $e$ is not a redex, so no redex rule can apply. 
It can have the form $F[e_1]$ or $S[e_1]$, but by the unique analysis lemma $e_1$ must be terminal, so by the induction 
hypothesis $e_1$ cannot make a move, so no context rule can apply to $e$ either.


 We next prove determinism by induction on expressions $e$. We split into cases using the analysis lemma.
If $e$ is terminal, then,as we have just seen, $e$ cannot make any transition.
If $e$ is a redex, then, by the analysis lemma it is so uniquely. 
There is then a unique rule that can apply and it is deterministic (all rules are). Finally if $e$ has 
one of the forms $F[e_1]$ or $S[e_1]$, then there is at most one context rule that can apply. 
By the induction. hypothesis,
$e_1$ can make at most one transition, and so then $e$ can only make at most one transition as context rules 
are deterministic in the transitions the sub-expressions can make.

 Suppose next that, for a non-terminal $e$, we have $~\myg\type \sigma \to \real\etype \epsilon_2$ and $e\type \sigma\etype \epsilon_1$ with $\epsilon_2 \subseteq \epsilon_1$. We  show that 
 $\myg \vdash_{\epsilon_1} e \evalto{r} e'$  for some $r$ and $e'$ with $e'\type \sigma\etype\epsilon_1$. This  proves progress and type safety.

 We first consider the cases where $e$ is a redex:

 \begin{enumerate} 
 \item Suppose $e$ the form $f(v)$. 
 For some $\sigma_1$ and $\tau$ we have  $f\type \sigma_1 \to \tau$. As $e\type \sigma\etype \epsilon_1$ we have 
 $v\type \sigma_1$ and $\sigma = \tau$. So, for some value $v' \type \tau$,  
 we have $f(v) \to v'$. So $\myg \vdash_\epsilon e \xrightarrow{0} v'$ 
 and $v'\type\sigma\etype \epsilon_1$.  

\item Suppose $e$ has the form $v.i$. As $e\type \sigma$, we have $\sigma = (\sigma_1,\dots, \sigma_n)$
and $v = (v_1,\dots,v_n)$, for some $v_1\type\sigma_1,\dots, v_n\type\sigma_n$. Then
$\myg\vdash_{\epsilon_1}v.i \xrightarrow{0} v_i$ and 
$v_i\type \sigma$.
\item Suppose $e$ has the form $\mycases{\inl{\sigma_1}{\sigma_2}(v)}{x_1\type \sigma_1}{e_1}{x_2\type \sigma_2}{e_2}$.
 Then $\myg \vdash_{\epsilon_1} e \xrightarrow{0} e_1[v/x_1]$. As $e\type\sigma\etype\epsilon_1$ we have $v\type \sigma_1$ and $x_1\type \sigma_1\vdash e_1\type \sigma\etype \epsilon_1$. So by Lemma~\ref{Alem:cut} we have $e_1[v/x_1]\type\sigma\etype\epsilon_1$.

\item Suppose $e$ has the form $ \iter{0}{v_2}{v_3}$. Then we have  
$\myg \vdash_{\epsilon_1}  e  \evalto{0}  v_2$. As $e\type \sigma\etype \epsilon_1$ we have $v_2\type \sigma$.

\item Suppose $e$ has the form    $\fold{\cons{v_1}{v_2}}{v_3}{v_4}$.
Then $\myg \vdash_{\epsilon_1} e \evalto{0} v_4(v_1,\fold{v_2}{v_3}{v_4})$. 
As $e\type \sigma \etype \epsilon_1$, for some $\tau$ we have  
$v_1\type \tau$,
$v_2\type \mylist(\tau)$, 
$v_3\type \sigma$, 
and $v_4\type (\tau,\sigma) \to \sigma\etype \epsilon_1$.
So we see that $\fold{v_2}{v_3}{v_4})\type \sigma \etype \epsilon_1$, and so that
$v_4(v_1,\fold{v_2}{v_3}{v_4})\type \sigma \etype \epsilon_1$.

\item Suppose that $e$ has the form $v_1~v_2$. As $e\type\sigma\etype \epsilon_1$ we have $v_1\type \tau \to \sigma\etype\epsilon_1$ and $v_2\type\tau$ for some $\tau$. So $v_1$ has the form $\lambda^{\epsilon_1} x\type \tau.\, e_3$. So $\myg \vdash_{\epsilon_1} e \xrightarrow{0} e_3[v_2/x]$. As 
$\lambda^{\epsilon_1} x\type \tau.\, e_3\type \tau \to \sigma\etype\epsilon_1$ and $v_2\type \tau$, we have $e_3[v_2/x]\type \sigma\etype\epsilon_1$.

\item Suppose $e$ has the form $\loss(v)$. As $e\type \sigma$, we have $v = r$, for some $r \in \R$, and
$\sigma = ()$. We have $\myg\vdash_{\epsilon_1} e \xrightarrow{r} ()$, and $()\type ()$.

\item Suppose $e$ has the form $\wph{h}{v_1}{K[\op(v_2)]}$ with $\op \notin \hop(K)$ and $ \op \in h$.

 As $e\type\sigma\etype\epsilon_1$ we have $h$ has effect $\epsilon_1$ and also 
$h \mbox{ handles } \ell$, $ h\type \parr, \sigma_1\etype\epsilon_1\ell \Rightarrow \sigma\etype \epsilon_1$, 
$v_1\type \parr$,
and $K[\op(v_2)] \type \sigma_1\etype \epsilon_1\ell$,
for some $\ell$, $\parr$, and $\sigma_1$. 
As $\op \in h$, from the first of these  we have
 $\op\type \outt \xrightarrow{\ell} \inn$ for some $\outt$ and $\inn$. 

 We then have 
 %
 \[\myg\vdash_{\epsilon_1} e \xrightarrow{0} v_o(v_1,v_2,f_l,f_k)\]
 %
 where 
%
\[f_k = \lambda^{\epsilon_1}(p,y)\type (par,in).\,\glocal{\epsilon_1}{\wph{h}{p}{K[y]}}{\myg}\]
%
and 
%
\[f_l = \lambda^{\epsilon_1} (p,y)\type (par,in).\,\then{\epsilon_1}{\wph{h}{p}{K[y]}}{\myg}\]

 From $ h\type \parr, \sigma_1\etype\epsilon_1\ell \Rightarrow \sigma\etype \epsilon_1$ we see that 
$v_o \type (\parr, \outt, (\parr, in) \to \real\etype \epsilon,(\parr,  in)\to \sigma \etype \epsilon_1)\to  \sigma\etype \epsilon_1$, where  $\op \mapsto v_o \in h$.
%
From $K[\op(v_2)] \type \sigma_1\etype \epsilon_1\ell$ and $\op\type \outt \xrightarrow{\ell} \inn$ we see,
via Lemma~\ref{Alem:ctx}, that $v_2\type \outt$ and $y\type \inn \vdash K[y]\type \sigma_1\etype\epsilon_1\ell$.
%
From the latter and the typing of $h$ we see that 
%
\[p\type par, y\type in \vdash \wph{h}{p}{K[y]}\type \sigma \etype \epsilon_1\]
%
From that and $\myg\type \sigma \to \real\etype \epsilon_2$ with $ \epsilon_2 \subseteq \epsilon_1$  we see that 
%
\[p\type par, y\type in \vdash \glocal{\epsilon_1}{\wph{h}{p}{K[y]}}{\myg}\type \sigma \etype \epsilon_1\]
%
and
%
\[p\type par, y\type in \vdash \then{\epsilon_1}{\wph{h}{p}{K[y]}}{\myg}\type \sigma \etype \epsilon_1\]
