\newcommand{\ov}{\overline}
\paragraph{\textbf{Well-foundness of effects}}

We write $e(\epsilon)$ and $e(\sigma)$ for the effect labels appearing in $\epsilon$ or $\sigma$. So, for example 
$e(\sigma \to \tau\etype\epsilon) =  e(\sigma) \cup  e(\tau) \cup (\epsilon)$. Our  well-foundedness assumption is that there is an ordering $\ell_1,\dots, \ell_n$ of the effect labels such that:
%
\[\op\type \outt \xrightarrow{\ell_j} \inn \;\wedge\; \ell_i \in e(\outt) \cup e(\inn) \implies i < j\]
%
We make this assumption for this subsection, and the next section (\Cref{sec:denotational}).

With it, we define the effect levels of multisets of effect labels and types by setting:
$l(\epsilon) = \max_i \{i | \ell_i \in e(\epsilon)\}$ and  $l(\sigma) = \max_i \{i | \ell_i \in e(\sigma)\}$.
We will also make use of the size $|\sigma|$ of an type defined in a standard way (e.g.
$|\sigma \to \tau\etype\epsilon| =  1 + |\sigma| +  |\tau| + |\epsilon|$).


\paragraph{\textbf{Computability}}
Our proof uses suitable recursively-defined notions of computability, following Tait~\cite{Tait67}. 
We define the following main notions:
\begin{itemize}
\item[-] \textit{computability} of  values $v\type \sigma$,
%
\item[-]  \textit{loss computability} of  loss continuations  $\myg\type \sigma \to \real\etype \epsilon$, and   
\item[-]  \textit{computability} of  expressions $e\type\sigma\etype\epsilon$.
\end{itemize}

The definitions are proper (i.e. the recursions terminate) as can be be seen by suitable measures $m$ defined on closed values $v\type \sigma$, closed expressions $e\type \real\etype \epsilon$, closed loss continuations $\myg \type \sigma \to \real\etype \epsilon$, and closed expressions $e\type \sigma\etype \epsilon$; these are pairs of natural numbers, with the lexicographic ordering and are given by:
%
\[m(v) = (l(\sigma), |\sigma|)
\quad
m(e) = (l(\epsilon), 1)
\quad
m(\myg) = (l( \sigma) \max l(\epsilon), | \sigma| )
\quad
m(e) = (l( \sigma) \max l(\epsilon), |\sigma|)\]

We define these notions by the following clauses. 
They employ two auxiliary notions.
One is an inductively defined  notion of \textit{$G$-computability} of closed expressions, where $G$ is a set of closed loss continuations; the other is  a notion of  \emph{R-computability} of closed real-valued expressions.


\begin{enumerate}
\item \begin{enumerate}
         \item Every constant $c\type b$ of ground type is computable.as is $\zero$ and every $\nil_\sigma$.
         \item A  closed value $(v_1,\dots,v_n)\type (\sigma_1,\dots,\sigma_n)$ is computable if every 
                   $v_i\type \sigma_i$ is computable.
                   \item A closed value of one of the forms $\inl{\sigma}{\tau}(v)$,  $\inr{\sigma}{\tau}(v)$, or $\mysucc{v}$ is computable if $v$ is. 
            \item A closed value of  the form  $\cons{v_1}{v_2}$ is computable if $v_1$ and $v_2$ are.  

              \item A closed value $\lambda^{\epsilon} x\type \sigma.\, e \type \sigma \to 
                    \tau\etype\epsilon$ is computable if, for every computable value $ v\type \sigma$, the 
                    expression $e[v/x]\type \tau\etype\epsilon$ is computable.
                \end{enumerate}
%
\item The property  of %
{$G$-computability} of  closed expressions $ e\type \sigma\etype \epsilon$, for a set $G$ of closed loss continuations of type $ \myg\type \sigma \to \real\etype \epsilon'$, where $\epsilon' \subseteq \epsilon$,   is the least such property  $P_{\sigma,\epsilon}$ of these expressions such that 
one of the following three mutually exclusive possibilities holds:
\begin{enumerate}
\item  $e$ is a  computable value.
\item  $e$ is an  stuck expression  $K[\op(v)]$, with $\op\type \outt \xrightarrow{\ell} \inn$, where $v:\outt$ is  a computable  value, and  for every  computable closed value $v_1\type \inn$, 
$P_{\sigma,\epsilon}(K[v_1])$ holds.
\item $e$ is not stuck and for every $\myg \in G$, if $\myg \vdash_\epsilon e \xrightarrow{r} e'$ then  $P_{\sigma,\epsilon}(e')$ holds.
\end{enumerate} 
%
%
\item \begin{enumerate}
                 \item A closed expression $e:\real\etype \epsilon$ is {R-computable}
iff it is $\{0_{\real,\epsilon}\}$-computable.


%
\item A closed loss continuation $\lambda^\epsilon x\type \sigma.\, e\type \sigma \to \real\etype \epsilon$ is {loss-computable} if $e[v/x]$ is R-computable for every closed computable value $v\type \sigma$.
\end{enumerate}
\item A closed expression $e\type \sigma\etype\epsilon$ is {computable} 
iff it is $\Lsc$-computable, where $\Lsc$ is the set of loss-computable 
loss continuations $\myg\type \sigma \to \real\etype \epsilon'$, 
for some $\epsilon'\subseteq \epsilon$. 

\end{enumerate} 



