We say that a handler $\myG \vdash h\type \parr,\sigma\etype \epsilon\ell \Rightarrow \sigma'\etype \epsilon$ is computable if,  for every handler operation  definition clause  
$\op \mapsto e_{\op}$, $\myG\vdash e_{\op}\type ((\parr, \outt_i, (\parr, in_i) \to \real\etype \epsilon,(\parr,  in_i)\to \sigma'\etype \epsilon)\to  \sigma'\etype \epsilon)\etype \epsilon$ is   and so is $\myG\vdash e_r\type (\parr, \sigma) \to \sigma'\etype \epsilon$ (where  the handler's return clause is $\return \mapsto e_r$).



\begin{lemma} \label{Alem:glocal}
 If $e\type \sigma\etype \epsilon_1$ is $\{\myg\}$-computable for a loss-computable $\myg\type \sigma \to \real\etype \epsilon_2$ (with 
 $\epsilon_2 \subseteq \epsilon_1$), then $\glocal{\epsilon_1}{e}{\myg}\type \sigma\etype\epsilon$ (with $\epsilon_1 \subseteq \epsilon$) is computable.

 %
\end{lemma}
\begin{proof} 
We proceed by $\{\myg\}$-induction. There are three cases:
%
\begin{enumerate}
\item If $e$ is a computable value $v$, then 
  for any $\myg_1 \in \Lsc$   we have 
$\myg_1 \vdash_\epsilon \glocal{\epsilon_1}{v}{\myg} 
\xrightarrow{0}v$.

    \item If $e$ is a stuck expression of the form $K[\op(v)]$ 
    with $\op : \outt \to \inn$, $v$ computable and $\glocal{\epsilon_1}{K[w]}{\myg}$ computable 
    for every computable $w\type \inn$, then we simply note that
    $\glocal{\epsilon_1}{K[op(v)]}{\myg}$ is stuck.
    \item Suppose that $e$ is not stuck. Then $\glocal{\epsilon_1}{e}{\myg}$ is not stuck.
    Further, if $\myg_1 \vdash_\epsilon \glocal{\epsilon_1}{e}{\myg} \xrightarrow{r} e''$ for $\myg_1 \in \Lsc$, then, as $e$ is not stuck, for some $e'$,
    $\myg \vdash_{\epsilon_1} e \xrightarrow{r} e'$
    and $e'' = \glocal{\epsilon_1}{e'}{\myg}$ and, by the induction hypothesis, $e''$ is computable.



\end{enumerate}
\end{proof}

\begin{lemma} \label{Alem:technical}
 \myskip
 \begin{enumerate}
    \item Suppose $e\type \real\etype\epsilon_1$ is $R$-computable. Then so is any
    $r + \glocal{\epsilon_1}{e}{0_{\real,\epsilon_1}}\type \real\etype\epsilon$ (where $\epsilon_1 \subseteq \epsilon$).
    \item 
 Suppose $\myg\type \real \to \real\etype\epsilon_1$  is loss-computable. Then, for any $r \in \R$, so is
$\lambda^\epsilon x\type\real.\, \then{\epsilon}{(r + x)}{\myg}$  (where $\epsilon_1 \subseteq \epsilon$).
\end{enumerate}
%
\end{lemma}
\begin{proof}
\myskip
\begin{enumerate}
\item We proceed by R-induction. There are three clauses:
\begin{enumerate}
\item  For a value $v\type\real$ we have 
$0_{\real,\epsilon} \vdash_\epsilon  r + \glocal{\epsilon_1}{v}{0_{\real,\epsilon_1}} 
\xrightarrow{0} r + v \xrightarrow{0} s$, 
where $s = r +v$.
\item For a stuck expression  $K[\op(v)]$, with $\op\type \outt \to \inn$ and computable value $v\type \outt$, suppose that $r + \glocal{\epsilon_1}{K[v_1]}{0_{\real,\epsilon_1}}$  is $0_{\real,\epsilon}$-computable for every  computable value $v_1\type \inn$.  This case is immediate, as then $r + \glocal{\epsilon_1}{K[v]}{0_{\real,\epsilon_1}}$ is a stuck expression, and every  $r + \glocal{\epsilon_1}{K[v_1]}{0_{\real,\epsilon_1}}$ is $0_{\real,\epsilon}$-computable.
\item Suppose that $e$ is not stuck. Then neither is
$r + \glocal{\epsilon_1}{e}{0_{\real,\epsilon_1}}$.
%
We may suppose that $0_{\real,\epsilon_1} \vdash_\epsilon e \xrightarrow{s} e'$, for some $e'$ and $s$, with $r + \glocal{\epsilon_1}{e'}{0_{\real,\epsilon_1}}$   $0_{\real,\epsilon}$-computable. Then we have
  %
  \[0_{\real,\epsilon} \vdash_\epsilon  \glocal{\epsilon_1}{e}{0_{\real,\epsilon_1}} \xrightarrow{s}
  \glocal{\epsilon_1}{e'}{0_{\real,\epsilon_1}}\]
  %
  and so
  %
  \[0_{\real,\epsilon} \vdash_\epsilon r + \glocal{\epsilon_1}{e}{0_{\real,\epsilon_1}} \xrightarrow{s}
  r + \glocal{\epsilon_1}{e'}{0_{\real,\epsilon_1}}\]
  %
  and we conclude.
  \end{enumerate}

\item 
Suppose $\myg$ has the form $\lambda^{\epsilon_1} x\type \real.\, e$. Then, for any $v \in \R$ we have:
%
\[0\vdash_\epsilon \then{\epsilon}{(r + v)}{\myg} \;\xrightarrow{0}\;
0 + (\then{\epsilon}{s}{\myg})\; \xrightarrow{0}\; 0 + \glocal{\epsilon_1}{e[s/x]}{0_{\real,\epsilon_1}}\]
where $s = r + v$, and we apply part 1.
\end{enumerate}
\end{proof}

\begin{lemma} \label{Alem:ginc}
\myskip
\begin{enumerate}
\item Let $e\type \real\etype \epsilon$ be computable,
for $\myg_1:\real \to \real\etype\epsilon_1$ with $\epsilon_1 \subseteq \epsilon$. Then $r+ e$ is too, for any $r \in \R$.
\item
Let $\myg\type \sigma \to \real \etype \epsilon'$ be  loss-computable   and let $e\type \sigma \etype \epsilon$ be a $\{\myg\}$-computable expression (with $\epsilon'\subseteq \epsilon$). Then 
$\then{\epsilon}{e}{\myg}$  is computable
 for $\myg_1:\real \to \real\etype\epsilon_1$ with $\epsilon_1 \subseteq \epsilon$.
\item 
Let $\myg\type \sigma \to \real \etype \epsilon'$ be loss-computable
 and let 
$x\type \tau \vdash e\type \sigma \etype \epsilon$ be a computable expression (with $\epsilon'\subseteq \epsilon$). Then $\lambda^\epsilon x\type \tau.\, \then{\epsilon}{e}{\myg}\type \tau \to \real\etype \epsilon$ is computable.
\end{enumerate}
%
\end{lemma}
\begin{proof}
%
\myskip
\begin{enumerate}
\item  We proceed by $L_{\real,\epsilon}$-induction on $e$ to show that $r + e$ is computable. We consider the three clauses in turn:
\begin{enumerate}
\item  For a value $v\type\real$, we have $\myg \vdash_\epsilon r + v  \xrightarrow{0} s$ where $s = r +v$, for $\myg\in \L_{\real,\epsilon}$.
\item For a stuck expression  $K[\op(v)]$, with $\op\type \outt \to \inn$ and computable value $v\type \outt$, suppose that $r + K[v_1]$ is R-computable for every  computable value $v_1\type \inn$.  This case is immediate, as then $r + K[\op(v)]$ is a stuck expression, and every  $r + K[v_1]$ is R-computable.
\item Suppose that for all $\myg' \in L_{\real,\epsilon}$, if $\myg' \vdash_\epsilon e \xrightarrow{s'} e'$ then $r + e'$ is computable. 
Now, choose a $\myg\in \L_{\real,\epsilon}$ and suppose $\myg\vdash_\epsilon r+ e \xrightarrow{s} e''$ to show that $e''$ is computable. 
Then $\lambda^\epsilon x\type\real.\, \then{}{(r +x)}{\myg}\vdash _\epsilon e \xrightarrow{s} e'$, for some $e'$, and $e'' = r+e'$.
%
By Lemma~\ref{Alem:technical}, as $\myg \in \L_{\real,\epsilon}$, so is $\lambda^\epsilon x\type\real.\, \then{}{(r +x)}{\myg}$. Then, by our initial assumption we have $e'' = r+e'$ computable, as required.



\end{enumerate}


\item  We proceed by $\{\myg\}$-induction on $e$, to show that $\then{\epsilon}{e}{\myg}$ is computable. Suppose $\myg$ 
has the form $\lambda^{\epsilon} x\type \sigma.\, e_1$. We consider the three clauses in turn:
\begin{enumerate}
\item  For a value $v\type\real$, we have $\myg_1 \vdash_\epsilon \then{\epsilon}{v}{\myg}  \xrightarrow{0} \glocal{\epsilon'}{e_1[v/x]}{\lambda^{\epsilon'} x:\real.\,0}$ for
$\myg_1 \in \Lsc$. As $\myg$ is loss-computable, this shows that $\then{\epsilon}{v}{\myg}$ is computable, using Lemma~\ref{Alem:glocal}.
\item For a stuck expression  $K[\op(v)]$, with $\op\type \outt \to \inn$ and computable value $v\type \outt$, suppose that $\then{\epsilon}{K[v_1]}{\myg} $ is computable for every  computable value $v_1\type \inn$.  This case is immediate, as then $\then{\epsilon}{K[\op(v)]}{\myg} $ is a stuck expression, and every  $\then{\epsilon}{K[v_1]}{\myg} $ is computable.
\item Suppose that $\myg \vdash_\epsilon e \xrightarrow{r} e'$ and $\then{\epsilon}{e'}{\myg}$ is computable. Then
  $\myg_1 \vdash_\epsilon \then{\epsilon}{e}{\myg} \xrightarrow{0} r + (\then{\epsilon}{e'}{\myg})$, for any $\myg_1 \in \Lsc$. So, using part 1 of this lemma, we see that $\then{\epsilon}{e}{\myg}$ is computable.
\end{enumerate}

\item Part 3 follows immediately from part 2.
\end{enumerate}
\end{proof}


\begin{lemma} \label{{Alem:easyframe}} 
Let $F$ be a regular frame such  that $x\type \sigma \vdash F[x]\type \tau \etype \epsilon$ is computable.  Then 
$F[e]\type \tau\etype\epsilon$ is computable for any computable expression $e\type \sigma \etype \epsilon$.
\end{lemma} 
\begin{proof} 
%
Fix a loss-computable $\myg: \tau \to \real\etype\epsilon'$ 
with $\epsilon'\subseteq\epsilon$, to show $F[e]$ $\{\myg\}$-computable. 
By Lemma~\ref{Alem:ginc}, the loss continuation 
$\myg' \eqdef \lambda^\epsilon x\type \sigma. (\then{\epsilon}{F[x]}{\myg}) \type \tau \to \real\etype \epsilon$ is loss-computable
and so $e$ is $\{\lambda^\epsilon x\type \sigma. (\then{\epsilon}{F[x]}{\myg})\}$-computable.

%
%
%
%
%


We show by $\{\myg'\}$-induction on $\{\myg'\}$-computable expressions $e$  that $F[e]\type \tau\etype \epsilon$ is $\{\myg\}$-computable. 

\begin{enumerate}
\item  $F[v]$ is computable for every computable value $v\type \sigma$ as $F$ is assumed computable.
\item 
Let $K[\op(v)]$ be a stuck expression, with $\op\type \outt \to \inn$, computable value $v\type \outt$, and $F[K[v_1]]$ $\{\myg'\}$-computable, for every computable value $v_1\type \inn$. Then $F[K[\op(v)]]$ is a stuck expression as $F$ is not $\wph{h}{v}{\square}$, and it is then seen to be $\{\myg'\}$-computable as every $F[K[v_1]]$ is.
\item We may suppose that 
$\lambda^\epsilon x\type \sigma.\, (\then{\epsilon}{F[x]}{\myg}) \vdash_\epsilon e \xrightarrow{r} e'$ and $F[e']$ is $\{\myg\}$-computable. Then $\myg \vdash_\epsilon F[e] \xrightarrow{r} F[e']$ and so $F[e]$ is too.
\end{enumerate}

\end{proof}
