\begin{lemma} \label{Alem:handframe}
 Suppose the $\ell$-handler  $h\type \parr, \sigma \etype \epsilon\ell \Rightarrow \sigma'\etype \epsilon$ and 
the expression $e\type \sigma \etype \epsilon\ell $ are both computable. Then, for any  computable  value, $v\type \parr$ so is the expression 
$\wph{h}{v}{e}\type \sigma'\etype \epsilon$.
\end{lemma}
\begin{proof}
%
First, for any computable value $v\type\parr$, set $F_v \eqdef \wph{h}{v}{\square}$, and for any $\myg \in L_{\sigma',\epsilon}$ set 
$\myg_v \eqdef  \lambda^\epsilon x\type \sigma.\,\then{\epsilon}{e_r(v_p,x)}{\myg}$,
where the return clause in $h$ is $\return \mapsto e_r$.
By Lemmas~\ref{Alem:ginc} and~\ref{{Alem:easyframe}}, each $\myg_v$ is 
computable, since $e_r$ is computable as $h$ is.
%
We use $\Lsc$-induction on $e$ to show that for any computable $v\type\parr$, $F_v[e]$  is computable. 
The three cases are:
\begin{enumerate}
\item Suppose $e$ is a computable value $w\type\sigma$. Choose  computable values $v\type\parr$  to show $F_v[w]$ is computable. For any
$\myg \in L_{\sigma',\epsilon}$ we have 
%
\[\myg \vdash_\epsilon F_v[w] \xrightarrow{0} e_r(v_p,v) \qquad (\ast)\]
%
 Applying Lemma~\ref{{Alem:easyframe}}, we see that $e_r(v_p,v)$ is computable, as $e_r$ is computable since $h$ is. So, using $(\ast)$, we see that $F_v[w]$ is $\{\myg\}$-computable.
\item 
Let $K[\op(w)]$ be stuck, with $\op\type \outt \to \inn$, computable value $w\type \outt$, such that for every computable value $w_1\type \inn$,$F_{v_1}[K[w_1]]$ is computable  for every computable value $v_1\type\parr$. 
We have to show that $F_v[K[\op(w)]]$ is computable for all computable values $v\type\parr$.



In case $\op$ is not an $h$-operation, we see that each  $F_{v}[K[\op(w)]]$ is a stuck expression and $F_{v}[K[w_1]]$ is computable for all values  $w_1\type \inn$. So, in this case, 
each $F_v[K[\op(w)]]$ is $\{\myg\}$-computable, as required.

In case $\op$ is an  $h$-operation, for any $\myg \in L_{\sigma',\epsilon}$ we have
\[\myg \vdash_\epsilon F_v[K[\op(w)]] \xrightarrow{0} e_\op(v,w,f_l,f_k)\qquad (\ast\ast)\]
where 
\[\op \mapsto e_\op \in h\]
and
\[f_k = \lambda^\epsilon(p,y)\type (par,in).\,\glocal{\epsilon}{\wph{h}{p}{K[y]}}{\myg}\]
%
and
%
 \[f_l = \lambda^\epsilon (p,y)\type (par,in).\,\then{\epsilon}{(\wph{h}{p}{K[y]})}{\myg}\]

 %
%
%
and it suffices to prove that $e_\op(v,w,f_l,f_k)$ is computable.
As $e_\op$ is computable by the assumption that $h$ is and as $v$ and $w$ are computable by assumption, we need only prove that $f_k$ and $f_l$ are.

To see that $f_k$ is computable we note that,  for all $v_1\type \parr$ and $w_1 \type \inn$, we are given that
$\wph{h}{v_1}{w_1}$ is computable, and then, using Lemma~\ref{Alem:glocal}, we see that  $\glocal{\epsilon}{\wph{h}{v_1}{K[w_1]}}{\myg}$ is computable .

The proof for $f_l$ is similar, instead using Lemma~\ref{Alem:ginc}.
%
%
%
%

 %
 \item Suppose $e$ is not stuck. Here, for any $\myg_1 \in L_{\sigma,\epsilon\ell}$, if 
 $\myg_1 \vdash_{\epsilon\ell} e \xrightarrow{r} e'$ then $F_v[e']$
is computable for any computable value $v\type\parr$. 
As $e$ is not stuck then neither is any $F_v[e]$ and for any
$\myg \in L_{\sigma',\epsilon}$, if $\myg\vdash_\epsilon F_v[e] \xrightarrow{r} e''$ then 
 $e'' = F_v[e']$, for some $r$ and $e'$ such that
 $\myg_v \vdash_{\epsilon\ell} e \xrightarrow{r} e'$ (recall that $\myg_v$ is computable and so in $L_{\sigma,\epsilon\ell}$) and so $e'' = F_v[e']$ is computable, as required.

\end{enumerate}

\end{proof}


