\begin{lemma}[Fundamental Lemma] \label{Alem:comp}Every expression $\myG \vdash e\type \sigma\etype \epsilon$ is computable.
\end{lemma} 
\begin{proof}

  The proof is by induction on the size of $e$ (defined in a standard way). Consider a context $\myG = x_1\type \sigma_1,\dots,x_n\type \sigma_n$, and choose computable  values $v_1\type\sigma_1,\dots,v_n\type \sigma_n$. We have to show that 
  $\ov{e} = e[v_1/x_1,\dots,v_n/x_n]$ is computable. 
  %

 The proof splits into cases according to the form of $e$, following Lemma~\ref{eal}.
\begin{enumerate}
\item %
 \begin{enumerate}
      \item If $e = x_i$ then $\ov{e} = v_i$ is a computable  value by assumption. So $e$ is a computable expression. 
\item If $e$ is a basic constant, $\zero$, or some $\nil_\sigma$ then it is a computable value by definition.
 \item If $e = (v'_1,\dots, v'_m)$ then $\ov{e} = (\ov{v'_1},\dots, \ov{v'_n})$ is a computable value as, by the induction hypothesis all the $\ov{v'_j}$ are computable expressions.
 \item If $e$ has one of the forms $\inl{\sigma}{\tau}(v)$, $\inr{\sigma}{\tau}(v)$, 
   $\mysucc{v}$, or $\cons{v_1}{v_2}$ the proof is similar to the previous case.
   \item If $e = \lambda^{\epsilon} x\type \sigma_1.\, e_1$ then we  show that $\ov{e} =  \lambda^{\epsilon} x\type \sigma_1.\, \ov{e_1}$ is a computable value, that is that for every computable value $ v\type \sigma_1$, $\ov{e_1}[v/x]$ is a computable expression, and that is immediate from the induction hypothesis.
 \end{enumerate}
\item %
The next case is when $e$ is stuck, with the form $K[\op(v)]$ with $\op\type \outt \xrightarrow{\ell} \inn$ and $\myG \vdash v\type \outt$. It suffices to show that $\ov{K}[w]$ is computable for every computable $w\type \inn$. However, as $K[x]$ (choosing $x \notin \Dom(\myG)$)  is smaller than $e$, we have $K[x]$ computable, and so $\ov{K}[w] = K[x][v_1/x_1,\dots,v_n/x_n,w/x]$ is computable.
\item The next case is when $e$ is a redex. As before we split into subcases according to the form of the expression.
  \begin{enumerate}
  \item %

  \item  %


  \item  %
  Suppose that $e$ has the form  $v.i$. Then, using the typing information, the fact that $v$ is a value,  and the induction hypothesis we see that  $\ov{e}$ has the form $(v_1,\dots,v_m).i$ with the $v_j$ computable. So as   $\myg \vdash_\epsilon \ov{e} \xrightarrow{0} v_i$ (for every loss-computable loss continuation $\myg\type b \to \real\etype \epsilon'$ with  $\epsilon' \subseteq  \epsilon$)  and as $v_i$ is computable, we see that $\ov{e}$ is computable, as required.


  \item %
  $\inl{\sigma}{\tau}(v')$ or $\inr{\sigma}{\tau}(v')$ with $v'$ computable. In the first case we see that $\ov{e_1}[\ov{v'}/x]$ is computable (as $\ov{e_1}$ is computable by the induction hypothesis) and that $\myg\vdash_\epsilon \ov{e} \xrightarrow{0}  \ov{e_1}[\ov{v_1}/x]$ (for the relevant $\myg$)  and so that  $\ov{e}$ is computable, as required. The second case is similar to the first case.

    \item %
    $(\lambda^\epsilon x\type \sigma_1.\, e_1)\ov{v_2}$ with $e_1$ and $\ov{v_2}$ computable, and we  have   $\myg\vdash_\epsilon \ov{e} \xrightarrow{0}  \ov{e_1}[\ov{v_2}/x]$ for the relevant $\myg$.

  \item %
 By the induction hypothesis, $v_1$, $v_2$, and $v_3$ are computable. 
  We proceed by (natural numbers) induction on $\ov{v_1}$ to show that 
  $\ov{e} = \iter{\ov{v_1}}{\ov{v_2}}{\ov{v_3}}$ is computable.  

  If $\ov{v_1}$ is $\zero$ then, for any relevant $\myg$ we have  
  $\myg \vdash_\epsilon \iter{\ov{v_1}}{\ov{v_2}}{\ov{v_3}} \xrightarrow{0} \ov{v_2}$ and we are done as $\ov{v_2}$ is computable.
  %
    If $\ov{v_1}$ is $\mysucc{w}$ then, for any relevant $\myg$ we have  
    $\myg \vdash_\epsilon   \iter{\mysucc{w}}{\ov{v_2}}{\ov{v_3}} \xrightarrow{0} 
v_3 \iter{w}{\ov{v_2}}{\ov{v_3}}$. As $v_3$ is computable, the frame $\ov{v_3}\square$ is computable (see previous case), further, by the induction hypothesis, 
$\iter{w}{\ov{v_2}}{\ov{v_3}}$ is computable. So,  by Lemma~\ref{{Alem:easyframe}}, $\ov{v_3} \iter{w}{\ov{v_2}}{\ov{v_3}}$ is computable, and so $\iter{\mysucc{w}}{\ov{v_2}}{\ov{v_3}}$ is too, as required.






  \item %
  By the induction hypothesis, $v_1$, $v_2$, and $v_3$ are computable. 
  We proceed by (structural) induction on $\ov{v_1}$ to show that 
  $\ov{e} = \fold{\ov{v_1}}{\ov{v_2}}{\ov{v_3}}$ is computable.  



  If $\ov{v_1}$ is $\nil$ then, for any relevant $\myg$ we have  
  $\myg \vdash_\epsilon \fold{\ov{v_1}}{\ov{v_2}}{\ov{v_3}} \xrightarrow{0} \ov{v_2}$ and we are done as $\ov{v_2}$ is computable.

    If $\ov{v_1}$ is $\cons{w_1}{w_2}$ then we have  
    $\myg \vdash_\epsilon   \fold{\cons{w_1}{w_2}}{\ov{v_2}}{\ov{v_3}} \xrightarrow{0} 
\ov{v_3} (w_1,\fold{w_2}{\ov{v_2}}{\ov{v_3}})$,  for any relevant $\myg$. 
%
The frame $(w_1,\square)$ is computable and so $(w_1,\fold{w_2}{\ov{v_2}}{\ov{v_3}})$ is computable using Lemma~\ref{{Alem:easyframe}}, as, by the induction hypothesis, $\fold{w_2}{\ov{v_2}}{\ov{v_3}}$ is computable.
%
Next, as $v_3$ is computable, the frame $\ov{v_3}\square$ is computable, 
and so, again using   Lemma~\ref{{Alem:easyframe}}, we see that $\ov{v_3} (w_1,\fold{w_2}{\ov{v_2}}{\ov{v_3}})$
is computable, as  $(w_1,\fold{w_2}{\ov{v_2}}{\ov{v_3}})$ is computable.
%
  So, as  \[\myg \vdash_\epsilon   \fold{\cons{w_1}{w_2}}{\ov{v_2}}{\ov{v_3}} \xrightarrow{0} 
\ov{v_3} (w_1,\fold{w_2}{\ov{v_2}}{\ov{v_3}})\] $ \fold{\cons{w_1}{w_2}}{\ov{v_2}}{\ov{v_3}} $ is computable, as required.



  \item %
Using the induction hypothesis, we see that  $h$, and so $\ov{h}$ is computable as are $v_1$ and $v_2$, or $v'_1$, $v$, and $\ov{K}[\op(v)]$. We may then apply Lemma~\ref{Alem:handframe} to show that $\ov{e}$ is computable.



