 \item %

  Suppose that $e$ has the form $\reset{v}$, for a value $v$. This case is immediate.

  \end{enumerate}
\item %
  %
 Suppose that $\myG \vdash e\type \sigma \etype \epsilon$ has the form $F[e_1]$, with $e_1$ not a value or stuck. In this case, by the induction hypothesis, both $F[x]$ (with $x \notin \Dom(\myG)$) and $e_1$ are computable. So both
$\ov{F}[x]$ and $\ov{e_1}$ are computable. We may then apply Lemma~\ref{{Alem:easyframe}}.

\item The last case is where $\myG \vdash e\type \sigma \etype \epsilon$ has the form $S[e_1]$, with $e_1$ not a value or stuck.
There are four possibilities:
\begin{enumerate}
\item %
$S$ is $ \wph{h}{v}{\square}$. In this case, $h$ and $e_1$ are computable, by the induction hypothesis, and we may apply Lemma~\ref{Alem:handframe}.
%


\item %
In this case, $e_1$ are $\lambda^{\epsilon} x\type \sigma. \, e_2$ are computable, by the induction hypothesis, and we may apply  Lemma~\ref{Alem:ginc}.

\item %
$S$ is $\glocal{\epsilon_1}{\square}{\myg}$. In this case $e_1$
is computable by the induction hypothesis, and $\myg$ is computable (and so loss-computable) by the induction hypthesis. We can apply Lemma~\ref{Alem:glocal}.


\item %
$S$ is $\reset{\square}$. We show by $\Lsc$-induction on computable $e$ that $\reset{e}$ is computable. There are three cases:
%
\begin{enumerate}
\item If $e$ is a computable value $v$, then 
  for any $\myg_1 \in \Lsc$   we have 
$\myg_1 \vdash_\reset{v}
\xrightarrow{0}v$.

    \item If $e$ is a stuck expression of the form $K[\op(v)]$ 
    with $\op : \outt \to \inn$, $v$ computable and $\reset{K[w]}$ computable 
    for every computable $w\type \inn$, then we simply note that
    $\reset{K[op(v)]}$ is stuck.
    \item Suppose that $e$ is not stuck. Then $\reset{e}$ is not stuck.
    Further, if $\myg_1 \vdash_\epsilon \reset{e} \xrightarrow{r} e''$ for $\myg_1 \in \Lsc$, then, as $e$ is not stuck, for some $r' \in \R$ and $e'$,
    $\myg \vdash_{\epsilon_1} e \xrightarrow{r'} e'$
    and $e'' = \reset{e'}$ and, by the induction hypothesis, $e''$ is computable (and note that $r=0$ in this case).



\end{enumerate}


\end{enumerate}


