\end{enumerate}
\end{proof}
It follows at once from this fundamental lemma that all loss continuations are loss-computable.
As usual we can deduce termination from computability. 
\begin{theorem}[Termination] \label{Athm:term} 
For $e_1\type \sigma \etype  \epsilon$ and $\myg \type \sigma\to \bool\etype \epsilon'$ with $\epsilon'\subseteq \epsilon$, there are no infinite sequences:
%
\[\myg \vdash e_1 \xrightarrow{r_1} e_2 \xrightarrow{r_2} \dots \xrightarrow{r_{n-2}} e_{n-1 }\xrightarrow{r_{n-1}} e_n \dots\]
\end{theorem}
%
%
%
\begin{proof}
 By the Fundamental Lemma $\myg$ is computable and so loss-computable and so then $e$ is $\{\myg\}$-computable. An evident L-induction then shows that there is no such infinite sequence.
 %
\end{proof}

%

We then have:
\begin{theorem} \label{Athm:bterm}
For $e\type \sigma \etype  \epsilon$ and $\myg \type \sigma\to \bool\etype \epsilon'$ with $\epsilon'\subseteq \epsilon$ we have $\myg \vdash e \xRightarrow{r} w$ for a unique $r \in \R$ and terminal expression $w$ (and then $w\type \sigma\etype \epsilon$).
\end{theorem}

\section{Denotational semantics}



\label{sec:Adenotational}

%
%
%

We first repeat the material on the denotational semantics of \cname, viz the semantics of types (Section~\ref{sec:Asemtypes}), the semantics of expressions (Section~\ref{sec:Asemexp}), and the semantics of handlers (Section~\ref{sec:Ahandsem}). We then  prove  correctness and adequacy in  Section~\ref{sec:Aproofs}.

\subsection{Semantics of Types} \label{sec:Asemtypes}


%
%
%
 %

As discussed in Section~\ref{sec:semtypes}, our semantics employs a family $S_\epsilon(X) = (X \to R_\epsilon) \to W_\epsilon(X)$ of augmented selection  monads,
where 
$W_\epsilon(X) = F_\epsilon(\R \times X)$ and 
$R_\epsilon = F_\epsilon(\R)$. The $W_\epsilon$ are used to interpret  the loss operation and unhandled effect operations, viz, those of the effects in  $\epsilon$ (taking account of their multiplicity).
%
We remark that the  $W_\epsilon$ are the commutative  combination \cite{HPP06} of the 
$F_\epsilon$  and the writer monad $\R \times -$; algebraically this corresponds to having the  loss operation commute with  the operations. Finally, $R_\epsilon$ is the free $W_\epsilon$-algebra on the one-point set.
%
%
%
%

Given the $S_\epsilon$, we can define $\ssem{\sigma}$ the semantics of types, as in  Figure~\ref{fig:Atsem},
where we assume available a given semantics $\sem{b}$ of basic types.
%
\begin{figure}[H]
\small{
\[\begin{array}{lcl}
\ssem{b} & = & \sem{b}\\
 \ssem{(\sigma_1,\dots,\sigma_n)} & = &  \ssem{\sigma_1} \times \dots \times  \ssem{\sigma_n} \\
 \ssem{\sigma + \tau} & = & \ssem{\sigma} +  \ssem{\tau}\\
 \ssem{\nat} & = & \N\\
  \ssem{\mylist(\sigma)} & = &  \ssem{\sigma}^*\\
  \ssem{\sigma \to \tau\etype \epsilon} & = &   \ssem{\sigma} \to   S_\epsilon(\ssem{\tau})\\
\end{array}\] }


\caption{Semantics of types}
\label{fig:Atsem}
\end{figure}

We define  $W_\epsilon(X)$. 
%
to be the least set $Y$ such that:
%
\[Y\; = \; \left ( \sum_{\ell \in \epsilon, \op: \outt \xrightarrow{\ell} \inn, 0 < i \leq \epsilon(\ell)} 
 \ssem{\outt} \times Y^{\ssem{\inn}}  \right ) + X \]
%
There is an inclusion $F_{\epsilon_1}(X) \subseteq F_{\epsilon_2}(X)$ if $\epsilon_1 \subseteq \epsilon_2$; we will use it  without specific comment.  
%
%
Note the recursion in these definitions: $\ssem{-}$ is defined using the $S_\epsilon$, the $S_\epsilon$ using the $W_\epsilon$,  the  $W_\epsilon$ using the $F_\epsilon$, and the $F_\epsilon$ using $\ssem{-}$. However,  the well-foundedness assumption (\Cref{sec:termination}) justifies these  definitions.

\subsection{{Semantics of Expressions}} \label{sec:Asemexp}

