\begin{lemma}(Substitution)\label{lem:sublem}
Suppose that $\myG \vdash v\type \sigma$ and 
$\myG, x\type \sigma\vdash e\type \tau\etype\epsilon$.
Then
$\myG\vdash e[v/x]\type \tau\etype\epsilon$.
\end{lemma}

The following ``value semantics"  for values allows us to state our soundness and adequacy results. It follows the following scheme:
%
\[\frac{\myG\vdash v\type \sigma}{\vsem{v}\type \ssem{\myG} \to \ssem{\sigma}}\]
{\small \[\begin{array}{lcl}
\vsem{x}(\rho) &=& \rho(x)\\
\vsem{c}(\rho) &=& \sem{c}\\
\vsem{(v_1,\dots,v_n)}(\rho) &=& (\vsem{v_1}(\rho),\dots,\vsem{v_n}(\rho))\\
\vsem{\inl{\sigma}{\tau}(v)}(\rho) &=& (0,\vsem{v}(\rho))\\
\vsem{\inr{\sigma}{\tau}(v)}(\rho) &=& (1,\vsem{v}(\rho))\\
\vsem{\zero}(\rho) &=& 0\\
\vsem{\mysucc{v}}(\rho) &=& \vsem{v}(\rho) +1\\
\vsem{\nil}(\rho) &=& \varepsilon\\
\vsem{\cons{v_1}{v_2}}(\rho) &=& \vsem{v_1}(\rho)\vsem{v_2}(\rho)\\
\vsem{\lambda^{\epsilon_1} x\type \sigma_1.e}(\rho) &=& \lambda a \in \ssem{\sigma}.\, \ssem{e}(\rho[a/x])\\
\end{array}\]}


Below we may omit $\rho$ in $\ssem{e}(\rho)$ (or $\vsem{v}(\rho)$) when $e$ (respectively $v$) is closed. 

 \begin{lemma} \label{Alem:valsem} For any value $\myG \vdash v\type \sigma \etype \epsilon$ we have:
 %
 \[\ssem{v}(\rho) = \eta_{S_\epsilon}(\vsem{v}(\rho))\]
 \end{lemma}
\begin{proof}
%
The proof is by structural induction, split into cases according to the form of $v$:
\begin{enumerate}
    \item  Suppose that $e$ has the form $x$. Then we calculate:
    %
    \[\begin{array}{lcl}
       \ssem{x}(\rho)  & = & \eta_{S_\epsilon}(\rho(x))\\
         & = & \eta_{S_\epsilon}(\vsem{x}(\rho))\\
    \end{array}\]

    \item  Suppose that $e$ has the form $c$. Then we calculate:
    %
    \[\begin{array}{lcl}
       \ssem{c}(\rho)  & = & \eta_{S_\epsilon}(\sem{\con})\\
         & = & \eta_{S_\epsilon}(\vsem{c}(\rho))\\
    \end{array}\]

    \item  Suppose that $e$ has the form $(v_1,\dots,v_n)$. Then we calculate:
    %
    \[\begin{array}{lcl}
       \ssem{(v_1,\dots,v_n)}(\rho)  & = & 
 \mlet{{S_\epsilon}}{a_1 \in \ssem{b_1}}{\ssem{v_1}(\rho)}
                                                       {\\&& \dots \\&& \mlet{{S_\epsilon}}{a_n \in \ssem{b_n}}{\ssem{v_n}(\rho)}{\\&&\eta_{S_\epsilon}((a_1,\dots,a_n))}} \\
         & = & 
 \mlet{{S_\epsilon}}{a_1 \in \ssem{b_1}}{\eta_{S_\epsilon}(\vsem{v_1}(\rho))}
                                                       {\\&& \dots \\&& \mlet{{S_\epsilon}}{a_n 
                    \ssem{b_n}}{\eta_{S_\epsilon}(\vsem{v_n}(\rho))}{\\&&\eta_{S_\epsilon}((a_1,\dots,a_n))}} \\
                    & = &\eta_{S_\epsilon}( (\vsem{v_1}(\rho),\dots,\vsem{v_n}(\rho)))\\
                    & = & \eta_{S_\epsilon}(\vsem{(v_1,\dots,v_n)})
    \end{array}\]

    \item  Suppose that $e$ has the form $\inl{\sigma}{\tau}(v)$. Then we calculate:
    %
    \[\begin{array}{lcl}
       \ssem{\inl{\sigma}{\tau}(v)}(\rho)  & = & 
          S_\epsilon(\lambda a \in \ssem{\sigma}.\, (0,a))(\ssem{v}(\rho))\\
         & = & S_\epsilon(\lambda a \in \ssem{\sigma}.\, (0,a))(\eta_{S_\epsilon}(\vsem{v}(\rho)))\\
         & = &\eta_{S_\epsilon}((0,\vsem{v}(\rho))) \\
         & = & \eta_{S_\epsilon}(\vsem{\inl{\sigma}{\tau}(v)}(\rho))
    \end{array}\]
    %
    The case where $e$ has the form $\inr{\sigma}{\tau}(v)$ is similar.
    \item  Suppose that $e$ has the form $\zero$. Then we calculate:
    %
    \[\begin{array}{lcl}
       \ssem{\zero}(\rho)  & = & \eta_{S_\epsilon}(0)\\
         & = & \eta_{S_\epsilon}(\vsem{\zero}(\rho))\\
    \end{array}\]
    \item  Suppose that $e$ has the form $\mysucc{v}$. Then we calculate:
    %
    \[\begin{array}{lcl}
       \ssem{\mysucc{v}}(\rho)  & = & \mlet{{S_\epsilon}}{n \in \N}{\ssem{v}(\rho)}{\eta_{S_\epsilon}(n + 1)}\\
       & = &  \mlet{{S_\epsilon}}{n \in \N}{\eta_{S_\epsilon}(\vsem{v}(\rho))}
                   {\eta_{S_\epsilon}(n + 1)}\\
         & = & \eta_{S_\epsilon}(\vsem{v}(\rho) + 1)\\
         & = & \eta_{S_\epsilon}(\vsem{\mysucc{v}}(\rho))
    \end{array}\]

    \item  Suppose that $e$ has the form $\nil$. Then we calculate:
    %
    \[\begin{array}{lcl}
       \ssem{\nil}(\rho)  & = & \eta_{S_\epsilon}(\varepsilon)\\
         & = & \eta_{S_\epsilon}(\vsem{\nil}(\rho))\\
             \end{array}\]

    \item  Suppose that $e$ has the form $\cons{v_1}{v_2}$. Then we calculate:
    %
    \[\begin{array}{lcl}
      \ssem{\cons{v_1}{v_2}}(\rho)  & = & 
        \mlet{{S_\epsilon}}
 {a \in \ssem{\sigma_1}}{\ssem{v_1}(\rho)}
     {\\&&  \mlet{{S_\epsilon}}{l \in \ssem{\sigma_1}^*}{\ssem{v_2}(\rho)}{\\&& \eta_{S_\epsilon}(al)}}
     \\
         & = & 
\mlet{{S_\epsilon}}
 {a \in \ssem{\sigma_1}}{\eta_{S_\epsilon}(\vsem{v_1}(\rho))}
     {\\&&  \mlet{{S_\epsilon}}{l \in \ssem{\sigma_1}^*}{\eta_{S_\epsilon}(\vsem{v_2}(\rho))}{\\&& \eta_{S_\epsilon}(al)}}
     \\
     & = & \eta_{S_\epsilon}(\vsem{v_1}(\rho)\vsem{v_2}(\rho))\\
     & = & \eta_{S_\epsilon}(\vsem{\cons{v_1}{v_2}}(\rho))
    \end{array}\]

    \item  Suppose that $e$ has the form 
    $\lambda^{\epsilon_1} x\type \sigma_1.e$. Then we calculate:
    %
    \[\begin{array}{lcl}
       \ssem{\lambda^{\epsilon_1} x\type \sigma_1.e}(\rho)  
         & = & \eta_{S_\epsilon}(\lambda a \in \ssem{\sigma}.\, \ssem{e}(\rho[a/x]))\\
         & = & \eta_{S_\epsilon}(\vsem{\lambda^{\epsilon_1} x\type \sigma_1.e}(\rho))\\ 

    \end{array}\]


\end{enumerate}

\end{proof}
\begin{lemma} \label{lem:actc}
%
With the notation of the handler semantics, the following diagram commutes:
 %
 %
\[\begin{tikzcd}
	{F_{\epsilon\ell}(\R \times \ssem{\sigma})} &&& {F_{\epsilon}(\R \times \ssem{\sigma'})^{\ssem{\parr}}} \\
	\\
	\\
	{F_{\epsilon\ell}(\R \times \ssem{\sigma})} &&& {F_{\epsilon}(\R \times \ssem{\sigma'})^{\ssem{\parr}}}
	\arrow["{s^{\dagger_{F_{\epsilon\ell}}}}", from=1-1, to=1-4]
	\arrow["{r\cdot -}"', from=1-1, to=4-1]
	\arrow["{(r\cdot -)^P}", from=1-4, to=4-4]
	\arrow["{s^{\dagger_{F_{\epsilon\ell}}}}"', from=4-1, to=4-4]
\end{tikzcd}\]

\end{lemma}
\begin{proof} The map $\comp{s^{\dagger_{F_{\epsilon\ell}}}}{(r\cdot -)}$ 
is the extension of the map 
%
\[\comp{s}{(r\cdot -)}\type \R \times \ssem{\sigma} \to F_{\epsilon}(\R \times \ssem{\sigma'})^{\ssem{\parr}} \]
%
and the map $\comp{(r\cdot -)}{s^{\dagger_{F_{\epsilon\ell}}}}$
is the extension of the map 
%
\[\comp{(r\cdot -)^{\ssem{\parr}}}{s}\type \R \times \ssem{\sigma} \to F_{\epsilon}(\R \times \ssem{\sigma'})^{\ssem{\parr}} \].
We prove those two maps are equal.
We have: 
%
\[(\comp{s}{(r\cdot -)})(r',a) = s(r+r',a) = \lambda p\in \ssem{\parr}.\, (r+r')\cdot(\ssem{e_r}(\rho[(p,a)/z])\gamma)\]
%
and we have:
%
\[\begin{array}{lcl}
 (\comp{(r\cdot -)^{\ssem{\parr}}}{s})(r',a)
 & = &
 (r\cdot -)^{\ssem{\parr}}(\lambda p\in \ssem{\parr}.\, r'\cdot(\ssem{e_r}(\rho[(p,a)/z])\gamma))\\
 & = &
 \lambda p\in \ssem{\parr}.\, r\cdot (r'\cdot(\ssem{e_r}(\rho[(p,a)/z])\gamma))\\
 & = &
 \lambda p\in \ssem{\parr}.\, (r + r')\cdot(\ssem{e_r}(\rho[(p,a)/z])\gamma)\\
 \end{array}\]
%
recalling for the last equality that $F_{\epsilon}(\R \times \ssem{\sigma'})$ is an action $\epsilon$-algebra.
\end{proof}



\begin{lemma} \label{lem:smalllem}
\myskip
\begin{enumerate}
\item For any $\myG \vdash v\type \sigma$ and 
     $\myG \vdash  e\type \tau\etype \epsilon$ we have:
     %
     \[\ssem{(v,e)}(\rho) = \mlet{S_\epsilon}{b\in \ssem{\tau}}{\ssem{e}(\rho)}{\eta_{S_\epsilon}((\vsem{v}(\rho),b))}\]
\item For any $\myG \vdash v\type \sigma \to \tau\etype \epsilon$ and $\myG \vdash v\type e\type \sigma\etype \epsilon$ we have:
%
\[\ssem{v ~ e}(\rho)  = \mlet{{S_\epsilon}}
        {a \in \ssem{\sigma}}{\ssem{e}(\rho)}{\vsem{v}(\rho)(a)}\]
\end{enumerate} 
\end{lemma}
\begin{proof}%
\myskip
\begin{enumerate}
\item
We calculate:
%
\[\begin{array}{lcl}
\ssem{(v,e)}(\rho) 
 & = & 
 \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\ssem{v}(\rho)}
                                                       {\\&&  \mlet{{S_\epsilon}}{b \in \ssem{\tau}}{\ssem{e}(\rho)}{\\&&\eta_{S_\epsilon}((a,b))}} \\
 & = &
   \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\eta_{S_\epsilon}(\vsem{v}(\rho))}
                                                       {\\&&  \mlet{{S_\epsilon}}{b \in \ssem{\tau}}{\ssem{e}(\rho)}{\\&&\eta_{S_\epsilon}((a,b))}}\\
& = &

\mlet{{S_\epsilon}}
     {b \in \ssem{\tau}}
     {\ssem{e}(\rho)}
     {\\&&\eta_{S_\epsilon}((\vsem{v}(\rho),b))}


\end{array}\]
\item
We calculate:
%
\[\begin{array}{lcl}\ssem{v ~ e}(\rho) & = &
 \mlet{{S_\epsilon}}
 {\varphi \in \ssem{\sigma} \to S_\epsilon(\ssem{\sigma})}{\ssem{v}(\rho)}
     {\\&&  \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\ssem{e}(\rho)}{\varphi(a)}}\\
     & = &
     \mlet{{S_\epsilon}}
 {\varphi \in \ssem{\sigma} \to S_\epsilon(\ssem{\sigma})}{\eta_{S_\epsilon}(\vsem{v}(\rho))}
     {\\&&  \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\ssem{e}(\rho)}{\varphi(a)}}\\
     & = & \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\ssem{e}(\rho)}{\vsem{v}(\rho)(a)}
     \end{array}\]
\end{enumerate}
\end{proof}

