\begin{lemma} \label{lem:theng}
\myskip
\begin{enumerate}
    \item 
For $\myG \vdash e \type \sigma\etype \epsilon$
and $\myG \vdash \myg\type \sigma \to \real\etype \epsilon_1$ 
with $\epsilon_1 \subseteq \epsilon$ we have:
%
\[\ssem{\then{}{e}{\myg}}(\rho)\gamma_1 = \delta_\epsilon(\ER{\epsilon}{\ssem{e}(\rho)}{\lsem{\myg}(\rho)})\]
\item For $\myG \vdash \myg\type \sigma \to \real\etype \epsilon$
we have 
%
\[\comp{\delta_\epsilon}{\lsem{\myg}(\rho)} = \lambda a \in \ssem{\sigma}.\,\vsem{\myg}(\rho) a \gamma_1\]
\item
For $\myG,x\type\sigma \vdash e\type\tau\etype\epsilon$ and $\myG,x\type\sigma \vdash \myg\type \tau \to \real\etype\epsilon_1$ with $\epsilon_1 \subseteq \epsilon$ we have:
%
\[\lsem{\lambda^\epsilon x\type \sigma.\,\then{\epsilon}{e}{\myg}}(\rho) = 
\lambda a \in \ssem{\sigma}.\, \ER{\epsilon}{\ssem{e}(\rho[a/x])}{\lsem{\myg}(\rho[a/x])}
 \]
\end{enumerate}

%
\end{lemma}
\begin{proof}

We prove the first two parts by a mutual induction.

For the first part we calculate:
%
\[\begin{array}{lcll}
     \ssem{\then{}{e}{\myg}}(\rho)\gamma_1
     & = &
\mlet{F_\epsilon}{r_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho)(\lsem{\myg}(\rho))}
{\\&&\;\quad \mlet{F_\epsilon}
                {r_2,r_3\in \R}
                {\vsem{\myg}(\rho)a(\lambda r \in \R.\,0)}
                {(r_2,r_1 + r_3})} \\     
& = &
\mlet{F_\epsilon}{r_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho)(\lsem{\myg}(\rho))}
{\\&&\;\quad \mlet{F_\epsilon}
                {r_2,r_3\in \R}
                {\delta_\epsilon(\lsem{\myg}(\rho)a)}
                {(r_2,r_1 + r_3})} & (\mbox{using the induction hypothesis})\\
& = &
\mlet{F_\epsilon}{r_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho)(\lsem{\myg}(\rho))}
{\\&&\;\quad \mlet{F_\epsilon}
                {r_2,r_3\in \R}
                {\delta_\epsilon(\lsem{\myg}(\rho)a)}
                {(0,r_1 + r_3})}\\
& = &
\mlet{F_\epsilon}{r_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho)(\lsem{\myg}(\rho))}
{\\&&\;\quad \mlet{F_\epsilon}
                {r_3\in \R}
                {\lsem{\myg}(\rho)a}
                {(0,r_1 + r_3})} \\
                & = &
\delta_\epsilon(\mlet{F_\epsilon}{r_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho)(\lsem{\myg}(\rho))}
{\\&&\;\quad \mlet{F_\epsilon}
                {r_3\in \R}
                {\lsem{\myg}(\rho)a}
                {r_1 + r_3}}) \\
& = &
\delta_\epsilon(\ER{\epsilon}{\ssem{e}(\rho)}{\lsem{\myg}(\rho)})
                \end{array}\]
%
For the second part, the case where $\myg = \lambda^{\epsilon} x\in \sigma.\, 0$ is evident. For the case where $\myg$ has the form $\lambda^{\epsilon} x \in \sigma.\then{}{e}{\myg_1}$, we calculate:
%
\[\begin{array}{lcl}
    \delta_\epsilon(\lsem{\myg}(\rho)a)
     & = & 
    \delta_\epsilon(\mlet{F_\epsilon}{r_1,r_2\in \R}{\vsem{\myg}(\rho)a (\lambda r \in \R.\,0)}{r_2}) \\
    & = & 
    \mlet{F_\epsilon}{r_1,r_2\in \R}{\vsem{\myg}(\rho)a (\lambda r \in \R.\,0)}{(0,r_2)} \\
    & = & 
    \mlet{F_\epsilon}{r_1,r_2\in \R}{\ssem{\then{}{e}{\myg_1}}(\rho[a/x])(\lambda r \in \R.\,0)}{(0,r_2)} \\
    & = & 
    \mlet{F_\epsilon}{r_1,r_2\in \R}{\delta_\epsilon(\ER{\epsilon}{\ssem{e}(\rho[a/x])}{\lsem{\myg}(\rho[a/x])})}{(0,r_2)} \\\\
    & = & 
    \mlet{F_\epsilon}
          {r_1,r_2\in \R}
          {\\&&\quad (\delta_\epsilon(
                \mlet{F_\epsilon}{r'_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho[a/x])(\lsem{\myg_1}(\rho[a/x]))}
{\\&&\;\quad \mlet{F_\epsilon}
                {r'_3\in \R}
                {\lsem{\myg_1}(\rho[a/x])a}
                {r'_1 + r'_3}}) )\\ &&\!\!}
          { (0,r_2)} \\\\
& = & 
    \mlet{F_\epsilon}
          {r_1,r_2\in \R}
          {\\&&\quad (
                \mlet{F_\epsilon}{r'_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho[a/x])(\lsem{\myg_1}(\rho[a/x]))}
{\\&&\;\quad \mlet{F_\epsilon}
                {r'_3\in \R}
                {\lsem{\myg_1}(\rho[a/x])a}
                {(0,r'_1 + r'_3)}} )\\ &&\!\!}
          { (0,r_2)} \\\\
&= &
\mlet{F_\epsilon}{r'_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho[a/x])(\lsem{\myg_1}(\rho[a/x]))}
{\\&&\;\quad \mlet{F_\epsilon}
                {r'_3\in \R}
                {\lsem{\myg_1}(\rho[a/x])a}
                {\\&&\quad\quad \mlet{F_\epsilon}{r_1,r_2\in \R}{(0,r'_1 + r'_3)}{(0,r_2)}}} \\\\
%
&= &
\mlet{F_\epsilon}{r'_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho[a/x])(\lsem{\myg_1}(\rho[a/x]))}
\\&&\;\quad \mlet{F_\epsilon}
                {r'_3\in \R}
                {\lsem{\myg_1}(\rho[a/x])a}
                {(0,r'_1 + r'_3)} \\
%
%
%
%
%
%
%

%
&= &
\mlet{F_\epsilon}{r'_1 \in \R, a \in \ssem{\sigma}}{\ssem{e}(\rho[a/x])(\lsem{\myg_1}(\rho[a/x]))}
\\&&\;\quad \mlet{F_\epsilon}
                {r'_2,r'_3\in \R}
                {\vsem{\myg_1}(\rho[a/x])a (\lambda r\in \R.\, 0))}
                {(r'_2,r'_1 + r'_3)}\\ && \qquad(\mbox{using the induction hypothesis})\\
& = &
\ssem{\then{}{e}{\myg_1}}(\rho[a/x])\gamma_1\\
&=&
\ssem{\myg}(\rho)a\gamma_1\\
\end{array}\]



The third part follows from the first two:
%
\[\begin{array}{lcl}
   \comp{\delta_\epsilon}{ \lsem{\lambda^\epsilon x\type \sigma.\,\then{\epsilon}{e}{\myg}}(\rho)} 
     &= & 
     \lambda a \in \ssem{\sigma}.\,\vsem{\lambda^\epsilon x\type \sigma.\,\then{\epsilon}{e}{\myg}}(\rho) a \gamma_1\\
     & = &
     \lambda a \in \ssem{\sigma}.\,\ssem{\then{\epsilon}{e}{\myg}}(\rho[a/x])  \gamma_1\\
     & = &
     \lambda a \in \ssem{\sigma}.\,\delta_\epsilon(\ER{\epsilon}{\ssem{e}(\rho[a/x])}{\lsem{\myg}(\rho[a/x])})\\
     & = &
     \comp{\delta_\epsilon}{\lambda a \in \ssem{\sigma}.\,\ER{\epsilon}{\ssem{e}(\rho[a/x])}{\lsem{\myg}(\rho[a/x])}}\\
\end{array}\]
%
and we can cancel the $\delta_\epsilon$'s.
\end{proof}

