\begin{lemma} \label{lem:Fsem} For $e\type \sigma\etype\epsilon$ and $F[e]\type \tau\etype\epsilon$ we have:
 %
 \[\ssem{F[e]}(\rho) = \mlet{S_\epsilon}{a \in \ssem{\sigma}}{\ssem{e}(\rho)}{\ssem{F[x]}(\rho[x/a])}\]
 \end{lemma}
 \begin{proof}
 The proof is by cases on the form of $F$. We consider 
 some illustrative examples.

 \begin{enumerate}
     \item For $F = f(\square)$ with $f\type \sigma \to \tau $ 
     we have
    %
     \[\begin{array}{lcl} \ssem{f(x)}(\rho)
     & = & 
     \mlet{{S_\epsilon}}{b \in \ssem{\sigma}}{\ssem{x}(\rho[a/x])}
     {\eta_{S_\epsilon}(\sem{f}(b))}\\
     & = &
     \mlet{{S_\epsilon}}{b \in \ssem{\sigma}}{a}
     {\eta_{S_\epsilon}(\sem{f}(b))}\\
     & = & 
     {\eta_{S_\epsilon}(\sem{f}(a))}
     \end{array}\]
     %
     and so:
     %
     \[\begin{array}{lcl}
     \ssem{f(e)} (\rho)
        & = & \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\ssem{e}(\rho)}
     {\eta_{S_\epsilon}(\sem{f}(a))}\\
        & = & \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\ssem{e}(\rho)}
     {\ssem{f(x)}(\rho[a/x]x)}
     \end{array}\]

    as required
     \item For $F = (v_1,\dots, v_k, \square, e_{k+2},\dots, e_n)$ we calculate:
      \[\begin{array}{lcl}
    \ssem{(v_1,\dots, v_k, e, e_{k+2},\dots, e_n)}(\rho) & = & 
    \mlet{{S_\epsilon}}{a_1 \in \ssem{\sigma_1}}{\ssem{v_1}(\rho)}
     {\\&& \dots \\&& \mlet{{S_\epsilon}}{a_k\in \ssem{\sigma_k}}{\ssem{v_k}(\rho)}
     {\\&& \mlet{S_\epsilon}{a_{k+1}\in \ssem{\sigma_{k+1}}}{\ssem{e}(\rho)}
     {\\&&\mlet{{S_\epsilon}}{a_{k+2} \in \ssem{\sigma_{k+2}}}{\ssem{e_{k+2}}(\rho)}
     {\\&& \dots 
      \\&& \mlet{{S_\epsilon}}{a_n \in \ssem{\sigma_n}}{\ssem{e_n}(\rho)}
      {\\&&\eta_{S_\epsilon}((a_1,\dots,a_n))}}}}}\\

     &=&
     \mlet{S_\epsilon}{a_{k+1}\in \ssem{\sigma_{k+1}}}{\ssem{e}(\rho)}
     {\\&&\mlet{{S_\epsilon}}{a_{k+2} \in \ssem{\sigma_{k+2}}}{\ssem{e_{k+2}}(\rho)}
     {\\&& \dots 
      \\&& \mlet{{S_\epsilon}}{a_n \in \ssem{\sigma_n}}{\ssem{e_n}(\rho)}
      {\\&&\eta_{S_\epsilon}((\vsem{v_1},\dots,\vsem{v_k},a_{k+1},\dots, a_n))}}}\\
     & = &
     \mlet{S_\epsilon}{a_{k+1} \in \ssem{\sigma_{k+1}}}{\ssem{e}(\rho)}
     {\ssem{(v_1,\dots, v_k, x, e_{k+2},\dots, e_n)}(\rho[a_{k+1}/x])}\\
     \end{array}\]


     \item 

     For $F = \square.i$ we calculate:
     \[\begin{array}{lcl}

     \ssem{e.i}(\rho)  
       & = & 
        S_\epsilon(\pi_i)(\ssem{e}(\rho))\\ 
        & = &
        \mlet{S_\epsilon}{a\in (\sigma_1,\dots,\sigma_n)}{\ssem{e}(\rho)}{\pi_i(a)}\\
        & = &
        \mlet{S_\epsilon}{a\in (\sigma_1,\dots,\sigma_n)}{\ssem{e}(\rho)}{\ssem{\pi_i(x)}(\rho[a/x])}
     \end{array}\]

 \end{enumerate}
%
%
%
%
%
%
%
%
%
 \end{proof}

 \begin{lemma} \label{lem:Fsemg} For an expression $F[e]\type \tau$, 
 where $e\type \sigma$, and a loss continuation 
 $\myg\type \tau \to \real\etype\epsilon$ we have:
 %
 %
 %
 %
 \[\begin{array}{lcl}\ssem{F[e]}\lsem{\myg} 
  & = &
 \mlet{W_\epsilon}{a \in \ssem{\sigma}\\&&\quad}
      {\ssem{e}\lsem{\lambda^\epsilon x\type \sigma.\,\then{\epsilon}{F[x]}{\myg}}\\&&\quad}
