For our soundness theorem we assume that the semantics of basic functions is sound w.r.t.\, the operational semantics, i.e.
$f(v) \rightarrow v' \implies \sem{f}(\sem{v}) = \sem{v'}$. 
%
The main result we need is that the small step operational semantics is sound:

%

\begin{theorem}[Small-step Soundness] \label{Athm:smallsound} Suppose we have an expression $e\type \sigma\etype \epsilon$ and a loss continuation $\myg \type \sigma \to \real\etype \epsilon_1$ with $\epsilon_1 \subseteq \epsilon$. Then:
%
\[\myg \vdash_\epsilon e \xrightarrow{r} e' \;\; \implies \;\; 
    \ssem{e}\lsem{\myg} = r\cdot(\ssem{e'}\lsem{\myg})\]
\end{theorem}
\begin{proof} we split into cases according to the various possible transitions.
We use  Lemma~\ref{Alem:valsem} without comment.
\begin{enumerate}
    \item  %
    Suppose the transition is 
    \[f(v) \evalto{0}  v'\] 
    for $f\type \sigma \to \tau$, where $f(v) \to v'$.
    Then we calculate:
    %
    \[\begin {array}{lcll}
    \ssem{f(v)}
        & = & 
       \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\ssem{v}}
     {\eta_{S_\epsilon}(\sem{f}(a))} \\
       & = &
       \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\eta_{S_\epsilon}(\vsem{v})}
     {\eta_{S_\epsilon}(\sem{f}(a))} & (\mbox{by Lemma~\ref{Alem:valsem}})\\
      & = & \eta_{S_\epsilon}(\sem{f}(\vsem{v}))\\
      & = & \eta_{S_\epsilon}(\vsem{v'})

    \end{array}\]
    %
    and this  gives the required result as it is equivalent to
    %
    \[\ssem{f(v)}\gamma = 0\cdot \ssem{v'}\gamma\]
    %
    for all relevant $\gamma$.
    %
    \item  %
    \[\myg \vdash_\epsilon  (v_1,\dots,v_n).i  \evalto{0}  v_i \] 
    %

    %
    %
    %
    %
    %
    %
    %
    %
    %
    Then we calculate:

    \[\begin {array}{lcll}
    \ssem{(v_1,\dots,v_n).i} & = & S_\epsilon(\pi_i)(\ssem{(v_1,\dots,v_n)})\\
                             & = & S_\epsilon(\pi_i)(\eta_{S_\epsilon}((\vsem{v_n},\dots,\vsem{v_n})))& \mbox{(by Lemma~\ref{Alem:valsem})}\\
                             & = & \eta_{S_\epsilon}(\vsem{v_1})\\
                             & = & \ssem{v_i}
    \end{array}\]
    %
    and this  gives the required result as it is equivalent to
    %
    \[\ssem{(v_1,\dots,v_n).i}\gamma = 0\cdot \ssem{v_i}\gamma\]
    %
    for all relevant $\gamma$.
    %
    \item %
    %
    \[\myg \vdash_\epsilon   \mycases{\inl{\sigma_1}{\sigma_2}(v)}{x_1\type \sigma_1}{e_1}{x_2\type \sigma_2}{e_2}  \evalto{0}  e_1[v/x_1]\]
    %

    Again using Lemma~\ref{Alem:valsem}, we calculate:
    %
    \[\begin{array}{lcll}
        \ssem{ \mycases{\inl{\sigma_1}{\sigma_2}(v)}{x_1\type \sigma_1}{e_1}{x_2\type \sigma_2}{e_2}} 
        & = &
        \mlet{S_\epsilon}{a \in \ssem{\sigma_1} + \ssem{\sigma_2}}{\ssem{\inl{\sigma_1}{\sigma_2}(v)}}{\\&&\;[\lambda b_1 \in \ssem{\sigma_1}.\, \ssem{e_1}(x_1 \mapsto b_1),
\\&&\;\;\,\lambda b_2 \in \ssem{\sigma_2}.\, \ssem{e_2}(x_2 \mapsto b_2)](a)}\\
         & = &
    \mlet{S_\epsilon}{a \in \ssem{\sigma_1} + \ssem{\sigma_2}}{\eta_{S_\epsilon}((0,\vsem{v}))}{\\&&\;[\lambda b_1 \in \ssem{\sigma_1}.\, \ssem{e_1}(x_1 \mapsto b_1),
\\&&\;\;\,\lambda b_2 \in \ssem{\sigma_2}.\, \ssem{e_2}(x_2 \mapsto b_2)](a)}\\             & = &
  [\lambda b_1 \in \ssem{\sigma_1}.\, \ssem{e_1}(x_1 \mapsto b_1),
\\&&\;\;\,\lambda b_2 \in \ssem{\sigma_2}.\, \ssem{e_2}(x_2 \mapsto b_2)]((0,\vsem{v}))\\
     & = &
  \ssem{e_1}(x_1 \mapsto \vsem{v})\\
    & = & \ssem{e_1[v_1/x_1]}\qquad (\mbox{by Lemma~\ref{lem:sublem}})
\end{array}\]
%
The case $\inr{\sigma_1}{\sigma_2}(v)$ is similar.
    \item %
    %
    \[ \myg \vdash_\epsilon   \iter{0}{v_2}{v_3}  \evalto{0}  v_2\]

%
We have 
%
\[\begin{array}{lcl}
   \ssem{\iter{0}{v_2}{v_3}}  & = & 
       \mlet{{S_\epsilon}}{n \in \N}{\ssem{0}}
     {\\&&  \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\ssem{v_2}}{\\&&\mlet{S_\epsilon}{\varphi \in \ssem{\sigma} \to S_\epsilon(\ssem{\sigma})}{\ssem{v_3}}
     {\\&& (\varphi^{\dagger_{S_\epsilon}})^n(\eta_{S_\epsilon}(a))}}}\\
     & = &
      \mlet{{S_\epsilon}}{n \in \N}{\eta_{S_\epsilon}(\vsem{0})}
     {\\&&  \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\eta_{S_\epsilon}(\vsem{v_2})}{\\&&\mlet{S_\epsilon}{\varphi \in \ssem{\sigma} \to S_\epsilon(\ssem{\sigma})}{\eta_{S_\epsilon}(\vsem{v_3})}
     {\\&& (\varphi^{\dagger_{S_\epsilon}})^n(\eta_{S_\epsilon}(a))}}}\\
& = & (\vsem{v_3}^{\dagger_{S_\epsilon}})^0(\eta_{S_\epsilon}(\vsem{v_2}))
     \\
& = &         \eta_{S_\epsilon}(\vsem{v_2})\\
& = &         \ssem{v_2}
\end{array}\]

    \item %
    %
    \[ \myg \vdash_\epsilon   \iter{\mysucc{v_1}}{v_2}{v_3}  \evalto{0} 
v_3 \iter{v_1}{v_2}{v_3}\]

   We calculate:
%
\[\begin{array}{lcll}
   \ssem{\iter{\mysucc{v_1}}{v_2}{v_3}}  & = & 
       \mlet{{S_\epsilon}}{n \in \N}{\ssem{\mysucc{v_1}}}
     {\\&&  \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\ssem{v_2}}{\\&&\mlet{S_\epsilon}{\varphi \in \ssem{\sigma} \to S_\epsilon(\ssem{\sigma})}{\ssem{v_3}}
     {\\&& (\varphi^{\dagger_{S_\epsilon}})^n(\eta_{S_\epsilon}(a))}}}\\
     & = &
      \mlet{{S_\epsilon}}{n \in \N}{\eta_{S_\epsilon}(\vsem{v_1} + 1)}
     {\\&&  \mlet{{S_\epsilon}}{a \in \ssem{\sigma}}{\eta_{S_\epsilon}(\vsem{v_2})}{\\&&\mlet{S_\epsilon}{\varphi \in \ssem{\sigma} \to S_\epsilon(\ssem{\sigma})}{\eta_{S_\epsilon}(\vsem{v_3})}
     {\\&& (\varphi^{\dagger_{S_\epsilon}})^n(\eta_{S_\epsilon}(a))}}}\\
& = & (\vsem{v_3}^{\dagger_{S_\epsilon}})^{\vsem{v_1} + 1}(\eta_{S_\epsilon}(\vsem{v_2}))
     \\
& = &     \vsem{v_3}^{\dagger_{S_\epsilon}}(\ssem{\iter{v_1}{v_2}{v_3}})   \\
& = &         \ssem{v_3~\iter{v_1}{v_2}{v_3}} & (\mbox{by Lemma~\ref{lem:smalllem}})
\end{array}\]

    \item %
    %
    \[\myg \vdash_\epsilon  \fold{\nil_{\sigma_1}}{v_2}{v_3}    \evalto{0}    v_2\]

