\[\ssem{e_1}\lsem{\myg_1} = r_0\cdot\ssem{e'_1}\lsem{\myg_1}\]
%
Suppose that:
%
\[\myg_1 = \lambda^{\epsilon_1} x\type \sigma_1. \, e_2\]
%
with $\epsilon_1 \subseteq \epsilon$.



                We then have:
 \[\begin{array}{lcl}
      \ssem{\then{\epsilon_1}{e_1}
  {\lambda^\epsilon x\type \sigma_1.\, e_2}}\gamma 
&=&\mlet{F_\epsilon}{r_1 \in \R, a \in \ssem{\sigma_1}}{\ssem{e_1}(\lsem{\lambda^\epsilon x\type \sigma_1.\, e_2})}
{\\&&\;\quad \mlet{F_\epsilon}
                {r_2,r_3\in \R}
                {\ssem{e_2}(x \mapsto a)(\lambda r \in \R.\,0)}
                {(r_2,r_1 + r_3})}
\end{array}\]



\[\begin{array}{lcl}
\ssem{\then{\epsilon_1}{e_1}
        {\lambda^{\epsilon_1} x\type \sigma_1. \, e_2}} 
        \lsem{\myg}
&=& 
\mlet{F_\epsilon}{r_1 \in \R, a \in \ssem{\sigma_1}}{\ssem{e_1}(\lsem{\myg_1})}
{\\&&\;\quad \mlet{F_\epsilon}
                {r_2, r_3\in \R}
                {\ssem{e_2}(x \mapsto a)(\lambda r \in \R.\,0)}
                {(r_2,r_1 + r_3})}\\

&=& 
\mlet{F_\epsilon}{r_1 \in \R, a \in \ssem{\sigma_1}}{r_0\cdot \ssem{e'_1}(\lsem{\myg_1})}
{\\&&\;\quad \mlet{F_\epsilon}
                {r_2,r_3\in \R}
                {\ssem{e_2}(x \mapsto a)(\lambda r \in \R.\,0)}
                {(r_2, r_1 + r_3})}\\
&=& 
\mlet{F_\epsilon}{r_1 \in \R, a \in \ssem{\sigma_1}}{\ssem{e'_1}(\lsem{\myg_1})}
{\\&&\;\quad \mlet{F_\epsilon}
                {r_2,r_3\in \R}
                {\ssem{e_2}(x \mapsto a)(\lambda r \in \R.\,0)}
                {(r_2,r_0 + r_1 + r_3})}\\
&=&         
\ssem{r_0 + (\then{\epsilon_1}{e_1}
        {\lambda^{\epsilon_1} x\type \sigma_1. \, e_2})} 
        \lsem{\myg}
\end{array}\]



