\item Suppose the transition is generated using the rule

\[\inferrule{\myg \vdash_\epsilon e_1 \evalto{r} e'_1}
         {\myg \vdash_\epsilon  \reset{e_1} \evalto{\; 0 \;} \reset{e'_1}}\] 

By the induction hypothesis we have:
%
\[\ssem{e_1}\lsem{\myg} = r\cdot \ssem{e'_1}\lsem{\myg}\]
%
So then:
%
\[\begin{array}{lcl}
\ssem{\reset{e_1}}\lsem{\myg}
 &=& \mlet{F_\epsilon}
            {r_1 \in \R, a \in \ssem{\sigma}}
            {\ssem{e_1}\lsem{\myg}}
            {(0,a)}\\
&=& \mlet{F_\epsilon}
            {r_1 \in \R, a \in \ssem{\sigma}}
            {r\cdot\ssem{e'_1}\lsem{\myg}}
            {(0,a)}\\
&=& \mlet{F_\epsilon}
            {r_1 \in \R, a \in \ssem{\sigma}}
            {\ssem{e'_1}\lsem{\myg}}
            {(0,a)}\\
& = & \ssem{\reset{e'_1}}\lsem{\myg}\\
& = & 0\cdot\ssem{\reset{e'_1}}\lsem{\myg}\\ 
\end{array}\]

\end{enumerate}





\end{proof}

Soundness for the big-step operational semantics  then follows:
%
\begin{theorem} [Evaluation Soundness] \label{Athm:sound}
For all expressions $e\type \sigma\etype \epsilon$ and loss continuations $\myg \type \sigma \to \real\etype \epsilon'$ with $\epsilon' \subseteq \epsilon$ we have:
%
\[\myg \vdash_\epsilon e \xRightarrow{r} v \;\; \implies \;\; 
\ssem{e}\lsem{\myg} = (r,\vsem{v}) \]
%
and
%
\[\begin{array}{l}
\myg \vdash_\epsilon e \xRightarrow{r} K[\op(v)] \;\; \implies \\\\ 
\hspace{30pt} \ssem{e}\lsem{\myg} = \varphi^{\R \times \ssem{\sigma}}_{\ell,\op,\epsilon(\ell)}
 (\vsem{v},\lambda a \in \ssem{\inn}.\,
   r\cdot  \ssem{K[x]}(x \mapsto a)\lsem{\myg}
     \end{array}\]
     \end{theorem}
\begin{proof}
Both statements are proved by induction on the proof of the evaluation relation. For the first one, in the base case we have $e = v$ and $r=0$ and, using Lemma~\ref{Alem:valsem} we have:
%
\[\ssem{e}\lsem{\myg} = \ssem{v}\lsem{\myg} = (0,\vsem{v}) \]
%
In the other case we have $\myg \vdash_\epsilon e \xrightarrow{r_1} e'$ and 
$\myg \vdash_\epsilon e' \xRightarrow{r_2} v$ and $r = r_1 + r_2$. So using Theorem~\ref{Athm:smallsound} we obtain:
%
\[\ssem{e}\lsem{\myg} = r_1\cdot (\ssem{e'}\lsem{\myg}) = r_1 \cdot (r_2,\vsem{v}) = (r,\vsem{v})\]


For the second one, in the base case we have $e = K[\op(v)]$ and $r=0$ and, using Lemma~\ref{Alem:Kop} we have:
%
\[\ssem{e}\lsem{\myg} = \ssem{K[\op(v)]}\lsem{\myg} =  
 \varphi^{\R \times \ssem{\sigma}}_{\ell,\op,\epsilon(\ell)}
 (\vsem{v},\lambda a \in \ssem{\inn}.\,
     \ssem{K[x]}(x \mapsto a)\lsem{\myg})\]
%
In the other case we have $\myg \vdash_\epsilon e \xrightarrow{r_1} e'$ and 
$\myg \vdash_\epsilon e' \xRightarrow{r_2} v$ and $r = r_1 + r_2$. So we obtain:
%
\[\begin{array}{lcl}
\ssem{e}\lsem{\myg} 
& = &
r_1\cdot (\ssem{e'}\lsem{\myg})\\
& = &
r_1\cdot (\varphi^{\R \times \ssem{\sigma}}_{\ell,\op,\epsilon(\ell)}
 (\vsem{v},\lambda a \in \ssem{\inn}.\,
     r_2\cdot\ssem{K[x]}(x \mapsto a)\lsem{\myg}))\\
& = &
(\varphi^{\R \times \ssem{\sigma}}_{\ell,\op,\epsilon(\ell)}
  \vsem{v},\lambda a \in \ssem{\inn}.\,
     r\cdot\ssem{K[x]}(x \mapsto a)\lsem{\myg})
\end{array}
\]

\end{proof}

\begin{theorem}[Adequacy] \label{Athm:adequate} For all expressions
$e\type \sigma\etype \epsilon$ and loss continuations $\myg \type \sigma \to \real\etype \epsilon'$ with $\epsilon' \subseteq \epsilon$ we have:
%
\[\ssem{e}\lsem{\myg} = (r,a) \implies 
    \exists v.\,  \myg \vdash_\epsilon e \xRightarrow{r} v \wedge \vsem{v} = a\]
%
and
%
\[\begin{array}{l}
\ssem{e}\lsem{\myg} = \varphi^{\R \times \ssem{\sigma}}_{\ell,\op,\epsilon(\ell)} (a,f)\;\; \implies \;\;   \exists K[\op(v)].\,  \myg \vdash_\epsilon e \xRightarrow{r} K[\op(v)]\; \wedge \\\\
\hspace{20pt} a = \vsem{v} 
 \;\wedge \; f = \lambda b \in \ssem{\inn}.\,
    r\cdot \ssem{K[x]}(x \mapsto b)\lsem{\myg}
 \end{array}\]
 %
    %
%
%
%
%
%
%
\end{theorem}
\begin{proof}
\myskip
%
%
%
%
%
%
%
%
%
%

Suppose that $\ssem{e}\lsem{\myg} = (r,a)$. By the termination theorem, Theorem~\ref{Athm:term}, either there are $r'$ and $v$ such that
$\myg \vdash_\epsilon e \xRightarrow{r'} v$ or else there are $r'$ and $K[\op(v)]$ such that
$\myg \vdash_\epsilon e \xRightarrow{r'} K[\op(v)]$. 
Using the second part of Theorem~\ref{Athm:sound} we see that the latter cannot happen, as then $\ssem{e}\lsem{\myg}$ would not ahve the form $(r,a)$.
So there are $r'$ and $v$ such that
$\myg \vdash_\epsilon e \xRightarrow{r'} v$.
Then, by evaluation soundness, we have $\ssem{e}\lsem{\myg} = (r',\vsem{v})$. So $(r,\vsem{v}) = (r',a)$ and the conclusion follows.

The second case is proved similarly.
%
\end{proof}

For the following corollary we assume the interpretation of constants is 1-1, I.e. that $\sem{c} = \sem{c'}$ implies $c = c'$. 
\begin{corollary}[First-order adequacy] 
Suppose we have a first-order type $\sigma$, an expression $e\type \sigma\etype \emptyset$, and a loss continuation $\myg \type \sigma \to \real\etype \emptyset$. Then for any $v\type \sigma$ we have:
\[\ssem{e}\lsem{\myg} = (r,\vsem{v}) \iff
    \myg \vdash_\epsilon e \xRightarrow{r} v\]
\end{corollary}
\begin{proof} This follows from the adequacy theorem, together with the fact that as the interpretation of constants is 1-1 so is that of first-order values, i.e., if $\vsem{v} = \vsem{v'}$, for $v,v'\type \sigma$ then $v = v'$.
\end{proof}

 %
 %
 %
 %
%
%
%
%
%
%
%
%
%

Turning to giant step operational semantics, fix $\sigma$ and $\epsilon$. Define the set $\EV$ of effect values by:
\[\EV\; = \; 
\left ( \sum_{\ell \in \epsilon, \op: \outt \xrightarrow{\ell} \inn} 
  V_\outt \times \EV^{V_\inn}  \right ) \,+ \,R \times V_\sigma \]
%
%
%
%
%
where $V_\tau = \{v|v\type\tau\}$.
%
Next, fix $\myg\type \sigma \to \loss\etype \epsilon'$ (with $\epsilon'\subseteq\epsilon$)
and define a partial function 
$\mathrm{Eval}: \mathrm{E} \rightharpoonup \EV$ on expressions $e\type\sigma\etype \epsilon$ by:
%
{\small \[\mathrm{Eval}(e) = 
   \left \{
   \begin{array}{ll}
      (r,v)  & (\myg \vdash_\epsilon e \xRightarrow{r} v) \\
       ((\ell,\op),(v, \lambda w \in \V_{\inn}.\, r\cdot\mathrm{Eval}(K[w])) & 
        (\myg \vdash_\epsilon e \xRightarrow{r} K[\op(v)], \op: \outt \xrightarrow{\ell} \inn)
   \end{array}
   \right .\]}
%
using the evident $R$-action on $\EV$.
Using $\{\myg\}$-induction, one sees that $\mathrm{Eval}$ is  total.
Next, inductively define a relation $\mysim$ between $\EV$ and $W_\epsilon(\ssem{\sigma})$ by:
\[(r,v) \mysim (s,a) \iff r = s \;\wedge\; \vsem{v} = a\]
and:
\[((\ell,\op),(v,f)) \mysim ((\ell',\op',n'),(a,g))
\iff \ell = \ell' \,\wedge\, \op = \op' \,\wedge\, n' = \epsilon(\ell)\,
\wedge \, \vsem{v} = a \,\wedge \, \forall w \in V_\inn. f(w) \mysim g(\ssem{w}) 
\]
%
Notice that in case all the $\inn$ and $\outt$ such that $\op\type \outt \xrightarrow{\ell} \inn$ for some $\ell \in \epsilon$ are first-order, and the semantics of constants is the identity, this relation is a bijection. 

\begin{theorem} \label{Athm:giant} For all $e\type \sigma\etype \epsilon$ we have: $\mathrm{Eval}(e) \mysim \ssem{e}\lsem{\myg}$.
\end{theorem}
\begin{proof}
We proceed by well-founded-tree induction on  $\mathrm{Eval(e)}$.
By Theorem~\ref{Athm:bterm} there are two cases:
%
\begin{enumerate}
\item Here $\myg \vdash_\epsilon e  \xRightarrow{r} v$. 
We have $\mathrm{Eval}(e) = (r,v)$ 
and, by Theorem~\ref{Athm:sound},  $\ssem{e}\lsem{\myg} = (r,\vsem{v})$.
\item Here $\myg \vdash_\epsilon e \xRightarrow{r} K[\op(v)]$.
We have 
%
\[\mathrm{Eval}(e) = ((\ell,\op),(v, \lambda w \in \V_{\inn}.\, r\cdot\mathrm{Eval}(K[w]))\]
%
and, by Theorem~\ref{Athm:sound} again, we have:
%
\[\begin{array}{lcl}
\ssem{e}\lsem{\myg} & = & \varphi^{\R \times \ssem{\sigma}}_{\ell,\op,\epsilon(\ell)}
 (\vsem{v},\lambda a \in \ssem{\inn}.\,
   r\cdot  \ssem{K[x]}(x \mapsto a)\lsem{\myg}\\
   & = & ((\ell,\op,\epsilon(\ell)),
 (\vsem{v},\lambda a \in \ssem{\inn}.\,
   r\cdot  \ssem{K[x]}(x \mapsto a)\lsem{\myg}))
     \end{array}\]
and the conclusion follows, since, using the induction hypothesis, 
when $a = \vsem{w}$ for $w\type\inn$ we have:
%
\[\mathrm{Eval}(K[w]) \mysim \ssem{K[w]}\lsem{\myg} = \ssem{K[x]}(x \mapsto \vsem{w})\lsem{\myg} 
= \ssem{K[x]}(x \mapsto a)\lsem{\myg}\]
%

\end{enumerate}
\end{proof}

