\subsection{The algorithm for Hamiltonicity parameterized by pathwidth~\cite{CyganKN2018}.}\label{subsec:revckn}
We paraphrase the algorithm from~\cite{CyganKN2018}. That algorithm uses a standard technique that assigns a random weight $\omega(e) \in \{1,\ldots,\omega_{\max}\}$ with $\omega_{\max}=n^2$ to every edge of the input graph and computes the parity of the number of Hamiltonian cycles $C$ with weight $\omega(C):=\sum_{e \in C}\omega(e)=w$ for every $w \in \{0,\ldots,n \cdot \omega_{\max} \}$. By the Isolation Lemma~\cite{MulmuleyVV87}, one of these parities is odd with constant probability if a Hamiltonian cycle exists (and otherwise all computed parities naturally are even). Hence, computing these parities is sufficient for obtaining a randomized algorithm for the decision variant of the Hamiltonicity problem.

For each bag $i$, we compute table entries~$t_i[d,w,M] \in \mathbb{Z}_2$ for all functions $d: B_i  \rightarrow \{0,1,2\}$, all
integers~$w\in\{0,\ldots,n\cdot \omega_{\max}\}$, and all perfect matchings~$M$ of $Z_{d^{-1}(1)}$. 
First, define $\mathcal{T}_i[d,w]$ as the family of edge sets $X \subseteq E_i$ such that
\begin{enumerate}
	\item $\deg_X(v)=d(v)$ for every $v \in B_i$,
	\item $\deg_X(v)=2$ for every $v \in V_i \setminus B_i$,
	\item $\omega(X)=w$,
	\item $X$ has no cycles, unless $d(v)=1$ for all $v \in B_i$.
\end{enumerate}
Here we let $\deg_X(v)$ denote the number of edges in $X$ that are incident to $v$.
Define $\mathcal{T}_i[d,w,M]$ as the family of edge sets $X \in \mathcal{T}_i[d,w]$ such that $X \cup M$ is a single cycle.
The dynamic programming table entries $t_i[d,w,M]$ computed in~\cite[Section 4]{CyganKN2018} are defined as the parity of $|\mathcal{T}_i[d,w,M]|$. The algorithm from~\cite{CyganKN2018} shows how to compute $t_i$ whenever $i$ is a leaf, introduce vertex, introduce edge, or forget bag, based on the table $t_j$ where $j$ is a child of $i$ in $\mathbb{T}$ (if $i$ is not a leaf bag). It remains to show how to compute $t_j$ based on the tables $t_{j}$ and $t_{j'}$ if $x$ is a join bag with children $j$ and $j'$. To this end, we provide a formula for this that sets up the tensor that we need to study. 
We also use the shorthand notation $\overline{M}$ to denote $\mathcal{B}(V(M),\overline{a})$, if $M = \mathcal{B}(V(M),a)$ and the vertex set $V(M)$ denotes the endpoints of $M$.


\begin{Lem}\label{lem:join}
	If $i$ is a join bag with children $j$ and $j'$, then
	\[
		t_i[d,w,M] \equiv_2 \sum_{\substack{d_j+d_{j'}=d \\ w_j+w_{j'}=w \\ \overline{M_j} \cup \overline{M_{j'}} \cup M \text{ is a cycle}}}t_j[d_j,w_j,M_j]\cdot t_{j'}[d_{j'},w_{j'},M_{j'}].
	\]
\end{Lem}	
\begin{proof}
	It is easy to see that $\mathcal{T}_i[d,w,M]$ equals
	\[
		\bigcup_{\substack{d_j+d_{j'}=d \\ w_j+w_{j'}=w}} \bigg\{ Y \cup Z\ \bigg|\ Y \in \mathcal{T}_j[d_j,w_j], Z\in \mathcal{T}_{j'}[d_{j'},w_{j'}],  Y \cup Z \cup M \text{ is a cycle}\bigg\},
	\]
	and all terms in the union are disjoint since $E_{j} \cap E_{j'} = \emptyset$. Hence, we have that $t_i[d,w,M]$ equals
	\begin{align*}
		&\hphantom{=} \sum_{\substack{d_j+d_{j'}=d \\ w_j+w_{j'}=w \\ Y \in \mathcal{T}_j[d_j,w_j] \\ Z\in \mathcal{T}_{j'}[d_{j'},w_{j'}]}} [Y \cup Z \cup M \text{ is a cycle}],\\
		\intertext{which we can rewrite by applying Lemma~\ref{lem:fact} with $Y$ and $Z \cup M$ (with degree $2$ vertices contracted), since they are both perfect matchings of $K_{d^{-1}_j(1)}$, into}
		&= \sum_{\substack{d_j+d_{j'}=d \\ w_j+w_{j'}=w \\ Z\in \mathcal{T}_{j'}[d_{j'},w_{j'}]}} \sum_{a \in \{0,1\}^{|d_j^{-1}(1)|/2-1}} t_j[d_j,w_j,\mathcal{B}(d_j^{-1}(1),a)] \cdot [\mathcal{B}(d_j^{-1}(1),\overline{a}) \cup Z \cup M \text{ is a cycle}],\\
		\intertext{which we can rewrite by applying Lemma~\ref{lem:fact} with $Z$ and $\mathcal{B}(d_j^{-1}(1),a) \cup M$ (with degree $2$ vertices contracted), since they are both perfect matchings of $K_{d^{-1}_{j'}(1)}$, into}
		&= \sum_{\substack{d_j+d_{j'}=d \\ w_j+w_{j'}=w \\ Z\in \mathcal{T}_{j'}[d_{j'},w_{j'}]}} \sum_{\substack{a \in \{0,1\}^{|d_j^{-1}(1)|/2-1}\\b \in \{0,1\}^{|d_{j'}^{-1}(1)}|/2-1}} t_j[d_j,w_j,\mathcal{B}(d_j^{-1}(1),a)] \cdot t_{j'}[d_{j'},w_{j'},\mathcal{B}(d_{j'}^{-1}(1),b)]\\
		&\hspace{14em} \cdot [\mathcal{B}(d_j^{-1}(1),\overline{a}) \cup \mathcal{B}(d_{j'}^{-1}(1),\overline{b}) \cup M \text{ is a cycle}].
	\end{align*}
\end{proof}

\subsection{Kronecker scaling for the Matchings Connectivity Tensor}\label{subsec:mct}
Partition $U$ into $r = \lceil q/b \rceil $ blocks $U_1,\ldots,U_{r}$ of size at most $b$.
Let $(d_1,M_1),(d_2,M_2),(d_3,M_3)$ be a triple consisting of three $U$-fingerprints. The \emph{type} of this triple is defined as the triple $(X_1,X_2,X_3)$ where $X_i \subseteq M_i$ is the subset edges of $M_i$ that have both endpoints in distinct blocks for $i=1,2,3$ and $M^*$ is obtained from $M_1 \cup M_2 \cup M_3$ by contracting all vertices that are not an endpoint of an edge in $X_1 \cup X_2 \cup X_3$.
We let $T^q_b$ denote the set of all types. We first show this set is relatively small, using the following easy observation about the family of basis matchings:

\begin{Obs}\label{obs:cut}
	For any $i \in [t]$ and $X \subseteq [t]$ and perfect matching $M$ of $Z_X$, there are at most $2$ edges in $Z_X$ with one endpoint in $\{x_j: j\leq i\}$ and one endpoint in $\{x_j: j > i\}$.
\end{Obs}


\begin{Lem}
	For positive integers $b < q$ we have that
	\[
		|T^q_b| \leq (20b)^{12r}.
	\]
\end{Lem}
\begin{proof}
	For every $i \in \{1,2,3\}$ and $j \in \{1,\ldots,r\}$, let $x_{i,j}$ be the number of edges in $X_i$ with exactly one endpoint in $B_j$, and let $U_{i,j}$ be the set of vertices in $U_j$ incident to an edge of $X_i$.

	We have $|U_{i,j}| \leq x_{i,j}$, and by Observation~\ref{obs:cut}, $x_{i,j} \leq 4$.
	Moreover, if a vertex in $U_{i,j}$ is matched to a vertex in $U_{i,j'}$ in $X_i$, then as a direct consequence of the definition of the basis matchings from Definition~\ref{def:basis} there is at most one $j''$ such that $U_{i,j''}$ is nonempty.

	Hence, we can describe $X_i$ with $U_{i,1},\ldots,U_{i,r}$ and per vertex in $U_{i,1},\ldots,U_{i,r}$ there are at most $19$  possible\footnote{We arrived at this rough upper bound by counting five possible blocks of each $4$ vertices minus the vertex itself.} vertices to whom it could be adjacent in $X_i$. Hence, the number of possibilities for $X_i$ is at most
	\[
		\binom{b}{4}^r 20^{4r}	\leq (20b)^{4r}.
	\]
	Hence the number of options for $(X_1,X_2,X_3)$ is as claimed in the lemma statement.
\end{proof}

Since there are only few options for $(X_1,X_2,X_3)$ we can sum over all possibilities and deal with each one separately. Unfortunately this does not directly help to decompose $H_q$ into a Kronecker product since the (at most $12$) edges leaving a block still cause complications. We now argue this can be reduced to two edges leaving the block to a larger block (for blocks $U_1,\ldots,U_{r-1}$) and two edges leaving the block to a smaller block (for blocks $U_2,\ldots,U_{r}$) by decomposing $X_1 \cup X_2 \cup X_3$ into basis matchings.

Formally, suppose that $(d_1,M_1),(d_2,M_2),(d_3,M_3)$ are $U$-fingerprints such that $d_1(v)+d_2(v)+d_3(v)=2$, and suppose that the type of this triple is $\tau = (X_1,X_2,X_3)$, let $E(\tau)$ denote $X_1 \cup X_2 \cup X_3$, and let $V(\tau)$ denote all endpoints of $E(\tau)$.
Let $M^*$ be obtained by contracting all edges from $(M_1 \setminus X_1) \cup (M_2 \cup X_2) \cup (M_3 \cup X_3)$ that are not a self-loop. We have that $M_1 \cup M_2 \cup M_3$ is a single cycle if and only if $M^* \cup X$ is a single cycle. Hence, by Lemma~\ref{lem:fact}
\begin{equation}\label{eq:factx}
	[M_1 \cup M_2 \cup M_3 \text{ is a cycle}] \equiv_2 
	\sum_{\substack{ a \in \{0,1\}^{|V(\tau)|/2-1} \\ E(\tau) \cup \mathcal{B}(V(\tau),\overline{a}) \text{ is a HC }}} [M^* \cup \mathcal{B}(V(\tau),a) \text{ is a HC }].
\end{equation}
If we let $\mathcal{B}(\tau)$ denote 
\[
	\{ \mathcal{B}(V(\tau),a): E(\tau) \cup \mathcal{B}(V(\tau),\overline{a}) \text{ is a HC}\},
\]
then we can rewrite~\eqref{eq:factx} as
\begin{equation}\label{eq:factxb}
	[M_1 \cup M_2 \cup M_3 \text{ is a cycle}] \equiv_2 
	\sum_{A \in \mathcal{B}(\tau)} [M^* \cup A \text{ is a HC }].
\end{equation}

Moreover, since $A \in \mathcal{B}_\tau$, we have by Observation~\ref{obs:cut} for every $j=1,\ldots,r$ that at most two edges of $A$ leave $U_j$ to a block $U_{j'}$ with $j' < j$ and at most two edges of $A$ leave $U_j$ to a block $U_{j'}$ with $j' > j$. Call the first type of edges the \emph{left $A$-exits} of $U_j$ and the second type of edges the \emph{right $A$-exits} of $U_j$.




For $i\in\{1,2,3\}$, $j=1,\ldots,r$, $\tau \in T_b^q$, $A \in \mathcal{B}_\tau$ and $U$-fingerprints $(d_{1},M_{1}),(d_{2},M_{2}),(d_{3},M_{3})$ we define $U_j$-fingerprints
$\varphi(i,j,\tau,A,d_i,M_i):= (d^{\tau,A}_{i,j},M^{\tau,A}_{i,j})$ as follows:

$M^{\tau,A}_{1,j}$ is constructed from starting with all edges in $M_1$ contained in $U_j$ and by adding every edge in $A$ that is contained in $U_j$. Additionally:
\begin{itemize}
	\item If there is one edge in $A$ with endpoints in blocks $U_{j'}$ and $U_{j''}$ with $j'< j < j''$, there is at most one left exit of $U_j$ and at most one right exit of $U_j$. Add the endpoints of those exits that are in $U_j$ to $M^{\tau,A}_{1,j}$.

	\item If there are two left exits, add the endpoints of those exits that are in $U_j$ to $M^{\tau,A}_{1,j}$.

	\item If there are two right exits, add the endpoints of those exits that are in $U_j$ to $M^{\tau,A}_{1,j}$.	
\end{itemize} 

$d^{\tau,A}_{1,j}$ is defined as $d^{\tau,A}_{1,j}(V(M^{\tau,A}_{1,j}))=1$, and for all vertices in $U_j \setminus V(M^{\tau,A}_{1,j})$ we have $d^{\tau,A}_{1,j}(v)=d_1(v)$.

$M^{\tau,A}_{2,j}$ (respectively,$M^{\tau,A}_{3,j}$) are defined as $M_2$ (respectively, $M_3$) restricted to all edges contained in $U_j$ and $d^{\tau,A}_{2,j}$ (respectively, $d^{\tau,A}_{3,j}$) are defined as $d_2$ (respectively, $d_3$) restricted to $U_j$ with the exception that edges in $A$ do not contribute anymore.

Though somewhat tediously, we can make the following observation about this rerouting:

\begin{Obs}\label{obs:reroute}
	$M^* \cup A$ is a single cycle if and only if for every $j=1,\ldots,r$ we have that  $M^{\tau,A}_{1,j} \cup M^{\tau,A}_{2,j} \cup M^{\tau,A}_{3,j}$ is a single cycle.
\end{Obs} 

Hence, we can define
\[
\begin{aligned}
x^{\tau,A}_{(d_1,M_1),\ldots,(d_r,M_r)} &= \sum_{\substack{ (d,M) \\ \forall j \in \{1,\ldots,r\}: \varphi(1,j,\tau,A,d,M)=(d_j,M_j)}}x_{d,M},\\
y^{\tau,A}_{(d_1,M_1),\ldots,(d_r,M_r)} &= \sum_{\substack{ (d,M) \\ \forall j \in \{1,\ldots,r\}: \varphi(2,j,\tau,A,d,M)=(d_j,M_j)}}y_{d,M},\\
z^{\tau,A}_{(d_1,M_1),\ldots,(d_r,M_r)} &= \sum_{\substack{ (d,M) \\ \forall j \in \{1,\ldots,r\}: \varphi(3,j,\tau,A,d,M)=(d_j,M_j)}}z_{d,M}.
\end{aligned}
\]
and obtain the main result of this subsection:
\begin{Thm}[Kronecker scaling for the Matchings Connectivity Tensor]\label{thm:fac}
\label{thm:matchings-connectivity-tensor-kronecker-scaling}
	For all $q$ and $b$:
	\[
		H_q(x,y,z) = \sum_{\tau\in T_b^{q}} \sum_{\substack{A \in \mathcal{B}_\tau \\ E(\tau) \cup A \textnormal{ is a cycle}}} \left(\bigotimes_{j\in [r]} H_{|U_j|} \right)(x^{\tau,A},y^{\tau,A},z^{\tau,A}).
	\]
\end{Thm}
\begin{proof}
	We have by definition that
	\begin{align*}
		H_q(x,y,z) &\equiv_2 \sum_{\substack{(d_1,M_1),(d_2,M_2),(d_3,M_3) \\ \forall v \in [q]: d_1(v)+d_2(v)=d_3(v)} }x_{d_1,M_1}\cdot y_{d_2,M_2}\cdot z_{d_3,M_3} [M_1 \cup M_2 \cup M_3 \text{ is a cycle}],\\
				   &\equiv_2 \sum_{\substack{(d_1,M_1),(d_2,M_2),(d_3,M_3) \\ \forall v \in [q]: d_1(v)+d_2(v)=d_3(v)}}x_{d_1,M_1}\cdot y_{d_2,M_2}\cdot z_{d_3,M_3} \sum_{\substack{ A \in \mathcal{B}_\tau \\ E(\tau) \cup A \text{ is a HC }}} [M^* \cup A \text{ is a HC }]\\
				   &\equiv_2  \sum_{\tau \in T^q_b}\sum_{\substack{ A \in \mathcal{B}_\tau \\ E(\tau) \cup A \text{ is a HC }}}\sum_{\substack{(d_1,M_1),(d_2,M_2),(d_3,M_3) \\ \forall v \in [q]: d_1(v)+d_2(v)=d_3(v)}}x_{d_1,M_1}\cdot y_{d_2,M_2}\cdot z_{d_3,M_3}\cdot [M^* \cup A \text{ is a HC }]\\				   
   				   &\equiv_2  \sum_{\tau \in T^q_b}\sum_{\substack{ A \in \mathcal{B}_\tau \\ E(\tau) \cup A \text{ is a HC }}}\left(\bigotimes_{j\in [r]} H_{|U_j|} \right)(x^{\tau,A},y^{\tau,A},z^{\tau,A}),
	\end{align*}
	where the second congruence is by~\eqref{eq:factxb}, and $\tau$ denotes the type of $(d_1,M_1),(d_2,M_2),(d_3,M_3)$, the third equivalence is by reordering summations (and hence the third summation runs over all $(d_1,M_1),(d_2,M_2),(d_3,M_3)$ with type $\tau$), and the final equivalence is by Observation~\ref{obs:reroute}.
\end{proof}


\subsection{Rank bounds imply faster algorithms for Hamiltonicity parameterized by treewidth}
\label{subsec:fin}
We now prove Theorem~\ref{thm:hcmain}. 
By Lemma~\ref{lem:join} and the discussion in Subsection~\ref{subsec:revckn}, it suffices to compute
\[
t_i[d,w,M] \equiv_2 \sum_{\substack{d_j+d_{j'}=d \\ w_j+w_{j'}=w \\ \overline{M_j} \cup \overline{M_{j'}} \cup M \text{ is a cycle}}}t_j[d_j,w_j,M_j]\cdot t_{j'}[d_{j'},w_{j'},M_{j'}],
\] 
in $O^*\left((2+\sqrt{2}+o(1))^{(\sigma(H_\mathbb{N})+\varepsilon)\tw}\right)$ time, when we are given tables $t_j$ and $t_{j}$.
We use $H_d$ as a bilinear form via its partial derivatives. We iterate over all $w_j,w_{j'}$ such that $w_j+w_{j'}=w$ and let
\[
	y_{d,M} := t_j[d,w_j,\overline{M_j}], \quad z_{d,M} := t_{j'}[d_{j'},w_{j'},\overline{M_{j'}}].
\]
Consider the polynomial $H_{\tw}(x,y,z)$ in variables $x$.
By Theorem~\ref{thm:fac} we have that
\[
	H_\tw(x,y,z) = \sum_{\tau\in T_b^{\tw}} \sum_{\substack{A \in \mathcal{B}_\tau \\ E(\tau) \cup A \textnormal{ is a cycle}}} \left(\bigotimes_{j\in [r]} H_{|U_j|} \right)(x^{\tau,A},y^{\tau,A},z^{\tau,A}),
\]
and it is easy to see from the proof of Theorem~\ref{thm:fac} that $T^\tw_b,B_\tau,y^{\tau,A},z^{\tau,A}$ can all be constructed in $O^*\left((2+\sqrt{2})^{\tw}\right)$ time.

\begin{Lem}
	For every $\epsilon> 0$ we can, given $\tw$, $r$, $\tau$ and $A$, produce in $O((2+\sqrt{2})^{\sigma(H_{\mathbb{N}})+\varepsilon})$ time an arithmetic circuit $C$ of size $O((2+\sqrt{2})^{\sigma(H_{\mathbb{N}})+\varepsilon})$ that evaluates $\left(\bigotimes_{j\in [r]} H_{|U_j|} \right)(x^{\tau,A},y^{\tau,A},z^{\tau,A})$.
\end{Lem}
\begin{proof}
	Recall that $\sigma(H_{\mathbb{N}})=\inf\,\biggl\{\sigma>0:\Ra(H_q)\leq(2+\sqrt{2})^{q(\sigma+o(1))}\biggr\} $. Hence, for every $\epsilon$ there exists $b$ such that $\Ra(H_b) \leq (2+\sqrt{2})^{b(\sigma+\epsilon)}$.

	As mentioned below Definition~\ref{def:matchtensor}, $H_{q'}(x,y,z)$ is a sub-tensor of $H_{q}(x,y,z)$ whenever $q' < q$. Hence, $H_{|U_r|}$ is a sub-tensor $H_{b}$ and by adjusting 
	$x^{\tau,A},y^{\tau,A},z^{\tau,A}$ accordingly if needed, we can restrict attention to evaluating
	\[
		H_b^{\otimes r}(x^{\tau,A},y^{\tau,A},z^{\tau,A}).
	\]
	Applying Lemma~\ref{lem:yates-kron} with $T$ being the tensor $H_b$ and $r$ being the Kronecker power, we obtain the lemma statement.	
\end{proof}	




Then, if we denote $\overline{d}$ for the vector $(2-d_1,\ldots,2-d_\tw)$, we have that
\[
	\frac{\partial H_{\tw}(x,y,z)}{\partial x_{\overline{d},M}} = \sum_{\substack{d_j+d_{j'}=d \\ \overline{M_j} \cup \overline{M_{j'}} \cup M \text{ is a cycle}}}t_j[d_j,w_j,M_j]\cdot t_{j'}[d_{j'},w_{j'},M_{j'}],
\]
and hence we can recover all values $t_i[d,w,M]$ efficiently once we computed all partial derivatives $\frac{\partial H_{\tw}(x,y,z)}{\partial x_{\overline{d},M}}$.
To do so, we use the following well-known lemma:
\begin{Lem}[Baur-Strassen~\cite{BaurS83}]\label{lem:bs}
	If a polynomial $P(x_1,\ldots,x_n) \in \mathbb{F}[x_1,\ldots,x_n]$ can be computed by an arithmetic circuit $C$ of size $s$, then there is another arithmetic circuit of size $O(s)$ that computes all partial derivatives $\frac{\partial P(x_1,\ldots,x_n)}{\partial x_1},\ldots,\frac{\partial P(x_1,\ldots,x_n)}{\partial x_n}$ simultaneously.
\end{Lem}
The circuit promised by Lemma~\ref{lem:bs} can also be constructed from $C$ in linear time, see~\cite{Morgenstern85}.
Thus, we can turn the arithmetic circuit $C$ constructed above into one that computes all partial derivates with linear overhead, as required.

